import { changesScreen } from './screens/changes'
import { overviewScreen } from './screens/overview'
import { pictureScreen } from './screens/picture'
import { recentsScreen } from './screens/recents'
import { requestsScreen } from './screens/requests'
import { treeScreen } from './screens/tree'
import { foldOf } from './semantic'
import type { Settings } from './settings'
import { DEFAULTS, settingsOf } from './settings'
import { readSource } from './source'
import {
  NO_CRUMB,
  NO_LISTING,
  NO_PICKED,
  NO_SCAN,
  NO_SOURCE,
  NO_SYMBOL,
  NO_VIEW,
  changedDiags,
  comparisonOf,
  settledPicked,
  settledScan,
  settledView,
  totalsOf,
} from './state'
import { stepShown } from './changes'
import { clamp, foldEnd } from './text'

const PANE = 'lens'

// The parked mod's pane, which lens draws in while that mod hosts it. Parked
// says so in its own `guest` state when a file of one of its items is opened:
// the file is then read where the item was, with no other pane to switch to.
// Parked draws its own rows above (the way back), and lens has the rest.
const HOST = 'parked'
const HOST_ROWS = 2
const GUEST = { plugin: 'parked', key: 'guest' } as const
const isGuest = ($: EngineInterface): Promise<boolean> =>
  $.state.get(GUEST).then(
    got => got.value === true,
    () => false,
  )
// How many unchanged files opened from the tree of every file stay among
// those checked.
const EXTRA_FILES = 20
// The most lines of code sent to the prompt with a review thread.
const TALK_CODE = 80

// The session's state. Its shapes are the contract's (types/index.d.ts) and
// its defaults are in state.ts; the atoms are written here because the
// engine reads a state reference only in the file that uses it.
const view = atom({ plugin: 'lens', key: 'view' } as const, NO_VIEW)
const scan = atom({ plugin: 'lens', key: 'scan' } as const, NO_SCAN)
const source = atom({ plugin: 'lens', key: 'source' } as const, NO_SOURCE)
const listing = atom({ plugin: 'lens', key: 'listing' } as const, NO_LISTING)
const picked = atom({ plugin: 'lens', key: 'picked' } as const, NO_PICKED)
// The repos reviewed lately, as the store holds them between sessions: the
// copy the recents screen draws from, written by `rememberReview`,
// `forgetReview` and the /lens command.
const recents = atom({ plugin: 'lens', key: 'recents' } as const, [] as Recent[])
// The frame of the busy mark, stepped by the timer while a scan runs.
const spin = atom({ plugin: 'lens', key: 'spin' } as const, 0)
const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

// What the module holds beside the state. A reload of the mod drops all of
// it, and each is asked for again where it is missed. Every one below is
// written only by the function or hook its comment names; the rest of the
// session's caches belong to the modules that fill them (the history and
// the list of every file to scan.ts, the base's diagnostics to check.ts).

// The person's settings, read from the module's options when it registers
// (a change in the config menu loads the module again with the new ones).
let settings: Settings = DEFAULTS

// How the repo stood when it was last looked at (see `git.repoMark`), and
// the timer's count of ticks: every so many, `watchRepo` looks again.
let repoMarked: { repo: string; mark: string } | undefined
let ticks = 0
let isWatching = false
// Ticks of the 400 ms timer between two looks at the repo: about 4 seconds.
const WATCH_TICKS = 10

// The scan queue, written by anything that wants a scan and taken by the
// timer: a reload drops a waiting scan, and the next refresh asks again.
let job: Job | undefined
let isBusy = false

// The open file's coloured lines, written by `loadSource`. A whole file is
// too much to keep as state, so a reload loses them and the render hook asks
// for them again through `wanted`, which the timer takes.
let cache:
  | {
      path: string
      // The commit the file was read at; '' for the working tree's.
      commit: string
      lines: Span[][]
      removed: Record<number, string[]>
      // Where the first of each run of removed lines was, in the base.
      removedAt: Record<number, number>
      // A commit's own changed lines; the working tree's come from the scan.
      changed: LineRange[] | undefined
    }
  | undefined
let wanted: string | undefined
let isLoading = false

// The commit or stash message as typed so far, and the comment being typed:
// each field holds its own text, and these are the copies the buttons beside
// it read. Written by the fields' actions, and cleared by `commitFiles`,
// `stashFiles` and `postReview` once what was typed has been used.
let draft = ''
let draftBody = ''
let commentDraft = ''
// Whether anything has been typed since a comment was put in the field to be changed.
let commentTouched = false
// How many comments have been sent or dropped: see `FileModel.commentRound`.
let commentRound = 0
// The same for the review being written in the file tree's box.
let reviewDraft = ''
let reviewRound = 0
// And for the comment on the request as a whole being written there.
let talkDraft = ''
let talkRound = 0

// How the language-server bridge runs its commands, made by `serverRun` from
// the first handle that needs it.
let servers: ServerRun | undefined

// What the language server knows of the file the file screen shows, written
// by `loadInsight` (and dropped by `loadSource` for a commit's file). Read
// after the file itself, so the file draws first and gains these.
let insight: ({ path: string } & Insight) | undefined
// The file `loadInsight` is reading for, while it is: the screen says so.
let insightFor: string | undefined

// Opens the pane on a file at a line, for another mod that names the place: a
// path that is absolute, or from the session's folder. The repository the
// file is in becomes the one under review, unless the folder under review
// already holds the file.
const showPlace = async ($: EngineInterface, named: string, line: number): Promise<void> => {
  // Asked by a mod that is showing lens in its own pane, lens's own pane is
  // left as it is: opening it would bring it forward whenever the prompt, and
  // not the host's pane, happened to hold the keyboard.
  const isHosted = await isGuest($)
  const run = runOf($)
  const root = await $.session.cwd().catch(() => '')
  const full = placeOf(named, root)
  const now = await read($, view)
  let repo = now.repo !== '' && full.startsWith(`${now.repo}/`) ? now.repo : ''

  if (repo === '') {
    const top = await run(['git', '-C', full.replace(/\/[^/]*$/, ''), 'rev-parse', '--show-toplevel'])
    // Outside any repository, the session's folder is listed where it holds
    // the file.
    repo = top.exitCode === 0 ? top.stdout.trim() : root

    if (repo === '' || !full.startsWith(`${repo}/`)) {
      $.ui.toast(`Lens: ${named} is not in a git repository or this session's folder`)

      return
    }

    await openReview($, repo, undefined, isHosted)
  }

  const path = full.slice(repo.length + 1)

  await loadSource($, repo, path)
  await update(
    $,
    view,
    (last): View => ({
      ...last,
      screen: 'file',
      file: path,
      commit: '',
      origin: 'tree',
      top: Math.max(1, line - 3),
      cursor: -1,
      isDiff: false,
      isPreview: false,
      symbol: NO_SYMBOL,
      crumb: NO_CRUMB,
    }),
  )

  if (!isHosted) {
    await $.ui.open({ id: PANE, title: 'Lens', focus: true })
  }
}

// The ledger mod's run, where that mod is loaded: its findings are drawn with
// a request's comments.
const LEDGER_RUN = { plugin: 'ledger', key: 'run' } as const

// The comments on the pull or merge request under review, as the forge gave
// them, with the folder under review's place in the repo (`prefix`). Written
// by `loadComments`; `postReview` adds the comment it posted.
let commentsCache: { key: string; prefix: string; comments: Comment[] } | undefined

// The open request of the branch checked out, where it has one: its comments
// show on the working tree's files without a comparison being set up.
// Written by `findBranchRequest`, with each scan of the working tree.
let branchRequest:
  | {
      repo: string
      branch: string
      typed: string
      label: string
      // What it is called, the branch it targets, and when the forge said so.
      title: string
      baseRef: string
      url: string
      at: number
      // What the branch changes since it forked from that target, read
      // again with every scan: the commit it forked at, and the files.
      base: string
      files: ChangedFile[]
      stats: Record<string, LineStat>
    }
  | undefined

// The repo's open pull or merge requests, for the compare panel to offer.
// Written by `loadRequests`, when the panel opens.
let requestsCache: { repo: string; list: Listed[] } | undefined
// Whether the list is of the requests that are over (merged or closed) in
// place of the open ones.
let requestsPast = false

// The whole comparison as one page, for the changes screen: what git said of
// the repo, base and target in `key`. Written by `loadPatch`, when that
// screen opens or is refreshed; `patchWanted` is the key being read.
// `staged` is the marks of the hunks the index holds (see `hunkMark`).
let patchCache: { key: string; files: PatchFile[]; refusal: string; staged: Set<string> } | undefined
// How many unchanged lines each file expanded on that page shows round its
// changes, by path, for the page in `key`; and how many each press adds.
let pageMore: { key: string; by: Map<string, number> } = { key: '', by: new Map() }
const MORE_STEP = 20
// The hunk whose undoing the page is asking about, by its name; '' for none.
let hunkAsked = ''
let patchWanted: string | undefined
// The files of that page as the highlighter coloured them, by path, and the
// ones asked for: written by `colorPage` as each stretch of the page is drawn.
let pageColors: { key: string; lines: Map<string, Span[][]>; asked: Set<string> } = {
  key: '',
  lines: new Map(),
  asked: new Set(),
}
// How many files are highlighted at a time, and how many times one is asked
// for before it is left plain; `colorTries` counts them, by page and path.
const COLORED_AT_ONCE = 3
const COLOR_TRIES = 3
const colorTries = new Map<string, number>()
// The changes screen's window as last drawn, for the scroll hook.
let pageWindow: ChangesWindow = { maxTop: 0 }

// The view with its count of asked-for drawings one higher: what a module
// value changing (a list read, a file coloured) writes to have the pane
// drawn again. A value written back unchanged is no change to draw for.
const nudged = (last: View): View => ({ ...last, redraws: (last.redraws ?? 0) + 1 })

// How many requests' ticks are kept between sessions.
const REVIEWED_KEPT = 40
// And how many ticked files of each.
const REVIEWED_PATHS = 2000
// How many lines of a request's description the file tree shows.
const ABOUT_LINES = 3
// The most comments one review holds unsent.
const DRAFTS_KEPT = 200

// What the folder the breadcrumb last opened holds, written by `loadCrumb`.
let crumbCache: { dir: string; entries: string[] } | undefined

// Who last changed each line of the file the blame column was asked for,
// written by `loadBlame`.
let blameCache: { path: string; commit: string; lines: Blamed[] } | undefined

// What the render hook leaves for the scroll hook and the timer: the graph's
// and the file's windows as last drawn (see `GraphWindow`, `FileWindow`),
// and whether the pane's own scroll needs holding one row down, for a screen
// that draws its own window; the drawing asks, the timer does it.
let graphWindow: GraphWindow = { header: 0, kinds: [], maxTop: 0, bodyMax: 0 }
let fileWindow: FileWindow = { maxTop: 1, shown: undefined, crumbBox: undefined }
let wantPin = false
// How many rows the last drawing of a screen the pane scrolls was reckoned
// to take, and what the engine then said it took (see `rowsBelow`).
let paneEstimate = 0
let paneMeasured: { content: number; estimate: number } | undefined

const noteEdit = async ($: EngineInterface, path: string): Promise<void> => {
  const { repo, isTelling } = await read($, view)

  if (repo !== '' && path.startsWith(`${repo}/`)) {
    job = { isProject: false }

    if (isTelling ?? false) {
      noteTouched(path.slice(repo.length + 1))
    }
  }
}

// Every command of the session is run through this: the handle's own
// `process.run`, made never to reject (see `Run`).
const runOf =
  ($: EngineInterface): Run =>
  (argv, init) =>
    $.process
      .run(argv, init ?? {})
      .catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

// The open file where it is a picture: itself and what it was before, each
// as a file the terminal draws, or undefined where there is none to draw.
let shot:
  | { path: string; commit: string; now: Picture | undefined; before: Picture | undefined; against: string }
  | undefined

// Reads a whole file as coloured lines and keeps it for the file screen, with
// what the diff view interleaves.
//
// With a `commit` the file is read as that commit left it, and its diff is
// what the commit changed; without one it is the working tree's file, against
// the base.
const loadSource = async (
  $: EngineInterface,
  repo: string,
  path: string,
  commit = '',
): Promise<void> => {
  const run = runOf($)

  // A picture is not read as text: it is made a file the terminal draws,
  // and so is what it was on the other side, where it was a different one.
  if (isPictureFile(path)) {
    const { base, target, diffBase } = await read($, view)
    const own = commit === '' && diffBase?.path === path && diffBase.base !== '' ? diffBase.base : ''
    const other = commit === '' ? own || base || 'HEAD' : commit === target && base !== '' ? base : `${commit}^`
    const [now, was] = await Promise.all([localPicture(run, repo, path, commit), localPicture(run, repo, path, other)])

    shot = {
      path,
      commit,
      now,
      before: was !== undefined && was.file !== now?.file ? was : undefined,
      against: /^[0-9a-f]{40}$/.test(other) ? other.slice(0, 8) : other,
    }
    cache = { path, commit, lines: [], removed: {}, removedAt: {}, changed: undefined }
    insight = undefined
    const stamp = await $.clock.now()
    await update($, source, () => ({ path, lineCount: 0, note: '', stamp }))

    return
  }

  const committed = commit === '' ? undefined : await git.fileAt(run, repo, path, commit)
  const { lines, note } = await readSource(
    run,
    file => $.fs.read(file).catch(() => ''),
    repo,
    path,
    committed,
  )
  const { base, target, diffBase } = await read($, view)
  // A file of the branch's request is read against where the request forked.
  const own = commit === '' && diffBase?.path === path && diffBase.base !== '' ? diffBase.base : ''
  const diff = await git.fileDiff(run, repo, path, commit, own || base, target ?? '', own !== '')

  cache = { path, commit, lines, removed: diff.removed, removedAt: diff.removedAt, changed: diff.changed }
  const stamp = await $.clock.now()
  await update($, source, () => ({ path, lineCount: lines.length, note, stamp }))

  // What the language server adds comes after, so the file is not kept
  // waiting for it; only the working tree's files are on disk for a server.
  if (commit === '') {
    void loadInsight($, repo, path)
  } else {
    insight = undefined
  }
}

// The repos reviewed lately, as the store holds them.
const readRecents = async ($: EngineInterface): Promise<Recent[]> =>
  settledRecents(await $.store.get('recents').catch(() => undefined))

// Keeps the review as it stands (its repo, comparison and layout) for the
// sessions to come, where the person has not switched remembering off.
const rememberReview = async ($: EngineInterface): Promise<void> => {
  const now = await read($, view)

  if (!settings.remembers || now.repo === '') {
    return
  }

  const list = remember(
    await readRecents($),
    recentOf(now, await $.clock.now(), await git.mainRepoOf(runOf($), now.repo)),
  )

  await $.store.set('recents', list).catch(() => undefined)
  await update($, recents, () => list)
}

const forgetReview = async ($: EngineInterface, repo: string): Promise<void> => {
  const list = (await readRecents($)).filter(one => one.repo !== repo)

  await $.store.set('recents', list).catch(() => undefined)
  await update($, recents, () => list)
}

// Starts a review of a repo and opens the pane on it. With no `base` named,
// the repo is picked up where it was last left: its layout, and its
// comparison where git still knows both sides (a pull or merge request is
// fetched again). Answers what it did, in a sentence.
const openReview = async (
  $: EngineInterface,
  repo: string,
  base: string | undefined,
  // Set where another mod's pane is to show the review: the pane is not opened.
  isHosted = false,
): Promise<string> => {
  const kept =
    base === undefined && settings.remembers
      ? (await readRecents($)).find(one => one.repo === repo)
      : undefined

  await update($, view, () => ({
    ...NO_VIEW,
    repo,
    base: base ?? 'HEAD',
    layout: kept?.layout ?? 'tree',
    isBrowsing: kept?.isBrowsing ?? false,
  }))
  // The ticks of the requests reviewed before come back with the review.
  void readReviewed($).then(reviewed => update($, view, (last): View => ({ ...last, reviewed })))
  // And the comments written for a review and not sent yet.
  void readDrafts($).then(drafts => update($, view, (last): View => ({ ...last, drafts })))
  await update($, scan, () => ({ ...NO_SCAN, status: 'running' }))
  job = { isProject: false }

  if (!isHosted) {
    await $.ui.open({ id: PANE, title: 'Lens', focus: true })
  }

  // A folder git does not know has nothing to compare: its files are listed.
  if ((await git.findRepo(runOf($), repo)) === '') {
    return `Listing ${repo}, which is not in a git repository: its code files are checked, and nothing is compared.`
  }

  if (kept === undefined || (kept.base === 'HEAD' && kept.target === '')) {
    return `Reviewing ${repo} against ${base ?? 'HEAD'}.`
  }

  if (kept.requestTyped !== '') {
    void startCompare($, repo, '', kept.requestTyped)

    return `Reviewing ${repo}: fetching ${kept.requestTyped} again, as you left it.`
  }

  const run = runOf($)
  const isKnown =
    (await git.isCommit(run, repo, kept.base)) &&
    (kept.target === '' || (await git.isCommit(run, repo, kept.target)))

  if (!isKnown) {
    return `Reviewing ${repo} against HEAD (what it was last compared with is gone).`
  }

  await update($, view, (last): View => ({ ...last, base: kept.base, target: kept.target }))
  job = { isProject: false }

  return `Reviewing ${repo}: ${kept.target === '' ? 'the working tree' : kept.target} against ${kept.base}, as you left it.`
}

// Scans again when the repo has changed under the pane: a commit, a
// checkout, a merge, an edit or a stash made anywhere (Claude's own shell,
// another terminal, an editor). Only while the pane is open, and never
// while a scan is running or waiting.
const watchRepo = async ($: EngineInterface): Promise<void> => {
  const { repo } = await read($, view)

  if (repo === '' || isBusy || job !== undefined) {
    return
  }

  const open = await $.ui.panes().catch(() => [])

  if (!open.some(one => one.id === PANE)) {
    return
  }

  const mark = await git.repoMark(runOf($), repo)

  if (mark === '') {
    return
  }

  // The first look only notes how things stand: the scan that opened the
  // review has just read them.
  if (repoMarked !== undefined && repoMarked.repo === repo && repoMarked.mark !== mark) {
    job ??= { isProject: false }
  }

  repoMarked = { repo, mark }
}

// Runs one scan with this handle. The pipeline itself is in scan.ts; what
// it reads and writes of the session goes through the ports made here.
const runScan = async ($: EngineInterface, taken: Job): Promise<void> => {
  const now = await read($, view)

  // Every change of what is compared starts a scan, so this is where the
  // review is kept for next time.
  void rememberReview($)

  // With no request under review, the branch checked out may have one open:
  // its comments are then read as a request's are.
  const requestTyped =
    (now.target ?? '') !== '' && (now.requestTyped ?? '') !== ''
      ? now.requestTyped
      : (now.target ?? '') === ''
        ? await findBranchRequest($, now.repo)
        : ''

  // A comparison with another worktree is with its files as they stand now:
  // they are read again, and the scan runs against that.
  let base = now.base

  if ((now.baseWorktree ?? '') !== '') {
    const taken = await git.snapshotWorktree(runOf($), now.baseWorktree)

    if (taken.hash !== '' && taken.hash !== base) {
      base = taken.hash
      await update($, view, (last): View => ({ ...last, base }))
    }
  }

  await scanRepo(
    {
      run: runOf($),
      servers: serverRun($),
      readFile: path => $.fs.read(path).catch(() => ''),
      readScan: () => read($, scan),
      writeScan: change => update($, scan, change),
      onListed: async () => {
        if (now.screen === 'file') {
          await loadSource($, now.repo, now.file, now.commit ?? '')
        }
      },
      readComments: typed => loadComments($, now.repo, typed),
      showStatus: text => {
        $.ui.status(text === '' ? undefined : text)
      },
      tellClaude: text =>
        $.session
          .append({ message: { type: 'user', content: [{ type: 'text', text }] } })
          .catch(() => undefined),
      // The file being read, where it is the side the checkers run over.
      openFile: async () => {
        const { screen, file, commit, target } = await read($, view)

        return screen === 'file' && (commit ?? '') === (target ?? '') ? file : ''
      },
      isOvertaken: () => job !== undefined,
    },
    {
      repo: now.repo,
      base,
      target: now.target ?? '',
      extra: now.extra ?? [],
      isBrowsing: now.isBrowsing ?? false,
      isTelling: now.isTelling ?? false,
      requestTyped,
      use: settings.checkers,
      marksNew: settings.marksNew,
    },
    taken,
  )
}

// Throws away the uncommitted changes in the given files, which cannot be
// undone, and scans again whatever happened.
const discardFiles = async (
  $: EngineInterface,
  repo: string,
  tracked: string[],
  staged: string[],
  untracked: string[],
): Promise<void> => {
  const refusal = await git.discard(runOf($), repo, tracked, staged, untracked)
  const count = tracked.length + staged.length + untracked.length

  $.ui.toast(
    refusal === '' ? `Discarded the changes in ${count} ${count === 1 ? 'file' : 'files'}` : refusal,
    { timeoutMs: refusal === '' ? 4000 : 10_000 },
  )
  await update($, view, last => ({ ...last, checked: [], isDiscarding: false }))
  job = { isProject: false }
}

// How the language-server bridge runs its commands: kept for the session, so
// the bridge's script is written once.
const serverRun = ($: EngineInterface): ServerRun => (servers ??= runOf($))

// Reads what the language server knows of a whole file, for the file screen:
// its outline (exact folds, the breadcrumb), what each name is (colours), the
// file's own lines (a server counts a tab as one column, the screen draws
// four), and, when they are switched on, its inlay hints. A file outside the
// folder under review, or of a kind no server reads, has none.
const loadInsight = async ($: EngineInterface, repo: string, path: string): Promise<void> => {
  if (path.startsWith('/') || !isServed(path)) {
    insight = undefined

    return
  }

  const run = serverRun($)

  insightFor = path

  const { isHinting } = await read($, view)
  const [raw, outline, semantic, hinted] = await Promise.all([
    $.fs.read(`${repo}/${path}`).catch(() => ''),
    lspOutline(run, repo, path),
    lspSemanticTokens(run, repo, path),
    (isHinting ?? false) ? lspInlayHints(run, repo, path, 1, 1_000_000) : undefined,
  ])
  const tokens = new Map<number, SemanticToken[]>()
  const hints = new Map<number, InlayHint[]>()

  for (const token of semantic.tokens) {
    tokens.set(token.line, [...(tokens.get(token.line) ?? []), token])
  }

  for (const hint of hinted?.hints ?? []) {
    hints.set(hint.line, [...(hints.get(hint.line) ?? []), hint])
  }

  insight = { path, raw: raw.split('\n'), items: outline.items, tokens, hints }

  if (insightFor === path) {
    insightFor = undefined
  }

  // The file screen reads the source's stamp: a new one redraws it.
  await update($, source, last => ({ ...last, stamp: last.stamp + 1 }))

  if ((isHinting ?? false) && (hinted?.hints.length ?? 0) === 0 && (hinted?.notes.length ?? 0) > 0) {
    $.ui.toast(hinted?.notes[0] ?? '', { timeoutMs: 6000 })
  }
}

// Shows a list of places (or anything with a place) on the list screen; one
// with nothing in it is said in a toast instead, with the server's reason
// (`notes`) where it gave one.
const showList = async (
  $: EngineInterface,
  { title, rows, prompt, commit }: Listing,
  notes: readonly string[],
): Promise<void> => {
  if (rows.length === 0) {
    $.ui.toast(notes[0] ?? `${title}: nothing found`, { timeoutMs: 6000 })

    return
  }

  await update($, listing, () => ({
    title,
    rows: rows.slice(0, LIST_ROWS),
    prompt,
    ...(commit === undefined ? {} : { commit }),
  }))
  // Back from the list returns to the screen it was asked for on.
  await update(
    $,
    view,
    (last): View => ({
      ...last,
      screen: 'list',
      listBack: last.screen === 'list' ? (last.listBack ?? 'file') : last.screen === 'tree' ? 'tree' : 'file',
    }),
  )
}

// Everywhere the looked-up name is used.
const listReferences = async ($: EngineInterface, repo: string, at: Lookup): Promise<void> => {
  const answer = await lspReferences(serverRun($), repo, at.file, at.at, at.col)

  await showList($, usesList(at.name, at.file, answer.places), answer.notes)
}

// Who calls the looked-up function, or what it calls.
const listCalls = async (
  $: EngineInterface,
  repo: string,
  at: Lookup,
  direction: 'incoming' | 'outgoing',
): Promise<void> => {
  const answer = await lspCalls(serverRun($), repo, at.file, at.at, at.col, direction)

  await showList($, callsList(at.name, direction, answer.calls), answer.notes)
}

// What implements the looked-up interface, abstract method or protocol.
const listImplementations = async ($: EngineInterface, repo: string, at: Lookup): Promise<void> => {
  const answer = await lspSymbol(serverRun($), repo, at.file, at.at, at.col)

  await showList(
    $,
    implementationsList(at.name, answer.implementations ?? []),
    answer.notes.length > 0 ? answer.notes : ['The language server knows of none'],
  )
}

// Names anywhere in the project that match what was typed. `near` is a file
// of the project to search: it decides the language and the project.
const searchSymbols = async (
  $: EngineInterface,
  repo: string,
  query: string,
  near: string,
): Promise<void> => {
  if (query.trim() === '') {
    return
  }

  if (near === '') {
    $.ui.toast('There is no Python or TypeScript file here to search from')

    return
  }

  const answer = await lspWorkspaceSymbols(serverRun($), repo, query.trim(), near, {
    limit: LIST_ROWS,
  })

  await showList($, namesList(query.trim(), answer.hits), answer.notes)
}

// Asks the language server what a name on a line of a file is, and keeps the
// answer for the file screen to show. The column is found on the file's own
// text: the screen draws a tab as spaces, which a server does not count.
const lookUp = async (
  $: EngineInterface,
  repo: string,
  file: string,
  line: number,
  name: string,
): Promise<void> => {
  const raw = await $.fs.read(`${repo}/${file}`).catch(() => '')
  const col = Math.max(0, (raw.split('\n')[line - 1] ?? '').indexOf(name)) + 1
  const answer = await lspSymbol(serverRun($), repo, file, line, col)

  if (answer.text === '' && answer.notes.length > 0) {
    $.ui.toast(answer.notes[0] ?? 'The language server did not answer', { timeoutMs: 8000 })

    return
  }

  await update($, view, last => ({ ...last, symbol: lookupOf(file, name, line, col, answer) }))
}

// Reads what a folder of the folder under review holds, for the breadcrumb's
// list: folders first (their names end with a slash), then files, git's own
// folder left out. `left` is the column the list opens under.
const loadCrumb = async (
  $: EngineInterface,
  repo: string,
  dir: string,
  left: number,
): Promise<void> => {
  const ran = await runOf($)(['ls', '-1Ap', '--', dir === '' ? '.' : dir], { cwd: repo })

  if (ran.exitCode !== 0) {
    $.ui.toast(`That folder could not be read: ${tail(ran.stderr)}`, { timeoutMs: 6000 })

    return
  }

  const names = ran.stdout.split('\n').filter(name => name !== '' && name !== '.git/')

  crumbCache = {
    dir,
    entries: [
      ...names.filter(name => name.endsWith('/')),
      ...names.filter(name => !name.endsWith('/')),
    ],
  }
  await update(
    $,
    view,
    (last): View => ({ ...last, crumb: { kind: 'dir', dir, level: 0, left, top: -1 } }),
  )
}

// Reads who last changed each line of a file (as a commit left it, or as the
// working tree has it) and keeps it for the file screen's blame column.
const loadBlame = async (
  $: EngineInterface,
  repo: string,
  path: string,
  commit: string,
): Promise<void> => {
  const answer = await git.blame(runOf($), repo, path, commit, () => $.clock.now())

  if ('refusal' in answer) {
    $.ui.toast(`git blame did not go through: ${answer.refusal}`, { timeoutMs: 8000 })

    return
  }

  blameCache = { path, commit, lines: answer.lines }
  await update($, view, last => ({ ...last, isBlame: true }))
}

// Asks before undoing the last commit, saying whether it has been pushed:
// one that has stays on the remote, and the branch here falls behind it.
const askUndo = async ($: EngineInterface, repo: string): Promise<void> => {
  const pushed = await git.remotesWithHead(runOf($), repo)

  await update($, view, last => ({
    ...last,
    isUndoing: true,
    undoNote:
      pushed.length === 0
        ? 'It has not been pushed, so nothing else has it.'
        : `It is already on ${pushed[0] ?? 'a remote'}: undoing it here leaves it there, and this branch behind it.`,
  }))
}

// Takes the last commit back and keeps what it changed, as uncommitted edits.
const undoCommit = async ($: EngineInterface, repo: string): Promise<void> => {
  await report(
    $,
    await git.undoLastCommit(runOf($), repo),
    'Undid the last commit; its changes are uncommitted again',
  )
  await update($, view, last => ({ ...last, isUndoing: false, selected: '' }))
}

// Adds text to the end of the person's draft, on its own line, and never
// submits it: sending stays theirs.
const sendToComposer = async ($: EngineInterface, text: string): Promise<void> => {
  const draft = await $.prompt.read().then(
    box => box.text,
    () => '',
  )
  const lead = draft === '' || draft.endsWith('\n') ? '' : '\n'
  const filled = await $.prompt.fill({ text: `${lead}${text}\n`, mode: 'append' })

  $.ui.toast(
    filled.isFilled
      ? 'Added to the prompt'
      : `Could not add to the prompt${filled.refusal === undefined ? '' : ` (${filled.refusal})`}`,
  )
}

// Says how a git command that changes the repo went: `done` on success, the
// command's `refusal` (git's own last words) where it has one. A success
// clears the ticks and scans again, since the working tree is no longer what
// the pane shows.
const report = async ($: EngineInterface, refusal: string, done: string): Promise<boolean> => {
  if (refusal !== '') {
    $.ui.toast(refusal, { timeoutMs: 10_000 })

    return false
  }

  $.ui.toast(done)
  await update($, view, last => ({ ...last, checked: [] }))
  job = { isProject: false }

  return true
}

// Commits the ticked files and nothing else.
const commitFiles = async (
  $: EngineInterface,
  repo: string,
  paths: readonly string[],
  message: string,
  body = '',
): Promise<void> => {
  if (message.trim() === '') {
    $.ui.toast('Type a commit message first')

    return
  }

  if (
    await report(
      $,
      await git.commit(runOf($), repo, paths, message, body),
      `Committed ${paths.length} ${paths.length === 1 ? 'file' : 'files'}`,
    )
  ) {
    draft = ''
    draftBody = ''
  }
}

// Stashes the ticked files, the untracked ones among them included.
const stashFiles = async (
  $: EngineInterface,
  repo: string,
  paths: readonly string[],
  message: string,
): Promise<void> => {
  const label = message.trim() || `${paths.length} ${paths.length === 1 ? 'file' : 'files'}`

  if (
    await report(
      $,
      await git.stash(runOf($), repo, paths, label),
      `Stashed ${paths.length} ${paths.length === 1 ? 'file' : 'files'}`,
    )
  ) {
    draft = ''
  }
}

const applyStash = async (
  $: EngineInterface,
  repo: string,
  ref: string,
  isPop: boolean,
): Promise<void> => {
  await report(
    $,
    await git.restoreStash(runOf($), repo, ref, isPop),
    isPop ? `Popped ${ref}` : `Applied ${ref}`,
  )
}

// How the forge module runs its commands: in the folder under review.
const forgeRun =
  (run: Run, repo: string): ForgeRun =>
  (argv, timeoutMs = 60_000, stdin) =>
    run(argv, { cwd: repo, timeoutMs, ...(stdin === undefined ? {} : { stdin }) })

// How long what the forge said of a branch's request is taken as still so.
const BRANCH_REQUEST_MS = 5 * 60_000

// Finds the open request of the branch checked out, asking the forge at most
// once in a while for the same branch; '' when it has none.
const findBranchRequest = async ($: EngineInterface, repo: string): Promise<string> => {
  const run = runOf($)
  const branch = (await run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], { cwd: repo })).stdout.trim()
  const at = await $.clock.now()

  if (
    branchRequest === undefined ||
    branchRequest.repo !== repo ||
    branchRequest.branch !== branch ||
    at - branchRequest.at > BRANCH_REQUEST_MS
  ) {
    const found = await requestOfBranch(forgeRun(run, repo), branch)

    branchRequest = {
      repo,
      branch,
      typed: found?.typed ?? '',
      label: found?.label ?? '',
      title: found?.title ?? '',
      baseRef: found?.baseRef ?? '',
      url: found?.url ?? '',
      at,
      base: '',
      files: [],
      stats: {},
    }
  }

  // The forge's word is kept a while; what the branch changes is git's to
  // say, and a commit made since changes it.
  if (branchRequest.typed !== '' && branchRequest.baseRef !== '') {
    Object.assign(branchRequest, await git.requestChanges(run, repo, branchRequest.baseRef))
  }

  return branchRequest.typed
}

// Asks the forge for the repo's open requests and has the compare panel,
// which is already open, drawn again with them.
// The overview of the request under review, as the forge gave it, or why it
// did not. Written by `loadOverview`, when the overview screen opens.
let overviewCache: { key: string; overview: Overview | undefined; refusal: string } | undefined
let overviewWanted: string | undefined
// Who is signed in to the forge for a repo, by the name comments carry: read
// once for each, by `loadMe`, so the person's own comments can be told.
let meCache: { repo: string; me: string } | undefined
let meWanted = ''

const loadMe = async ($: EngineInterface, repo: string): Promise<void> => {
  meWanted = repo
  meCache = { repo, me: await whoAmI(forgeRun(runOf($), repo)) }
  await update($, view, nudged)
}
// The action on a request the overview is asking about before it is done
// (of which request, and which), and whether one is under way.
// The request being opened from the list, as it is typed; '' for none.
let requestOpening = ''
// The request whose every commit the overview lists, by its key; '' for none.
let commitsOpen = ''
// The same for all of its conversation, and for every thread on its files.
let talkAll = ''
let threadsAll = ''
let requestAsked: { key: string; act: RequestAct | '' } = { key: '', act: '' }
let requestActing = false

// The pictures of descriptions, by their address: fetched (the file that
// holds each), being fetched, or not drawable. Held for the session, and
// held to a size: the oldest go when it is passed.
const pictureCache = new Map<string, Picture | 'loading' | 'none'>()
const PICTURES_KEPT = 200

// Lets the oldest pictures go once more are held than are kept.
const trimPictures = (): void => {
  if (pictureCache.size > PICTURES_KEPT) {
    for (const old of [...pictureCache.keys()].slice(0, pictureCache.size - PICTURES_KEPT)) {
      pictureCache.delete(old)
    }
  }
}

// How a request stands, in a few parts for a row of the file tree: its
// checks (the worst of them says how they stand), what its reviews come to,
// and whether it merges. Each part is the state that colours it, in the
// forge's own word, and the words to say.
const standingOf = (overview: Overview | undefined): [state: string, words: string][] => {
  if (overview === undefined) {
    return []
  }

  const marks = overview.checks.map(check => stateOf(check.state)[0])
  const failed = marks.filter(mark => mark === '✖').length
  const going = marks.filter(mark => mark === '●').length

  return [
    ...(overview.checks.length === 0
      ? [['NONE', 'no checks'] as [string, string]]
      : [
          failed > 0
            ? (['FAILURE', `${failed} of ${marks.length} checks fail`] as [string, string])
            : going > 0
              ? (['PENDING', `${going} of ${marks.length} checks running`] as [string, string])
              : (['SUCCESS', `${marks.length} ${marks.length === 1 ? 'check passes' : 'checks pass'}`] as [string, string]),
        ]),
    ...(overview.decision === ''
      ? []
      : [[overview.decision, overview.decision.toLowerCase().replace(/_/g, ' ')] as [string, string]]),
    ...(overview.mergeable === ''
      ? []
      : [[overview.mergeable, overview.mergeable.toLowerCase().replace(/_/g, ' ')] as [string, string]]),
  ]
}

const loadOverview = async ($: EngineInterface, repo: string, typed: string): Promise<void> => {
  const key = `${repo}\n${typed}`

  overviewWanted = key

  const answer = await readOverview(forgeRun(runOf($), repo), typed)

  if (overviewWanted === key) {
    overviewWanted = undefined
    overviewCache =
      'error' in answer
        ? { key, overview: undefined, refusal: plain(answer.error).slice(0, 300) }
        : { key, overview: answer.overview, refusal: '' }
    await update($, view, nudged)
  }
}

const loadRequests = async ($: EngineInterface, repo: string): Promise<void> => {
  const isPast = requestsPast
  const list = await listRequests(forgeRun(runOf($), repo), isPast)

  // An answer for the other list, asked for before the switch, is let go.
  if (isPast === requestsPast) {
    requestsCache = { repo, list }
  }
  await update($, view, nudged)
}

// Reads the whole comparison for the changes screen and has it drawn again.
const loadPatch = async (
  $: EngineInterface,
  repo: string,
  base: string,
  target: string,
  key: string,
  context: number,
  ignoresSpace: boolean,
): Promise<void> => {
  patchWanted = key

  // With the working tree's own changes, what the index holds is read
  // beside them, the same way, to say which hunks are staged.
  const [read, index] = await Promise.all([
    readPatch(runOf($), repo, base, target, { context, ignoresSpace }),
    target === '' && !ignoresSpace
      ? readPatch(runOf($), repo, base, '', { context, isStaged: true })
      : Promise.resolve({ files: [], refusal: '' }),
  ])

  // A comparison asked for since is the one that counts.
  if (patchWanted === key) {
    patchCache = {
      key,
      ...read,
      staged: new Set(index.files.flatMap(file => file.hunks.map(hunk => hunkMark(file, hunk)))),
    }
    patchWanted = undefined
    await update($, view, nudged)
  }
}

// Shows more of one file round its changes on the page of every change: the
// file is read again with more unchanged lines, and takes its place there.
const expandFile = async (
  $: EngineInterface,
  repo: string,
  base: string,
  target: string,
  key: string,
  path: string,
  ignoresSpace: boolean,
): Promise<void> => {
  const held = patchCache?.key === key ? patchCache : undefined
  const at = held?.files.findIndex(file => file.path === path) ?? -1

  if (held === undefined || at === -1) {
    return
  }

  const context = (pageMore.key === key ? (pageMore.by.get(path) ?? 0) : 0) + MORE_STEP

  if (pageMore.key !== key) {
    pageMore = { key, by: new Map() }
  }

  pageMore.by.set(path, context)

  const read = await readPatch(runOf($), repo, base, target, { context, ignoresSpace, paths: [path] })
  const [again] = read.files

  if (again !== undefined && patchCache === held) {
    held.files[at] = again
    await update($, view, nudged)
  }
}

// Highlights the files the changes screen has drawn and not yet coloured, a
// few at a time, drawing the page again as each few come in. A file is read
// as the comparison's new side has it: the target commit's, or the working
// tree's.
const colorPage = async (
  $: EngineInterface,
  key: string,
  repo: string,
  target: string,
  paths: readonly string[],
): Promise<void> => {
  if (pageColors.key !== key) {
    pageColors = { key, lines: new Map(), asked: new Set() }
  }

  const held = pageColors
  const wanted = paths.filter(path => !held.asked.has(path))

  for (const path of wanted) {
    held.asked.add(path)
  }

  const run = runOf($)

  for (let at = 0; at < wanted.length; at += COLORED_AT_ONCE) {
    await Promise.all(
      wanted.slice(at, at + COLORED_AT_ONCE).map(async path => {
        const { lines, note } = await readSource(
          run,
          file => $.fs.read(file).catch(() => ''),
          repo,
          path,
          undefined,
          target,
        )

        // Where the highlighter did not run there are no colours to add. It
        // may only have been slow to start (its first run, or a scan under
        // way beside it), so the file is asked for again a couple of times.
        if (note === '') {
          held.lines.set(path, lines)
        } else {
          const tries = (colorTries.get(`${key}\n${path}`) ?? 0) + 1

          colorTries.set(`${key}\n${path}`, tries)

          if (tries < COLOR_TRIES) {
            held.asked.delete(path)
          }
        }
      }),
    )

    if (pageColors === held) {
      await update($, view, nudged)
    }
  }
}

// The files ticked as reviewed, as the store keeps them between sessions.
const readReviewed = async ($: EngineInterface): Promise<Record<string, string[]>> => {
  const stored: unknown = await $.store.get('reviewed').catch(() => undefined)
  const kept: Record<string, string[]> = {}

  if (typeof stored === 'object' && stored !== null) {
    for (const [key, paths] of Object.entries(stored)) {
      if (Array.isArray(paths)) {
        kept[key] = paths
          .filter((path): path is string => typeof path === 'string')
          .slice(-REVIEWED_PATHS)
      }
    }
  }

  // What the store holds is held to the same limits as what is written.
  return Object.fromEntries(Object.entries(kept).slice(-REVIEWED_KEPT))
}

// The comments written for reviews and not sent yet, as the store keeps them
// between sessions: only what reads as a draft is taken.
const readDrafts = async ($: EngineInterface): Promise<View['drafts']> => {
  const stored: unknown = await $.store.get('drafts').catch(() => undefined)
  const kept: View['drafts'] = {}

  if (typeof stored === 'object' && stored !== null) {
    for (const [key, list] of Object.entries(stored).slice(-REVIEWED_KEPT)) {
      if (Array.isArray(list)) {
        kept[key] = list.flatMap((one: unknown): Draft[] => {
          const draft = (typeof one === 'object' && one !== null ? one : {}) as Record<string, unknown>

          return typeof draft.id === 'string' &&
            typeof draft.path === 'string' &&
            typeof draft.line === 'number' &&
            typeof draft.body === 'string'
            ? [
                {
                  id: draft.id,
                  path: draft.path,
                  line: draft.line,
                  body: draft.body,
                  ...(typeof draft.startLine === 'number' ? { startLine: draft.startLine } : {}),
                  ...(typeof draft.oldLine === 'number' ? { oldLine: draft.oldLine } : {}),
                },
              ]
            : []
        })
      }
    }
  }

  return kept
}

// Changes a request's drafts, here and in the store. A request left with
// none is dropped, and the oldest give way as the reviewed ticks do.
const changeDrafts = async (
  $: EngineInterface,
  key: string,
  change: (list: readonly Draft[]) => Draft[],
): Promise<void> => {
  await update($, view, (last): View => {
    const { [key]: held = [], ...rest } = last.drafts ?? {}
    const list = change(held).slice(-DRAFTS_KEPT)

    return {
      ...last,
      drafts: Object.fromEntries(
        [...Object.entries(rest), ...(list.length === 0 ? [] : [[key, list] as const])].slice(-REVIEWED_KEPT),
      ),
    }
  })
  await $.store.set('drafts', (await read($, view)).drafts ?? {}).catch(() => undefined)
}

// Ticks or unticks a file of a request as reviewed, here and in the store.
// The request last ticked is kept last, and the oldest give way.
// The request whose "viewed" marks the forge keeps, once they have been
// read: its id there, and the folder under review's place in the repo. An
// empty id is a forge that keeps none (the ticks are then the pane's own).
let viewedCache: { key: string; id: string; prefix: string } | undefined
let viewedWanted = ''

// Reads the files the person has marked as viewed on the forge, and makes
// them the request's ticks: the forge's word is the one that counts, since
// it is what the request's own page shows.
const loadViewed = async ($: EngineInterface, repo: string, typed: string, key: string): Promise<void> => {
  viewedWanted = key

  const run = forgeRun(runOf($), repo)
  const [seen, prefix] = await Promise.all([readViewed(run, typed), repoPrefix(run)])

  viewedCache = { key, id: seen?.id ?? '', prefix }

  if (seen !== undefined) {
    const paths = seen.viewed
      .filter(path => path.startsWith(prefix))
      .map(path => path.slice(prefix.length))
      .slice(-REVIEWED_PATHS)

    await update($, view, (last): View => {
      const { [key]: _held, ...rest } = last.reviewed ?? {}

      return {
        ...last,
        reviewed: Object.fromEntries([...Object.entries(rest), [key, paths]].slice(-REVIEWED_KEPT)),
      }
    })
    await $.store.set('reviewed', (await read($, view)).reviewed ?? {}).catch(() => undefined)
  }
}

const toggleReviewed = async ($: EngineInterface, key: string, path: string): Promise<void> => {
  await update($, view, (last): View => {
    const { [key]: held = [], ...rest } = last.reviewed ?? {}
    const paths = (
      held.includes(path) ? held.filter(one => one !== path) : [...held, path]
    ).slice(-REVIEWED_PATHS)

    return {
      ...last,
      reviewed: Object.fromEntries([...Object.entries(rest), [key, paths]].slice(-REVIEWED_KEPT)),
    }
  })
  await $.store.set('reviewed', (await read($, view)).reviewed ?? {}).catch(() => undefined)
}

// Marks several files of a request as reviewed, or as not, in one go.
const setReviewed = async (
  $: EngineInterface,
  key: string,
  paths: readonly string[],
  isOn: boolean,
): Promise<void> => {
  const named = new Set(paths)

  await update($, view, (last): View => {
    const { [key]: held = [], ...rest } = last.reviewed ?? {}
    const kept = held.filter(one => !named.has(one))

    return {
      ...last,
      reviewed: Object.fromEntries(
        [...Object.entries(rest), [key, (isOn ? [...kept, ...paths] : kept).slice(-REVIEWED_PATHS)]].slice(-REVIEWED_KEPT),
      ),
    }
  })
  await $.store.set('reviewed', (await read($, view)).reviewed ?? {}).catch(() => undefined)
}

// Starts a comparison between two things the person named: `side` is what is
// read (a branch or commit, or '' for the working tree) and `against` is what
// it is compared with. Each name is checked with git first, so a typo is said
// and nothing changes. Nothing is checked out: git diffs the two as they are.
const startCompare = async (
  $: EngineInterface,
  repo: string,
  side: string,
  against: string,
): Promise<void> => {
  const run = runOf($)
  const known = async (name: string): Promise<boolean> =>
    name === '' || (await git.isCommit(run, repo, name))
  let [from, to] = [side.trim(), against.trim()]
  let request = ''
  let typed = ''

  // A request is a comparison by itself (its head with where it forked from
  // its target), so it may be typed in either field, and what the other
  // field holds is set aside.
  const isRequest = async (name: string): Promise<boolean> =>
    name !== '' && parseRequest(name) !== undefined && !(await known(name))

  if (await isRequest(from)) {
    ;[from, to] = ['', from]
  } else if (await isRequest(to)) {
    from = ''
  } else if (from.startsWith('@')) {
    // A worktree, likewise, whichever field it was typed in.
    ;[from, to] = ['', from]
  }

  if (to === '') {
    $.ui.toast('Name a branch, a commit or a pull request to compare with')

    return
  }

  // "@name" is another worktree of the repo as its files stand, uncommitted
  // work and all: a commit is made of them (nothing of that worktree
  // changes) and compared with like any other. `beside` is its folder.
  let beside = ''

  if (to.startsWith('@')) {
    const name = to.slice(1)
    const other = ((await read($, scan)).worktrees ?? []).find(
      one => !one.isCurrent && one.path.split('/').pop() === name,
    )

    if (other === undefined) {
      $.ui.toast(`This repo has no other worktree called "${name}"`, { timeoutMs: 8000 })

      return
    }

    const taken = await git.snapshotWorktree(run, other.path)

    if (taken.hash === '') {
      $.ui.toast(`${name} could not be read as it stands: ${taken.refusal}`, { timeoutMs: 10_000 })

      return
    }

    beside = other.path
    to = taken.hash
  }

  // What is not a ref but reads as a pull or merge request (#12, !34, a
  // link) is looked up on the forge: its head is fetched under a ref of the
  // mod's own, and it is compared with where it forked from its target.
  if (from === '' && !(await known(to)) && parseRequest(to) !== undefined) {
    $.ui.toast(`Fetching ${to}…`)

    const answer = await resolveRequest(forgeRun(run, repo), to)

    if ('error' in answer) {
      $.ui.toast(answer.error, { timeoutMs: 10_000 })

      return
    }

    // What was typed is kept: the forge is asked about the request by it again,
    // for its comments and to post one.
    typed = to
    from = answer.side
    to = answer.against
    request = `${answer.label} → ${answer.target}${answer.title === '' ? '' : ` · ${answer.title}`}`
  }

  const unknown = !(await known(from)) ? from : !(await known(to)) ? to : undefined

  if (unknown !== undefined) {
    $.ui.toast(`"${unknown}" is not a branch or commit here`, { timeoutMs: 8000 })

    return
  }

  await update(
    $,
    view,
    (last): View => ({
      ...last,
      base: to,
      target: from,
      baseWorktree: beside,
      request,
      requestTyped: typed,
      isCommenting: false,
      commentLine: 0,
      screen: 'tree',
      isPicking: false,
      selected: '',
      commit: '',
      checked: [],
    }),
  )
  job = { isProject: false }
}

// Switches the repo to a branch, or to a commit with HEAD detached. Where
// git refuses, the person reads git's own reason.
const checkOut = async (
  $: EngineInterface,
  repo: string,
  target: string,
  isBranch: boolean,
): Promise<void> => {
  // A branch another worktree has checked out cannot be checked out here
  // too (git refuses); its worktree is where it is, so the review goes there.
  const held = isBranch
    ? ((await read($, scan)).worktrees ?? []).find(one => one.branch === target && !one.isCurrent)
    : undefined

  if (held !== undefined) {
    $.ui.toast(`${target} is checked out in the worktree ${held.path.split('/').pop() ?? ''}: reviewing it there`, {
      timeoutMs: 6000,
    })
    await openReview($, held.path, undefined)

    return
  }

  const refusal = await git.checkOut(runOf($), repo, target, isBranch)

  if (refusal !== '') {
    $.ui.toast(`Not checked out: ${refusal}`, { timeoutMs: 10_000 })

    return
  }

  $.ui.toast(isBranch ? `Checked out ${target}` : `Checked out ${target} (detached HEAD)`)
  // A checkout starts over: no comparison, just what is modified in the tree
  // now checked out, until the person picks a commit to compare with again.
  await update(
    $,
    view,
    (last): View => ({
      ...last,
      base: 'HEAD',
      target: '',
      baseWorktree: '',
      screen: 'tree',
      selected: '',
      commit: '',
    }),
  )
  job = { isProject: false }
}

// Reads the comments of the pull or merge request under review, and where in
// the repo the folder under review sits (a forge's paths are from the repo's
// root). Answers '' when it has them, else why not, in a sentence.
const loadComments = async ($: EngineInterface, repo: string, typed: string): Promise<string> => {
  const run = forgeRun(runOf($), repo)
  const [answer, prefix] = await Promise.all([fetchComments(run, typed), repoPrefix(run)])

  if ('error' in answer) {
    return answer.error
  }

  commentsCache = { key: `${repo}\n${typed}`, prefix, comments: answer.comments }

  return ''
}

// Posts one comment on a line of the request's head version of a file. It
// writes to the forge, so it runs only from the post button or Enter in the
// comment field, and says how it went.
const postReview = async (
  $: EngineInterface,
  repo: string,
  typed: string,
  target: string,
  path: string,
  line: number,
  body: string,
  // The first line, when the comment is on several (`line` is the last).
  from = 0,
  // The removed line it is on, by its number in the other side (`line` is
  // then 0); 0 for a comment on this side.
  old = 0,
): Promise<void> => {
  if (body.trim() === '') {
    $.ui.toast('Type the comment first')

    return
  }

  const run = forgeRun(runOf($), repo)
  // With no target, the request is the checked-out branch's: its head is HEAD.
  const [head, prefix] = await Promise.all([
    git.fullHash(runOf($), repo, target === '' ? 'HEAD' : target),
    repoPrefix(run),
  ])
  const answer = await postComment(
    run,
    typed,
    {
      path: `${prefix}${path}`,
      line,
      commit: head,
      ...(from > 0 && from < line ? { startLine: from } : {}),
      ...(old > 0 ? { oldLine: old } : {}),
    },
    unfold(body.trim()),
  )

  if ('error' in answer) {
    $.ui.toast(answer.error, { timeoutMs: 10_000 })

    return
  }

  if (commentsCache !== undefined && commentsCache.key === `${repo}\n${typed}`) {
    commentsCache.comments.push(answer.comment)
  }

  commentDraft = ''
  commentRound += 1
  $.ui.toast(line === 0 ? `Comment posted on ${path}` : `Comment posted on line ${line}`)
  await update($, view, last => ({ ...last, commentLine: 0, commentFrom: 0, commentOld: 0 }))
}

// Answers the thread whose first comment is `root`, on the forge.
const postReply = async (
  $: EngineInterface,
  repo: string,
  typed: string,
  root: Comment,
  body: string,
): Promise<void> => {
  if (isFinding(root)) {
    $.ui.toast('A ledger finding has no thread to answer: send it to the prompt instead')

    return
  }

  if (body.trim() === '') {
    $.ui.toast('Type the reply first')

    return
  }

  const answer = await replyComment(forgeRun(runOf($), repo), typed, root, unfold(body.trim()))

  if ('error' in answer) {
    $.ui.toast(answer.error, { timeoutMs: 10_000 })

    return
  }

  if (commentsCache !== undefined && commentsCache.key === `${repo}\n${typed}`) {
    // The forge's own path and line for a reply may be missing; it sits
    // where the thread does.
    commentsCache.comments.push({ ...answer.comment, path: root.path, line: root.line })
  }

  commentDraft = ''
  commentRound += 1
  $.ui.toast(`Replied to ${root.author}`)
  await update($, view, last => ({ ...last, commentLine: 0, commentFrom: 0, commentOld: 0, replyTo: '', editing: '' }))
}

// Marks the thread `root` starts as resolved, or open again, on the forge.
const settleThread = async (
  $: EngineInterface,
  repo: string,
  typed: string,
  root: Comment,
  isResolved: boolean,
): Promise<void> => {
  if (isFinding(root)) {
    $.ui.toast('A ledger finding is closed in the ledger, once it is fixed')

    return
  }

  const refusal = await resolveThread(forgeRun(runOf($), repo), typed, root.thread ?? '', isResolved)

  if (refusal !== '') {
    $.ui.toast(refusal, { timeoutMs: 10_000 })

    return
  }

  if (commentsCache !== undefined && commentsCache.key === `${repo}\n${typed}`) {
    for (const one of commentsCache.comments) {
      if (one.id === root.id || one.replyTo === root.id) {
        one.isResolved = isResolved
      }
    }
  }

  $.ui.toast(isResolved ? 'Thread resolved' : 'Thread reopened')
  // The file screen reads the source's stamp: a new one redraws it.
  await update($, source, last => ({ ...last, stamp: last.stamp + 1 }))
}

// Submits a review of the request under review, and says how it went.
// Posts a comment on the request as a whole. `quoted` is the comment it
// answers, which it then starts by quoting: neither forge threads these, so
// that is how an answer says what it is to.
const sendTalk = async (
  $: EngineInterface,
  repo: string,
  typed: string,
  quoted: Comment | undefined,
  body: string,
): Promise<void> => {
  if (body.trim() === '') {
    $.ui.toast('Type the comment first')

    return
  }

  const answer = await postGeneral(
    forgeRun(runOf($), repo),
    typed,
    `${quoted === undefined ? '' : quoteOf(quoted)}${unfold(body.trim())}`,
  )

  if ('error' in answer) {
    $.ui.toast(answer.error, { timeoutMs: 10_000 })

    return
  }

  if (commentsCache !== undefined && commentsCache.key === `${repo}\n${typed}`) {
    commentsCache.comments.push(answer.comment)
  }

  talkDraft = ''
  talkRound += 1
  $.ui.toast(quoted === undefined ? 'Comment posted' : `Replied to ${quoted.author}`)
  await update($, view, (last): View => ({ ...last, talkReply: '' }))
}

const sendReview = async (
  $: EngineInterface,
  repo: string,
  typed: string,
  verdict: 'approve' | 'request-changes' | 'comment',
  summary: string,
  // The request's head when it is not what is checked out ('' then).
  target = '',
): Promise<void> => {
  const run = forgeRun(runOf($), repo)
  const key = `${repo}\n${typed}`
  const drafts = (await read($, view)).drafts?.[key] ?? []
  // The comments written for the review go with it, on the request's head.
  const [commit, prefix] =
    drafts.length === 0
      ? ['', '']
      : await Promise.all([git.fullHash(runOf($), repo, target === '' ? 'HEAD' : target), repoPrefix(run)])
  const { refusal, sent } = await submitDrafted(run, typed, verdict, unfold(summary), { drafts, commit, prefix })

  // What reached the forge is no longer waiting, whether or not the rest did.
  if (sent.length > 0) {
    await changeDrafts($, key, list => list.filter(one => !sent.includes(one.id)))
  }

  if (refusal !== '') {
    $.ui.toast(refusal, { timeoutMs: 10_000 })

    return
  }

  reviewDraft = ''
  reviewRound += 1
  $.ui.toast(
    `${verdict === 'approve' ? 'Approved' : verdict === 'comment' ? 'Review sent' : 'Changes requested'}${sent.length === 0 ? '' : `, with ${sent.length} ${sent.length === 1 ? 'comment' : 'comments'}`}`,
  )
  await update($, view, last => ({ ...last, isReviewing: false }))
  // What was said shows among the request's comments on the next scan.
  job = { isProject: false }
}

// Loads the file the pane asked for, when the module does not hold its lines.
const loadWanted = async ($: EngineInterface, path: string): Promise<void> => {
  const { repo, commit } = await read($, view)

  if (repo !== '') {
    await loadSource($, repo, path, commit ?? '')
  }
}

// The files a commit changed, with their line counts, for the graph screen.
const loadCommit = async ($: EngineInterface, repo: string, hash: string): Promise<void> => {
  const details = await git.commitDetails(runOf($), repo, hash)

  await update($, picked, () => details)
}

export const register: Register = (on, options) => {
  settings = settingsOf(options)

  // What sessions leave on the machine is removed as one ends (not on a
  // /clear or a resume, where the process goes on): the exports of commits,
  // the refs requests were fetched under, the language servers' keeper.
  on('session.end', async ($, e, next) => {
    if (settings.cleansUp && e.reason !== 'clear' && e.reason !== 'resume') {
      const [{ repo }, list] = await Promise.all([read($, view), readRecents($)])

      await cleanUp(runOf($), [repo, ...list.map(one => one.repo)])
    }

    return next(e)
  })

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'lens',
      description: 'Review changed files with inline diagnostics: /lens [folder] [base ref]',
    })

    // A reload keeps the session's state but drops what the module held, so a
    // review already under way is scanned again with the code just loaded.
    if ((await read($, view)).repo !== '') {
      job = { isProject: false }
    }

    $.clock.every(400, () => {
      // A screen that draws its own window asked for the pane to be held one
      // row down (see `frame`): done here, once the screen has been drawn.
      if (wantPin) {
        wantPin = false
        void $.ui.scroll({ in: PANE, to: { key: 'pin' }, block: 'start' }).catch(() => undefined)
      }

      if (wanted !== undefined && !isLoading) {
        const path = wanted
        wanted = undefined
        isLoading = true
        void loadWanted($, path).finally(() => {
          isLoading = false
        })
      }

      // While a scan runs the busy mark turns: each step redraws its readers.
      if (isBusy) {
        void update($, spin, frame => (frame + 1) % SPINNER.length)
      }

      ticks += 1

      if (ticks % WATCH_TICKS === 0 && !isWatching) {
        isWatching = true
        void watchRepo($)
          .catch(() => undefined)
          .finally(() => {
            isWatching = false
          })
      }

      if (job === undefined || isBusy) {
        return
      }

      const taken = job
      job = undefined
      isBusy = true
      void runScan($, taken)
        .catch((error: unknown) =>
          update(
            $,
            scan,
            (last): Scan => ({
              ...last,
              status: 'done',
              pending: [],
              notes: [`The scan stopped on an error (${String(error)}). Press r to run it again`],
            }),
          ),
        )
        .finally(() => {
          isBusy = false
        })
    })

    return next(e)
  })

  on('command.run', { command: 'lens' }, async ($, e) => {
    const words = e.args.split(/\s+/).filter(word => word !== '')
    const isFolder = /^[~./]/.test(words[0] ?? '')
    const folder = isFolder ? (words[0] ?? '.') : '.'
    const base = isFolder ? words[1] : words[0]
    const isRecent = words[0] === 'recent' && words.length === 1
    // A folder git does not know is opened too, to list its files.
    const repo = isRecent
      ? ''
      : (await git.findRepo(runOf($), folder)) || (await git.findFolder(runOf($), folder))

    if (repo !== '') {
      return { text: await openReview($, repo, base) }
    }

    if (isFolder) {
      return {
        text: `/lens: ${folder} is not a folder. Check the path, or run /lens recent to pick a recent one.`,
      }
    }

    // Asked for the repos reviewed lately (/lens recent), or run where the
    // folder cannot be read: the pane opens on them, to pick one.
    const list = await readRecents($)

    await update($, recents, () => list)
    await update($, view, () => NO_VIEW)
    await $.ui.open({ id: PANE, title: 'Lens', focus: true })

    return {
      text:
        list.length === 0
          ? 'Nothing has been reviewed lately. Name a folder: /lens ~/Code/my-repo [base]'
          : 'Pick a recent one in the pane, or name a folder (/lens ~/Code/my-repo).',
    }
  })

  // The parked mod, where it is loaded, asks for a place to be shown (a file
  // reference pressed on one of its items): the pane opens on that file at
  // that line, reviewing the repository the file is in.
  on('state.set', { plugin: 'parked', key: 'jump' }, async ($, e, next) => {
    const written = await next(e)
    const asked = e.value

    if (asked !== null && asked !== undefined && asked.path !== '') {
      void showPlace($, asked.path, asked.line).catch(() => undefined)
    }

    return written
  })

  // The ledger mod asks the same way, for the place of a finding.
  on('state.set', { plugin: 'ledger', key: 'jump' }, async ($, e, next) => {
    const written = await next(e)
    const asked = e.value

    if (asked !== null && asked !== undefined && asked.path !== '') {
      void showPlace($, asked.path, asked.line).catch(() => undefined)
    }

    return written
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const ran = await next(e)
    await noteEdit($, e.file_path)

    return ran
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const ran = await next(e)
    await noteEdit($, e.file_path)

    return ran
  })

  // The file and graph screens draw their own window, so the person's wheel
  // and scroll keys move that window's first line and the engine's stays put.
  on('ui.scroll', async ($, e, next) => {
    // Lens's own pane, or the one that hosts it.
    if (e.requestId !== PANE && !(e.requestId === HOST && (await isGuest($)))) {
      return next(e)
    }

    const now = await read($, view)

    // How tall the drawing came out, in the engine's own count: what says
    // how much is below the window, in place of the estimate.
    paneMeasured = { content: e.contentRows, estimate: paneEstimate }

    // The screens as long as their lists are pages of the pane's own to scroll.
    if (
      e.origin.kind !== 'person' ||
      now.screen === 'tree' ||
      now.screen === 'list' ||
      now.screen === 'requests' ||
      now.screen === 'overview'
    ) {
      return next(e)
    }

    // The list of keys is a page of the pane's own to scroll.
    if (now.isHelp ?? false) {
      return next(e)
    }

    // A rendered markdown file is a page of the pane's own to scroll.
    if (
      now.screen === 'file' &&
      isMarkdownFile(now.file) &&
      (now.isPreview ?? true) &&
      !(now.isDiff ?? false)
    ) {
      return next(e)
    }

    // The page of every change draws its own window too: the wheel and the
    // scroll keys move its first row.
    if (now.screen === 'changes') {
      await update(
        $,
        view,
        (last): View => ({ ...last, pageTop: clamp((last.pageTop ?? 0) + e.by, 0, pageWindow.maxTop) }),
      )

      return {}
    }

    if (now.screen === 'graph') {
      // A tick with the pointer over the opened commit's body scrolls that
      // body; anywhere else, and from the keys, it scrolls the history.
      const { header, kinds, maxTop, bodyMax } = graphWindow
      const isOverBody =
        e.pointer !== undefined && kinds[e.pointer.row - header] === 'body' && bodyMax > 0

      await update($, view, last =>
        isOverBody
          ? { ...last, bodyTop: clamp((last.bodyTop ?? 0) + e.by, 0, bodyMax) }
          : { ...last, graphTop: clamp((last.graphTop ?? 0) + e.by, 0, maxTop) },
      )

      return {}
    }

    // A tick with the pointer over the breadcrumb's open list scrolls the list.
    const box = (now.crumb?.kind ?? 'none') === 'none' ? undefined : fileWindow.crumbBox

    if (
      box !== undefined &&
      e.pointer !== undefined &&
      e.pointer.row >= box.from &&
      e.pointer.row <= box.to
    ) {
      await update($, view, last => ({
        ...last,
        crumb: { ...(last.crumb ?? NO_CRUMB), top: clamp(box.top + e.by, 0, box.max) },
      }))

      return {}
    }

    await update($, view, last => ({
      ...last,
      // In the changes-only view the window steps among the lines that show.
      top: clamp(
        fileWindow.shown === undefined
          ? (last.top ?? 1) + e.by
          : stepShown(fileWindow.shown, last.top ?? 1, e.by),
        1,
        fileWindow.maxTop,
      ),
    }))

    return {}
  })

  // Builds the model and the actions of the screen the person is on, and has
  // that screen draw them. A model is plain data read here; an action is a
  // closure over this drawing's handle. Nothing here writes state: the
  // actions do, when they are pressed.
  on('ui.render', { component: 'Pane' }, async ($, raw, next) => {
    const isHosted = raw.requestId === HOST && (await isGuest($))

    if (raw.requestId !== PANE && !isHosted) {
      return next(raw)
    }

    // Hosted, the pane's first rows are the host's, and the window is that
    // much shorter.
    const above = isHosted ? await next(raw) : undefined
    const e = isHosted
      ? {
          ...raw,
          props: {
            ...raw.props,
            scroll: { ...raw.props.scroll, bodyRows: Math.max(4, raw.props.scroll.bodyRows - HOST_ROWS) },
          },
        }
      : raw
    const tree = await (async () => {
    const kit = kitOf($.ui.resolve(e))
    const { Text } = kit
    const now = settledView(await read($, view))
    const stored = await read($, scan)
    const found = settledScan(stored)

    if (now.repo === '') {
      return frame(
        kit,
        false,
        settings.sidePadding,
        recentsScreen(
          kit,
          { recents: await read($, recents), now: await $.clock.now() },
          {
            open: one => void openReview($, one.repo, undefined),
            forget: one => void forgetReview($, one.repo),
          },
        ),
      )
    }

    const { repo, target } = now
    const history = historyOf(repo)
    const compared = comparisonOf(now, found, history)
    const { isComparing } = compared
    // The request whose comments show: the one under review, or else the
    // open request of the branch checked out.
    const ofBranch =
      target === '' && branchRequest?.repo === repo && branchRequest.branch === found.head
        ? branchRequest
        : undefined
    const requestTyped = compared.requestTyped || (ofBranch?.typed ?? '')
    const requestLabel = (compared.request.split(' → ')[0] ?? '') || (ofBranch?.label ?? '')
    // The request's comments, as the forge has them, on the files of the
    // folder under review: a forge's paths are from the repo's root, the
    // pane's from that folder. A comment on the request as a whole keeps its
    // empty path.
    const reviewed =
      requestTyped !== '' && commentsCache?.key === `${repo}\n${requestTyped}`
        ? commentsCache
        : undefined
    const requestComments = (reviewed?.comments ?? [])
      .flatMap(one =>
        one.path === ''
          ? [one]
          : one.path.startsWith(reviewed?.prefix ?? '')
            ? [{ ...one, path: one.path.slice((reviewed?.prefix ?? '').length) }]
            : [],
      )
      // What other people wrote is drawn as plain text: nothing in it that
      // a terminal would act on reaches the pane.
      .map(one => ({ ...one, author: plain(one.author), body: plainBlock(one.body) }))
    // The ledger mod's review findings, where it is loaded and has a run, join
    // them: each shows on its line as a thread does. Reading the run here
    // draws the pane again when it changes.
    const ledgerRun = await $.state.get(LEDGER_RUN).then(
      got => got.value,
      () => undefined,
    )
    const sessionRoot = await $.session.cwd().catch(() => '')
    // With a request under review, who the person is on the forge is asked
    // once, to tell their own comments by.
    if (requestTyped !== '' && meCache?.repo !== repo && meWanted !== repo) {
      void loadMe($, repo)
    }

    // And what the request says of itself is read once, for the file tree
    // to show its title and the first lines of its description.
    const aboutKey = `${repo}\n${requestTyped}`
    const aboutRequest = requestTyped !== '' && overviewCache?.key === aboutKey ? overviewCache : undefined

    if (requestTyped !== '' && aboutRequest === undefined && overviewWanted !== aboutKey) {
      void loadOverview($, repo, requestTyped)
    }

    // The comments written for the review and not sent yet are drawn where
    // they will sit, as comments of their own kind.
    const drafts = requestTyped === '' ? [] : (now.drafts[`${repo}\n${requestTyped}`] ?? [])
    const comments = [
      ...requestComments,
      ...drafts.map(draftComment),
      ...findingComments(
        ledgerRun,
        repo,
        sessionRoot,
        found.files.map(one => one.path),
      ),
    ]
    // The comparison border takes a cell on each side, which the screens that
    // size their own window leave out of their width and height.
    const inset = isComparing ? 2 : 0
    // While a scan runs: a mark that turns. Reading its frame subscribes the
    // drawing only then, so an idle pane stays still.
    const busyMark =
      found.status === 'running' ? (SPINNER[(await read($, spin)) % SPINNER.length] ?? '') : ''
    const inChanged = changedDiags(found)

    // A scan from before the line counts and graph existed has neither: ask
    // for a fresh one, which the timer picks up.
    if (stored.stats === undefined && found.status !== 'running') {
      job ??= { isProject: false }
    }

    const shell: Shell = {
      columns: (e.props.bodyColumns ?? 80) - inset - 2 * settings.sidePadding,
      rows: (e.props.scroll?.bodyRows ?? e.viewport?.rows ?? 30) - inset - TOP_MARGIN,
      inset,
      padding: settings.sidePadding,
      repoName: repo.split('/').pop() ?? '',
      isPlain: found.isPlain,
      // git lists the main checkout first; any other is a worktree of it.
      worktreeOf:
        found.worktrees.length > 1 && found.worktrees[0]?.isCurrent === false
          ? (found.worktrees[0].path.split('/').pop() ?? '')
          : '',
      headName: compared.headName,
      side: compared.side,
      against: compared.against,
      request: compared.request,
      reviewing: requestLabel,
      isComparing,
      isScanning: found.status === 'running',
      busyMark,
      pending: found.pending,
      checked: found.checked,
      toCheck: found.toCheck,
      // Shown while the language server reads the open file: its colours,
      // outline and hints come after the file itself.
      working:
        now.screen === 'file' && insightFor === now.file && now.commit === ''
          ? 'language server reading this file…'
          : '',
      isProjectChecked: found.isProjectChecked,
      notes: found.notes,
      totals: totalsOf(found, inChanged),
    }
    // A screen that draws its own window (`isOwn`) needs the pane held one
    // row down (see `frame`): asked for here, done by the timer once the
    // screen has been drawn.
    //
    // Where there is more below the window than it shows, a mark says so on
    // its last row. A screen that draws its own window says how many rows it
    // has left (`left`); for the rest it is worked out from the drawing, and
    // from the engine's own count once the person has scrolled.
    const framed = (screen: RenderChildren, isOwn = false, color?: string, left = 0) => {
      if (isOwn) {
        wantPin = (e.props.scroll?.offset ?? 1) !== 1
      }

      const tree = frame(kit, isComparing, settings.sidePadding, screen, isOwn, color)
      const scroll = e.props.scroll

      if (scroll === undefined) {
        return tree
      }

      if (isOwn) {
        return moreBelow(kit, tree, scroll.offset + scroll.bodyRows - 1, left > 0 ? `▼ ${left} more below` : '')
      }

      paneEstimate = rowsOf(tree as never, e.props.bodyColumns ?? 80)

      const { below, isExact } = rowsBelow(paneEstimate, { offset: scroll.offset, rows: scroll.bodyRows }, paneMeasured)

      return moreBelow(
        kit,
        tree,
        scroll.offset + scroll.bodyRows - 1,
        below <= 0 ? '' : isExact ? `▼ ${below} more below` : '▼ more below',
      )
    }

    // What several screens' actions are made of.
    const set = (change: (last: View) => View): void => void update($, view, change)
    const rescan = (): void => {
      job = { isProject: false }
    }
    const help = (): void => set(last => ({ ...last, isHelp: true }))

      // A request has been pressed: its page is drawn at once, as it is
      // while the forge is asked about it, so the bars that stand for it do
      // not change shape when the request has been opened and is being read.
      if (requestOpening !== '') {
        const still = (): void => undefined

        return framed(
          overviewScreen(
            kit,
            {
              shell,
              label: `${requestOpening.startsWith('!') ? 'MR' : 'PR'} ${requestOpening}`,
              overview: undefined,
              refusal: '',
              pictures: pictureCache,
              now: await $.clock.now(),
              asking: '',
              isActing: false,
              isCommitsOpen: false,
              comments: [],
              canTalk: false,
              talkOpen: '',
              talkReply: '',
              talkRound,
              isTalkAll: false,
              isThreadsAll: false,
            },
            { back: still, refresh: still, sinceReview: still, openFiles: still, openChanges: still, ask: still, act: still, toggleCommits: still, toggleTalkAll: still, toggleThreadsAll: still, openThread: still, openTalk: still, writeTalk: still, typeTalk: still, postTalk: still, help: still },
          ),
        )
      }
    if (now.isHelp) {
      return framed(
        helpScreen(kit, shell, now.screen, {
          close: () => set(last => ({ ...last, isHelp: false })),
        }),
      )
    }

    // Opens a file of the working tree at a line: a definition, a use, an
    // outline entry. A library's file is read from where it is installed,
    // outside what git tracks.
    const openAt = async (path: string, line: number): Promise<void> => {
      await loadSource($, repo, path)
      await update(
        $,
        view,
        (last): View => ({
          ...last,
          screen: 'file',
          file: path,
          commit: '',
          origin: 'tree',
          top: Math.max(1, line - 3),
          cursor: -1,
          isDiff: false,
          isPreview: false,
          symbol: NO_SYMBOL,
          crumb: NO_CRUMB,
        }),
      )
    }

    // Opens a file as a commit left it, at a line, on its diff.
    const openCommitAt = async (id: string, path: string, line: number): Promise<void> => {
      await loadSource($, repo, path, id)
      await update(
        $,
        view,
        (last): View => ({
          ...last,
          screen: 'file',
          file: path,
          commit: id,
          origin: 'tree',
          top: Math.max(1, line - 3),
          cursor: -1,
          isDiff: true,
          isPreview: false,
        }),
      )
    }
    // Every thread of the request under review, on the list screen.
    const listThreads = (): void =>
      void showList(
        $,
        { ...threadsList(requestLabel, comments), commit: target },
        ['This request has no review comments yet'],
      )

    if (now.screen === 'list') {
      const shown = await read($, listing)

      return framed(
        listScreen(kit, shell, shown, {
          back: () => set((last): View => ({ ...last, screen: last.listBack ?? 'file' })),
          sendList: () => void sendToComposer($, shown.prompt),
          // A request's threads sit on its head commit; anything else is a
          // place in the working tree.
          open: (path, line) =>
            void ((shown.commit ?? '') === ''
              ? openAt(path, line)
              : openCommitAt(shown.commit ?? '', path, line)),
          help,
        }),
      )
    }

    // The files of the request under review ticked as reviewed, and the
    // name they are kept under; '' with no request, when nothing is ticked.
    const seenKey = requestTyped === '' ? '' : `${repo}\n${requestTyped}`
    const seen = seenKey === '' ? [] : (now.reviewed[seenKey] ?? [])
    // Where the forge keeps "viewed" marks of its own (GitHub), they are
    // read once for the request and are what the ticks start as; a tick
    // made here is then made there too.
    if (seenKey !== '' && viewedCache?.key !== seenKey && viewedWanted !== seenKey) {
      void loadViewed($, repo, requestTyped, seenKey)
    }

    const markReviewed = (path: string): void => {
      if (seenKey === '') {
        return
      }

      const held = viewedCache?.key === seenKey ? viewedCache : undefined
      const isNowViewed = !seen.includes(path)

      void toggleReviewed($, seenKey, path)

      if (held !== undefined && held.id !== '') {
        void markViewed(forgeRun(runOf($), repo), requestTyped, held.id, `${held.prefix}${path}`, isNowViewed).then(
          refusal => {
            if (refusal !== '') {
              $.ui.toast(`Ticked here, but not on the forge: ${refusal}`, { timeoutMs: 8000 })
            }
          },
        )
      }
    }

    // A folder's tick: every file under it is marked, or every one unmarked,
    // here at once and on the forge one after another, with one word said
    // if the forge refused any.
    const markReviewedAll = (paths: readonly string[], isOn: boolean): void => {
      const todo = paths.filter(path => seen.includes(path) !== isOn)

      if (seenKey === '' || todo.length === 0) {
        return
      }

      const held = viewedCache?.key === seenKey ? viewedCache : undefined

      void (async () => {
        await setReviewed($, seenKey, todo, isOn)

        let refused = ''

        for (const path of held !== undefined && held.id !== '' ? todo : []) {
          refused ||= await markViewed(forgeRun(runOf($), repo), requestTyped, held?.id ?? '', `${held?.prefix ?? ''}${path}`, isOn)
        }

        if (refused !== '') {
          $.ui.toast(`Ticked here, but not all on the forge: ${refused}`, { timeoutMs: 8000 })
        }
      })()
    }

    // What the conversation of a request does, wherever it is drawn: the file
    // tree, and the request's own page.
    const talkActions = {
      openTalk: (id: string): void => set((last): View => ({ ...last, talkOpen: id })),
      writeTalk: (id: string): void => {
        talkDraft = ''
        talkRound += 1
        set((last): View => ({ ...last, talkReply: id }))
      },
      typeTalk: (text: string): void => {
        talkDraft = text
      },
      postTalk: (entered?: string): void =>
        void sendTalk(
          $,
          repo,
          requestTyped,
          comments.find(one => one.id === now.talkReply && one.path === ''),
          entered ?? talkDraft,
        ),
    }

    if (now.screen === 'overview') {
      const key = `${repo}\n${requestTyped}`
      const held = overviewCache?.key === key ? overviewCache : undefined

      if (held === undefined && overviewWanted !== key && requestTyped !== '') {
        void loadOverview($, repo, requestTyped)
      }

      // The description's first pictures are fetched once each, from the
      // forge's own hosts alone, and drawn when they have come.
      const forge = hostOf(held?.overview?.url ?? '')
      const wantedPictures = mediaOf(held?.overview?.body ?? '')
        .filter(one => one.kind === 'image' && isFetched(one.url, forge))
        .slice(0, PICTURES_SHOWN)
        .filter(one => !pictureCache.has(one.url))

      for (const one of wantedPictures) {
        trimPictures()
        pictureCache.set(one.url, 'loading')
        void fetchPicture(runOf($), one.url, forge).then(picture => {
          pictureCache.set(one.url, picture ?? 'none')

          return update($, view, nudged)
        })
      }

      return framed(
        overviewScreen(
          kit,
          {
            shell,
            label: requestLabel,
            overview: held?.overview,
            refusal: requestTyped === '' ? 'No request is under review' : (held?.refusal ?? ''),
            pictures: pictureCache,
            now: await $.clock.now(),
            asking: requestAsked.key === key ? requestAsked.act : '',
            isActing: requestActing,
            isCommitsOpen: commitsOpen === key,
            comments,
            canTalk: requestLabel !== '',
            talkOpen: now.talkOpen,
            talkReply: now.talkReply,
            talkRound,
            isTalkAll: talkAll === key,
            isThreadsAll: threadsAll === key,
          },
          {
            // Back goes where the overview was opened from: the list of requests, or the file tree.
            back: () => {
              if (now.overviewFrom === 'requests' && requestsCache?.repo !== repo) {
                void loadRequests($, repo)
              }

              // Back to the list is out of the request altogether: the
              // comparison it was read as ends with it, so the list (and
              // the tree behind it) is the working tree's again.
              if (now.overviewFrom === 'requests') {
                rescan()
              }

              // Leaving the request's page this way, the tree is nobody's
              // next step: it has nothing behind it to go back to.
              set(
                (last): View => ({
                  ...last,
                  screen: last.overviewFrom === 'requests' ? 'requests' : 'tree',
                  codeFrom: 'tree',
                  ...(last.overviewFrom === 'requests' ? { base: 'HEAD', target: '', baseWorktree: '' } : {}),
                }),
              )
            },
            ...talkActions,
            toggleTalkAll: () => {
              talkAll = talkAll === key ? '' : key
              set(nudged)
            },
            toggleThreadsAll: () => {
              threadsAll = threadsAll === key ? '' : key
              set(nudged)
            },
            // A thread opens its file where it is: the request's own version
            // of it, or the working tree's where the request is the branch's.
            openThread: (path, line) =>
              void (target === '' ? openAt(path, line) : openCommitAt(target, path, line)).then(() =>
                update($, view, (last): View => ({ ...last, origin: 'overview' })),
              ),
            toggleCommits: () => {
              commitsOpen = commitsOpen === key ? '' : key
              set(nudged)
            },
            // On to the code: the files it changes, or every change on one page.
            openFiles: () => set((last): View => ({ ...last, screen: 'tree', codeFrom: 'overview' })),
            openChanges: () => {
              patchCache = undefined
              pageColors = { key: '', lines: new Map(), asked: new Set() }
              set((last): View => ({ ...last, screen: 'changes', pageTop: 0, codeFrom: 'overview' }))
            },
            refresh: () => {
              overviewCache = undefined
              set(nudged)
            },
            ask: act => {
              requestAsked = { key, act }
              set(nudged)
            },
            // Done only from the question's own yes: the action must be the
            // one asked about, of this request.
            act: act => {
              if (requestAsked.key !== key || requestAsked.act !== act || requestActing) {
                return
              }

              requestAsked = { key: '', act: '' }
              requestActing = true
              set(nudged)
              void actOnRequest(forgeRun(runOf($), repo), requestTyped, act)
                .then(refusal => {
                  $.ui.toast(
                    refusal !== ''
                      ? refusal
                      : `${requestLabel}: ${act === 'checkout' ? 'checked out' : act === 'ready' ? 'marked ready' : act === 'close' ? 'closed' : 'merged'}`,
                    { timeoutMs: refusal === '' ? 5000 : 12_000 },
                  )
                })
                .finally(() => {
                  requestActing = false
                  // What the forge and the working tree say now is read again.
                  overviewCache = undefined
                  job = { isProject: false }
                  void update($, view, nudged)
                })
            },
            // What has come in since the person last reviewed it: the
            // request's head against the commit that review was of.
            sinceReview: () => {
              const from = held?.overview?.lastReviewed ?? ''

              if (from === '') {
                $.ui.toast('You have not reviewed this request yet')
              } else if (target === '') {
                $.ui.toast('Open the request from the requests list (p) first, then compare')
              } else {
                void startCompare($, repo, target, from)
              }
            },
            help,
          },
        ),
      )
    }

    if (now.screen === 'requests') {
      const prefix = `${repo}\n`


      return framed(
        requestsScreen(
          kit,
          {
            shell,
            list: requestsCache?.repo === repo ? requestsCache.list : undefined,
            current: requestTyped,
            isPast: requestsPast,
            reviewed: Object.fromEntries(
              Object.entries(now.reviewed)
                .filter(([key]) => key.startsWith(prefix))
                .map(([key, paths]) => [key.slice(prefix.length), paths.length]),
            ),
            now: await $.clock.now(),
          },
          {
            back: () => set((last): View => ({ ...last, screen: 'tree', codeFrom: 'tree' })),
            refresh: () => {
              requestsCache = undefined
              void loadRequests($, repo)
              set(nudged)
            },
            // Between the open requests and those that are over.
            togglePast: () => {
              requestsPast = !requestsPast
              requestsCache = undefined
              void loadRequests($, repo)
              set(nudged)
            },
            // A request is a comparison by itself: its head against where it
            // forked, which the file tree then lists.
            //
            // Opened from the list, a request is first shown as what it is
            // (its title, what it says of itself, where it stands): the
            // overview, from which its files and its changes are a key
            // away. Where the request could not be opened, the list stays.
            //
            // One is opened at a time: the list gives way to the shape of
            // the page that is coming as soon as one is pressed, so there is
            // nothing left to press twice, and a press that does arrive
            // while one is being opened is dropped.
            open: typed => {
              if (requestOpening !== '') {
                return
              }

              requestOpening = typed
              // What was read of it before is let go now, so it is asked
              // for once, while it opens, and its page is not emptied again
              // after it has been filled.
              overviewCache = undefined
              set(nudged)
              void startCompare($, repo, '', typed)
                .then(async () => {
                  if ((await read($, view)).requestTyped === typed) {
                    await update($, view, (last): View => ({ ...last, screen: 'overview', overviewFrom: 'requests' }))
                  }
                })
                .finally(() => {
                  requestOpening = ''

                  return update($, view, nudged)
                })
            },
            help,
          },
        ),
      )
    }

    if (now.screen === 'changes') {
      // The branch's own request, with no comparison on, is read as the
      // request has it: from where the branch forked, to the files as they
      // stand.
      const isOfBranch = !isComparing && ofBranch !== undefined && ofBranch.base !== ''
      const pageBase = isOfBranch ? ofBranch.base : now.base
      const pageKey = `${repo}\n${pageBase}\n${target}\n${now.pageContext}\n${now.pageSpace}`
      const page = patchCache?.key === pageKey ? patchCache : undefined

      if (page === undefined && patchWanted !== pageKey) {
        void loadPatch($, repo, pageBase, target, pageKey, now.pageContext, now.pageSpace)
      }

      // A change is staged or undone a hunk at a time only where the page is
      // of the working tree against what is checked out, spaces and all: a
      // hunk read any other way is not one git takes back.
      const canStage =
        target === '' && !isComparing && !isOfBranch && !found.isPlain && !now.pageSpace && now.base === 'HEAD'

      const drawn = changesScreen(
          kit,
          {
            shell,
            top: now.pageTop,
            context: now.pageContext,
            ignoresSpace: now.pageSpace,
            colors: pageColors.key === pageKey ? pageColors.lines : new Map(),
            title: isOfBranch
              ? `${requestLabel}: your branch as it stands`
              : shell.request !== ''
                ? shell.request
                : isComparing
                  ? `${shell.side} vs ${shell.against}`
                  : 'Uncommitted changes',
            files: page?.files,
            refusal: page?.refusal ?? '',
            statusOf: new Map(
              [...(ofBranch?.files ?? []), ...found.files].map(one => [one.path, one.status]),
            ),
            comments: comments.filter(one => !(now.hidesResolved && one.isResolved === true)),
            canMark: seenKey !== '',
            reviewed: seen,
            untracked: found.files.filter(one => one.status === '?').length,
            isSplit: now.pageSplit,
            isFinding: now.pageFinding,
            find: now.pageFind,
            canStage,
            staged: page?.staged ?? new Set<string>(),
            asking: hunkAsked,
            isCommitting: now.pageCommitting && canStage,
          },
          {
            back: () => set((last): View => ({ ...last, screen: last.codeFrom === 'overview' ? 'overview' : 'tree' })),
            refresh: () => {
              rescan()
              patchCache = undefined
              pageColors = { key: '', lines: new Map(), asked: new Set() }
              set(nudged)
            },
            // A file opens as the comparison has it, and back returns here.
            open: (path, line) =>
              void (target === '' ? openAt(path, line) : openCommitAt(target, path, line)).then(() =>
                update($, view, (last): View => ({ ...last, origin: 'changes' })),
              ),
            toggleReviewed: markReviewed,
            scrollTo: row => set((last): View => ({ ...last, pageTop: row })),
            say: text => $.ui.toast(text),
            // More lines round each change, step by step and back round;
            // and lines that differ only in their spaces, left out or not.
            moreContext: () =>
              set((last): View => {
                const at = CONTEXTS.findIndex(step => step === (last.pageContext ?? CONTEXT))

                return { ...last, pageContext: CONTEXTS[(at + 1) % CONTEXTS.length] ?? CONTEXT }
              }),
            toggleSpace: () => set((last): View => ({ ...last, pageSpace: !(last.pageSpace ?? false) })),
            toggleSplit: () => set((last): View => ({ ...last, pageSplit: !(last.pageSplit ?? false) })),
            expand: path => void expandFile($, repo, pageBase, target, pageKey, path, now.pageSpace),
            toggleFind: () =>
              set((last): View => ({ ...last, pageFinding: !(last.pageFinding ?? false), pageFind: '' })),
            setFind: text => set((last): View => ({ ...last, pageFind: text.trim().slice(0, 200) })),
            ask: name => {
              hunkAsked = name
              set(nudged)
            },
            // A hunk is handed back to git as git wrote it: into the index,
            // out of it, or undone in the file. Undoing is done only from
            // its own question's yes.
            hunk: (path, index, how, mark) => {
              const file = page?.files.find(one => one.path === path)
              const hunk = file?.hunks[index]

              if (!canStage || file === undefined || hunk === undefined) {
                return
              }

              // The hunk acted on is the one whose button was pressed: where
              // the page has been read again since and that place holds
              // another, nothing is done.
              if (hunkMark(file, hunk) !== mark) {
                $.ui.toast('That change has moved since it was drawn: look again, then press')

                return
              }

              // And an undoing is of the very hunk that was asked about.
              if (how === 'discard' && hunkAsked !== mark) {
                return
              }

              hunkAsked = ''
              void applyHunk(runOf($), repo, file, hunk, how).then(refusal => {
                $.ui.toast(
                  refusal !== ''
                    ? `git did not ${how} it: ${refusal}`
                    : how === 'discard'
                      ? `That change is undone in ${path}`
                      : how === 'stage'
                        ? 'Staged'
                        : 'Taken back out of what is staged',
                  { timeoutMs: refusal === '' ? 3000 : 10_000 },
                )
                // The page is read again where it stands.
                patchCache = undefined
                pageMore = { key: '', by: new Map() }
                rescan()
                void update($, view, nudged)
              })
            },
            toggleCommit: () =>
              set((last): View => ({ ...last, pageCommitting: !(last.pageCommitting ?? false) })),
            // What is staged is committed as it is: no file is named, so
            // nothing but the index goes into the commit.
            commitStaged: message => {
              if (message.trim() === '') {
                $.ui.toast('Type what changed first')

                return
              }

              void runOf($)(['git', 'commit', '-m', unfold(message.trim())], { cwd: repo, timeoutMs: 60_000 }).then(
                done => {
                  $.ui.toast(
                    done.exitCode === 0
                      ? 'Committed what was staged'
                      : `git did not commit: ${(done.stderr || done.stdout).trim().split('\n').pop() ?? ''}`,
                    { timeoutMs: done.exitCode === 0 ? 4000 : 10_000 },
                  )

                  if (done.exitCode === 0) {
                    patchCache = undefined
                    rescan()
                    void update($, view, (last): View => ({ ...nudged(last), pageCommitting: false }))
                  }
                },
              )
            },
            help,
          },
        )

      pageWindow = drawn.window

      // The files in and just under the window are highlighted, where they
      // have not been.
      if (
        page !== undefined &&
        drawn.shown.some(path => pageColors.key !== pageKey || !pageColors.asked.has(path))
      ) {
        void colorPage($, pageKey, repo, target, drawn.shown)
      }

      return framed(drawn.tree, true, undefined, Math.max(0, drawn.window.maxTop - (now.pageTop ?? 0)))
    }

    // What the graph and the file tree both offer: a commit or a stash
    // opened under its row, a file of it opened as it left it, and a stash
    // brought back.
    const chosen = settledPicked(await read($, picked))
    const openCommitFile = async (id: string, path: string): Promise<void> => {
      await loadSource($, repo, path, id)
      await update(
        $,
        view,
        (last): View => ({
          ...last,
          screen: 'file',
          file: path,
          commit: id,
          // Where back returns to: the screen the file was opened from.
          origin: last.screen === 'tree' ? 'tree' : 'graph',
          top: 1,
          cursor: -1,
          isDiff: true,
        }),
      )
    }
    const pick = (id: string): void => {
      if (now.selected !== id) {
        void loadCommit($, repo, id)
      }

      set(last => ({
        ...last,
        selected: last.selected === id ? '' : id,
        bodyTop: 0,
      }))
    }

    if (now.screen === 'graph') {
      const drawn = graphScreen(
        kit,
        {
          shell,
          rows: history,
          stashes: found.stashes,
          worktrees: found.worktrees,
          requests: requestsCache?.repo === repo ? requestsCache.list : [],
          branches: found.branches,
          head: found.head,
          headHash: found.headHash,
          base: now.base,
          hasTarget: target !== '',
          selected: now.selected,
          picked: chosen,
          bodyTop: now.bodyTop,
          top: now.graphTop,
          isUndoing: now.isUndoing,
          undoNote: now.undoNote,
          isPicking: now.isPicking,
          pickA: now.pickA,
          pickB: now.pickB,
          pickField: now.pickField,
        },
        {
          back: () =>
            // Reached from a file's blame, back returns to that file,
            // where it was; otherwise to the file tree.
            set(
              (last): View =>
                (last.backFile ?? '') === ''
                  ? { ...last, screen: 'tree' }
                  : {
                      ...last,
                      screen: 'file',
                      file: last.backFile,
                      commit: last.backCommit ?? '',
                      top: last.backTop ?? 1,
                      selected: '',
                      backFile: '',
                    },
            ),
          help,
          refresh: rescan,
          scrollTo: line => set(last => ({ ...last, graphTop: line })),
          open: pick,
          openFile: (id, path) => void openCommitFile(id, path),
          applyStash: ref => void applyStash($, repo, ref, false),
          popStash: ref => void applyStash($, repo, ref, true),
          compareWith: hash => {
            rescan()
            set(
              (last): View => ({
                ...last,
                base: hash,
                target: '',
                baseWorktree: '',
                screen: 'tree',
                selected: '',
              }),
            )
          },
          checkOutBranch: name => void checkOut($, repo, name, true),
          checkOutCommit: hash => void checkOut($, repo, hash, false),
          askUndo: () => void askUndo($, repo),
          undo: () => void undoCommit($, repo),
          keepCommit: () => set(last => ({ ...last, isUndoing: false })),
          toggleCompare: () => {
            if (!now.isPicking) {
              void loadRequests($, repo)
            }

            set(
              (last): View => ({
                ...last,
                isPicking: !now.isPicking,
                // It opens on the comparison in force, ready to change.
                pickA: last.target ?? '',
                pickB: isComparing ? last.base : '',
                pickField: 'b',
              }),
            )
          },
          cancelCompare: () => set((last): View => ({ ...last, isPicking: false })),
          typeCompare: (field, text) =>
            set(
              (last): View =>
                field === 'a'
                  ? { ...last, pickA: text, pickField: 'a' }
                  : { ...last, pickB: text, pickField: 'b' },
            ),
          takeOffer: value =>
            set(
              (last): View =>
                now.pickField === 'a'
                  ? { ...last, pickA: value, pickField: 'b' }
                  : { ...last, pickB: value },
            ),
          compare: (side, against) => void startCompare($, repo, side, against),
          switchWorktree: path => {
            $.ui.toast(`Now reviewing the worktree ${path.split('/').pop() ?? ''}`, { timeoutMs: 5000 })
            void openReview($, path, undefined)
          },
        },
      )

      graphWindow = drawn.window

      return framed(drawn.tree, true, undefined, Math.max(0, drawn.window.maxTop - (now.graphTop ?? 0)))
    }

    if (now.screen === 'tree') {
      const statusOf = new Map(found.files.map(one => [one.path, one.status]))
      // What "send issues" hands the prompt: the diagnostics the change
      // brought, or every one in the changed files where that is not known.
      const isFreshKnown = inChanged.some(diag => diag.isNew !== undefined)
      const sendable = isFreshKnown ? inChanged.filter(diag => diag.isNew === true) : inChanged
      const needTicks = () => $.ui.toast('Tick some files first (☐)')
      // The files listed are those whose path holds what the person typed
      // to narrow the lists by, whatever its case; all of them with nothing
      // typed.
      const wanted = now.filter.trim().toLowerCase()
      const isListed = (path: string): boolean => wanted === '' || path.toLowerCase().includes(wanted)

      return framed(
        treeScreen(
          kit,
          {
            shell,
            files: found.files.filter(one => isListed(one.path)),
            filter: now.filter,
            // Where b goes back to, when the files were opened from the
            // request's own page; '' for a tree that is nobody's next step.
            backTo: now.codeFrom === 'overview' && requestTyped !== '' ? plain(requestLabel).slice(0, 40) : '',
            about:
              requestTyped === ''
                ? undefined
                : {
                    // Whatever the forge said is drawn as plain text of a
                    // bounded length, whichever answer it came in.
                    label: plain(requestLabel).slice(0, 80),
                    title: plain(aboutRequest?.overview?.title ?? ofBranch?.title ?? '').slice(0, 300),
                    lines: sampleOf(aboutRequest?.overview?.body ?? '', ABOUT_LINES, Math.max(20, shell.columns - 4)),
                    isLoading: aboutRequest === undefined,
                    refusal: plain(aboutRequest?.refusal ?? '').slice(0, 300),
                    standing: standingOf(aboutRequest?.overview),
                  },
            stats: found.stats,
            dirty: found.dirty,
            diags: found.diags,
            isScanned: found.status === 'done',
            isQueued: path => isQueued(repo, path),
            layout: now.layout,
            toggled: now.toggled,
            checked: now.checked,
            isDiscarding: now.isDiscarding,
            isMore: now.isMore || settings.showsAllKeys,
            isPlain: found.isPlain,
            isBrowsing: now.isBrowsing || found.isPlain,
            allFiles: now.isBrowsing || found.isPlain ? allFilesOf(repo).filter(isListed) : [],
            isTelling: now.isTelling,
            issuesToSend: sendable.length,
            comments,
            canMark: seenKey !== '',
            reviewed: seen,
            stashes: found.stashes,
            isReviewing: now.isReviewing,
            pending: drafts.length,
            reviewRound,
            talkOpen: now.talkOpen,
            talkReply: now.talkReply,
            talkRound,
            request:
              ofBranch === undefined || ofBranch.files.length === 0
                ? undefined
                : {
                    isGitlab: ofBranch.label.startsWith('MR'),
                    typed: ofBranch.typed,
                    url: ofBranch.url,
                    title: ofBranch.title,
                    files: ofBranch.files.filter(one => isListed(one.path)),
                    stats: ofBranch.stats,
                  },
            selected: now.selected,
            picked: chosen,
            bodyTop: now.bodyTop,
          },
          {
            refresh: rescan,
            listThreads,
            // A file of the branch's request opens as the working tree has
            // it, on what the request changes in it; one not edited here is
            // checked along with the rest from then on.
            openRequestFile: async path => {
              if (ofBranch === undefined) {
                return
              }

              const isListed = found.files.some(one => one.path === path)

              await update(
                $,
                view,
                (last): View => ({
                  ...last,
                  diffBase: { path, base: ofBranch.base, name: ofBranch.baseRef },
                  extra: isListed
                    ? (last.extra ?? [])
                    : [path, ...(last.extra ?? []).filter(one => one !== path)].slice(0, EXTRA_FILES),
                }),
              )

              if (!isListed) {
                rescan()
              }

              await loadSource($, repo, path)
              await update(
                $,
                view,
                (last): View => ({
                  ...last,
                  screen: 'file',
                  file: path,
                  commit: '',
                  origin: 'tree',
                  top: 1,
                  cursor: -1,
                  isDiff: !isMarkdownFile(path),
                  isPreview: isMarkdownFile(path),
                }),
              )
            },
            toggleReviewing: () => {
              reviewDraft = ''
              reviewRound += 1
              set(last => ({ ...last, isReviewing: !now.isReviewing }))
            },
            typeReview: text => {
              reviewDraft = text
            },
            submitReview: (verdict, entered) =>
              void sendReview($, repo, requestTyped, verdict, entered ?? reviewDraft, target),
            checkProject: () => {
              job = { isProject: true }
            },
            switchLayout: () =>
              void update(
                $,
                view,
                (last): View => ({ ...last, layout: now.layout === 'tree' ? 'list' : 'tree' }),
              ).then(() => rememberReview($)),
            openGraph: () => set((last): View => ({ ...last, screen: 'graph', backFile: '' })),
            stopComparing: () => {
              rescan()
              set((last): View => ({ ...last, base: 'HEAD', target: '', baseWorktree: '', codeFrom: 'tree' }))
            },
            toggleMore: () => set(last => ({ ...last, isMore: !(last.isMore ?? false) })),
            help,
            toggleAllFiles: () => {
              rescan()
              set(last => ({ ...last, isBrowsing: !now.isBrowsing }))
            },
            sendIssues: () =>
              sendable.length === 0
                ? $.ui.toast('There are no issues to send')
                : void sendToComposer(
                    $,
                    `${isFreshKnown ? 'New issues' : 'Issues'} in my changes (${sendable.length}):\n${issueList(sendable, ISSUES_SENT)}`,
                  ),
            toggleTelling: () => set(last => ({ ...last, isTelling: !(last.isTelling ?? false) })),
            // The language server of the first changed file it can read searches.
            setFilter: text => set((last): View => ({ ...last, filter: text.trim().slice(0, 200) })),
            searchNames: query =>
              void searchSymbols(
                $,
                repo,
                query,
                [...found.files.map(one => one.path), ...now.extra].find(hasNameSearch) ?? '',
              ),
            // From the file tree a file opens as the working tree has it, or,
            // while two commits are compared, as the target commit has it, in
            // the diff view.
            open: async path => {
              // A file the change does not touch has not been checked: opening
              // it asks for it to be, along with the last few opened the same
              // way.
              if (target === '' && !found.isPlain && !found.files.some(one => one.path === path)) {
                await update($, view, last => ({
                  ...last,
                  extra: [path, ...(last.extra ?? []).filter(one => one !== path)].slice(0, EXTRA_FILES),
                }))
                rescan()
              }

              await update($, view, (last): View => ({ ...last, diffBase: NO_VIEW.diffBase }))
              await loadSource($, repo, path, target)
              await update(
                $,
                view,
                (last): View => ({
                  ...last,
                  screen: 'file',
                  file: path,
                  commit: target,
                  origin: 'tree',
                  top: 1,
                  cursor: -1,
                  // In a comparison a file opens on what differs.
                  // In a comparison a file opens on what differs; markdown
                  // opens as it reads, its threads set into the page.
                  // Where git knows nothing of the folder, nothing differs.
                  isDiff:
                    isMarkdownFile(path) || found.isPlain ? false : isComparing ? true : last.isDiff,
                  isPreview: isMarkdownFile(path) ? true : last.isPreview,
                }),
              )
            },
            toggleFolder: key =>
              set(last => ({
                ...last,
                toggled: (last.toggled ?? []).includes(key)
                  ? (last.toggled ?? []).filter(path => path !== key)
                  : [...(last.toggled ?? []), key],
              })),
            // A tick box ticks or unticks all its paths together.
            tick: paths =>
              set(last => {
                const held = new Set(last.checked ?? [])
                const isAll = paths.every(path => held.has(path))

                for (const path of paths) {
                  if (isAll) {
                    held.delete(path)
                  } else {
                    held.add(path)
                  }
                }

                return { ...last, checked: [...held] }
              }),
            tickOnly: paths => set(last => ({ ...last, checked: [...paths] })),
            typeMessage: text => {
              draft = text
            },
            typeDetails: text => {
              draftBody = text
            },
            commit: (paths, entered) =>
              paths.length === 0
                ? needTicks()
                : void commitFiles(
                    $,
                    repo,
                    paths,
                    entered?.message ?? draft,
                    entered?.details ?? draftBody,
                  ),
            stash: paths =>
              paths.length === 0 ? needTicks() : void stashFiles($, repo, paths, draft),
            askDiscard: paths =>
              paths.length === 0 ? needTicks() : set(last => ({ ...last, isDiscarding: true })),
            // What a discard does to a file depends on what git has of it:
            // tracked, added but never committed, or not tracked at all.
            discard: paths =>
              void discardFiles(
                $,
                repo,
                paths.filter(path => !['?', 'A'].includes(statusOf.get(path) ?? '')),
                paths.filter(path => statusOf.get(path) === 'A'),
                paths.filter(path => statusOf.get(path) === '?'),
              ),
            keepChanges: () => set(last => ({ ...last, isDiscarding: false })),
            openStash: pick,
            openStashFile: (ref, path) => void openCommitFile(ref, path),
            scrollBody: line => set(last => ({ ...last, bodyTop: line })),
            applyStash: ref => void applyStash($, repo, ref, false),
            popStash: ref => void applyStash($, repo, ref, true),
            openOverview: () => {
              // Asked again each time it is opened: checks and reviews move.
              overviewCache = undefined
              set((last): View => ({ ...last, screen: 'overview', overviewFrom: 'tree' }))
            },
            // Back to what the request is, where its files were opened from
            // there: the overview as it was, which keeps where it came from.
            backToOverview: () => set((last): View => ({ ...last, screen: 'overview' })),
            openRequests: () => {
              void loadRequests($, repo)
              set((last): View => ({ ...last, screen: 'requests' }))
            },
            openChanges: () => {
              // Read again each time it is opened: the files may have changed.
              patchCache = undefined
              pageColors = { key: '', lines: new Map(), asked: new Set() }
              set((last): View => ({ ...last, screen: 'changes', pageTop: 0, codeFrom: 'tree' }))
            },
            toggleReviewed: markReviewed,
            markAll: markReviewedAll,
            ...talkActions,
          },
        ),
      )
    }

    // Reading the source subscribes the drawing: a load changes its stamp.
    const shown = await read($, source)
    // '' is the working tree's file; a hash is the file as that commit left it.
    const { file, commit } = now
    const held = cache !== undefined && cache.path === file && cache.commit === commit ? cache : undefined
    const lines = held?.lines

    if (lines === undefined) {
      wanted = file
    }

    const lineCount = lines?.length ?? 0
    const texts = (lines ?? []).map(spans => spans.map(span => span[1]).join(''))
    // The checkers ran on the working tree (or, between two commits, on the
    // target), so a file at any other commit has no diagnostics.
    const isChecked = commit === '' || commit === target
    const diags = isChecked ? diagsOf(found.diags, file) : []
    // A file the other side does not have is new from its first line to its last.
    const fileStatus = (isChecked ? found.files : chosen.files).find(one => one.path === file)?.status
    // Where back returns: a commit's file was opened from the graph or the
    // file tree, the working tree's from the file tree.
    const back = (): void =>
      set(
        (was): View => ({
          ...was,
          // A file opened from the page of every change goes back to it.
          // One opened from a thread on the request's page goes back to that page.
          screen: was.origin === 'changes' ? 'changes' : was.origin === 'overview' ? 'overview' : commit === '' ? 'tree' : (was.origin ?? 'graph'),
          commit: '',
        }),
      )
    const { Markdown } = kit

    // A picture is drawn as itself, beside what it was where it changed.
    if (isPictureFile(file)) {
      const drawn = shot !== undefined && shot.path === file && shot.commit === commit ? shot : undefined

      return framed(
        pictureScreen(
          kit,
          {
            shell,
            file,
            commit,
            isLoaded: held !== undefined && drawn !== undefined,
            now: drawn?.now,
            before: drawn?.before,
            against: drawn?.against ?? '',
          },
          { back, help, refresh: () => void loadSource($, repo, file, commit) },
        ),
      )
    }

    // The request's threads on this file's lines, for the rendered page.
    const pageTalk =
      commit === target
        ? comments.filter(
            one =>
              one.path === file &&
              one.line > 0 &&
              !(now.hidesResolved && one.isResolved === true),
          )
        : []

    // Markdown shows rendered unless the person asked for its source or its diff.
    if (Markdown !== undefined && isMarkdownFile(file) && now.isPreview && !now.isDiff && lines !== undefined) {
      return framed(
        markdownScreen(
          { ...kit, Markdown },
          { shell, file, commit, text: texts.join('\n'), talk: pageTalk },
          {
            back,
            help,
            showSource: () => set(was => ({ ...was, isPreview: false })),
            showDiff: () => set(was => ({ ...was, isDiff: true })),
            sendTalk: n =>
              void sendToComposer(
                $,
                talkBlock(
                  requestLabel,
                  file,
                  n,
                  pageTalk.filter(one => one.line === n),
                  Math.max(1, n - 3),
                  Math.min(lineCount, n + 3),
                  texts,
                ),
              ),
            // The source at the thread's line, on the diff, where the
            // thread's card has reply and resolve.
            openSource: n =>
              set(was => ({ ...was, isPreview: false, isDiff: true, top: Math.max(1, n - 3) })),
            sendSelection: () =>
              void $.ui.selection().then(selected =>
                selected === undefined || selected.text.trim() === ''
                  ? $.ui.toast('Nothing is selected: drag over some text first')
                  : sendToComposer($, quoteBlock(file, selected.text)),
              ),
          },
        ),
      )
    }

    // The blame column: who last changed each line, where it has been asked
    // for and still belongs to the file as shown.
    const blame =
      now.isBlame &&
      blameCache !== undefined &&
      blameCache.path === file &&
      blameCache.commit === commit &&
      // git counts a file's lines; the file screen also counts the empty one
      // after a final newline. An empty list is a file with no history.
      (blameCache.lines.length === 0 || Math.abs(blameCache.lines.length - lineCount) <= 1)
        ? blameCache.lines
        : undefined
    // What the language server added for this file, once it has answered.
    const info = insight !== undefined && insight.path === file && commit === '' ? insight : undefined
    // Only the request's own head version of a file can be commented on.
    const canComment = reviewed !== undefined && commit === target
    const isCommenting = now.isCommenting && canComment
    const symbol = now.symbol.file === file ? now.symbol : undefined
    // Whether the file's diff is against a base of its own (see `View.diffBase`).
    const isOwnDiff = commit === '' && now.diffBase.path === file && now.diffBase.base !== ''
    const talk =
      commit === target
        ? comments
            // A comment or a ledger finding on the file as a whole has no
            // line of its own: it is shown on the file's first, and says so.
            .map(one =>
              one.path === file && isOnWholeFile(one)
                ? { ...one, line: 1, body: `(whole file) ${one.body}` }
                : one,
            )
            // A comment on a removed line is shown under the removed lines
            // it is among: on the line of this side they are drawn before.
            .map(one => {
              const old = one.path === file && one.line === 0 ? (one.oldLine ?? 0) : 0
              const before =
                old === 0
                  ? undefined
                  : Object.entries(held?.removedAt ?? {}).find(
                      ([at, first]) => old >= first && old < first + (held?.removed[Number(at)]?.length ?? 0),
                    )?.[0]

              return before === undefined
                ? one
                : {
                    ...one,
                    line: clamp(Number(before), 1, Math.max(1, lineCount)),
                    body: `(removed line ${old}) ${one.body}`,
                  }
            })
            .filter(
              one =>
                one.path === file &&
                one.line > 0 &&
                // A resolved thread is left out where the person asked for that.
                !(now.hidesResolved && one.isResolved === true),
            )
        : []
    // The first comment of the thread on a line: what a reply answers and
    // what resolving settles. A reply is listed under the comment it answers.
    const rootOn = (n: number): Comment | undefined => {
      // A request's thread before a ledger finding on the same line: reply
      // and resolve are the thread's.
      const first =
        talk.find(one => one.line === n && !isFinding(one) && !isDraft(one)) ??
        talk.find(one => one.line === n && !isDraft(one))

      return first === undefined || first.replyTo === undefined
        ? first
        : (talk.find(one => one.id === first.replyTo) ?? first)
    }
    const drawn = fileScreen(
      kit,
      {
        shell,
        file,
        commit,
        isChecked,
        lines,
        texts,
        note: shown.note,
        removed: held?.removed ?? {},
        removedAt: held?.removedAt ?? {},
        changed:
          commit === '' && !isOwnDiff ? (found.changed[file] ?? []) : (held?.changed ?? []),
        diffAgainst: isOwnDiff ? now.diffBase.name : '',
        isNewFile: fileStatus === '?' || fileStatus === 'A',
        diags,
        faded: commit === '' ? found.faded.filter(diag => diag.path === file) : [],
        blame,
        insight: info,
        top: now.top,
        cursor: now.cursor,
        isExpanded: now.isExpanded,
        isDiff: now.isDiff,
        isChanges: now.isChanges,
        isMore: now.isMore || settings.showsAllKeys,
        isHinting: now.isHinting,
        isFinding: now.isFinding,
        find: now.find,
        findAt: now.findAt,
        canComment,
        isCommenting,
        commentLine: now.commentLine,
        commentFrom: now.commentFrom,
        commentOld: now.commentOld,
        me: meCache?.repo === repo ? meCache.me : '',
        editing: now.editing,
        deleting: now.deleting,
        draft: now.editing === '' ? '' : commentDraft,
        typed: commentDraft,
        replyTo: now.replyTo,
        hidesResolved: now.hidesResolved,
        commentRound,
        talk,
        crumb: now.crumb,
        folder: crumbCache,
        symbol,
      },
      {
        back,
        help,
        refresh: rescan,
        toggleMore: () => set(was => ({ ...was, isMore: !now.isMore })),
        scrollTo: line => set(last => ({ ...last, top: line })),
        showIssue: (cursor, top) => set(last => ({ ...last, cursor, top })),
        nextChange: top =>
          top === undefined ? $.ui.toast('No more changes below') : set(last => ({ ...last, top })),
        // Round the three views: the file, its diff, the diff cut down to
        // what differs.
        toggleDiff: () =>
          set(was =>
            !was.isDiff
              ? { ...was, isDiff: true, isChanges: false }
              : !(was.isChanges ?? false)
                ? { ...was, isChanges: true }
                : { ...was, isDiff: false, isChanges: false },
          ),
        toggleExpanded: () => set(was => ({ ...was, isExpanded: !was.isExpanded })),
        toggleBlame: () =>
          blame === undefined
            ? void loadBlame($, repo, file, commit)
            : set(was => ({ ...was, isBlame: false })),
        toggleHints: () =>
          // The hints are read with the rest of what the server knows
          // of the file, so switching them on reads that again.
          void update($, view, was => ({
            ...was,
            isHinting: !(was.isHinting ?? false),
          })).then(() => loadInsight($, repo, file)),
        showRendered: () => set(was => ({ ...was, isPreview: true, isDiff: false })),
        find: () =>
          // Open, it opens the field empty; already open, it puts the
          // keyboard back in the field to type another search.
          now.isFinding
            ? void $.ui.focus({ requestId: PANE, key: 'find-text' })
            : set(was => ({ ...was, isFinding: true, find: '', findAt: 0 })),
        typeFind: text => set(was => ({ ...was, find: text, findAt: 0 })),
        showMatch: (index, top) => set(last => ({ ...last, findAt: index, top })),
        leaveFindField: () => void $.ui.focus({ requestId: PANE, key: 'find-next' }),
        closeFind: () => set(was => ({ ...was, isFinding: false, find: '' })),
        // A removed line picked to comment on: the box opens under the line
        // of this side that those removed lines are drawn before.
        pressOldLine: (old, before) =>
          set(last => ({
            ...last,
            commentLine: clamp(before, 1, Math.max(1, lineCount)),
            commentFrom: 0,
            commentOld: old,
            replyTo: '',
            editing: '',
          })),
        pressLine: n =>
          // While commenting on a request, a line number picks the line
          // to comment on.
          // With the box already open on a line, a later line's number
          // stretches the comment down to it (the first line stays); the
          // first line's own number, or an earlier one, starts again there.
          isCommenting
            ? set(last => {
                const first = (last.commentFrom ?? 0) > 0 ? last.commentFrom : (last.commentLine ?? 0)

                return first > 0 && n > first && (last.replyTo ?? '') === ''
                  ? { ...last, commentLine: n, commentFrom: first, commentOld: 0 }
                  : { ...last, commentLine: n, commentFrom: 0, commentOld: 0, replyTo: '' }
              })
            : // The fold is the function or class the server says starts
              // here; without a server, what the indentation suggests.
              void sendToComposer(
                $,
                codeBlock(
                  file,
                  n,
                  (info === undefined ? undefined : foldOf(info.items, n))?.to ?? foldEnd(texts, n),
                  texts,
                ),
              ),
        sendIssues: n =>
          void sendToComposer(
            $,
            diagBlock(
              file,
              n,
              (diagsByLine(diags, lineCount).get(n) ?? []).map(({ diag }) => diag),
              texts,
            ),
          ),
        // A review thread goes with the code it is about: the function or
        // class that starts on its line, or else a few lines either side.
        // Only the card pressed goes to the prompt: a request's thread is
        // other people's words, and is not sent along with the ledger's
        // findings on the same line, nor they with it.
        sendTalk: (n, isLedger = false) => {
          const fold = (info === undefined ? undefined : foldOf(info.items, n))?.to ?? foldEnd(texts, n)
          const [from, to] =
            fold > n ? [n, Math.min(fold, n + TALK_CODE)] : [Math.max(1, n - 3), Math.min(lineCount, n + 3)]

          void sendToComposer(
            $,
            // The request's label is what its header line starts with.
            talkBlock(
              requestLabel,
              file,
              n,
              talk.filter(one => one.line === n && isFinding(one) === isLedger && !isDraft(one)),
              from,
              to,
              texts,
            ),
          )
        },
        // What the person last dragged over with the mouse, as a quoted block.
        sendSelection: async () => {
          const selected = await $.ui.selection()

          if (selected === undefined || selected.text.trim() === '') {
            $.ui.toast('Nothing is selected: drag over some code first')

            return
          }

          await sendToComposer($, quoteBlock(file, selected.text))
        },
        // Looks up the name the person dragged over: the pane cannot tell
        // where the pointer is inside a line, so the selection says which
        // name, and its first place on screen says where.
        lookUpSelection: async (from, to) => {
          const name = ((await $.ui.selection())?.text ?? '').trim()

          if (name === '' || name.includes('\n')) {
            $.ui.toast('Drag over one name first, then press t')

            return
          }

          const line = texts.findIndex((text, at) => at + 1 >= from && at + 1 <= to && text.includes(name))

          if (line === -1) {
            $.ui.toast(`"${name}" is not on screen`)

            return
          }

          await lookUp($, repo, file, line + 1, name)
        },
        closeLookup: () => set(was => ({ ...was, symbol: NO_SYMBOL })),
        listUses: () => void (symbol && listReferences($, repo, symbol)),
        listCallers: () => void (symbol && listCalls($, repo, symbol, 'incoming')),
        listCallees: () => void (symbol && listCalls($, repo, symbol, 'outgoing')),
        listImplementations: () => void (symbol && listImplementations($, repo, symbol)),
        openFile: (path, line) => void openAt(path, line),
        // Pressing a line's blame opens its commit in the graph, about where
        // it sits.
        openCommit: hash => {
          const at = history.findIndex(row => row.hash === hash)

          if (at === -1) {
            $.ui.toast(`${hash} is older than the graph reaches`)

            return
          }

          void loadCommit($, repo, hash)
          set(
            (last): View => ({
              ...last,
              screen: 'graph',
              commit: '',
              selected: hash,
              bodyTop: 0,
              graphTop: Math.max(0, at * 2 - 3),
              // Where the graph's back button returns to.
              backFile: last.file,
              backCommit: last.commit ?? '',
              backTop: last.top ?? 1,
            }),
          )
        },
        toggleFolder: (dir, left) =>
          now.crumb.kind === 'dir' && now.crumb.dir === dir
            ? set(was => ({ ...was, crumb: NO_CRUMB }))
            : void loadCrumb($, repo, dir, left),
        toggleNames: (level, left) =>
          set(
            (was): View => ({
              ...was,
              crumb:
                now.crumb.kind === 'symbol' && now.crumb.level === level
                  ? NO_CRUMB
                  : { kind: 'symbol', dir: '', level, left, top: -1 },
            }),
          ),
        listFolder: (dir, left) => void loadCrumb($, repo, dir, left),
        closeCrumb: () => set(was => ({ ...was, crumb: NO_CRUMB })),
        jumpTo: line => set(was => ({ ...was, top: line, crumb: NO_CRUMB })),
        toggleCommenting: () =>
          set(was => ({
            ...was,
            isCommenting: !isCommenting,
            commentLine: 0,
            replyTo: '',
          })),
        replyOn: n => {
          const root = rootOn(n)

          if (root !== undefined) {
            set(was => ({ ...was, isCommenting: true, commentLine: n, commentFrom: 0, commentOld: 0, replyTo: root.id }))
          }
        },
        resolveOn: (n, isResolved) => {
          const root = rootOn(n)

          if (root !== undefined) {
            void settleThread($, repo, requestTyped, root, isResolved)
          }
        },
        toggleResolved: () => set(was => ({ ...was, hidesResolved: !now.hidesResolved })),
        listThreads,
        cancelComment: () => {
          commentDraft = ''
          commentRound += 1
          set(was => ({ ...was, commentLine: 0, commentFrom: 0, commentOld: 0, replyTo: '', editing: '' }))
        },
        commentOnFile: () => {
          commentDraft = ''
          commentRound += 1
          set(was => ({
            ...was,
            commentLine: was.commentLine === FILE_COMMENT ? 0 : FILE_COMMENT,
            commentFrom: 0, commentOld: 0,
            replyTo: '',
          }))
        },
        // A comment of the person's own: put back in the field to be
        // changed; asked about, then removed; and any comment given a
        // thumbs-up.
        editComment: (id, n) => {
          commentDraft = fold(comments.find(one => one.id === id)?.body ?? '')
          commentTouched = false
          commentRound += 1
          set(was => ({
            ...was,
            isCommenting: true,
            editing: id,
            deleting: '',
            commentLine: n,
            commentFrom: 0, commentOld: 0,
            replyTo: '',
          }))
        },
        askDelete: id => set(was => ({ ...was, deleting: id })),
        deleteComment: id => {
          const one = comments.find(held => held.id === id)

          if (one === undefined || now.deleting !== id) {
            return
          }

          void changeComment(forgeRun(runOf($), repo), requestTyped, one, 'delete').then(refusal => {
            if (refusal !== '') {
              $.ui.toast(refusal, { timeoutMs: 10_000 })
            } else {
              // What answered it goes from the pane with it; the forge keeps
              // or drops those as it does.
              if (commentsCache !== undefined) {
                commentsCache.comments = commentsCache.comments.filter(
                  held => held.id !== id && held.replyTo !== id,
                )
              }

              $.ui.toast('Comment deleted')
            }

            set(was => ({ ...was, deleting: '' }))
          })
        },
        likeComment: id => {
          const one = comments.find(held => held.id === id)

          if (one !== undefined) {
            void changeComment(forgeRun(runOf($), repo), requestTyped, one, 'like').then(refusal =>
              $.ui.toast(refusal === '' ? `👍 added to ${one.author}'s comment` : refusal, {
                timeoutMs: refusal === '' ? 4000 : 10_000,
              }),
            )
          }
        },
        // Drops comments written for the review and not sent yet.
        discardDrafts: ids =>
          void changeDrafts($, `${repo}\n${requestTyped}`, list =>
            list.filter(one => !ids.includes(one.id)),
          ),
        // Back to a comment on the one line the box is under.
        commentOnOneLine: () => set(was => ({ ...was, commentFrom: 0 })),
        typeComment: text => {
          // A field drawn holding a comment being changed may first report
          // itself empty, before anything is typed: that is not the person
          // clearing it, and what the comment said is kept.
          if (text === '' && now.editing !== '' && !commentTouched) {
            return
          }

          commentTouched = true
          commentDraft = text
          // What is typed is drawn in full under the field, so the screen
          // is drawn again as it changes.
          set(nudged)
        },
        // An answer to a thread is posted at once. A comment of its own waits
        // with the review's others unless it is asked to go now (`isNow`).
        postComment: (entered, how = 'review') => {
          const isNow = how === 'now'
          const root = now.replyTo === '' ? undefined : rootOn(now.commentLine)
          const typedText = (entered ?? commentDraft).trim()
          // A suggestion is the typed text as a replacement for the lines
          // the comment is on, in the form the forge offers to apply.
          const body = how === 'suggest' && typedText !== '' ? suggestionOf(typedText) : unfold(typedText)
          // A comment of the person's own being changed takes what the
          // field holds in place of what it said.
          const edited = now.editing === '' ? undefined : comments.find(one => one.id === now.editing)

          if (edited !== undefined) {
            void changeComment(forgeRun(runOf($), repo), requestTyped, edited, { edit: unfold(typedText) }).then(
              refusal => {
                if (refusal !== '') {
                  $.ui.toast(refusal, { timeoutMs: 10_000 })

                  return
                }

                const held = commentsCache?.comments.find(one => one.id === edited.id)

                if (held !== undefined) {
                  held.body = unfold(typedText)
                }

                commentDraft = ''
                commentRound += 1
                $.ui.toast('Comment changed')
                set(was => ({ ...was, commentLine: 0, commentFrom: 0, commentOld: 0, replyTo: '', editing: '' }))
              },
            )

            return
          }

          if (root !== undefined) {
            void postReply($, repo, requestTyped, root, entered ?? commentDraft)

            return
          }

          if (!isNow) {
            if (body === '') {
              $.ui.toast('Type the comment first')

              return
            }

            // A comment on a removed line is on no line of this side.
            const line = now.commentLine === FILE_COMMENT || now.commentOld > 0 ? 0 : now.commentLine

            commentDraft = ''
            commentRound += 1
            void $.clock
              .now()
              .then(at =>
                changeDrafts($, `${repo}\n${requestTyped}`, list => [
                  ...list,
                  {
                    id: `${at}-${list.length}`,
                    path: file,
                    line,
                    body,
                    ...(now.commentFrom > 0 && now.commentFrom < line ? { startLine: now.commentFrom } : {}),
                    ...(now.commentOld > 0 ? { oldLine: now.commentOld } : {}),
                  },
                ]),
              )
              .then(() => {
                $.ui.toast(
                  `Added to your review (${drafts.length + 1} waiting): send it from the file tree with v`,
                  { timeoutMs: 6000 },
                )
                set(was => ({ ...was, commentLine: 0, commentFrom: 0, commentOld: 0, replyTo: '', editing: '' }))
              })

            return
          }

          void postReview(
            $,
            repo,
            requestTyped,
            target,
            file,
            // Line 0 is the file as a whole.
            now.commentLine === FILE_COMMENT || now.commentOld > 0 ? 0 : now.commentLine,
            entered ?? commentDraft,
            now.commentFrom,
            now.commentOld,
          )
        },
      },
    )

    fileWindow = drawn.window

    // While commenting, the frame is in the comments' colour.
    return framed(drawn.tree, true, isCommenting ? COMMENT_COLOR : undefined, Math.max(0, drawn.window.maxTop - Math.max(1, now.top ?? 1)))
    })()

    if (above === undefined) {
      return tree
    }

    const { Box } = $.ui.resolve(raw)

    return (
      <Box flexDirection="column">
        {above}
        {tree}
      </Box>
    )
  })
}

files.hooks/check.ts:
// Checking: given the files of a change, what is wrong with them, and which
// of it the change brought.
//
// Which tools exist is this module's own business. The language servers are
// asked first and the command-line checkers (ruff, pyright, tsc, eslint,
// terraform) cover what they could not; a file of any other language is
// checked by its language server alone, when the bridge has one that is
// installed. Each tool is run in the project its
// files belong to, and the base's version of a file is checked in an export
// of that commit, which git.ts makes. A caller sees diagnostics, notes on what could not run,
// and the names of the tools still out, and nothing of how any of it is done.
// The parsers are exported for their tests.

import type { ChangedFile, Diag, Severity } from '../types'
import { exportCommit, trackedFiles } from './git'
import type { Run as ServerRun } from './lsp'
import {
  isOtherServed,
  lspDiagnostics,
  lspIsRunning,
  lspServed,
  servedTools,
  unservedNotes,
} from './lsp'
import type { Run } from './run'
import { FILE_LIMIT, tail } from './run'
import type { Checkers } from './settings'

const PYTHON = /\.pyi?$/
const TYPESCRIPT = /\.[cm]?tsx?$/
const TERRAFORM = /\.(tf|tfvars)$/i
// The names the language servers' diagnostics carry as their tool.
const SERVER_TOOLS = ['pyright', 'tsserver', 'terraform-ls', 'terraform']
// What the language servers' own run is called while it is out.
const SERVERS = 'language servers'

// tsc and eslint start with `#!/usr/bin/env node`, and a Node installed
// through nvm is not on the PATH of a process started outside a login shell.
const WITH_NODE = [
  'sh',
  '-c',
  'command -v node >/dev/null || for d in "$HOME"/.nvm/versions/node/*/bin; do [ -x "$d/node" ] && PATH="$d:$PATH"; done; exec "$@"',
  'sh',
]

// For each file after the marker list, prints "file<tab>folder": the nearest
// folder at or above the file that holds one of the markers, or "." for none.
const NEAREST = `markers="$1"; shift
for f in "$@"; do
  d=$(dirname "$f")
  while :; do
    for m in $markers; do
      if [ -e "$d/$m" ]; then printf '%s\\t%s\\n' "$f" "$d"; continue 3; fi
    done
    [ "$d" = "." ] && break
    d=$(dirname "$d")
  done
  printf '%s\\t.\\n' "$f"
done`

// Whether the language servers are switched on, as the last scan had it: a
// file of another language has no checker but its server.
let areServersUsed = true

// Whether a file of another language than the three above is checked: by its
// language server, when one is installed and the servers are switched on.
const isOther = (path: string): boolean => areServersUsed && isOtherServed(path)

// Asks the bridge again which other languages it has an installed server for
// (the screens ask `isCheckable` as they draw, and cannot wait for it), and
// notes whether the servers are switched on. Resolves with what is wrong
// with the person's config file; never rejects.
export const refreshServed = async (servers: ServerRun, isUsed: boolean): Promise<string[]> => {
  areServersUsed = isUsed

  const notes = await lspServed(servers)

  return isUsed ? notes : []
}

// One line for each language among `wanted` that would be checked were its
// server installed, saying what to install.
export const uncheckedNotes = (wanted: readonly string[]): string[] =>
  areServersUsed ? unservedNotes(wanted) : []

// Whether a file is of a kind some checker reads; one that is not has
// nothing to say, which is not the same as being clean.
export const isCheckable = (path: string): boolean =>
  PYTHON.test(path) || TYPESCRIPT.test(path) || TERRAFORM.test(path) || isOther(path)

// Whether a file is of a language whose server can search the project's names.
export const hasNameSearch = (path: string): boolean =>
  PYTHON.test(path) || TYPESCRIPT.test(path) || isOtherServed(path)

// Whether a file's own checkers are among those still out: `pending` is the
// tools a check has started and not finished, as `Progress` named them.
export const isAwaited = (path: string, pending: readonly string[]): boolean =>
  pending.some(tool =>
    tool.startsWith(SERVERS)
      ? isCheckable(path)
      : PYTHON.test(path)
        ? tool.startsWith('ruff') || tool.startsWith('pyright')
        : TERRAFORM.test(path)
          ? tool.startsWith('terraform')
          : TYPESCRIPT.test(path) && (tool.startsWith('tsc') || tool.startsWith('eslint')),
  )

// The tools (as a diagnostic's `tool` names them) whose answers the pending
// ones will bring: what they found last time is not yet replaced.
export const toolsAwaited = (pending: readonly string[]): Set<string> =>
  new Set(
    pending.flatMap(tool =>
      tool.startsWith(SERVERS) ? [...SERVER_TOOLS, ...servedTools()] : [tool.split(' ')[0] ?? ''],
    ),
  )

// Told as each tool starts and finishes, with everything found so far, so a
// caller can show results as they come in.
export type Progress = {
  start: (tool: string) => void
  done: (tool: string, found: Diag[]) => void
}

export type Ports = {
  run: Run
  // How the language servers' bridge runs its commands.
  servers: ServerRun
  // A file's text by its absolute path; '' for one that cannot be read.
  readFile: (path: string) => Promise<string>
}

// What to check: the files `wanted` (relative to `repo`) of a comparison of
// `base` with the working tree or, when `target.ref` is not '', with that
// commit. `short` is each side's short hash, '' where git knows none; `files`
// is what differs between the sides. `isProject` asks for every file of
// every project, changed or not.
export type Ask = {
  repo: string
  base: { ref: string; short: string }
  target: { ref: string; short: string }
  files: readonly ChangedFile[]
  wanted: readonly string[]
  isProject: boolean
  // The checkers the person has left switched on, and whether the base is
  // checked too, to mark each diagnostic new or already there.
  use: Checkers
  marksNew: boolean
}

// What the checkers said about the base's version of the files last asked
// about, and those files' lines there. Kept while the base and the files
// stay the same, so an edit re-checks the working tree alone.
let before: { key: string; diags: Diag[]; texts: Record<string, string[]> } | undefined

// The same for the target commit, when the comparison is between two commits
// (a commit does not change, so its diagnostics are kept until the commit or
// the files asked about do).
let after: { key: string; diags: Diag[] } | undefined

// Checks the files asked about and marks each diagnostic as new or already
// there (`isNew`), where the base could be checked too. Never rejects for a
// tool that cannot run: `notes` says which could not, and why.
export const checkChange = async (
  ports: Ports,
  { repo, base, target, files, wanted, isProject, use, marksNew }: Ask,
  progress: Progress,
): Promise<{ diags: Diag[]; notes: string[] }> => {
  const notes: string[] = []
  // A language with every one of its checkers switched off is not asked about.
  const asked: Files = {
    python: (use.ruff || use.pyright ? wanted.filter(path => PYTHON.test(path)) : []).slice(0, FILE_LIMIT),
    typescript: (use.tsc || use.eslint ? wanted.filter(path => TYPESCRIPT.test(path)) : []).slice(
      0,
      FILE_LIMIT,
    ),
    terraform: (use.terraform ? wanted.filter(path => TERRAFORM.test(path)) : []).slice(0, FILE_LIMIT),
    other: (use.servers ? wanted.filter(isOther) : []).slice(0, FILE_LIMIT),
  }
  // A whole-project check wants every file, which the command-line checkers
  // give; anything else asks the language servers first.
  const useServers = use.servers && (target.ref !== '' || !isProject)
  // `side` is the tree the comparison reads and the checkers run over: the
  // working tree, or, when two commits are compared, an export of the target.
  let side = repo
  let checked: Diag[] = []

  if (target.ref === '') {
    checked = await checkTree(ports, repo, repo, asked, isProject, useServers, use, notes, progress)
  } else {
    const sideKey = `${repo}\n${target.short}\n${JSON.stringify(use)}\n${[...asked.python, ...asked.typescript, ...asked.terraform, ...asked.other].join('\n')}`
    const exported = await exportCommit(ports.run, repo, target.ref, target.short, base.short)

    if (exported.dir === '') {
      notes.push(
        `diagnostics are not shown: ${target.ref} could not be exported to check it (${exported.refusal})`,
      )
    } else if (after?.key === sideKey) {
      side = exported.dir
      checked = after.diags
    } else {
      side = exported.dir
      checked = await checkTree(ports, repo, side, asked, false, useServers, use, notes, progress)
      after = { key: sideKey, diags: checked }
    }
  }

  // New or already there: the same checkers run over the base's version of
  // each modified file that has a diagnostic, and a diagnostic the base also
  // had, on a line with the same text, was there before the change.
  const statusOf = new Map(files.map(one => [one.path, one.status]))
  const troubled = [...new Set(checked.map(diag => diag.path))]
    .filter(path => statusOf.get(path) === 'M')
    .sort()
  const diags = checked.map(diag =>
    statusOf.get(diag.path) === '?' || statusOf.get(diag.path) === 'A'
      ? { ...diag, isNew: true }
      : diag,
  )

  if (troubled.length === 0 || !marksNew) {
    return { diags, notes }
  }

  const textsIn = async (tree: string): Promise<Record<string, string[]>> => {
    const texts: Record<string, string[]> = {}

    await Promise.all(
      troubled.map(async path => {
        texts[path] = (await ports.readFile(`${tree}/${path}`)).split('\n')
      }),
    )

    return texts
  }
  const key = `${repo}\n${base.short}\n${useServers}\n${JSON.stringify(use)}\n${troubled.join('\n')}`

  if (before?.key !== key && base.short !== '') {
    // The base is checked last and all at once; until it is, what is new
    // and what was there before is not known.
    progress.start('new or pre-existing')

    const exported = await exportCommit(
      ports.run,
      repo,
      base.ref,
      base.short,
      target.short || base.short,
    )

    if (exported.dir === '') {
      notes.push(
        `new or pre-existing is not marked: ${base.ref} could not be exported to check it (${exported.refusal})`,
      )
    } else {
      const missed: string[] = []
      // The base is asked the same way as the side it is compared with: a
      // diagnostic is matched by its tool and its words, and the servers
      // and the command-line checkers do not put them the same.
      const baseDiags = await checkTree(
        ports,
        repo,
        exported.dir,
        {
          python: troubled.filter(path => PYTHON.test(path)),
          typescript: troubled.filter(path => TYPESCRIPT.test(path)),
          terraform: troubled.filter(path => TERRAFORM.test(path)),
          other: use.servers ? troubled.filter(isOther) : [],
        },
        false,
        useServers,
        use,
        missed,
      )
      const texts = await textsIn(exported.dir)

      if (missed.length > 0) {
        notes.push(`on the base, ${missed[0] ?? ''}`)
      }

      before = { key, diags: baseDiags, texts }
    }
  }

  return {
    diags: before?.key === key ? labelNew(diags, before.diags, await textsIn(side), before.texts) : diags,
    notes,
  }
}

// The files to check, by what checks them. `other` is every other language
// the bridge has an installed server for: nothing but that server reads it.
type Files = { python: string[]; typescript: string[]; terraform: string[]; other: string[] }

// Runs the checkers over one tree of the repo's files: the working tree
// itself, or an export of a commit. Projects, virtualenvs and node_modules
// are always found in the working tree (`repo`), since an export has only
// what git tracks; `sink` takes a line for each tool that could not run.
// `isWhole` checks every file of every project with the command-line
// checkers; otherwise, with `useServers`, the language servers are asked
// first: they answer for the files given, in milliseconds once warm. The
// `other` files are asked of the servers either way.
const checkTree = async (
  ports: Ports,
  repo: string,
  tree: string,
  { python, typescript, terraform, other }: Files,
  isWhole: boolean,
  useServers: boolean,
  use: Checkers,
  sink: string[],
  progress?: Progress,
): Promise<Diag[]> => {
  const found: Diag[] = []
  // A server speaks in the name of the checker it stands in for; what one
  // says for a checker that is switched off is left out.
  const isWanted = (diag: Diag): boolean =>
    diag.tool === 'pyright'
      ? use.pyright
      : diag.tool === 'tsserver'
        ? use.tsc
        : diag.tool.startsWith('terraform')
          ? use.terraform
          : true
  // `dir` is a folder of the repo, relative to it: the project a tool runs in.
  const at = (dir: string): string => (dir === '.' ? repo : `${repo}/${dir}`)
  const inTree = (dir: string): string => (dir === '.' ? tree : `${tree}/${dir}`)
  const under = (dir: string, path: string): string => (dir === '.' ? path : `${dir}/${path}`)
  const run = (argv: string[], timeoutMs = 60_000, dir = '.') =>
    ports.run(argv, { cwd: at(dir), timeoutMs })
  const exec = (argv: string[], timeoutMs: number, dir = '.') =>
    ports.run(argv, { cwd: inTree(dir), timeoutMs })
  const has = async (path: string, dir = '.'): Promise<boolean> =>
    (await run(['test', '-e', path], 60_000, dir)).exitCode === 0
  // The projects the given files belong to, each with its files relative to it.
  const projectsOf = async (markers: string, paths: string[]): Promise<Map<string, string[]>> =>
    paths.length === 0
      ? new Map()
      : groupByRoot((await run(['sh', '-c', NEAREST, 'sh', markers, ...paths])).stdout)
  // In a whole-project check, every project the repo tracks counts, changed or not.
  const addTracked = async (projects: Map<string, string[]>, patterns: string[]): Promise<void> => {
    for (const path of await trackedFiles(ports.run, repo, patterns)) {
      const dir = path.includes('/') ? path.slice(0, path.lastIndexOf('/')) : '.'

      if (!projects.has(dir)) {
        projects.set(dir, [])
      }
    }
  }
  const collect = (tool: string, parsed: Diag[] | undefined, stderr: string): void => {
    if (parsed === undefined) {
      sink.push(explain(tool, stderr))
    } else {
      found.push(...parsed)
    }

    progress?.done(tool, found)
  }
  const checks: Promise<void>[] = []

  if (python.length > 0 && use.ruff) {
    progress?.start('ruff')
    checks.push(
      exec(
        ['uvx', 'ruff', 'check', '--output-format', 'json', '--exit-zero', ...python],
        60_000,
      ).then(ran => collect('ruff', parseRuff(ran.stdout, tree), ran.stderr)),
    )
  }

  // Each Python project is checked from its own folder, with its own venv.
  const pythonProjects = await projectsOf('pyrightconfig.json pyproject.toml .venv venv', python)

  if (isWhole) {
    await addTracked(pythonProjects, ['*pyproject.toml', '*pyrightconfig.json'])

    if (pythonProjects.size === 0) {
      pythonProjects.set('.', [])
    }
  }

  // Each TypeScript project is the folder of the nearest tsconfig.json; its
  // tools are the nearest node_modules at or above it (a workspace hoists them).
  const typescriptProjects = await projectsOf('tsconfig.json', typescript)

  if (isWhole) {
    await addTracked(typescriptProjects, ['*tsconfig.json'])
  }

  const bins = new Map<string, string>()

  for (const dir of typescriptProjects.keys()) {
    const nearest = await run(['sh', '-c', NEAREST, 'sh', 'node_modules/.bin/tsc', under(dir, 'x')])
    const binDir = [...groupByRoot(nearest.stdout).keys()][0] ?? '.'

    bins.set(dir, `${at(binDir)}/node_modules/.bin`)

    // An export has no node_modules of its own; it borrows the working
    // tree's, so imports resolve there as they do here.
    if (tree !== repo) {
      await exec(
        ['ln', '-sfn', `${at(binDir)}/node_modules`, `${inTree(binDir)}/node_modules`],
        10_000,
      )
    }
  }

  // The language servers answer first. What they covered is not asked of
  // the command-line type checkers again; what they could not cover (a
  // server not installed, a file outside any project) still is.
  const served = new Set<string>()
  const asked = useServers && !isWhole ? [...python, ...typescript, ...terraform, ...other] : other

  if (asked.length > 0) {
    // Servers not yet running take their time over the first answer (the
    // very first run fetches them), which is said while it lasts.
    const servers = (await lspIsRunning(ports.servers))
      ? SERVERS
      : `${SERVERS} (starting: the first answer can take a minute)`

    progress?.start(servers)

    const answer = await lspDiagnostics(
      ports.servers,
      tree,
      asked,
      tree === repo ? {} : { envRoot: repo },
    )

    for (const path of answer.covered) {
      served.add(path)
    }

    // A missing terraform-ls is not worth a note: the terraform command
    // below checks those files, and says so itself when it cannot.
    sink.push(...answer.notes.filter(note => !note.includes('terraform-ls')).map(explainServer))
    found.push(...answer.diags.filter(isWanted))
    progress?.done(servers, found)
  }

  // Terraform files no server answered for are validated by the terraform
  // command, a folder at a time: a folder is one configuration.
  const terraformDirs = new Set(
    terraform
      .filter(path => !served.has(path))
      .map(path => (path.includes('/') ? path.slice(0, path.lastIndexOf('/')) : '.')),
  )

  for (const dir of terraformDirs) {
    checks.push(
      (async () => {
        progress?.start(`terraform (${dir})`)

        const ran = await exec(['terraform', 'validate', '-json', '-no-color'], 120_000, dir)
        const parsed = parseTerraform(ran.stdout, dir)

        sink.push(...(parsed?.notes ?? []))
        collect(`terraform (${dir})`, parsed?.diags, ran.stderr)
      })(),
    )
  }

  for (const [dir, paths] of pythonProjects) {
    const left = isWhole ? paths : paths.filter(path => !served.has(under(dir, path)))

    if (!use.pyright || (!isWhole && left.length === 0)) {
      continue
    }

    checks.push(
      (async () => {
        progress?.start(`pyright (${dir})`)

        const [hasDotVenv, hasVenv] = await Promise.all([
          has('.venv/bin/python', dir),
          has('venv/bin/python', dir),
        ])
        const python3 = hasDotVenv
          ? `${at(dir)}/.venv/bin/python`
          : hasVenv
            ? `${at(dir)}/venv/bin/python`
            : undefined
        const args = [
          '--outputjson',
          ...(python3 === undefined ? [] : ['--pythonpath', python3]),
          ...(isWhole ? [] : left),
        ]
        const installed = await exec(['pyright', ...args], 300_000, dir)
        // A pyenv shim only answers in a Python version that has pyright
        // installed, and a project's .python-version may pin another one;
        // uvx runs pyright whatever the folder's Python is.
        const ran =
          parsePyright(installed.stdout, tree) === undefined
            ? await exec([...WITH_NODE, 'uvx', 'pyright', ...args], 300_000, dir)
            : installed
        collect(`pyright (${dir})`, parsePyright(ran.stdout, tree), ran.stderr)
      })(),
    )
  }

  for (const [dir, paths] of typescriptProjects) {
    const bin = bins.get(dir) ?? `${at(dir)}/node_modules/.bin`
    const needsTsc = use.tsc && (isWhole || paths.some(path => !served.has(under(dir, path))))

    checks.push(
      (async () => {
        if (needsTsc && !(await has(`${bin}/tsc`))) {
          // Packages can only be installed where something lists them.
          const listed = await run(['sh', '-c', NEAREST, 'sh', 'package.json', under(dir, 'x')])
          const packageDir = [...groupByRoot(listed.stdout).keys()][0] ?? '.'

          sink.push(
            (await has('package.json', packageDir))
              ? `tsc skipped in ${here(dir)}: its packages are not installed. Run npm install (or pnpm, yarn, bun) there, then press r`
              : `tsc skipped in ${here(dir)}: no package.json`,
          )
        } else if (needsTsc) {
          progress?.start(`tsc (${dir})`)

          // A solution-style tsconfig only lists references; the app's own
          // config is the one that holds the source files.
          const hasAppConfig = await has('tsconfig.app.json', dir)
          const ran = await exec(
            [
              ...WITH_NODE,
              `${bin}/tsc`,
              ...(hasAppConfig ? ['-p', 'tsconfig.app.json'] : []),
              '--noEmit',
              '--pretty',
              'false',
            ],
            300_000,
            dir,
          )
          const parsed = parseTsc(ran.stdout).map(diag => ({
            ...diag,
            path: under(dir, diag.path),
          }))
          const isRun = !(ran.exitCode > 0 && parsed.length === 0)

          // tsc speaks for the whole project, so what the server said of
          // some of its files is dropped: one tool's word per project.
          if (isRun) {
            const prefix = dir === '.' ? '' : `${dir}/`

            for (let at = found.length - 1; at >= 0; at -= 1) {
              if (found[at]?.tool === 'tsserver' && (found[at]?.path ?? '').startsWith(prefix)) {
                found.splice(at, 1)
              }
            }
          }

          collect(`tsc (${dir})`, isRun ? parsed : undefined, ran.stdout + ran.stderr)
        }

        if (paths.length === 0 || !use.eslint) {
          return
        }

        // A project that does not use eslint is not missing anything.
        if (!(await has(`${bin}/eslint`))) {
          return
        }

        progress?.start(`eslint (${dir})`)

        const ran = await exec(
          [...WITH_NODE, `${bin}/eslint`, '-f', 'json', ...paths],
          120_000,
          dir,
        )
        collect(`eslint (${dir})`, parseEslint(ran.stdout, tree), ran.stderr)
      })(),
    )
  }

  await Promise.all(checks)

  return found
}

// A project's folder as a person reads it.
const here = (dir: string): string => (dir === '.' ? 'the folder under review' : dir)

// Why a tool did not run, with what to do about it where the reason is one
// of the usual ones; the tool's own last words otherwise. `tool` is the name
// progress knows it by ("pyright (backend)").
export const explain = (tool: string, stderr: string): string => {
  const name = tool.split(' ')[0] ?? tool
  const dir = /\((.*)\)$/.exec(tool)?.[1] ?? '.'
  const said = stderr.toLowerCase()
  const isMissing = /not found|no such file|enoent|cannot find|not installed/.test(said)

  if (/timed? ?out|etimedout|sigterm|killed/.test(said)) {
    return `${tool} was stopped: it took too long. Press r to try again; a first run can be slow while the tool is fetched`
  }

  if ((name === 'ruff' || name === 'pyright') && isMissing && /\buvx?\b/.test(said)) {
    return `${tool} did not run: uv is not installed. Install it (brew install uv), then press r`
  }

  if (name === 'pyright' && isMissing && said.includes('node')) {
    return `${tool} did not run: pyright needs Node, and none was found. Install Node (brew install node), then press r`
  }

  if ((name === 'tsc' || name === 'eslint') && isMissing && said.includes('node')) {
    return `${tool} did not run: Node was not found. Install Node (brew install node, or nvm install), then press r`
  }

  if (name === 'eslint' && /eslint\.config|no eslint configuration|couldn't find a configuration/.test(said)) {
    return `${tool} did not run: ${here(dir)} has no eslint config. Add an eslint.config.js there, or switch eslint off in /config`
  }

  if (name === 'terraform' && isMissing) {
    return `${tool} did not run: terraform is not installed. Install it (brew install terraform), then press r`
  }

  return `${tool} did not run: ${tail(stderr) || 'it printed nothing'}. Switch it off in /config if this project does not use it`
}

// What the language servers' bridge said it could not do, with what to do
// about it where that is known.
export const explainServer = (note: string): string =>
  /\buv\b.*(not found|not installed)|python3?: (command )?not found/i.test(note)
    ? `${note}. The language servers need uv or python3 (brew install uv); the command-line checkers are used meanwhile`
    : note

// ---------------------------------------------------------------------------
// How each tool prints what it found.
// ---------------------------------------------------------------------------

const relative = (path: string, root: string): string =>
  path.startsWith(`${root}/`) ? path.slice(root.length + 1) : path

const json = (out: string): unknown => {
  try {
    return JSON.parse(out)
  } catch {
    return undefined
  }
}

// "file<tab>folder" lines into each folder's files, relative to that folder.
export const groupByRoot = (out: string): Map<string, string[]> => {
  const groups = new Map<string, string[]>()

  for (const line of out.split('\n')) {
    const [path, root] = line.split('\t')

    if (path === undefined || root === undefined || path === '') {
      continue
    }

    const inside = root === '.' ? path : path.slice(root.length + 1)
    groups.set(root, [...(groups.get(root) ?? []), inside])
  }

  return groups
}

type RuffItem = {
  code?: string | null
  message?: string
  filename?: string
  location?: { row?: number; column?: number }
  end_location?: { row?: number; column?: number }
}

export const parseRuff = (out: string, root: string): Diag[] | undefined => {
  const items = json(out)

  if (!Array.isArray(items)) {
    return undefined
  }

  return (items as RuffItem[]).map(item => ({
    path: relative(item.filename ?? '', root),
    line: item.location?.row ?? 1,
    col: item.location?.column ?? 1,
    endCol: item.end_location?.row === item.location?.row ? (item.end_location?.column ?? 0) : 0,
    severity: item.code ? 'warning' : 'error',
    tool: 'ruff',
    rule: item.code ?? 'syntax',
    message: item.message ?? '',
  }))
}

type PyrightItem = {
  file?: string
  severity?: string
  message?: string
  rule?: string
  range?: {
    start?: { line?: number; character?: number }
    end?: { line?: number; character?: number }
  }
}

const PYRIGHT_SEVERITY: Record<string, Severity> = {
  error: 'error',
  warning: 'warning',
  information: 'info',
}

export const parsePyright = (out: string, root: string): Diag[] | undefined => {
  const report = json(out) as { generalDiagnostics?: PyrightItem[] } | undefined

  if (!Array.isArray(report?.generalDiagnostics)) {
    return undefined
  }

  return report.generalDiagnostics.map(item => ({
    path: relative(item.file ?? '', root),
    line: (item.range?.start?.line ?? 0) + 1,
    col: (item.range?.start?.character ?? 0) + 1,
    endCol:
      item.range?.end?.line === item.range?.start?.line ? (item.range?.end?.character ?? -1) + 1 : 0,
    severity: PYRIGHT_SEVERITY[item.severity ?? ''] ?? 'info',
    tool: 'pyright',
    rule: item.rule ?? '',
    message: item.message ?? '',
  }))
}

type TerraformItem = {
  severity?: string
  summary?: string
  detail?: string
  range?: {
    filename?: string
    start?: { line?: number; column?: number }
    end?: { line?: number; column?: number }
  }
}

// `terraform validate -json`, run in `dir` (a folder of the repo, '.' for
// the repo itself). A diagnostic that names no file (the folder needs
// `terraform init`, say) is a note about the run, not about a line.
export const parseTerraform = (
  out: string,
  dir: string,
): { diags: Diag[]; notes: string[] } | undefined => {
  const report = json(out) as { diagnostics?: TerraformItem[] } | undefined

  if (!Array.isArray(report?.diagnostics)) {
    return undefined
  }

  const said = (item: TerraformItem): string =>
    [item.summary, item.detail].filter(part => part !== undefined && part !== '').join(': ')
  const placed = report.diagnostics.filter(item => item.range?.filename !== undefined)

  return {
    diags: placed.map(item => ({
      path: dir === '.' ? (item.range?.filename ?? '') : `${dir}/${item.range?.filename ?? ''}`,
      line: item.range?.start?.line ?? 1,
      col: item.range?.start?.column ?? 1,
      endCol:
        item.range?.end?.line === item.range?.start?.line ? (item.range?.end?.column ?? 0) : 0,
      severity: item.severity === 'warning' ? 'warning' : 'error',
      tool: 'terraform',
      rule: '',
      message: said(item),
    })),
    notes: report.diagnostics
      .filter(item => item.range?.filename === undefined)
      .map(item =>
        // A folder never initialised has no providers to validate against.
        /terraform init|not installed|missing required provider/i.test(said(item))
          ? `terraform (${dir}) is not set up here: run terraform init in ${here(dir)}, then press r`
          : `terraform (${dir}): ${said(item).replace(/\s+/g, ' ')}`,
      ),
  }
}

// `tsc --pretty false`: "src/a.ts(12,5): error TS2322: message".
export const parseTsc = (out: string): Diag[] =>
  out.split('\n').flatMap(line => {
    const hit = /^(.+?)\((\d+),(\d+)\): (error|warning) (TS\d+): (.*)$/.exec(line)

    return hit === null
      ? []
      : [
          {
            path: hit[1] ?? '',
            line: Number(hit[2]),
            col: Number(hit[3]),
            endCol: 0,
            severity: hit[4] === 'error' ? 'error' : 'warning',
            tool: 'tsc',
            rule: hit[5] ?? '',
            message: hit[6] ?? '',
          } satisfies Diag,
        ]
  })

type EslintFile = {
  filePath?: string
  messages?: {
    line?: number
    column?: number
    endLine?: number
    endColumn?: number
    severity?: number
    ruleId?: string | null
    message?: string
  }[]
}

export const parseEslint = (out: string, root: string): Diag[] | undefined => {
  const files = json(out)

  if (!Array.isArray(files)) {
    return undefined
  }

  return (files as EslintFile[]).flatMap(file =>
    (file.messages ?? []).map(message => ({
      path: relative(file.filePath ?? '', root),
      line: message.line ?? 1,
      col: message.column ?? 1,
      endCol: message.endLine === message.line ? (message.endColumn ?? 0) : 0,
      severity: message.severity === 2 ? 'error' : 'warning',
      tool: 'eslint',
      rule: message.ruleId ?? '',
      message: message.message ?? '',
    })),
  )
}

// Marks each diagnostic of the files checked on both sides as new or already
// there. Line numbers shift as a file is edited, so one is matched to the
// base's by tool, rule, message and the text of the line it sits on; each of
// the base's stands for one match, so a second copy of an old problem is new.
export const labelNew = (
  head: readonly Diag[],
  base: readonly Diag[],
  headTexts: Readonly<Record<string, readonly string[]>>,
  baseTexts: Readonly<Record<string, readonly string[]>>,
): Diag[] => {
  const keyOf = (diag: Diag, texts: Readonly<Record<string, readonly string[]>>): string =>
    [
      diag.path,
      diag.tool,
      diag.rule,
      diag.message,
      (texts[diag.path]?.[diag.line - 1] ?? '').trim(),
    ].join('\u0001')
  const left = new Map<string, number>()

  for (const diag of base) {
    const key = keyOf(diag, baseTexts)
    left.set(key, (left.get(key) ?? 0) + 1)
  }

  return head.map(diag => {
    if (headTexts[diag.path] === undefined) {
      return diag
    }

    const key = keyOf(diag, headTexts)
    const count = left.get(key) ?? 0

    if (count > 0) {
      left.set(key, count - 1)
    }

    return { ...diag, isNew: count === 0 }
  })
}

files.hooks/diags.ts:
// Lists of diagnostics, read the ways the screens need: one file's, counted,
// by the line they show under.

import type { Diag } from '../types'

export const diagsOf = (diags: readonly Diag[], path: string): Diag[] =>
  diags
    .filter(diag => diag.path === path)
    .sort((a, b) => a.line - b.line || a.col - b.col)

export const countLabel = (diags: readonly Diag[]): string => {
  const errors = diags.filter(diag => diag.severity === 'error').length
  const others = diags.length - errors

  return [errors > 0 ? `${errors}✖` : '', others > 0 ? `${others}⚠` : '']
    .filter(part => part !== '')
    .join(' ')
}

// The file's diagnostics by the line they show under; one past the end of
// the file shows under its last line. `diags` is the file's, sorted.
export const diagsByLine = (
  diags: readonly Diag[],
  lineCount: number,
): Map<number, { diag: Diag; index: number }[]> => {
  const byLine = new Map<number, { diag: Diag; index: number }[]>()

  diags.forEach((diag, index) => {
    const line = Math.min(Math.max(1, diag.line), Math.max(1, lineCount))
    byLine.set(line, [...(byLine.get(line) ?? []), { diag, index }])
  })

  return byLine
}

// Whether a diagnostic only says code is never used, at the level of a hint:
// it fades that code and is no problem to count or list, as in an editor.
export const isFadeOnly = (diag: Diag): boolean => diag.isUnused === true && diag.severity === 'info'

files.hooks/git.ts:
// Everything that knows a git command line, or how git prints things: what
// differs and where, the history and its lanes, blame, stashes, and the
// commands that change the repo. Callers pass the `run` they hold and get
// the pane's own values back; the parsers are exported for their tests.

import type {
  ChangedFile,
  Commit,
  GraphRow,
  LineRange,
  LineStat,
  Picked,
  Scan,
  Span,
} from '../types'
import type { Run } from './run'
import { FILE_LIMIT, tail } from './run'

// `git diff --name-status`: "M\tpath", a rename "R100\told\tnew".
export const parseNameStatus = (out: string): ChangedFile[] =>
  out
    .split('\n')
    .filter(line => line.includes('\t'))
    .map(line => {
      const parts = line.split('\t')

      return { path: parts[parts.length - 1] ?? '', status: line.charAt(0) }
    })

export const parseUntracked =(out: string): ChangedFile[] =>
  out
    .split('\n')
    .filter(line => line !== '')
    .map(path => ({ path, status: '?' }))

// `git diff -U0 --no-prefix`: the added side of each hunk, per file.
export const parseChangedLines = (out: string): Record<string, LineRange[]> => {
  const changed: Record<string, LineRange[]> = {}
  let path = ''

  for (const line of out.split('\n')) {
    if (line.startsWith('+++ ')) {
      path = line.slice(4).trim()
      continue
    }

    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line)
    const count = hunk?.[2] === undefined ? 1 : Number(hunk[2])

    if (hunk === null || path === '' || path === '/dev/null' || count === 0) {
      continue
    }

    const from = Number(hunk[1])
    changed[path] = [...(changed[path] ?? []), [from, from + count - 1]]
  }

  return changed
}

// One file's `git diff -U0`: the lines the base had and the working tree
// dropped, keyed by the new file's line they come before. A hunk that only
// removes names the line it follows, so its lines come before the next one.
export const parseRemoved = (out: string): Record<number, string[]> => {
  const removed: Record<number, string[]> = {}
  let before = 0

  for (const line of out.split('\n')) {
    const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line)

    if (hunk !== null) {
      before = Number(hunk[1]) + (hunk[2] === '0' ? 1 : 0)
    } else if (before > 0 && line.startsWith('-') && !line.startsWith('---')) {
      removed[before] = [
        ...(removed[before] ?? []),
        line.slice(1).replace(/\t/g, '    ').replace(/[\u0000-\u001f\u007f]/g, ''),
      ]
    }
  }

  return removed
}

// The same diff, for where those lines were: the number, in the base's
// version of the file, of the first line removed before each such line. The
// rest of a run follow it one by one.
export const parseRemovedAt = (out: string): Record<number, number> => {
  const at: Record<number, number> = {}

  for (const line of out.split('\n')) {
    const hunk = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(line)

    // A hunk that removes nothing (`-12,0`) has no old lines to number.
    if (hunk !== null && hunk[2] !== '0') {
      at[Number(hunk[3]) + (hunk[4] === '0' ? 1 : 0)] ??= Number(hunk[1])
    }
  }

  return at
}

export type BlameLine = { hash: string; author: string; time: number; summary: string }

// `git blame --porcelain`: who last changed each line, in the file's order.
// A commit's details are printed with its first line only, so they are kept
// by hash for its later ones. A line not committed yet has an all-zero hash.
export const parseBlame = (out: string): BlameLine[] => {
  const known = new Map<string, BlameLine>()
  const lines: BlameLine[] = []
  let current: BlameLine | undefined

  for (const line of out.split('\n')) {
    const head = /^([0-9a-f]{40}) \d+ \d+/.exec(line)

    if (head !== null) {
      const hash = head[1] ?? ''

      current = known.get(hash) ?? { hash, author: '', time: 0, summary: '' }
      known.set(hash, current)
    } else if (current === undefined) {
      continue
    } else if (line.startsWith('\t')) {
      lines.push(current)
    } else if (line.startsWith('author ')) {
      current.author = line.slice(7)
    } else if (line.startsWith('author-time ')) {
      current.time = Number(line.slice(12))
    } else if (line.startsWith('summary ')) {
      current.summary = line.slice(8)
    }
  }

  return lines
}

// How long ago, in the shortest form that still reads: 5m, 3h, 12d, 4mo, 2y.
export const ageOf = (seconds: number): string => {
  const steps: [size: number, unit: string][] = [
    [31_536_000, 'y'],
    [2_592_000, 'mo'],
    [86_400, 'd'],
    [3600, 'h'],
    [60, 'm'],
  ]
  const step = steps.find(([size]) => seconds >= size)

  return step === undefined ? 'now' : `${Math.floor(seconds / step[0])}${step[1]}`
}

// `git diff --numstat`: "added<tab>deleted<tab>path"; a binary file has "-".
export const parseNumstat = (out: string): Record<string, LineStat> => {
  const stats: Record<string, LineStat> = {}

  for (const line of out.split('\n')) {
    const [added, deleted, path] = line.split('\t')

    if (path !== undefined && path !== '') {
      stats[path] = [Number(added) || 0, Number(deleted) || 0]
    }
  }

  return stats
}

// `wc -l` over untracked files: every line of a new file counts as added.
export const parseLineCounts = (out: string): Record<string, LineStat> => {
  const stats: Record<string, LineStat> = {}

  for (const line of out.split('\n')) {
    const hit = /^\s*(\d+)\s+(.+)$/.exec(line)

    if (hit !== null && hit[2] !== 'total') {
      stats[hit[2] ?? ''] = [Number(hit[1]), 0]
    }
  }

  return stats
}

// `git log` with each commit's fields set off by \x01: hash, parents, refs,
// subject, relative date, author.
export const parseCommits = (out: string): Commit[] =>
  out
    .split('\n')
    .filter(line => line !== '')
    .map(line => {
      const [hash = '', parents = '', refs = '', subject = '', when = '', author = ''] =
        line.split('\u0001')

      return {
        hash,
        parents: parents.split(' ').filter(parent => parent !== ''),
        refs: refs.split(', ').filter(ref => ref !== ''),
        subject,
        when,
        author,
      }
    })

// The lane colours of VS Code's Git Graph, in its order.
const LANE_COLORS = [
  '#0085d9',
  '#d9008f',
  '#00d90a',
  '#d98500',
  '#a300d9',
  '#ff0000',
  '#00d9cc',
  '#e138e8',
  '#85d900',
  '#dc5b23',
  '#6f24d6',
  '#ffcc00',
]

export const laneColor = (lane: number): string =>
  LANE_COLORS[lane % LANE_COLORS.length] ?? '#0085d9'

// Lays commits (newest first, children before parents) out in lanes, one row
// each. A lane holds the hash it waits for; a commit takes the lane waiting
// for it, closes the other lanes waiting for it (branches that started from
// it), hands its lane to its first parent and opens or joins a lane for each
// other parent (a merge).
export const layoutGraph = (commits: readonly Commit[]): GraphRow[] => {
  const lanes: (string | undefined)[] = []

  return commits.map(commit => {
    const before = [...lanes]
    const waiting = before.indexOf(commit.hash)
    const free = lanes.findIndex(held => held === undefined)
    const lane = waiting !== -1 ? waiting : free !== -1 ? free : lanes.length
    const closing = before.flatMap((held, at) => (held === commit.hash && at !== lane ? [at] : []))

    for (const at of closing) {
      lanes[at] = undefined
    }

    lanes[lane] = commit.parents[0]

    const opening: number[] = []
    const joining: number[] = []

    for (const parent of commit.parents.slice(1)) {
      const held = lanes.findIndex((one, at) => one === parent && at !== lane)

      if (held !== -1) {
        joining.push(held)
        continue
      }

      const spare = lanes.findIndex((one, at) => one === undefined && at !== lane)
      const at = spare !== -1 ? spare : lanes.length
      lanes[at] = parent
      opening.push(at)
    }

    while (lanes.length > 0 && lanes[lanes.length - 1] === undefined) {
      lanes.pop()
    }

    const width = Math.max(before.length, lanes.length, lane + 1)
    const reached = [...closing, ...opening, ...joining]
    const cells: Span[] = []

    const push = (color: string, text: string): void => {
      const last = cells[cells.length - 1]

      if (last !== undefined && last[0] === color) {
        last[1] += text
      } else {
        cells.push([color, text])
      }
    }

    for (let at = 0; at < width; at += 1) {
      // A connector runs along the row from the commit's lane to each lane it reaches.
      const crossing = reached.find(to => at > Math.min(lane, to) && at < Math.max(lane, to))
      const filling = reached.find(to => at >= Math.min(lane, to) && at < Math.max(lane, to))
      const glyph =
        at === lane
          ? '●'
          : closing.includes(at)
            ? at > lane
              ? '╯'
              : '╰'
            : opening.includes(at)
              ? at > lane
                ? '╮'
                : '╭'
              : joining.includes(at)
                ? at > lane
                  ? '┤'
                  : '├'
                : before[at] !== undefined
                  ? '│'
                  : crossing !== undefined
                    ? '─'
                    : ' '

      push(
        glyph === ' ' ? '' : glyph === '─' && crossing !== undefined ? laneColor(crossing) : laneColor(at),
        glyph,
      )
      push(filling === undefined ? '' : laneColor(filling), filling === undefined ? ' ' : '─')
    }

    // The lanes still open under this commit, drawn on a row of their own so
    // each dot is joined to the next one down its lane.
    const below: Span[] = []

    lanes.forEach((held, at) => {
      const color = held === undefined ? '' : laneColor(at)
      const last = below[below.length - 1]

      if (last !== undefined && last[0] === color) {
        last[1] += held === undefined ? '  ' : '│ '
      } else {
        below.push([color, held === undefined ? '  ' : '│ '])
      }
    })

    return { ...commit, cells, below, width: width * 2, lane }
  })
}

export const sumStats = (stats: readonly LineStat[]): LineStat =>
  stats.reduce<LineStat>((sum, one) => [sum[0] + one[0], sum[1] + one[1]], [0, 0])

// ---------------------------------------------------------------------------
// The commands. Each takes the `run` its caller holds and the folder under
// review, and answers in the pane's own terms; none rejects.
// ---------------------------------------------------------------------------

// The most commits the graph reads. Only the rows in view are drawn, so the
// limit is on what git prints and the module holds, not on the pane.
export const GRAPH_COMMITS = 5000

// The row that stands for what is not committed yet: a commit of the graph's
// own making whose parent is the commit checked out, so it is laid out in a
// lane that runs down to that commit like any other child of it.
export const UNCOMMITTED = '*'
const UNCOMMITTED_COLOR = '#8b949e'

export type Stash = Scan['stashes'][number]

// `git worktree list --porcelain`: a block per worktree, its folder first,
// then its commit and the branch it has checked out (none when detached).
export const parseWorktrees = (out: string): { path: string; branch: string; head: string }[] =>
  out
    .split(/\n\s*\n/)
    .map(block => ({
      path: /^worktree (.+)$/m.exec(block)?.[1] ?? '',
      branch: /^branch refs\/heads\/(.+)$/m.exec(block)?.[1] ?? '',
      head: /^HEAD ([0-9a-f]+)$/m.exec(block)?.[1] ?? '',
    }))
    .filter(one => one.path !== '')

// Exports a commit ($1, its short hash $2) of the folder it runs in to a
// temporary folder and prints that folder's real path. A repo folder keeps
// this export and the one named by $3 (the comparison's other side, when it
// is a commit too); older ones are removed. Nothing in the repo or its .git
// changes, which a `git worktree` would.
const EXPORT_BASE = [
  'root="${TMPDIR:-/tmp}/lens-base"',
  'name=$(basename "$PWD")',
  'dir="$root/$name-$2"',
  'if [ ! -d "$dir" ]; then',
  '  mkdir -p "$root" || exit 1',
  // Only what is inside the folder: `find` would otherwise offer the folder
  // itself, whose name a repo's can match (a repo called "lens", "lens-base").
  '  find "$root" -mindepth 1 -maxdepth 1 -name "$name-*" ! -name "$name-$2" ! -name "$name-${3:-$2}" -exec rm -rf {} +',
  '  mkdir "$dir.partial" && git archive "$1" | tar -x -C "$dir.partial" && mv "$dir.partial" "$dir" || exit 1',
  'fi',
  'cd "$dir" && pwd -P',
].join('\n')

const lines = (out: string): string[] => out.split('\n').filter(line => line !== '')

// The real path of the folder a person named (`~` and all), when it is inside
// a git repository; '' when it is not. A shell resolves it, and the folder
// rides as an argument.
export const findRepo = async (run: Run, folder: string): Promise<string> => {
  const resolved = await run([
    'sh',
    '-c',
    'case "$1" in "~"*) set -- "$HOME${1#\\~}";; esac; cd "$1" && git rev-parse --git-dir >/dev/null && pwd -P',
    'sh',
    folder,
  ])

  return resolved.exitCode !== 0 ? '' : resolved.stdout.trim()
}

// The real path of a folder a person named (`~` and all), whether or not git
// knows it; '' when there is no such folder.
export const findFolder = async (run: Run, folder: string): Promise<string> => {
  const resolved = await run([
    'sh',
    '-c',
    'case "$1" in "~"*) set -- "$HOME${1#\\~}";; esac; cd "$1" && pwd -P',
    'sh',
    folder,
  ])

  return resolved.exitCode !== 0 ? '' : resolved.stdout.trim()
}

// The most files listed of a folder git does not know.
export const PLAIN_FILES = 5000

// The folders left out of such a list: what tools make, never read by hand.
const MADE_FOLDERS = [
  '.git',
  'node_modules',
  '.venv',
  'venv',
  '__pycache__',
  '.terraform',
  '.mypy_cache',
  '.ruff_cache',
  '.pytest_cache',
  '.tox',
  '.next',
  '.cache',
]

const FIND_FILES = `find . \\( ${MADE_FOLDERS.map(name => `-name ${name}`).join(' -o ')} \\) -prune -o -type f ! -name .DS_Store -print`

// Whether git's answer says the folder is in no repository, which is not the
// same as git failing there.
const isOutside = (ran: { exitCode: number; stderr: string }): boolean =>
  ran.exitCode !== 0 && /not a git repository/i.test(ran.stderr)

// The files of a folder git does not know, sorted, the folders tools make
// left out; the first `PLAIN_FILES` of a larger folder.
export const folderFiles = async (run: Run, folder: string): Promise<string[]> =>
  lines(
    (
      await run(
        ['sh', '-c', `${FIND_FILES} 2>/dev/null | head -n ${PLAIN_FILES} | sed 's|^\\./||' | sort`],
        { cwd: folder, timeoutMs: 60_000 },
      )
    ).stdout,
  )

// The history as the graph draws it: the uncommitted row first (where there
// is anything uncommitted: `hasPending`), then the commits, laid out in lanes. The uncommitted row's lane is drawn grey down
// to the commit checked out, where the branch's own colour takes over: its
// cell is the first of each row until then.
export const layoutHistory = (
  commits: readonly Commit[],
  checkedOut: string,
  hasPending = true,
): GraphRow[] => {
  if (!hasPending) {
    return layoutGraph([...commits])
  }

  const laidOut = layoutGraph([
    {
      hash: UNCOMMITTED,
      parents: checkedOut === '' ? [] : [checkedOut],
      refs: [],
      subject: '',
      when: '',
      author: '',
    },
    ...commits,
  ])
  const headAt = laidOut.findIndex(row => row.hash === checkedOut)
  const pendingColor = laneColor(laidOut[0]?.lane ?? 0)
  const grey = (cells: Span[]): Span[] =>
    cells.map((cell, at): Span =>
      at === 0 && cell[0] === pendingColor ? [UNCOMMITTED_COLOR, cell[1]] : cell,
    )

  return laidOut.map((row, at) =>
    at < headAt || (headAt === -1 && at === 0)
      ? { ...row, cells: grey(row.cells), below: grey(row.below) }
      : row,
  )
}

// What git alone can say of a comparison: the files that differ and where,
// their line counts, what is checked out, what is not committed, the stashes
// and the whole history. `refusal` is git's reason when the comparison itself
// could not be read, and absent when it was.
export type Changes = {
  files: ChangedFile[]
  changed: Record<string, LineRange[]>
  stats: Record<string, LineStat>
  branches: string[]
  head: string
  headHash: string
  dirty: string[]
  stashes: Stash[]
  worktrees: Scan['worktrees']
  history: GraphRow[]
  // Whether the folder is in no git repository: nothing is compared then,
  // and its files are listed as they stand.
  isPlain: boolean
  refusal?: string
}

// Reads the comparison of `base` with the working tree, or, when `target`
// names a commit, of the two commits with each other: git then diffs the
// pair, and nothing of the working tree (its untracked files, its edits)
// counts.
export const readChanges = async (
  run: Run,
  repo: string,
  base: string,
  target: string,
): Promise<Changes> => {
  const sides = target === '' ? [base] : [base, target]
  const git = (argv: string[]) => run(['git', ...argv], { cwd: repo, timeoutMs: 60_000 })

  if (isOutside(await git(['rev-parse', '--git-dir']))) {
    return {
      files: [],
      changed: {},
      stats: {},
      branches: [],
      head: '',
      headHash: '',
      dirty: [],
      stashes: [],
      worktrees: [],
      history: [],
      isPlain: true,
    }
  }

  const [named, untracked, hunks, numstat, log, branches, head, headHash, dirty, stashes, trees, top, prefix] =
    await Promise.all([
      git(['diff', '--name-status', '--relative', ...sides]),
      git(['ls-files', '--others', '--exclude-standard']),
      git(['diff', '-U0', '--no-prefix', '--relative', ...sides]),
      git(['diff', '--numstat', '--no-renames', '--relative', ...sides]),
      // Children before parents, which the lane layout relies on.
      git([
        'log',
        '--branches',
        'HEAD',
        '--topo-order',
        '-n',
        String(GRAPH_COMMITS),
        '--pretty=format:%h%x01%p%x01%D%x01%s%x01%ar%x01%an',
      ]),
      git(['branch', '--format=%(refname:short)']),
      // The branch checked out, or "HEAD" when detached; and its commit.
      git(['rev-parse', '--abbrev-ref', 'HEAD']),
      git(['rev-parse', '--short', 'HEAD']),
      // What is edited but not committed, whatever the base is.
      git(['diff', '--name-only', '--relative', 'HEAD']),
      // Each stash with its parents (the first is the commit it was made on)
      // and how long ago.
      git(['stash', 'list', '--format=%gd%x01%gs%x01%p%x01%ar']),
      // The repo's worktrees, and where the folder under review sits in its own.
      git(['worktree', 'list', '--porcelain']),
      git(['rev-parse', '--show-toplevel']),
      git(['rev-parse', '--show-prefix']),
    ])
  // Each worktree is reviewed at the same folder of it as this one is.
  const inside = prefix.stdout.trim().replace(/\/$/, '')
  const worktrees = parseWorktrees(trees.stdout).map(one => ({
    path: inside === '' ? one.path : `${one.path}/${inside}`,
    branch: one.branch,
    head: one.head,
    isCurrent: one.path === top.stdout.trim(),
  }))
  // A worktree kept inside the repo is a checkout of its own, not new files
  // of this one: git lists its folder as untracked, and it is left out.
  const nested = parseWorktrees(trees.stdout)
    .map(one => one.path)
    .filter(path => path !== top.stdout.trim())
  const newFiles = parseUntracked(target === '' ? untracked.stdout : '').filter(one => {
    const whole = `${repo}/${one.path}`.replace(/\/$/, '')

    return !nested.some(path => whole === path || whole.startsWith(`${path}/`))
  })
  // git counts lines only for files it tracks; a new file's are all added.
  const counted =
    newFiles.length === 0
      ? { stdout: '' }
      : await run(
          [
            'sh',
            '-c',
            'wc -l -- "$@" 2>/dev/null',
            'sh',
            ...newFiles.map(one => one.path).slice(0, FILE_LIMIT),
          ],
          { cwd: repo, timeoutMs: 60_000 },
        )

  return {
    files: [...parseNameStatus(named.stdout), ...newFiles],
    changed: parseChangedLines(hunks.stdout),
    stats: { ...parseLineCounts(counted.stdout), ...parseNumstat(numstat.stdout) },
    branches: branches.stdout.split('\n').filter(name => name !== '' && !name.startsWith('(')),
    head: head.stdout.trim(),
    headHash: headHash.stdout.trim(),
    dirty: target === '' ? lines(dirty.stdout) : [],
    stashes: lines(stashes.stdout).map(line => {
      const [ref = '', subject = '', parents = '', when = ''] = line.split('\u0001')

      return { ref, subject, base: parents.split(' ')[0] ?? '', when }
    }),
    worktrees,
    history: layoutHistory(
      parseCommits(log.stdout),
      headHash.stdout.trim(),
      // A working tree with nothing edited and nothing new has no row of its own.
      lines(dirty.stdout).length > 0 ||
        parseUntracked(untracked.stdout).some(one => {
          const whole = `${repo}/${one.path}`.replace(/\/$/, '')

          return !nested.some(path => whole === path || whole.startsWith(`${path}/`))
        }),
    ),
    isPlain: false,
    ...(named.exitCode !== 0 ? { refusal: tail(named.stderr) } : {}),
  }
}

// Prints a commit holding a worktree's files as they stand: what it has
// checked out, with its uncommitted edits and its untracked files. The
// commit is built through an index of its own and belongs to no branch, so
// nothing of the worktree changes: not its files, its index or its HEAD.
// Worktrees kept inside it are left out, being checkouts of their own.
const SNAPSHOT = [
  'top=$(git rev-parse --show-toplevel) && cd "$top" || exit 1',
  'head=$(git rev-parse HEAD) || exit 1',
  'index=$(mktemp) || exit 1',
  'git worktree list --porcelain | sed -n "s/^worktree //p" > "$index.trees"',
  'set -- .',
  'while IFS= read -r tree; do',
  '  case "$tree" in "$top"/*) set -- "$@" ":(exclude)${tree#"$top"/}";; esac',
  'done < "$index.trees"',
  'rm -f "$index" "$index.trees"',
  'export GIT_INDEX_FILE="$index"',
  'git read-tree HEAD && git add -A -- "$@" && tree=$(git write-tree)',
  'status=$?',
  'rm -f "$index"',
  'unset GIT_INDEX_FILE',
  '[ "$status" -eq 0 ] || exit 1',
  'git -c user.name=lens -c user.email=lens@localhost commit-tree "$tree" -p "$head" -m "lens: a worktree as it stands"',
].join('\n')

// A commit of a worktree's files as they stand (see SNAPSHOT), by its hash;
// '' with git's reason where it could not be made.
export const snapshotWorktree = async (
  run: Run,
  path: string,
): Promise<{ hash: string; refusal: string }> => {
  const made = await run(['sh', '-c', SNAPSHOT], { cwd: path, timeoutMs: 120_000 })
  const hash = made.stdout.trim()

  return made.exitCode === 0 && /^[0-9a-f]{40,}$/.test(hash)
    ? { hash, refusal: '' }
    : { hash: '', refusal: tail(made.stderr) || 'git made no snapshot' }
}

// The repo a folder's worktree belongs to, by the path of its main
// checkout; the folder's own repo root when it is that one. '' outside a repo.
export const mainRepoOf = async (run: Run, repo: string): Promise<string> => {
  const asked = await run(['git', 'rev-parse', '--path-format=absolute', '--git-common-dir'], {
    cwd: repo,
    timeoutMs: 20_000,
  })

  return asked.exitCode === 0 ? asked.stdout.trim().replace(/\/\.git\/?$/, '') : ''
}

// What the branch checked out has changed since it forked from the branch
// its request targets: the commit it forked at ('' when git cannot say),
// the files, and their line counts.
export const requestChanges = async (
  run: Run,
  repo: string,
  baseRef: string,
): Promise<{ base: string; files: ChangedFile[]; stats: Record<string, LineStat> }> => {
  const git = (argv: string[]) => run(['git', ...argv], { cwd: repo, timeoutMs: 60_000 })
  // The remote's copy of the target is the truer one; a local branch may lag.
  const remote = await git(['merge-base', 'HEAD', `origin/${baseRef}`])
  const forked = remote.exitCode === 0 ? remote : await git(['merge-base', 'HEAD', baseRef])
  const base = forked.exitCode === 0 ? forked.stdout.trim() : ''

  if (base === '') {
    return { base, files: [], stats: {} }
  }

  const [named, numstat] = await Promise.all([
    git(['diff', '--name-status', '--relative', base, 'HEAD']),
    git(['diff', '--numstat', '--no-renames', '--relative', base, 'HEAD']),
  ])

  return { base, files: parseNameStatus(named.stdout), stats: parseNumstat(numstat.stdout) }
}

// A short mark of how the repo stands: what is checked out, what is edited,
// staged or new, the stashes and the worktrees. It changes when any of them
// does, whoever made the change; '' where git does not answer. A folder git
// does not know is marked by its files: their names, sizes and times.
export const repoMark = async (run: Run, repo: string): Promise<string> => {
  const asked = await run(
    [
      'sh',
      '-c',
      `if git rev-parse --git-dir >/dev/null 2>&1; then { git rev-parse HEAD; git symbolic-ref -q HEAD; git status --porcelain; git diff --numstat HEAD; git stash list; git worktree list; } 2>/dev/null; else ${FIND_FILES} 2>/dev/null | head -n ${PLAIN_FILES} | tr '\\n' '\\0' | xargs -0 ls -ln 2>/dev/null; fi | cksum`,
    ],
    { cwd: repo, timeoutMs: 15_000 },
  )

  return asked.exitCode === 0 ? asked.stdout.trim() : ''
}

// The files git tracks in the repo, or only those matching the patterns.
export const trackedFiles = async (
  run: Run,
  repo: string,
  patterns: readonly string[] = [],
): Promise<string[]> =>
  lines(
    (
      await run(['git', 'ls-files', ...(patterns.length === 0 ? [] : ['--', ...patterns])], {
        cwd: repo,
        timeoutMs: 60_000,
      })
    ).stdout,
  )

// A ref's commit by its short hash, and in full; '' for a ref git does not know.
export const shortHash = async (run: Run, repo: string, ref: string): Promise<string> =>
  (await run(['git', 'rev-parse', '--short', ref], { cwd: repo, timeoutMs: 60_000 })).stdout.trim()

export const fullHash = async (run: Run, repo: string, ref: string): Promise<string> =>
  (await run(['git', 'rev-parse', ref], { cwd: repo, timeoutMs: 60_000 })).stdout.trim()

// Whether a name is a branch, tag or commit here.
export const isCommit = async (run: Run, repo: string, name: string): Promise<boolean> =>
  (await run(['git', 'rev-parse', '--verify', '--quiet', `${name}^{commit}`], { cwd: repo }))
    .exitCode === 0

// A commit's files as a folder of their own, outside the repo: `dir` is its
// real path, or '' with the reason in `refusal`. `short` names the folder;
// the export of `keep` (the comparison's other side) is left in place, older
// ones are removed.
export const exportCommit = async (
  run: Run,
  repo: string,
  ref: string,
  short: string,
  keep: string,
): Promise<{ dir: string; refusal: string }> => {
  const exported = await run(['sh', '-c', EXPORT_BASE, 'sh', ref, short, keep], {
    cwd: repo,
    timeoutMs: 120_000,
  })
  const dir = exported.stdout.trim()

  return exported.exitCode !== 0 || dir === ''
    ? { dir: '', refusal: tail(exported.stderr) || 'no export' }
    : { dir, refusal: '' }
}

// A file as a commit left it; empty when the commit deleted it. A stash's
// untracked files live in its third parent, so that is tried next.
export const fileAt = async (
  run: Run,
  repo: string,
  path: string,
  commit: string,
): Promise<string> => {
  const shownAt = async (at: string): Promise<string | undefined> => {
    const shown = await run(['git', 'show', `${at}:./${path}`], { cwd: repo })

    return shown.exitCode === 0 ? shown.stdout : undefined
  }

  return (
    (await shownAt(commit)) ??
    (commit.startsWith('stash@') ? await shownAt(`${commit}^3`) : undefined) ??
    ''
  )
}

// What the diff view interleaves for one file: the lines the other side had
// (`removed`), and, for a file read at a commit, the lines that commit's side
// changed (the working tree's come with `readChanges`).
//
// The working tree's file (`commit` '') and a file read at the comparison's
// own `target` are diffed against the base; at any other commit, against its
// parent.
export const fileDiff = async (
  run: Run,
  repo: string,
  path: string,
  commit: string,
  base: string,
  target: string,
  // Whether the working tree's file wants its changed lines from this diff
  // too: its base is then not the one the scan compared with.
  isOwn = false,
): Promise<{
  removed: Record<number, string[]>
  removedAt: Record<number, number>
  changed: LineRange[] | undefined
}> => {
  const diff = await run(
    commit === ''
      ? ['git', 'diff', '-U0', '--no-prefix', '--relative', base, '--', path]
      : commit === target
        ? ['git', 'diff', '-U0', '--no-prefix', '--relative', base, commit, '--', path]
        : [
            'git',
            'show',
            '--format=',
            '-U0',
            '--no-prefix',
            '--relative',
            '--diff-merges=first-parent',
            commit,
            '--',
            path,
          ],
    { cwd: repo },
  )

  return {
    removed: parseRemoved(diff.stdout),
    removedAt: parseRemovedAt(diff.stdout),
    changed:
      commit === '' && !isOwn ? undefined : (parseChangedLines(diff.stdout)[path] ?? []),
  }
}

// What a commit or a stash (`stash@{0}`) holds: its message and the files it
// changed, with their line counts.
export const commitDetails = async (run: Run, repo: string, hash: string): Promise<Picked> => {
  // A stash keeps its untracked files in a commit of their own, which only
  // `git stash show` knows to include.
  const show = (format: string) =>
    run(
      hash.startsWith('stash@')
        ? ['git', 'stash', 'show', '--include-untracked', '--no-renames', '--relative', format, hash]
        : [
            'git',
            'show',
            '--format=',
            '--no-renames',
            '--relative',
            '--diff-merges=first-parent',
            format,
            hash,
          ],
      { cwd: repo },
    )
  // The graph's row has room for the subject alone; the rest of the message
  // is read here and shown when the commit is opened.
  const [named, counted, message] = await Promise.all([
    show('--name-status'),
    show('--numstat'),
    run(['git', 'log', '-1', '--format=%s%n%b', hash], { cwd: repo }),
  ])
  const [subject = '', ...rest] = message.stdout.split('\n')

  return {
    hash,
    files: parseNameStatus(named.stdout),
    stats: parseNumstat(counted.stdout),
    subject: subject.trim(),
    body: rest.join('\n').trim(),
  }
}

// Who last changed a line: the commit's short hash ('' for a line not
// committed yet), its author, how long ago, and its subject.
export type Blamed = { hash: string; author: string; age: string; summary: string }

// Who last changed each line of a file, as a commit left it or (`commit` '')
// as the working tree has it. A file git has never had committed has no
// history to blame: every line of it is new, which an empty list stands for.
// `now` is asked for the time, in milliseconds, once git has answered.
export const blame = async (
  run: Run,
  repo: string,
  path: string,
  commit: string,
  now: () => Promise<number>,
): Promise<{ lines: Blamed[] } | { refusal: string }> => {
  const ran = await run(
    ['git', 'blame', '--porcelain', ...(commit === '' ? [] : [commit]), '--', path],
    { cwd: repo, timeoutMs: 60_000 },
  )

  if (ran.exitCode !== 0) {
    return /no such path/i.test(ran.stderr) ? { lines: [] } : { refusal: tail(ran.stderr) }
  }

  const seconds = (await now()) / 1000

  return {
    lines: parseBlame(ran.stdout).map(line => ({
      hash: /^0+$/.test(line.hash) ? '' : line.hash.slice(0, 7),
      author: line.author,
      age: ageOf(Math.max(0, seconds - line.time)),
      summary: line.summary,
    })),
  }
}

// The remote branches that already hold the commit checked out: none when it
// has not been pushed.
export const remotesWithHead = async (run: Run, repo: string): Promise<string[]> =>
  (await run(['git', 'branch', '-r', '--contains', 'HEAD'], { cwd: repo })).stdout
    .split('\n')
    .map(line => line.trim())
    .filter(line => line !== '')

// The commands that change the repo answer '' when git did it, and otherwise
// why not, in words fit to show: git's own last ones.
const act = async (run: Run, repo: string, argv: string[]): Promise<string> => {
  const ran = await run(['git', ...argv], { cwd: repo, timeoutMs: 120_000 })

  return ran.exitCode !== 0
    ? `git ${argv[0] ?? ''} did not go through: ${tail(ran.stderr || ran.stdout)}`
    : ''
}

// Commits the given files and nothing else: each is added first, so a new or
// deleted file is taken too, and the commit names them, so anything staged
// beside them stays staged and uncommitted.
export const commit = async (
  run: Run,
  repo: string,
  paths: readonly string[],
  message: string,
  body: string,
): Promise<string> => {
  const added = await run(['git', 'add', '--', ...paths], { cwd: repo })

  if (added.exitCode !== 0) {
    return `git add did not go through: ${tail(added.stderr)}`
  }

  // A second -m is the commit's body, set off from the subject by a blank line.
  return act(run, repo, [
    'commit',
    '-m',
    message.trim(),
    ...(body.trim() === '' ? [] : ['-m', body.trim()]),
    '--',
    ...paths,
  ])
}

// Stashes the given files, the untracked ones among them included.
export const stash = (
  run: Run,
  repo: string,
  paths: readonly string[],
  label: string,
): Promise<string> =>
  act(run, repo, ['stash', 'push', '--include-untracked', '-m', label, '--', ...paths])

// Brings a stash back, keeping it (apply) or removing it (pop).
export const restoreStash = (run: Run, repo: string, ref: string, isPop: boolean): Promise<string> =>
  act(run, repo, ['stash', isPop ? 'pop' : 'apply', ref])

// Takes the last commit back and keeps what it changed, as uncommitted edits.
export const undoLastCommit = (run: Run, repo: string): Promise<string> =>
  act(run, repo, ['reset', '--soft', 'HEAD~1'])

// Throws away the uncommitted changes in the given files, which cannot be
// undone: `tracked` go back to the last commit, `staged` (added but never
// committed) and `untracked` are deleted. It stops at the first step git
// refuses.
export const discard = async (
  run: Run,
  repo: string,
  tracked: readonly string[],
  staged: readonly string[],
  untracked: readonly string[],
): Promise<string> => {
  const steps = [
    tracked.length > 0
      ? ['restore', '--staged', '--worktree', '--source=HEAD', '--', ...tracked]
      : undefined,
    staged.length > 0 ? ['rm', '-f', '--quiet', '--', ...staged] : undefined,
    untracked.length > 0 ? ['clean', '-f', '--quiet', '--', ...untracked] : undefined,
  ]
  let refusal = ''

  for (const argv of steps) {
    if (argv === undefined || refusal !== '') {
      continue
    }

    const ran = await run(['git', ...argv], { cwd: repo })

    if (ran.exitCode !== 0) {
      refusal = `git ${argv[0] ?? ''} did not go through: ${tail(ran.stderr || ran.stdout)}`
    }
  }

  return refusal
}

// Switches the repo to a branch, or to a commit with HEAD detached. Never
// forced: where git refuses (local changes it would overwrite), the working
// tree is left as it was and the answer is git's own reason.
export const checkOut = async (
  run: Run,
  repo: string,
  target: string,
  isBranch: boolean,
): Promise<string> => {
  const ran = await run(['git', 'switch', ...(isBranch ? [] : ['--detach']), target], { cwd: repo })

  return ran.exitCode !== 0 ? tail(ran.stderr) || 'git refused' : ''
}

files.hooks/lists.ts:
// What the language server answered, as the pane keeps it: lists of places
// for the list screen (uses of a name, callers, implementations, names that
// match), and the card of a looked-up name.

import type { Comment } from './review'
import type { Listing, ListRow, Lookup } from '../types'
import type { LspSymbol } from './lsp'
import type { CallNode, Place, PlaceLine, SymbolHit } from './lsp-types'
import { ISSUES_SENT } from './prompt'
import { groupPlaces, placesList, semanticColor } from './semantic'

// The most rows the list screen draws, and so the most a list holds.
export const LIST_ROWS = 300

// The colour a kind of name has in the code, for a list of names: an outline
// or a search names kinds as a symbol's, the colours are keyed by a token's.
const KIND_TOKEN = new Map([
  ['constant', 'variable'],
  ['field', 'property'],
  ['constructor', 'method'],
  ['module', 'namespace'],
])

export const kindColor = (kind: string): string =>
  semanticColor(KIND_TOKEN.get(kind) ?? kind, kind === 'constant' ? ['readonly'] : [])

// Where a list entry points, as a row: an indented line that reads
// "12: the line's text" under its file's heading.
const placeRows = (places: readonly PlaceLine[], current: string): ListRow[] =>
  groupPlaces(places, current).files.flatMap(group => [
    { label: `${group.path}  (${group.places.length})`, path: '', line: 0 },
    ...group.places.map(place => ({
      label: `  ${String(place.line).padStart(4)}: ${place.text}`,
      path: place.path,
      line: place.line,
    })),
  ])

// Everywhere a name is used, the file it was asked about first; this list
// also has a form for the prompt.
export const usesList = (name: string, file: string, places: readonly PlaceLine[]): Listing => ({
  title: `${places.length} uses of ${name}`,
  rows: placeRows(places, file),
  prompt: placesList(name, places, ISSUES_SENT),
})

// Who calls a function, or what it calls.
export const callsList = (
  name: string,
  direction: 'incoming' | 'outgoing',
  calls: readonly CallNode[],
): Listing => ({
  title: direction === 'incoming' ? `What calls ${name}` : `What ${name} calls`,
  rows: calls.map(call => ({
    label: `${call.name}  ${call.place.path.split('/').slice(-2).join('/')}:${call.place.line}  ${call.detail}`,
    path: call.place.path,
    line: call.place.line,
  })),
  prompt: '',
})

// What implements an interface, abstract method or protocol.
export const implementationsList = (name: string, places: readonly Place[]): Listing => ({
  title: `What implements ${name}`,
  rows: places.map(place => ({
    label: `${place.path}:${place.line}`,
    path: place.path,
    line: place.line,
  })),
  prompt: '',
})

// Names anywhere in the project that match what was typed, each with its
// kind's mark and colour.
export const namesList = (query: string, hits: readonly SymbolHit[]): Listing => ({
  title: `Names matching "${query}"`,
  rows: hits.map(hit => ({
    label: hit.name,
    mark: '›',
    path: hit.place.path,
    line: hit.place.line,
    color: kindColor(hit.kind),
    tail: `${hit.kind}${hit.container === '' ? '' : ` in ${hit.container}`} · ${hit.place.path.split('/').slice(-2).join('/')}`,
  })),
  prompt: '',
})

// What the server said of the name at a place in a file, as the file screen
// shows it: its type and docs, where it is defined, and the call it sits in.
export const lookupOf = (
  file: string,
  name: string,
  line: number,
  col: number,
  answer: LspSymbol,
): Lookup => ({
  file,
  name,
  at: line,
  col,
  text: answer.text.replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, ''),
  path: answer.definition?.path ?? '',
  line: answer.definition?.line ?? 0,
  typePath: answer.typeDefinition?.path ?? '',
  typeLine: answer.typeDefinition?.line ?? 0,
  hasImplementations: (answer.implementations?.length ?? 0) > 0,
  // The call the name sits in, with the argument being given marked.
  signature:
    answer.signature === undefined
      ? ''
      : answer.signature.parameters.length === 0
        ? answer.signature.label
        : `(${answer.signature.parameters.map((one, index) => (index === answer.signature?.active ? `[${one}]` : one)).join(', ')})`,
})

// A review comment in one line, for a list: where, who, and how it starts.
const threadLine = (one: Comment, replies: number): string =>
  `${one.path === '' ? '' : `${one.path}${one.line > 0 ? `:${one.line}` : ''}  `}${one.author}: ${one.body.trim().replace(/\s+/g, ' ').slice(0, 90)}${replies > 0 ? `  (+${replies})` : ''}`

// Every thread of a pull or merge request: the open ones first, then the
// resolved, then what was said of the request as a whole. A thread is its
// first comment; its replies are counted. The form for the prompt is the open
// threads in full, replies and all: what is still to be answered.
export const threadsList = (request: string, comments: readonly Comment[]): Listing => {
  const roots = comments.filter(one => one.replyTo === undefined)
  const repliesTo = (root: Comment): Comment[] => comments.filter(one => one.replyTo === root.id)
  const placed = roots.filter(one => one.path !== '')
  const open = placed.filter(one => one.isResolved !== true)
  const settled = placed.filter(one => one.isResolved === true)
  const general = roots.filter(one => one.path === '')
  const rowsOf = (threads: readonly Comment[], mark: string): ListRow[] =>
    threads.map(one => ({
      label: `${mark}${threadLine(one, repliesTo(one).length)}`,
      path: one.path,
      line: Math.max(1, one.line),
    }))

  return {
    title: `${request === '' ? 'Review' : request}: ${open.length} open, ${settled.length} resolved`,
    rows: [
      ...(open.length > 0 ? [{ label: `Open (${open.length})`, path: '', line: 0 }] : []),
      ...rowsOf(open, ''),
      ...(settled.length > 0 ? [{ label: `Resolved (${settled.length})`, path: '', line: 0 }] : []),
      ...rowsOf(settled, '✓ '),
      ...(general.length > 0
        ? [{ label: `On the request as a whole (${general.length})`, path: '', line: 0 }]
        : []),
      ...general.map(one => ({ label: `  ${threadLine(one, 0)}`, path: '', line: 0 })),
    ],
    prompt:
      open.length === 0
        ? ''
        : [
            `Open review comments${request === '' ? '' : ` in ${request}`} (${open.length}):`,
            ...open.flatMap(one => [
              `- ${one.path}${one.line > 0 ? `:${one.line}` : ''} ${one.author}: ${one.body.trim().replace(/\s*\n\s*/g, ' ')}`,
              ...repliesTo(one).map(
                reply => `  - ${reply.author}: ${reply.body.trim().replace(/\s*\n\s*/g, ' ')}`,
              ),
            ]),
          ].join('\n'),
  }
}

files.hooks/lsp.ts:
// Diagnostics, symbol lookups and the other things an editor asks of its
// language server (references, callers, outline, semantic tokens, a search by
// name, inlay hints), from long-running language servers, through
// the bridge in lsp-bridge.ts. Nothing here touches the engine: the caller hands in `run`
// (its `$.process.run`), and every call is one short-lived command. The first
// call writes the bridge script to a temp folder; the script's client mode
// starts the daemon when it is not running, and the daemon keeps one server
// per language and project until it has been idle for half an hour.
import type { Diag, Severity } from '../types'
import { LSP_BRIDGE_PY } from './lsp-bridge'
import type {
  CallNode,
  InlayHint,
  OutlineItem,
  Place,
  PlaceLine,
  SemanticToken,
  Signature,
  SymbolHit,
} from './lsp-types'

export type Run = (
  argv: string[],
  init?: { cwd?: string; stdin?: string; timeoutMs?: number },
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

export type LspOptions = {
  // Where a project's virtualenv and node_modules are looked for when `repo`
  // has none: the working tree, when `repo` is an export of a commit. The
  // project's folder is the same path under it.
  envRoot?: string
  // How long the servers may take to answer, in milliseconds (two minutes).
  timeoutMs?: number
}

export type LspResult = {
  diags: Diag[]
  // The files a server answered for; the rest still need another checker.
  covered: string[]
  // Why a language's server could not be used, one line each.
  notes: string[]
}

// A diagnostic as the Language Server Protocol spells it: 0-based positions,
// the end exclusive.
export type LspDiagnostic = {
  range?: {
    start?: { line?: number; character?: number }
    end?: { line?: number; character?: number }
  }
  severity?: number
  code?: string | number
  message?: string
  // 1 is DiagnosticTag.Unnecessary: code that is never used.
  tags?: number[]
}

type BridgeAnswer = {
  ok?: boolean
  error?: string
  files?: Record<string, { tool?: string; diagnostics?: LspDiagnostic[] }>
  notes?: string[]
}

// The files the bridge has a server for whatever else is installed: Python,
// TypeScript and Terraform. `isServed` adds what its table of servers reads.
export const LSP_FILE = /\.(pyi?|[cm]?tsx?|tf|tfvars)$/i

// One server of the bridge's table (the built-in ones, and the person's own
// from ~/.claude/lens/servers.json), as its `served` answer lists them.
export type ServedBy = {
  // Also the tool its diagnostics carry.
  name: string
  // What a person calls the language, for a note.
  language: string
  // In lower case, each with its dot.
  extensions: string[]
  // Whole file names, `*` and `?` standing for anything.
  filenames: string[]
  isInstalled: boolean
  // How to get the server; '' when the table does not say.
  install: string
}

// The table as the bridge last listed it, in the order a file is matched.
// The screens ask about a file as they draw, with nothing to await, so the
// answer is kept here and a scan asks again (`lspServed`). Empty until the
// first answer: `LSP_FILE` alone is then what is served, as it was before
// there was a table.
let table: { server: ServedBy; names: RegExp[] }[] = []

// A whole file name with `*` and `?` in it, as the bridge reads one.
const namePattern = (name: string): RegExp =>
  new RegExp(
    `^${name
      .replace(/[.+^$()|[\]{}\\]/g, '\\$&')
      .replace(/\*/g, '.*')
      .replace(/\?/g, '.')}$`,
  )

// The server that reads a file, as the bridge picks it: one that is installed
// before one that is not, a file's whole name before its extension.
const serverOf = (path: string): ServedBy | undefined => {
  const name = path.slice(path.lastIndexOf('/') + 1)
  const lower = name.toLowerCase()

  for (const group of [table.filter(one => one.server.isInstalled), table]) {
    const found =
      group.find(one => one.names.some(pattern => pattern.test(name))) ??
      group.find(one => one.server.extensions.some(extension => lower.endsWith(extension)))

    if (found !== undefined) {
      return found.server
    }
  }

  return undefined
}

// Whether a file that is not Python, TypeScript or Terraform is read by a
// server of the table that is installed.
export const isOtherServed = (path: string): boolean =>
  !LSP_FILE.test(path) && serverOf(path)?.isInstalled === true

// Whether the bridge has a server for a file.
export const isServed = (path: string): boolean => LSP_FILE.test(path) || isOtherServed(path)

// The names of the table's installed servers: the tools their diagnostics carry.
export const servedTools = (): string[] =>
  table.filter(one => one.server.isInstalled).map(one => one.server.name)

// For the files a server of the table would read were it installed: one line
// for each such server, saying what to install.
export const unservedNotes = (paths: readonly string[]): string[] => {
  const notes = new Set<string>()

  for (const path of paths) {
    const server = LSP_FILE.test(path) ? undefined : serverOf(path)

    if (server !== undefined && !server.isInstalled) {
      notes.add(
        `${server.language} is not checked: ${server.name} is not installed${server.install === '' ? '' : ` (${server.install})`}`,
      )
    }
  }

  return [...notes]
}

// DiagnosticTag.Unnecessary.
const UNNECESSARY = 1

const SEVERITY: Record<number, Severity> = { 1: 'error', 2: 'warning', 3: 'info', 4: 'info' }

// One protocol diagnostic of `path`, as the pane keeps them: 1-based, and
// `endCol` only when the range ends on the line it starts on.
export const toDiag = (path: string, tool: string, item: LspDiagnostic): Diag => {
  const start = item.range?.start
  const end = item.range?.end
  const line = start?.line ?? 0

  const diag: Diag = {
    path,
    line: line + 1,
    col: (start?.character ?? 0) + 1,
    endCol: end?.line === line && end.character !== undefined ? end.character + 1 : 0,
    severity: SEVERITY[item.severity ?? 1] ?? 'info',
    tool,
    rule: item.code === undefined ? '' : String(item.code),
    message: item.message ?? '',
  }

  if (Array.isArray(item.tags) && item.tags.includes(UNNECESSARY)) {
    diag.isUnused = true
  }

  return diag
}

const byPlace = (a: Diag, b: Diag): number =>
  a.path < b.path ? -1 : a.path > b.path ? 1 : a.line - b.line || a.col - b.col

const failed = (why: string): LspResult => ({
  diags: [],
  covered: [],
  notes: [`language servers did not answer: ${why}`],
})

const lastLine = (text: string): string => text.trim().split('\n').pop()?.slice(0, 200) ?? ''

// What the bridge's client printed, as diagnostics. Anything but its JSON
// answer (the command failed, or its output was cut) covers no file and says
// why in a note, so every file falls back to the other checkers.
export const parseBridge = (stdout: string, stderr = ''): LspResult => {
  let answer: BridgeAnswer | undefined

  try {
    answer = JSON.parse(stdout) as BridgeAnswer
  } catch {
    answer = undefined
  }

  if (answer === undefined || answer === null || typeof answer !== 'object') {
    return failed(lastLine(stderr) || lastLine(stdout) || 'no output')
  }

  if (answer.ok !== true) {
    return failed(answer.error ?? 'no reason given')
  }

  const diags: Diag[] = []
  const covered: string[] = []

  for (const [path, file] of Object.entries(answer.files ?? {})) {
    covered.push(path)

    for (const item of file.diagnostics ?? []) {
      diags.push(toDiag(path, file.tool ?? '', item))
    }
  }

  return {
    diags: diags.sort(byPlace),
    covered: covered.sort(),
    notes: (answer.notes ?? []).map(String),
  }
}

// Writes the script on stdin to this user's bridge folder (the socket, lock
// and log live beside it) and prints its path. Written under another name
// first, so a client never reads half a script.
const INSTALL = [
  'd="/tmp/lens-lsp-$(id -u)"',
  'mkdir -p -m 700 "$d" && [ -O "$d" ] || exit 1',
  'cat > "$d/bridge.py.$$" && mv "$d/bridge.py.$$" "$d/bridge.py" && printf %s "$d/bridge.py"',
].join('\n')

// uv picks a Python whatever the folder pins; the system's is the fallback.
const PYTHON =
  'command -v uv >/dev/null 2>&1 && exec uv run --no-project python "$@"; exec python3 "$@"'

// The script's path, per `run` it was written with: a caller that keeps one
// `run` writes the script once per load of the module, and one that makes a
// new `run` each time writes it each time (a few milliseconds). A script that
// differs from the one a running daemon was started from makes the client
// replace that daemon, so an update takes effect on the next call.
const installed = new WeakMap<Run, Promise<string>>()

const install = (run: Run): Promise<string> => {
  const known = installed.get(run)

  if (known !== undefined) {
    return known
  }

  const writing = run(['sh', '-c', INSTALL], { stdin: LSP_BRIDGE_PY, timeoutMs: 10_000 }).then(
    ran => {
      const path = ran.stdout.trim()

      if (ran.exitCode !== 0 || !path.endsWith('/bridge.py')) {
        throw new Error(`could not write the bridge script: ${lastLine(ran.stderr) || 'no output'}`)
      }

      return path
    },
  )
  installed.set(run, writing)
  // A failure is not remembered: the next call tries again.
  writing.catch(() => {
    installed.delete(run)
  })

  return writing
}

const bridge = async (
  run: Run,
  mode: 'query' | 'symbol' | 'ask' | 'served' | 'stop',
  request: object,
  timeoutMs: number,
): Promise<{ exitCode: number; stdout: string; stderr: string }> => {
  const script = await install(run)

  return run(['sh', '-c', PYTHON, 'sh', script, mode], {
    cwd: script.slice(0, script.lastIndexOf('/')),
    stdin: JSON.stringify(request),
    timeoutMs,
  })
}

// Diagnostics for `files` (paths relative to `repo`, an absolute real path)
// from the language servers that cover them. Never rejects: a bridge that
// cannot run covers nothing and says why in `notes`.
export const lspDiagnostics = async (
  run: Run,
  repo: string,
  files: readonly string[],
  options: LspOptions = {},
): Promise<LspResult> => {
  const wanted = files.filter(isServed)

  if (wanted.length === 0) {
    return { diags: [], covered: [], notes: [] }
  }

  const timeoutMs = options.timeoutMs ?? 120_000

  try {
    const ran = await bridge(
      run,
      'query',
      { repo, files: wanted, envRoot: options.envRoot, timeout: timeoutMs / 1000 },
      // The client gives the daemon a little longer than the servers get.
      Math.min(timeoutMs + 45_000, 600_000),
    )

    return parseBridge(ran.stdout, ran.stderr)
  } catch (error) {
    return failed(error instanceof Error ? error.message : String(error))
  }
}

const stringsOf = (value: unknown): string[] =>
  Array.isArray(value) ? value.filter((one): one is string => typeof one === 'string') : []

// What the bridge's client printed for `served`: its table and its notes, or
// undefined for anything but its JSON answer.
export const parseServed = (stdout: string): { servers: ServedBy[]; notes: string[] } | undefined => {
  let answer: { ok?: unknown; servers?: unknown; notes?: unknown } | null | undefined

  try {
    answer = JSON.parse(stdout) as typeof answer
  } catch {
    answer = undefined
  }

  if (answer === undefined || answer === null || answer.ok !== true || !Array.isArray(answer.servers)) {
    return undefined
  }

  const servers: ServedBy[] = []

  for (const one of answer.servers as Partial<Record<keyof ServedBy, unknown>>[]) {
    if (one !== null && typeof one === 'object' && typeof one.name === 'string' && one.name !== '') {
      servers.push({
        name: one.name,
        language: typeof one.language === 'string' && one.language !== '' ? one.language : one.name,
        extensions: stringsOf(one.extensions).map(extension => extension.toLowerCase()),
        filenames: stringsOf(one.filenames),
        isInstalled: one.isInstalled === true,
        install: typeof one.install === 'string' ? one.install : '',
      })
    }
  }

  return { servers, notes: stringsOf(answer.notes) }
}

// Asks the bridge for its table of servers and keeps it, for `isServed` and
// the rest above to answer from. Resolves with what is wrong with the
// person's config file, one line for each entry left out. Never rejects: a
// bridge that cannot answer leaves the table as it was, and says nothing
// (the next thing asked of it says why).
export const lspServed = async (run: Run): Promise<string[]> => {
  try {
    const answer = parseServed((await bridge(run, 'served', {}, 20_000)).stdout)

    if (answer === undefined) {
      return []
    }

    table = answer.servers.map(server => ({ server, names: server.filenames.map(namePattern) }))

    return answer.notes
  } catch {
    return []
  }
}

// Whether the servers' keeper is already up: one that is not has to start,
// and its servers with it, before the first answer comes.
export const lspIsRunning = async (run: Run): Promise<boolean> =>
  run(['sh', '-c', 'test -S "/tmp/lens-lsp-$(id -u)/bridge.sock"'], { timeoutMs: 5000 }).then(
    ran => ran.exitCode === 0,
    () => false,
  )

// Stops the servers of the projects at or under `root` (an export that is
// about to be deleted), or, with no root, the daemon and every server. A
// daemon that is not running is left that way.
export const stopLsp = async (run: Run, root?: string): Promise<void> => {
  try {
    await bridge(run, 'stop', root === undefined ? {} : { root }, 40_000)
  } catch {
    // Nothing to stop, or nothing to stop it with.
  }
}

// What a language server knows about the symbol at one place.
export type LspSymbol = {
  // Plain text: the signature or type as the server writes it, then a blank
  // line and the docs when there are any. '' when the server has nothing.
  text: string
  // Where the symbol is declared, when the server can say: 1-based, and
  // `path` relative to the repo when it is inside it, else absolute.
  definition?: { path: string; line: number; col: number; isInRepo: boolean }
  // The call the place is inside the arguments of, when it is in one.
  signature?: Signature
  // Where the symbol's type is declared, when that is not `definition`.
  typeDefinition?: Place
  // What implements it, for an interface, an abstract method or a protocol
  // (at most 50). Left out when the server knows of none.
  implementations?: Place[]
  // Why nothing came back: no server for the language, not installed, timed
  // out. Empty when the server answered, even with nothing (no symbol there).
  notes: string[]
}

type SymbolAnswer = {
  ok?: boolean
  error?: string
  text?: unknown
  definition?: { path?: unknown; line?: unknown; col?: unknown; isInRepo?: unknown }
  signature?: unknown
  typeDefinition?: unknown
  implementations?: unknown
  notes?: unknown[]
}

const noSymbol = (why: string): LspSymbol => ({
  text: '',
  notes: [`language server did not answer: ${why}`],
})

const isPlace = (value: unknown): value is number =>
  typeof value === 'number' && Number.isInteger(value) && value >= 1

const fields = (value: unknown): Record<string, unknown> | undefined =>
  value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined

const listOf = (value: unknown): unknown[] => (Array.isArray(value) ? value : [])

const textOf = (value: unknown): string => (typeof value === 'string' ? value : '')

// A whole place of an answer, or undefined when a part of it is missing.
const toPlace = (value: unknown): Place | undefined => {
  const at = fields(value)

  if (
    at === undefined ||
    typeof at.path !== 'string' ||
    at.path === '' ||
    !isPlace(at.line) ||
    !isPlace(at.col)
  ) {
    return undefined
  }

  return { path: at.path, line: at.line, col: at.col, isInRepo: at.isInRepo === true }
}

const toSignature = (value: unknown): Signature | undefined => {
  const found = fields(value)

  if (found === undefined || typeof found.label !== 'string') {
    return undefined
  }

  const parameters = listOf(found.parameters).map(textOf)
  const active = found.active

  return {
    label: found.label,
    parameters,
    active:
      typeof active === 'number' && Number.isInteger(active) && active < parameters.length
        ? Math.max(active, -1)
        : -1,
    docs: textOf(found.docs),
  }
}

// What the bridge's client printed for a symbol request. Anything but its JSON
// answer has no text and says why in one note.
export const parseSymbol = (stdout: string, stderr = ''): LspSymbol => {
  let answer: SymbolAnswer | undefined

  try {
    answer = JSON.parse(stdout) as SymbolAnswer
  } catch {
    answer = undefined
  }

  if (answer === undefined || answer === null || typeof answer !== 'object') {
    return noSymbol(lastLine(stderr) || lastLine(stdout) || 'no output')
  }

  if (answer.ok !== true) {
    return noSymbol(answer.error ?? 'no reason given')
  }

  const found: LspSymbol = {
    text: typeof answer.text === 'string' ? answer.text : '',
    notes: (answer.notes ?? []).map(String),
  }
  const at = answer.definition

  if (
    at !== undefined &&
    at !== null &&
    typeof at.path === 'string' &&
    at.path !== '' &&
    isPlace(at.line) &&
    isPlace(at.col)
  ) {
    found.definition = { path: at.path, line: at.line, col: at.col, isInRepo: at.isInRepo === true }
  }

  const signature = toSignature(answer.signature)
  const typeDefinition = toPlace(answer.typeDefinition)
  const implementations: Place[] = []

  for (const item of listOf(answer.implementations)) {
    const place = toPlace(item)

    if (place !== undefined) {
      implementations.push(place)
    }
  }

  if (signature !== undefined) {
    found.signature = signature
  }

  if (typeDefinition !== undefined) {
    found.typeDefinition = typeDefinition
  }

  if (implementations.length > 0) {
    found.implementations = implementations
  }

  return found
}

// What the language server knows about the symbol at a position: 1-based line
// and column in `file`, a path relative to `repo` (an absolute real path). The
// column counts the line's own characters as a string index does (UTF-16 code
// units; a tab is one). Uses the daemon and servers the diagnostics use, and
// opens the file in its server when it is not open yet. Never rejects: any
// failure is `text: ''` and one note. `options.timeoutMs` is how long the
// server may take (30 seconds when not given). Inside a call's arguments the
// answer has that call's `signature`; `typeDefinition` and `implementations`
// are there when the server has them (pyright has no implementations).
export const lspSymbol = async (
  run: Run,
  repo: string,
  file: string,
  line: number,
  col: number,
  options: LspOptions = {},
): Promise<LspSymbol> => {
  if (!isServed(file)) {
    return { text: '', notes: ['no language server for this kind of file'] }
  }

  const timeoutMs = options.timeoutMs ?? 30_000

  try {
    const ran = await bridge(
      run,
      'symbol',
      { repo, file, line, col, envRoot: options.envRoot, timeout: timeoutMs / 1000 },
      Math.min(timeoutMs + 45_000, 600_000),
    )

    return parseSymbol(ran.stdout, ran.stderr)
  } catch (error) {
    return noSymbol(error instanceof Error ? error.message : String(error))
  }
}

// What the bridge's client printed for one of the lookups below: its answer's
// fields and notes. Anything but its JSON answer is no fields and one note.
type Asked = { answer: Record<string, unknown>; notes: string[] }

const unanswered = (why: string): Asked => ({
  answer: {},
  notes: [`language server did not answer: ${why}`],
})

const parseAsked = (stdout: string, stderr: string): Asked => {
  let parsed: unknown

  try {
    parsed = JSON.parse(stdout)
  } catch {
    parsed = undefined
  }

  const answer = fields(parsed)

  if (answer === undefined) {
    return unanswered(lastLine(stderr) || lastLine(stdout) || 'no output')
  }

  if (answer.ok !== true) {
    return unanswered(typeof answer.error === 'string' ? answer.error : 'no reason given')
  }

  return { answer, notes: listOf(answer.notes).map(String) }
}

// One lookup in the server of `file`, with the daemon and servers everything
// else here uses. Never rejects. The server may take `options.timeoutMs` (30
// seconds when not given).
const ask = async (
  run: Run,
  what: 'references' | 'calls' | 'outline' | 'tokens' | 'symbols' | 'hints',
  file: string,
  request: object,
  options: LspOptions,
): Promise<Asked> => {
  if (!isServed(file)) {
    return { answer: {}, notes: ['no language server for this kind of file'] }
  }

  const timeoutMs = options.timeoutMs ?? 30_000

  try {
    const ran = await bridge(
      run,
      'ask',
      { what, ...request, envRoot: options.envRoot, timeout: timeoutMs / 1000 },
      Math.min(timeoutMs + 45_000, 600_000),
    )

    return parseAsked(ran.stdout, ran.stderr)
  } catch (error) {
    return unanswered(error instanceof Error ? error.message : String(error))
  }
}

const isCount = (value: unknown): value is number =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0

// Everywhere the symbol at a place is used, its declaration included, each
// with the text of its line: the project's own files first, then installed
// packages, each in path and line order. At most 1,000 (a note says how many
// there were). The place is 1-based, as for `lspSymbol`. A place with no symbol
// is no places and no note.
export const lspReferences = async (
  run: Run,
  repo: string,
  file: string,
  line: number,
  col: number,
  options: LspOptions = {},
): Promise<{ places: PlaceLine[]; notes: string[] }> => {
  const { answer, notes } = await ask(run, 'references', file, { repo, file, line, col }, options)
  const places: PlaceLine[] = []

  for (const item of listOf(answer.places)) {
    const place = toPlace(item)

    if (place !== undefined) {
      places.push({ ...place, text: textOf(fields(item)?.text) })
    }
  }

  return { places, notes }
}

// Who calls the function at a place ('incoming') or what it calls
// ('outgoing'), one level. A node's place is where that caller or callee is
// declared (its name), not the line of the call. At most 500.
export const lspCalls = async (
  run: Run,
  repo: string,
  file: string,
  line: number,
  col: number,
  direction: 'incoming' | 'outgoing',
  options: LspOptions = {},
): Promise<{ calls: CallNode[]; notes: string[] }> => {
  const request = { repo, file, line, col, direction }
  const { answer, notes } = await ask(run, 'calls', file, request, options)
  const calls: CallNode[] = []

  for (const item of listOf(answer.calls)) {
    const node = fields(item)
    const place = toPlace(node?.place)

    if (node !== undefined && place !== undefined) {
      calls.push({
        name: textOf(node.name),
        kind: textOf(node.kind),
        place,
        detail: textOf(node.detail),
      })
    }
  }

  return { calls, notes }
}

// The file's functions, classes, methods, variables and so on, in the file's
// order, a parent before its children. `line`..`endLine` is all an entry
// spans (a decorator above it included); `col` is its name's column when the
// name is on `line`, else where the span starts. At most 5,000.
export const lspOutline = async (
  run: Run,
  repo: string,
  file: string,
  options: LspOptions = {},
): Promise<{ items: OutlineItem[]; notes: string[] }> => {
  const { answer, notes } = await ask(run, 'outline', file, { repo, file }, options)
  const items: OutlineItem[] = []

  for (const item of listOf(answer.items)) {
    const entry = fields(item)

    if (
      entry !== undefined &&
      isPlace(entry.line) &&
      isPlace(entry.endLine) &&
      isPlace(entry.col) &&
      isCount(entry.depth)
    ) {
      items.push({
        name: textOf(entry.name),
        kind: textOf(entry.kind),
        line: entry.line,
        endLine: entry.endLine,
        col: entry.col,
        depth: entry.depth,
      })
    }
  }

  return { items, notes }
}

// What every name in the file is, in the file's order. The bridge sends each
// token as [line, col, length, type, modifier bits] against a legend, which
// keeps a large file's answer small; at most 100,000 tokens (a note says so).
export const lspSemanticTokens = async (
  run: Run,
  repo: string,
  file: string,
  options: LspOptions = {},
): Promise<{ tokens: SemanticToken[]; notes: string[] }> => {
  const { answer, notes } = await ask(run, 'tokens', file, { repo, file }, options)
  const types = listOf(answer.types).map(textOf)
  const names = listOf(answer.modifiers).map(textOf)
  const tokens: SemanticToken[] = []

  for (const row of listOf(answer.rows)) {
    const [line, col, length, type, bits] = listOf(row)
    const name = isCount(type) ? types[type] : undefined

    if (isPlace(line) && isPlace(col) && isCount(length) && isCount(bits) && name) {
      tokens.push({
        line,
        col,
        length,
        type: name,
        modifiers: names.filter((modifier, index) => modifier !== '' && (bits & (1 << index)) !== 0),
      })
    }
  }

  return { tokens, notes }
}

// Symbols anywhere in the project whose name matches `query`, the closest
// matches and the project's own files first. `near` is a file of the project
// (relative to `repo`): it picks the server and the project. At most
// `options.limit` hits (50 when not given, never more than 500).
export const lspWorkspaceSymbols = async (
  run: Run,
  repo: string,
  query: string,
  near: string,
  options: LspOptions & { limit?: number } = {},
): Promise<{ hits: SymbolHit[]; notes: string[] }> => {
  const request = { repo, near, query, limit: options.limit ?? 50 }
  const { answer, notes } = await ask(run, 'symbols', near, request, options)
  const hits: SymbolHit[] = []

  for (const item of listOf(answer.hits)) {
    const hit = fields(item)
    const place = toPlace(hit?.place)

    if (hit !== undefined && place !== undefined) {
      hits.push({
        name: textOf(hit.name),
        kind: textOf(hit.kind),
        container: textOf(hit.container),
        place,
      })
    }
  }

  return { hits, notes }
}

// The inferred types and parameter names the server would draw inside lines
// `fromLine`..`toLine` (1-based, both included), in the file's order. A label
// carries the space it is drawn with ('amount: ' before an argument, ': int'
// after a name). At most 5,000.
export const lspInlayHints = async (
  run: Run,
  repo: string,
  file: string,
  fromLine: number,
  toLine: number,
  options: LspOptions = {},
): Promise<{ hints: InlayHint[]; notes: string[] }> => {
  const request = { repo, file, fromLine, toLine }
  const { answer, notes } = await ask(run, 'hints', file, request, options)
  const hints: InlayHint[] = []

  for (const item of listOf(answer.hints)) {
    const hint = fields(item)

    if (hint !== undefined && isPlace(hint.line) && isPlace(hint.col)) {
      hints.push({
        line: hint.line,
        col: hint.col,
        label: textOf(hint.label),
        kind: hint.kind === 'type' || hint.kind === 'parameter' ? hint.kind : 'other',
      })
    }
  }

  return { hints, notes }
}

