// The ledger mod's review findings as the pane's review comments, so each
// shows on its line the way a request's thread does. Lens works without the
// ledger: with no run there are none.

import type { LedgerRunSeen } from '../types/ledger'
import type { Comment } from './review'

const PREFIX = 'ledger-'

// Whether a comment is a ledger finding: it has no thread on a forge to answer
// or resolve.
export const isFinding = (comment: Comment): boolean => comment.id.startsWith(PREFIX)

// A path with its `.` and `..` parts folded.
const folded = (path: string): string => {
  const parts: string[] = []

  for (const part of path.split('/')) {
    if (part === '..') {
      parts.pop()
    } else if (part !== '.' && part !== '') {
      parts.push(part)
    }
  }

  return `${path.startsWith('/') ? '/' : ''}${parts.join('/')}`
}

// A path another mod names, made absolute: as it is when it starts at the
// root, else from `root`, the session's folder.
export const placeOf = (path: string, root: string): string =>
  folded(path.startsWith('/') ? path : `${root}/${path}`)

// Where a finding's file is under the folder being reviewed, or undefined when
// it is not there. An agent writes the path from the session's folder, which
// may be the folder under review, one above it, or one inside it; failing
// those, a changed file whose path ends with the finding's is the one meant.
const placed = (path: string, repo: string, root: string, files: readonly string[]): string | undefined => {
  const full = folded(path.startsWith('/') ? path : `${root}/${path}`)
  const under = full.startsWith(`${repo}/`) ? full.slice(repo.length + 1) : undefined
  const tail = folded(path).replace(/^\//, '')

  if (under !== undefined && (path.startsWith('/') || files.includes(under))) {
    return under
  }

  // A path written from a folder above the one under review starts with
  // that folder's own last parts (`skills/lens/hooks/a.ts` for a review of
  // `…/skills/lens`), whatever the session's folder is by now.
  const parts = tail.split('/')

  for (let at = parts.length - 1; at >= 1; at -= 1) {
    if (repo.endsWith(`/${parts.slice(0, at).join('/')}`)) {
      return parts.slice(at).join('/')
    }
  }

  if (under !== undefined) {
    return under
  }


  return files.find(one => one === tail || one.endsWith(`/${tail}`) || tail.endsWith(`/${one}`))
}

// The run's findings as comments on the files of `repo`, the folder under
// review. `root` is the session's folder and `files` the changed files' paths.
// A fixed finding is a resolved thread; one with no line is on the file as a
// whole.
export const findingComments = (
  run: LedgerRunSeen | null | undefined,
  repo: string,
  root: string,
  files: readonly string[],
): Comment[] =>
  (run?.findings ?? []).flatMap(one => {
    const path = placed(one.path, repo, root, files)

    return path === undefined
      ? []
      : [
          {
            id: `${PREFIX}${one.id}`,
            path,
            line: one.line ?? 0,
            author: `ledger ${one.severity}${one.task === undefined ? '' : ` · ${one.task}`}`,
            body: one.summary,
            when: new Date(one.at).toISOString(),
            ...(one.status === 'fixed' ? { isResolved: true } : {}),
          },
        ]
  })

files.hooks/media.ts:
// What a description or a comment links to that a terminal cannot draw in
// place: pictures, videos and documents. They are found in the markdown and
// listed under it, each a link that opens where it can be seen.

export type Media = { kind: 'image' | 'video' | 'file'; url: string; label: string }

const VIDEO = /\.(?:mp4|mov|webm|m4v|avi|mkv)(?:[?#]|$)/i
const IMAGE = /\.(?:png|jpe?g|gif|webp|svg|bmp|avif|heic)(?:[?#]|$)/i
const FILE = /\.(?:pdf|docx?|xlsx?|pptx?|csv|txt|log|zip|gz|tar|json|ya?ml|md|key|numbers|pages)(?:[?#]|$)/i
// What a forge serves an upload from, whatever its name ends with.
const UPLOAD = /\/user-attachments\/|\/uploads\/[0-9a-f]{16,}\/|\/files\/\d+\//

// The last part of a link's path, as a name to show; the link itself when
// it has none.
const nameOf = (url: string): string => {
  const last = (url.split(/[?#]/)[0] ?? '').split('/').filter(part => part !== '').pop() ?? ''

  try {
    return decodeURIComponent(last) || url
  } catch {
    return last || url
  }
}

const kindOf = (url: string, written: Media['kind'] | undefined): Media['kind'] | undefined =>
  VIDEO.test(url)
    ? 'video'
    : IMAGE.test(url)
      ? 'image'
      : FILE.test(url)
        ? 'file'
        : (written ?? (UPLOAD.test(url) ? 'file' : undefined))

// The pictures, videos and documents a piece of markdown holds, in the order
// they come, each once. A picture is one written as a picture (`![]()`, an
// `<img>`); a video an `<video>` or a link to a video file; a document a
// link to an upload or to a file of a kind people attach. A bare link to a
// forge's upload counts too: that is how GitHub writes a dropped video.
//
// The text is whoever wrote the request's, so it is read as untrusted: only
// its first `SCANNED` characters are looked at, every pattern's repeats are
// bounded (none can be made to try the same stretch over and over), no more
// than `MEDIA_KEPT` are kept, and a label is plain printable text of a
// length a row can hold.
export const SCANNED = 60_000
export const MEDIA_KEPT = 100
const LABEL = 120

// Text with nothing a terminal would act on: control characters go, and
// runs of space become one.
export const plain = (text: string): string =>
  text
    .replace(new RegExp('[\\u0000-\\u001f\\u007f-\\u009f\\u200b-\\u200f\\u2028-\\u202e\\u2066-\\u2069]', 'g'), ' ')
    .replace(/\s+/g, ' ')
    .trim()

// Whether a character is one a terminal acts on or that reorders the text
// round it, by its code point: the control characters, the zero-width and
// the direction marks.
const isActedOn = (code: number): boolean =>
  code < 32 ||
  (code >= 127 && code <= 159) ||
  (code >= 0x200b && code <= 0x200f) ||
  (code >= 0x2028 && code <= 0x202e) ||
  (code >= 0x2066 && code <= 0x2069)

// A block of text (a description, a comment) with those characters taken
// out, its lines and its tabs kept: what is handed on to be drawn.
export const plainBlock = (text: string): string =>
  Array.from(text)
    .filter(char => {
      const code = char.codePointAt(0) ?? 0

      return code === 9 || code === 10 || !isActedOn(code)
    })
    .join('')

export const mediaOf = (markdown: string): Media[] => {
  const text = markdown.slice(0, SCANNED)
  const found = new Map<string, Media>()
  const take = (url: string, written: Media['kind'] | undefined, label: string) => {
    // A link is http or https, of printable characters with no space in it.
    const kind = /^https?:\/\/[\x21-\x7e]{1,2000}$/.test(url) ? kindOf(url, written) : undefined

    if (kind !== undefined && !found.has(url) && found.size < MEDIA_KEPT) {
      found.set(url, { kind, url, label: (plain(label) || plain(nameOf(url))).slice(0, LABEL) })
    }
  }
  // Each kind of mention is looked for with where it starts, so the list
  // comes out in the order of the text.
  const mentions: { at: number; url: string; written: Media['kind'] | undefined; label: string }[] = []
  const scan = (pattern: RegExp, read: (hit: RegExpExecArray) => Omit<(typeof mentions)[number], 'at'>) => {
    for (const hit of text.matchAll(pattern)) {
      mentions.push({ at: hit.index, ...read(hit as RegExpExecArray) })
    }
  }

  scan(/!\[([^\]\n]{0,300})\]\(([^\s)]{1,2000})(?: "[^"\n]{0,300}")?\)/g, hit => ({
    url: hit[2] ?? '',
    written: 'image',
    label: hit[1] ?? '',
  }))
  scan(/<img\b([^>]{0,1000})>/gi, hit => ({
    url: /\bsrc=["']([^"'\s]{1,2000})["']/i.exec(hit[1] ?? '')?.[1] ?? '',
    written: 'image',
    label: /\balt=["']([^"'\n]{0,300})["']/i.exec(hit[1] ?? '')?.[1] ?? '',
  }))
  scan(/<(?:video|source)\b([^>]{0,1000})>/gi, hit => ({
    url: /\bsrc=["']([^"'\s]{1,2000})["']/i.exec(hit[1] ?? '')?.[1] ?? '',
    written: 'video',
    label: '',
  }))
  scan(/(?<!!)\[([^\]\n]{1,300})\]\(([^\s)]{1,2000})(?: "[^"\n]{0,300}")?\)/g, hit => ({
    url: hit[2] ?? '',
    written: undefined,
    label: hit[1] ?? '',
  }))
  scan(/(?<![("'=\]])\bhttps?:\/\/[^\s<>)"']{1,2000}/g, hit => ({ url: hit[0], written: undefined, label: '' }))

  for (const one of mentions.sort((a, b) => a.at - b.at)) {
    take(one.url, one.written, one.label)
  }

  return [...found.values()]
}

// The first few lines of a description, to show what it says at a glance:
// its text without the marks markdown is written with (a heading's `#`, a
// list's bullet, emphasis, a link's address, a picture, a tag), each line
// held to `width` and no more than `count` of them. Empty for a description
// that says nothing. What it is cut from is bounded, as in `mediaOf`.
export const sampleOf = (markdown: string, count: number, width: number): string[] => {
  const lines: string[] = []
  let isCode = false

  for (const raw of plainBlock(markdown.slice(0, SCANNED)).split('\n')) {
    if (/^\s*(```|~~~)/.test(raw)) {
      isCode = !isCode
      continue
    }

    const line = isCode
      ? raw.trim()
      : plain(
          raw
            .replace(/<!--[^>]{0,2000}-->/g, ' ')
            .replace(/!\[[^\]\n]{0,300}\]\([^)\s]{0,2000}\)/g, ' ')
            .replace(/\[([^\]\n]{1,300})\]\([^)\s]{0,2000}\)/g, '$1')
            .replace(/<[^>\n]{0,1000}>/g, ' ')
            .replace(/^\s{0,3}(?:#{1,6}\s+|[-*+]\s+(?:\[[ xX]\]\s+)?|\d{1,4}[.)]\s+|>\s?)+/, '')
            .replace(/(\*\*|__|\*|_|`|~~)/g, ''),
        )

    // A rule, a table's dashes or a line the marks were all of is no line.
    if (line === '' || /^[-=|:\s]+$/.test(line)) {
      continue
    }

    lines.push(line.length > width ? `${line.slice(0, Math.max(1, width - 1))}…` : line)

    if (lines.length >= count) {
      break
    }
  }

  return lines
}

// The site a link goes to, to say beside whatever it is called: a name is
// the writer's to choose, where it leads is not.
export const hostOf = (url: string): string => /^https?:\/\/([^/?#\s]{1,200})/i.exec(url)?.[1]?.toLowerCase() ?? ''

// Markdown with every link that opens a page elsewhere marked as one: `mark`
// (the sign of such a link) is put after its words, so a link reads as
// something to press and not as coloured text. A picture written into the
// text is no picture in a terminal, so it becomes a link to itself, marked
// the same. Code is left as it is, fenced or between backticks, and so is a
// picture that is itself the words of a link.
const LINKED = new RegExp('(?<![\\[!])(!?)\\[([^\\[\\]\\n]{1,300})\\]\\((https?://[^\\s)]{1,2000})(?:\\s+"[^"\\n]{0,200}")?\\)', 'g')

export const markLinks = (markdown: string, mark: string): string => {
  let fence = ''

  return markdown
    .split('\n')
    .map(line => {
      const opened = /^\s{0,3}(```|~~~)/.exec(line)?.[1] ?? ''

      if (fence !== '') {
        fence = opened === fence ? '' : fence

        return line
      }

      if (opened !== '') {
        fence = opened

        return line
      }

      // Every other piece of a line cut at its backticks is code.
      return line
        .split(/(`[^`]*`)/)
        .map((piece, at) =>
          at % 2 === 1
            ? piece
            : piece.replace(LINKED, (_whole, _bang: string, label: string, url: string) =>
                label.endsWith(mark) ? `[${label}](${url})` : `[${label} ${mark}](${url})`,
              ),
        )
        .join('')
    })
    .join('\n')
}

files.hooks/pictures.ts:
// The pictures of a request's description, drawn in place where the terminal
// can draw one. A picture is a link in someone else's text, so which ones
// are fetched at all is decided here, and each is fetched by a fixed command
// with its address as an argument: only https, only from the forge's own
// hosts, a bounded size, a bounded time. What comes back is made a PNG file
// the terminal reads itself; anything else stays the link it was.

import type { Run } from './run'

// A picture ready to draw: the PNG file holding it, and its size in pixels.
export type Picture = { file: string; width: number; height: number }

// The most a picture may weigh to be fetched, and the widest and tallest one
// that is drawn.
export const PICTURE_BYTES = 2 * 1024 * 1024
const PICTURE_PIXELS = 4096
// How many of a description's pictures are drawn; the rest stay links.
export const PICTURES_SHOWN = 6
// How many times a picture's address may point on to another.
const REDIRECTS = 4

// The hosts a forge serves its own pictures from, beside the forge itself:
// what people drop into a description, and a file of a repository.
const GITHUB_HOSTS = [
  'github.com',
  'raw.githubusercontent.com',
  'user-images.githubusercontent.com',
  'private-user-images.githubusercontent.com',
  'objects.githubusercontent.com',
  'camo.githubusercontent.com',
  'avatars.githubusercontent.com',
]

// Whether a picture's address is one lens fetches: https, with no name and
// password in it, on the forge's own host or (for GitHub) one of the hosts
// it serves pictures from. `forge` is the host of the repository's remote.
export const isFetched = (url: string, forge: string): boolean => {
  const parts = /^https:\/\/([^/?#@\s:]{1,200})(?::443)?(?:[/?#][\x21-\x7e]{0,2000})?$/.exec(url)
  const host = parts?.[1]?.toLowerCase() ?? ''
  const home = forge.toLowerCase()

  return host !== '' && home !== '' && (host === home || (home === 'github.com' && GITHUB_HOSTS.includes(host)))
}

// How many cells a picture takes when it is drawn `columns` wide at most: as
// wide as it is, where it is narrower, and as tall as keeps its shape (a
// cell is about twice as tall as it is wide), within `rows`.
export const cellsOf = (
  picture: Pick<Picture, 'width' | 'height'>,
  columns: number,
  rows: number,
): { columns: number; rows: number } => {
  const wide = Math.max(1, Math.min(columns, 255, Math.round(picture.width / 8)))
  const tall = Math.max(1, Math.round((wide * picture.height) / picture.width / 2))

  return tall <= rows
    ? { columns: wide, rows: tall }
    : { columns: Math.max(1, Math.round((rows * 2 * picture.width) / picture.height)), rows: Math.max(1, rows) }
}

// The most pixels a picture may say it has before any tool is let open it.
const PIXELS_OPENED = 40_000_000

// A small file can say it is a picture of enormous size, and opening it
// would take all the memory there is. So before one is made a PNG, its size
// is read from its header alone (no pixel is opened for that), and one over
// the bound, or whose size cannot be read, is refused. A tool that runs away
// all the same is stopped by the bound on processor time.
const FITS = [
  'ulimit -t 30 2>/dev/null',
  'fits() {',
  '  if command -v sips >/dev/null 2>&1; then',
  '    wide=$(sips -g pixelWidth "$1" 2>/dev/null | awk "/pixelWidth/ {print \\$2}")',
  '    tall=$(sips -g pixelHeight "$1" 2>/dev/null | awk "/pixelHeight/ {print \\$2}")',
  '  elif command -v magick >/dev/null 2>&1; then',
  '    wide=$(magick identify -ping -format "%w" "$1[0]" 2>/dev/null)',
  '    tall=$(magick identify -ping -format "%h" "$1[0]" 2>/dev/null)',
  '  elif command -v identify >/dev/null 2>&1; then',
  '    wide=$(identify -ping -format "%w" "$1[0]" 2>/dev/null)',
  '    tall=$(identify -ping -format "%h" "$1[0]" 2>/dev/null)',
  // With no tool here nothing is opened either: a PNG is only copied.
  '  else return 0; fi',
  '  case "$wide$tall" in ""|*[!0-9]*) return 1 ;; esac',
  '  [ -n "$wide" ] && [ -n "$tall" ] && [ "${#wide}" -le 5 ] && [ "${#tall}" -le 5 ] || return 1',
  `  [ "$((wide * tall))" -ge 1 ] && [ "$((wide * tall))" -le ${PIXELS_OPENED} ]`,
  '}',
]

// Fetches one address into a folder that is the person's alone, makes what
// came a PNG, and prints the file and its size. $1 the address, $2 the most
// bytes, $3 the address the picture was first asked for by (its name). The folder is in the person's own cache, never the shared /tmp, and
// is refused where it is a link or someone else's. The file is named by the
// SHA-256 of the address, worked out here, so two addresses never share one.
// The address is taken as it is written (no braces or brackets are spread
// into many), and the picture is told by its first bytes, never by its name;
// what is no picture, or one no tool here can make a PNG, fails.
const FETCH = [
  'umask 077',
  ...FITS,
  'base="${XDG_CACHE_HOME:-${HOME:+$HOME/.cache}}"',
  '[ -n "$base" ] || exit 1',
  'dir="$base/lens-pictures"',
  'mkdir -p "$dir" || exit 1',
  '[ -d "$dir" ] && [ ! -L "$dir" ] && [ -O "$dir" ] || exit 1',
  'chmod 700 "$dir" || exit 1',
  'if command -v shasum >/dev/null 2>&1; then name=$(printf %s "$3" | shasum -a 256 | cut -c1-64)',
  'elif command -v sha256sum >/dev/null 2>&1; then name=$(printf %s "$3" | sha256sum | cut -c1-64)',
  'else exit 1; fi',
  '[ "${#name}" -eq 64 ] || exit 1',
  'case "$name" in *[!0-9a-f]*) exit 1 ;; esac',
  // Pictures not looked at for two weeks go, so the folder does not grow.
  'find "$dir" -type f -mtime +14 -delete 2>/dev/null',
  'raw="$dir/$name.$$.raw"; made="$dir/$name.$$.png"; png="$dir/$name.png"',
  'if [ ! -s "$png" ] || [ -L "$png" ]; then',
  '  rm -f "$png"',
  // No redirect is followed here: where the answer is one, the address it
  // points at is printed, for the caller to hold to the same hosts first.
  '  said=$(curl -sS --globoff --proto "=https" --max-redirs 0 --max-time 20 --max-filesize "$2" -o "$raw" -w "%{http_code} %{redirect_url}" -- "$1") || { rm -f "$raw"; exit 1; }',
  '  case "$said" in',
  '    3??\\ https://*) rm -f "$raw"; printf "to %s\\n" "${said#* }"; exit 0 ;;',
  '    200\\ *) ;;',
  '    *) rm -f "$raw"; exit 1 ;;',
  '  esac',
  '  [ "$(wc -c < "$raw" | tr -d " ")" -le "$2" ] || { rm -f "$raw"; exit 1; }',
  '  magic=$(od -An -tx1 -N12 "$raw" | tr -d " \\n")',
  '  case "$magic" in',
  '    89504e470d0a1a0a*) mv -f "$raw" "$png" ;;',
  '    ffd8ff*|474946383?61*|52494646????????57454250)',
  '      fits "$raw" || { rm -f "$raw"; exit 1; }',
  '      if command -v sips >/dev/null 2>&1; then sips -s format png "$raw" --out "$made" >/dev/null 2>&1',
  '      elif command -v magick >/dev/null 2>&1; then magick "$raw[0]" "png:$made" >/dev/null 2>&1',
  '      elif command -v convert >/dev/null 2>&1; then convert "$raw[0]" "png:$made" >/dev/null 2>&1',
  '      fi',
  '      rm -f "$raw"',
  '      [ -s "$made" ] && mv -f "$made" "$png" || { rm -f "$made"; exit 1; } ;;',
  '    *) rm -f "$raw"; exit 1 ;;',
  '  esac',
  'fi',
  '[ -s "$png" ] || exit 1',
  // A PNG says its size in its first chunk: four bytes each, big end first.
  'set -- $(od -An -tu1 -j16 -N8 "$png")',
  '[ "$#" -eq 8 ] || exit 1',
  'printf "%s\\n%s %s\\n" "$png" "$(( (($1 * 256 + $2) * 256 + $3) * 256 + $4 ))" "$(( (($5 * 256 + $6) * 256 + $7) * 256 + $8 ))"',
].join('\n')

// Fetches a picture and answers where it is and how big, or undefined where
// it is not one lens fetches, could not be fetched, or is no picture to
// draw.
export const fetchPicture = async (run: Run, url: string, forge: string): Promise<Picture | undefined> => {
  if (!isFetched(url, forge)) {
    return undefined
  }

  // A forge answers some pictures with another address. Each one it points
  // at is held to the same hosts before it is asked, a few times at most, so
  // a redirect cannot lead the fetch anywhere the first address could not go.
  let from = url
  let ran = await run(['sh', '-c', FETCH, 'sh', from, String(PICTURE_BYTES), url], { timeoutMs: 40_000 })

  for (let hop = 0; hop < REDIRECTS && ran.exitCode === 0 && ran.stdout.startsWith('to '); hop++) {
    from = ran.stdout.slice(3).trim()

    if (!isFetched(from, forge)) {
      return undefined
    }

    ran = await run(['sh', '-c', FETCH, 'sh', from, String(PICTURE_BYTES), url], { timeoutMs: 40_000 })
  }

  const [file = '', size = ''] = ran.stdout.trim().split('\n')
  const [width = 0, height = 0] = size.split(' ').map(Number)

  return ran.exitCode === 0 &&
    /^\/[\x20-\x7e]{1,900}\/lens-pictures\/[0-9a-f]{64}\.png$/.test(file) &&
    Number.isInteger(width) &&
    Number.isInteger(height) &&
    width >= 1 &&
    height >= 1 &&
    width <= PICTURE_PIXELS &&
    height <= PICTURE_PIXELS
    ? { file, width, height }
    : undefined
}

// The most a picture of the folder under review may weigh to be drawn, and
// the side one is brought down to where it is larger.
export const LOCAL_BYTES = 16 * 1024 * 1024
const LOCAL_SIDE = 2048

// Whether a file is a picture the code view draws, by its name: the kinds
// told by their first bytes below. (An SVG is text, and is read as code.)
export const isPictureFile = (path: string): boolean => /\.(png|jpe?g|gif|webp)$/i.test(path)

// Makes a picture of the folder under review a PNG in the same private
// folder, and prints the file and its size. $1 the folder, $2 the file's
// path in it, $3 the commit to read it at (- for the file as it stands),
// $4 the most bytes, $5 the longest side. The file is named by the SHA-256
// of what it holds, so a picture that changes is made again. A link is not
// followed: only a file of the folder itself is read.
const LOCAL = [
  'umask 077',
  ...FITS,
  'base="${XDG_CACHE_HOME:-${HOME:+$HOME/.cache}}"',
  '[ -n "$base" ] || exit 1',
  'dir="$base/lens-pictures"',
  'mkdir -p "$dir" || exit 1',
  '[ -d "$dir" ] && [ ! -L "$dir" ] && [ -O "$dir" ] || exit 1',
  'chmod 700 "$dir" || exit 1',
  'find "$dir" -type f -mtime +14 -delete 2>/dev/null',
  'raw="$dir/local.$$.raw"',
  'if [ "$3" != "-" ]; then',
  '  cd "$1" || exit 1',
  '  size=$(git cat-file -s "$3:./$2" 2>/dev/null) || exit 1',
  '  [ "$size" -le "$4" ] || exit 1',
  '  git cat-file blob "$3:./$2" > "$raw" 2>/dev/null || { rm -f "$raw"; exit 1; }',
  'else',
  '  src="$1/$2"',
  '  [ -f "$src" ] && [ ! -L "$src" ] || exit 1',
  '  [ "$(wc -c < "$src" | tr -d " ")" -le "$4" ] || exit 1',
  '  cp "$src" "$raw" || exit 1',
  'fi',
  'if command -v shasum >/dev/null 2>&1; then name=$(shasum -a 256 < "$raw" | cut -c1-64)',
  'elif command -v sha256sum >/dev/null 2>&1; then name=$(sha256sum < "$raw" | cut -c1-64)',
  'else rm -f "$raw"; exit 1; fi',
  '[ "${#name}" -eq 64 ] || { rm -f "$raw"; exit 1; }',
  'case "$name" in *[!0-9a-f]*) rm -f "$raw"; exit 1 ;; esac',
  'made="$dir/$name.$$.png"; png="$dir/$name.png"',
  'if [ ! -s "$png" ] || [ -L "$png" ]; then',
  '  rm -f "$png"',
  '  magic=$(od -An -tx1 -N12 "$raw" | tr -d " \\n")',
  '  case "$magic" in',
  '    89504e470d0a1a0a*|ffd8ff*|474946383?61*|52494646????????57454250)',
  '      fits "$raw" || { rm -f "$raw"; exit 1; }',
  // Brought down to a side the terminal draws, and made a PNG, in one go
  // where a tool for it is here; a PNG is kept as it is where none is.
  // (sips makes a small picture larger when asked for a side, so it is
  // asked only where the picture is over it.)
  '      if command -v sips >/dev/null 2>&1; then',
  '        sips -s format png "$raw" --out "$made" >/dev/null 2>&1',
  '        wide=$(sips -g pixelWidth "$made" 2>/dev/null | awk "/pixelWidth/ {print \\$2}")',
  '        tall=$(sips -g pixelHeight "$made" 2>/dev/null | awk "/pixelHeight/ {print \\$2}")',
  '        if [ "${wide:-0}" -gt "$5" ] || [ "${tall:-0}" -gt "$5" ]; then sips -Z "$5" "$made" >/dev/null 2>&1; fi',
  '      elif command -v magick >/dev/null 2>&1; then magick "$raw[0]" -resize "$5x$5>" "png:$made" >/dev/null 2>&1',
  '      elif command -v convert >/dev/null 2>&1; then convert "$raw[0]" -resize "$5x$5>" "png:$made" >/dev/null 2>&1',
  '      else case "$magic" in 89504e470d0a1a0a*) cp "$raw" "$made" ;; esac; fi',
  '      rm -f "$raw"',
  '      [ -s "$made" ] && mv -f "$made" "$png" || { rm -f "$made"; exit 1; } ;;',
  '    *) rm -f "$raw"; exit 1 ;;',
  '  esac',
  'else',
  '  rm -f "$raw"; touch "$png"',
  'fi',
  '[ -s "$png" ] || exit 1',
  'set -- $(od -An -tu1 -j16 -N8 "$png")',
  '[ "$#" -eq 8 ] || exit 1',
  'printf "%s\\n%s %s\\n" "$png" "$(( (($1 * 256 + $2) * 256 + $3) * 256 + $4 ))" "$(( (($5 * 256 + $6) * 256 + $7) * 256 + $8 ))"',
].join('\n')

// A picture of the folder under review, ready to draw: the file as it
// stands, or as `commit` left it. Undefined where the path is not a plain
// one inside the folder, the commit is not a plain name, or what is there is
// no picture a tool here can make a PNG.
export const localPicture = async (
  run: Run,
  repo: string,
  path: string,
  commit = '',
): Promise<Picture | undefined> => {
  const isInside = !path.startsWith('/') && !path.split('/').includes('..') && !/[\x00-\x1f\x7f]/.test(path)
  const isNamed = commit === '' || /^[0-9A-Za-z_][0-9A-Za-z._/@{}^~-]{0,200}$/.test(commit)

  if (!repo.startsWith('/') || !isInside || !isNamed || !isPictureFile(path)) {
    return undefined
  }

  const ran = await run(['sh', '-c', LOCAL, 'sh', repo, path, commit === '' ? '-' : commit, String(LOCAL_BYTES), String(LOCAL_SIDE)], {
    timeoutMs: 40_000,
  })
  const [file = '', size = ''] = ran.stdout.trim().split('\n')
  const [width = 0, height = 0] = size.split(' ').map(Number)

  return ran.exitCode === 0 &&
    /^\/[\x20-\x7e]{1,900}\/lens-pictures\/[0-9a-f]{64}\.png$/.test(file) &&
    Number.isInteger(width) &&
    Number.isInteger(height) &&
    width >= 1 &&
    height >= 1 &&
    width <= PICTURE_PIXELS &&
    height <= PICTURE_PIXELS
    ? { file, width, height }
    : undefined
}

files.hooks/patch.ts:
// A whole comparison as one page: git's unified diff read into files, hunks
// and lines, for the screen that shows every change one after another.

import type { Run } from './run'

// A line of a hunk: unchanged, added or removed, with its number in the new
// side of the file (0 for a removed line, which that side does not have).
// `old` is its number in the old side (0 for an added line).
export type PatchLine = { kind: ' ' | '+' | '-'; text: string; line: number; old: number }

// A hunk: the words git puts after its `@@` (the function it is in), its
// lines, and the hunk as git wrote it (`raw`: its `@@` line and every line
// under it, the "no newline" marks among them), which is what git takes
// back to stage it or undo it.
export type PatchHunk = { header: string; lines: PatchLine[]; raw: string[] }

// A file of the diff by its path on the new side (the old one for a deleted
// file). A binary file has no hunks.
export type PatchFile = {
  path: string
  // Its path on the old side: the same, another for a renamed file, and
  // '/dev/null' for a new one. '/dev/null' as `newPath` is a deleted file.
  oldPath: string
  newPath: string
  hunks: PatchHunk[]
  added: number
  deleted: number
  isBinary: boolean
  // Whether it is a symbolic link on either side: its "text" is the path it
  // points at, and the file itself is not to be read through.
  isLink: boolean
}

// How many lines of unchanged code git shows round each change.
export const CONTEXT = 3
// The steps the page's key for more context goes through, and back round.
export const CONTEXTS = [3, 10, 30] as const

// Reads `git diff --no-prefix` output. A path is taken from the `+++` line
// (the `---` line for a deleted file), so a renamed file is under its new name.
export const parsePatch = (diff: string): PatchFile[] => {
  const files: PatchFile[] = []
  let file: PatchFile | undefined
  let hunk: PatchHunk | undefined
  let line = 0
  let old = 0
  let oldPath = ''

  for (const raw of diff.split('\n')) {
    if (raw.startsWith('diff --git ')) {
      // The path is settled by the lines that follow; until then it is what
      // the heading names last, which is right for a file with no hunks (a
      // rename with nothing changed, a mode change).
      const named = raw.slice('diff --git '.length)
      const half = named.length >> 1

      file = {
        path: named.slice(half + 1) === named.slice(0, half) ? named.slice(half + 1) : named,
        oldPath: '',
        newPath: '',
        hunks: [],
        added: 0,
        deleted: 0,
        isBinary: false,
        isLink: false,
      }
      files.push(file)
      hunk = undefined
      oldPath = ''
    } else if (file === undefined) {
      continue
    } else if (
      hunk === undefined &&
      /^(?:(?:new|deleted) file mode|new mode|old mode) 120000$|^index \S+ 120000$/.test(raw)
    ) {
      file.isLink = true
    } else if (hunk === undefined && raw.startsWith('rename to ')) {
      file.path = raw.slice('rename to '.length)
    } else if (hunk === undefined && raw.startsWith('Binary files ')) {
      file.isBinary = true
    } else if (hunk === undefined && raw.startsWith('--- ')) {
      oldPath = raw.slice(4).split('\t')[0] ?? ''
      file.oldPath = oldPath
    } else if (hunk === undefined && raw.startsWith('+++ ')) {
      const path = raw.slice(4).split('\t')[0] ?? ''

      file.newPath = path
      file.path = path === '/dev/null' ? oldPath : path
    } else if (raw.startsWith('@@ ')) {
      const at = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@ ?(.*)$/.exec(raw)

      old = Number(at?.[1] ?? 1)
      line = Number(at?.[2] ?? 1)
      hunk = { header: at?.[3] ?? '', lines: [], raw: [raw] }
      file.hunks.push(hunk)
    } else if (hunk !== undefined && (raw.startsWith('+') || raw.startsWith('-') || raw.startsWith(' '))) {
      const kind = raw[0] as PatchLine['kind']

      hunk.raw.push(raw)
      hunk.lines.push({
        kind,
        text: raw.slice(1),
        line: kind === '-' ? 0 : line,
        old: kind === '+' ? 0 : old,
      })

      if (kind === '+') {
        file.added += 1
      } else if (kind === '-') {
        file.deleted += 1
      }

      if (kind !== '-') {
        line += 1
      }

      if (kind !== '+') {
        old += 1
      }
    } else if (hunk !== undefined && raw.startsWith('\\')) {
      // "\ No newline at end of file": part of the hunk as git takes it back.
      hunk.raw.push(raw)
    }
  }

  return files
}

// One hunk of a file as a patch git can apply by itself: the file's two
// names, then the hunk as git wrote it. The names carry the `a/` and `b/`
// git expects; a new or deleted file keeps its `/dev/null`.
export const hunkPatch = (file: PatchFile, hunk: PatchHunk): string => {
  const name = (side: 'a' | 'b', path: string): string => (path === '/dev/null' ? path : `${side}/${path}`)

  return [
    `--- ${name('a', file.oldPath || file.path)}`,
    `+++ ${name('b', file.newPath || file.path)}`,
    ...hunk.raw,
    '',
  ].join('\n')
}

// What tells one hunk from another whichever comparison it was read in: its
// file and its lines, without the numbers of its `@@` line (which shift when
// a hunk above it is staged or not). A hunk of the working tree whose mark
// is among the index's own is staged.
export const hunkMark = (file: PatchFile, hunk: PatchHunk): string => `${file.path}\n${hunk.raw.slice(1).join('\n')}`

// Whether a path is one a patch may name: of the folder, by a plain relative
// path. git quotes a name with a control character, a quote or a backslash
// in it (it then starts with `"`), and such a file is left to git itself.
const isPlainPath = (path: string): boolean =>
  path !== '' &&
  path.length <= 1024 &&
  !path.startsWith('/') &&
  !path.startsWith('"') &&
  !path.startsWith('-') &&
  !path.split('/').some(part => part === '..' || part === '.git') &&
  Array.from(path).every(char => {
    const code = char.codePointAt(0) ?? 0

    return code >= 32 && code !== 127 && char !== '"' && char !== '\\'
  })

// Whether a hunk can be handed back to git as a patch of its own: its file
// by plain paths (or `/dev/null` on one side), and its text one `@@` line
// followed by nothing but lines of a hunk.
export const isApplicable = (file: PatchFile, hunk: PatchHunk): boolean => {
  const sides = [file.oldPath || file.path, file.newPath || file.path]

  return (
    !file.isBinary &&
    !file.isLink &&
    isPlainPath(file.path) &&
    sides.every(side => side === '/dev/null' || isPlainPath(side)) &&
    !sides.every(side => side === '/dev/null') &&
    /^@@ -\d+(?:,\d+)? \+\d+(?:,\d+)? @@/.test(hunk.raw[0] ?? '') &&
    hunk.raw.slice(1).every(line => /^[ +\-\\]/.test(line) && !line.includes('\n'))
  )
}

// Applies one hunk to the index (`stage`), takes it back out of the index
// (`unstage`), or undoes it in the working tree (`discard`). Answers '' when
// git did it, else its reason. Run in the folder the diff was read in, whose
// paths the patch's are from.
export const applyHunk = async (
  run: Run,
  repo: string,
  file: PatchFile,
  hunk: PatchHunk,
  how: 'stage' | 'unstage' | 'discard',
): Promise<string> => {
  // The patch is built from what a diff said, so what goes into it is held
  // to what a hunk of one file is before git is handed it: plain paths that
  // stay inside the folder, and a body of nothing but a hunk's own lines.
  if (!isApplicable(file, hunk)) {
    return 'that change is not one lens hands back to git: its file has a name it does not take, or the hunk is not whole'
  }

  const ran = await run(
    [
      'git',
      'apply',
      ...(how === 'discard' ? ['--reverse'] : how === 'unstage' ? ['--cached', '--reverse'] : ['--cached']),
      '--whitespace=nowarn',
      '-',
    ],
    { cwd: repo, timeoutMs: 30_000, stdin: hunkPatch(file, hunk) },
  )

  return ran.exitCode === 0 ? '' : (ran.stderr.trim().split('\n').pop() ?? 'git could not apply it')
}

// The whole comparison as git diffs it: `base` with the working tree, or,
// when `target` names a commit, the two commits with each other. `refusal`
// is git's reason when it could not be read.
export const readPatch = async (
  run: Run,
  repo: string,
  base: string,
  target: string,
  // How many unchanged lines show round each change, and whether a line
  // that differs only in its spaces is left out.
  // `isStaged` reads what the index holds against `base` in place of the
  // working tree; `paths` reads those files alone.
  {
    context = CONTEXT,
    ignoresSpace = false,
    isStaged = false,
    paths = [],
  }: { context?: number; ignoresSpace?: boolean; isStaged?: boolean; paths?: readonly string[] } = {},
): Promise<{ files: PatchFile[]; refusal: string }> => {
  const ran = await run(
    [
      'git',
      'diff',
      '--no-color',
      '--no-ext-diff',
      `-U${Math.max(0, Math.floor(context))}`,
      ...(ignoresSpace ? ['-w'] : []),
      ...(isStaged ? ['--cached'] : []),
      '--no-prefix',
      '--relative',
      ...(target === '' ? [base] : [base, target]),
      ...(paths.length === 0 ? [] : ['--', ...paths]),
    ],
    { cwd: repo, timeoutMs: 60_000 },
  )

  return ran.exitCode === 0
    ? { files: parsePatch(ran.stdout), refusal: '' }
    : { files: [], refusal: ran.stderr.trim().split('\n').pop() ?? 'git could not diff' }
}

files.hooks/review.ts:
// Pull request / merge request lookup: turns what the user typed into two refs that exist locally.
// Handle-free on purpose: every command goes through the `run` the caller passes in.

import { plain, plainBlock, sampleOf } from './media'

// `stdin` is what the command reads, where it is given one (a JSON body).
export type Run = (
  argv: string[],
  timeoutMs?: number,
  stdin?: string,
) => Promise<{ exitCode: number; stdout: string; stderr: string }>

export type Forge = 'github' | 'gitlab' | 'unknown'

export type Request = {
  host: Forge
  number: number
  // "owner/repo" (or "group/sub/repo") when the text was a URL, so a link to another repo can be refused.
  repo?: string
}

export type Resolved = {
  side: string // the private ref holding the request's head, e.g. refs/lens/pr-12
  against: string // commit hash the head is compared with: where the branch forked from its target
  title: string // the request's title, or a note that the target was guessed
  label: string // "PR #12" or "MR !34"
  target: string // the target branch name, e.g. "main"
  isTargetGuessed: boolean // true when the forge CLI could not be asked
}

const FETCH_MS = 120_000
const CLI_MS = 30_000
const LOCAL_MS = 10_000

const REF_ROOT = 'refs/lens'

const asNumber = (digits: string | undefined): number | undefined => {
  const value = Number(digits)

  return Number.isSafeInteger(value) && value > 0 ? value : undefined
}

const trimRepo = (path: string): string => path.replace(/^\/+|\/+$/g, '').replace(/\.git$/i, '')

export const parseRequest = (text: string): Request | undefined => {
  const typed = text.trim()

  const mergeRequest = /^(?:https?:\/\/)?[^/\s]+\/(\S+?)\/(?:-\/)?merge_requests\/(\d+)(?:[/?#]\S*)?$/i.exec(typed)
  const pull = /^(?:https?:\/\/)?[^/\s]+\/(\S+?)\/pull\/(\d+)(?:[/?#]\S*)?$/i.exec(typed)
  const linked = mergeRequest ?? pull

  if (linked) {
    const number = asNumber(linked[2])

    return number === undefined
      ? undefined
      : { host: mergeRequest ? 'gitlab' : 'github', number, repo: trimRepo(linked[1] ?? '') }
  }

  const short = /^(pr|pull|mr)?\s*([#!])?\s*(\d+)$/i.exec(typed)

  if (!short) {
    return undefined
  }

  const number = asNumber(short[3])
  const word = short[1]?.toLowerCase()

  if (number === undefined) {
    return undefined
  }

  if (word !== undefined) {
    return { host: word === 'mr' ? 'gitlab' : 'github', number }
  }

  // "!34" is GitLab's own notation. "#12" is used loosely for both, so it is not a hint.
  return { host: short[2] === '!' ? 'gitlab' : 'unknown', number }
}

// Host and "owner/repo" path of a git remote URL, in its https, ssh:// or scp-like (git@host:path) form.
export const remoteParts = (remoteUrl: string): { host: string; repo: string } | undefined => {
  const url = remoteUrl.trim()
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\/(?:[^@/\s]+@)?([^/:\s]+)(?::\d+)?\/(\S+)$/i.exec(url)
  const scpLike = /^(?:[^@/\s]+@)?([^/:\s]+):(?!\/\/)(\S+)$/.exec(url)
  const found = withScheme ?? scpLike

  if (!found) {
    return undefined
  }

  return { host: (found[1] ?? '').toLowerCase(), repo: trimRepo(found[2] ?? '') }
}

export const forgeOf = (remoteUrl: string): Forge => {
  const host = remoteParts(remoteUrl)?.host ?? ''

  if (host.includes('github')) {
    return 'github'
  }

  return host.includes('gitlab') ? 'gitlab' : 'unknown'
}

const lastLine = (text: string): string =>
  text
    .split('\n')
    .map(line => line.trim())
    .filter(line => line !== '')
    .at(-1) ?? ''

const text = (value: unknown): string => (typeof value === 'string' ? value.trim() : '')

type Viewed = { title: string; target: string; forkPoint: string } | { why: string }

// Why the forge CLI gave nothing, in words that fit after "target guessed as main: ".
const whyNot = (cli: string, ran: { exitCode: number; stderr: string }): string => {
  if (/timed? ?out/i.test(ran.stderr)) {
    return `${cli} did not answer`
  }

  if (
    ran.exitCode === -1 ||
    ran.exitCode === 127 ||
    /ENOENT|command not found|no such file|not found in \$?PATH/i.test(ran.stderr)
  ) {
    return `${cli} is not installed`
  }

  if (/auth login|logged in|authenticat|unauthorized|401|token/i.test(ran.stderr)) {
    return `${cli} is not signed in, run ${cli} auth login`
  }

  return `${cli} could not read it`
}

const view = async (run: Run, forge: 'github' | 'gitlab', number: number, slug: string | undefined): Promise<Viewed> => {
  const cli = forge === 'github' ? 'gh' : 'glab'

  // gh is pointed at origin explicitly: on its own it may pick another remote (a fork's upstream).
  const argv =
    forge === 'github'
      ? [
          'gh',
          'pr',
          'view',
          String(number),
          ...(slug === undefined ? [] : ['--repo', slug]),
          '--json',
          'number,title,baseRefName,headRefName,baseRefOid',
        ]
      : ['glab', 'mr', 'view', String(number), '--output', 'json']

  const ran = await run(argv, CLI_MS).catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

  if (ran.exitCode !== 0) {
    return { why: whyNot(cli, ran) }
  }

  try {
    const parsed = JSON.parse(ran.stdout) as Record<string, unknown>
    const refs = (parsed.diff_refs ?? {}) as Record<string, unknown>
    const target = text(forge === 'github' ? parsed.baseRefName : parsed.target_branch)

    if (target === '') {
      return { why: `${cli} did not name a target branch` }
    }

    return {
      title: text(parsed.title),
      target,
      forkPoint: text(forge === 'github' ? parsed.baseRefOid : refs.base_sha),
    }
  } catch {
    return { why: `${cli} gave an answer that could not be read` }
  }
}

export const resolveRequest = async (run: Run, typed: string): Promise<Resolved | { error: string }> => {
  const request = parseRequest(typed)

  if (!request) {
    return { error: `"${typed.trim()}" is not a PR or MR: type a number like 12, or paste its URL` }
  }

  const remote = await run(['git', 'remote', 'get-url', 'origin'], LOCAL_MS)

  if (remote.exitCode !== 0 || remote.stdout.trim() === '') {
    return { error: 'This repo has no remote named origin to fetch a PR or MR from' }
  }

  const origin = remoteParts(remote.stdout)
  const known = forgeOf(remote.stdout)
  const forge = known === 'unknown' ? request.host : known

  if (forge === 'unknown') {
    return {
      error: `This repo's origin is not GitHub or GitLab; type "pr ${request.number}" or "mr ${request.number}" to say which it is`,
    }
  }

  const label = forge === 'github' ? `PR #${request.number}` : `MR !${request.number}`

  if (request.repo !== undefined && origin && request.repo.toLowerCase() !== origin.repo.toLowerCase()) {
    return { error: `That link is for ${request.repo}, but this repo's origin is ${origin.repo}; open that repo instead` }
  }

  const side = `${REF_ROOT}/${forge === 'github' ? 'pr' : 'mr'}-${request.number}`
  const tip = `${side}-base`
  const remoteHead = `refs/${forge === 'github' ? 'pull' : 'merge-requests'}/${request.number}/head`

  // The leading + lets a later fetch move the private ref after a force-push. No local branch is touched.
  const [fetched, viewed] = await Promise.all([
    run(['git', 'fetch', '--no-tags', 'origin', `+${remoteHead}:${side}`], FETCH_MS),
    view(run, forge, request.number, origin ? `${origin.host}/${origin.repo}` : undefined),
  ])

  if (fetched.exitCode !== 0) {
    return {
      error: /couldn't find remote ref/i.test(fetched.stderr)
        ? `${label} was not found on origin`
        : `${label} could not be fetched from origin: ${lastLine(fetched.stderr) || 'git fetch failed'}`,
    }
  }

  const fetchTarget = async (branch: string) =>
    run(['git', 'fetch', '--no-tags', 'origin', `+refs/heads/${branch}:${tip}`], FETCH_MS)

  let target = ''

  if ('why' in viewed) {
    const pointed = await run(['git', 'symbolic-ref', '--short', 'refs/remotes/origin/HEAD'], LOCAL_MS)
    const named = pointed.exitCode === 0 ? pointed.stdout.trim().replace(/^origin\//, '') : ''

    for (const branch of [...new Set([named, 'main', 'master'])].filter(one => one !== '')) {
      if ((await fetchTarget(branch)).exitCode === 0) {
        target = branch
        break
      }
    }

    if (target === '') {
      return { error: `No target branch for ${label} could be found on origin (${viewed.why})` }
    }
  } else {
    const got = await fetchTarget(viewed.target)

    if (got.exitCode !== 0) {
      return {
        error: `The target branch ${viewed.target} of ${label} could not be fetched from origin: ${lastLine(got.stderr) || 'git fetch failed'}`,
      }
    }

    target = viewed.target
  }

  // The forge records the target's commit the request is measured from. Once a request is merged, its
  // head is inside the target, so the target's tip alone would give an empty comparison.
  const forkPoint = 'why' in viewed ? '' : viewed.forkPoint
  const hasForkPoint =
    forkPoint !== '' && (await run(['git', 'cat-file', '-e', `${forkPoint}^{commit}`], LOCAL_MS)).exitCode === 0

  const merged = await run(['git', 'merge-base', side, hasForkPoint ? forkPoint : tip], LOCAL_MS)
  const against = merged.stdout.trim()

  if (merged.exitCode !== 0 || against === '') {
    return {
      error: `${label} and ${target} share no history here; if this is a shallow clone, run git fetch --unshallow`,
    }
  }

  const head = await run(['git', 'rev-parse', side], LOCAL_MS)
  const isEmpty = head.stdout.trim() === against

  const notes = [
    ...('why' in viewed ? [`target guessed as ${target}: ${viewed.why}`] : []),
    ...(isEmpty ? [`already merged into ${target}, nothing left to compare`] : []),
  ]

  const name = 'why' in viewed ? '' : viewed.title

  return {
    side,
    against,
    title: [name, notes.length > 0 ? `(${notes.join('; ')})` : ''].filter(part => part !== '').join(' ') || label,
    label,
    target,
    isTargetGuessed: 'why' in viewed,
  }
}

// ---------------------------------------------------------------------------------------------
// Review comments: reading every comment on a request, and posting one on a line.
// ---------------------------------------------------------------------------------------------

export type Comment = {
  // Line comments carry the forge's own number ("4109147516"). On GitHub the general ones are
  // prefixed ("issue-5917169258", "review-5393240365"), because the three kinds are numbered apart.
  id: string
  // Where it is attached: a path relative to the REPO ROOT and a 1-based line in the request's
  // head version of the file. `line` is 0 for a comment on the file as a whole, one on a removed
  // line (see oldLine), or one whose line no longer exists (outdated). `path` is '' for a general
  // comment on the request.
  path: string
  line: number
  author: string
  body: string
  when: string // ISO time as the forge gives it
  replyTo?: string // the id of the comment it answers: always the first comment of its thread
  isResolved?: boolean // where the forge says
  isOutdated?: boolean // attached to a version of the file that has since changed
  oldLine?: number // for a comment on a removed line: its line in the target's version of the file
  startLine?: number // for a comment on several lines: the first of them (`line` is the last)
  // What the forge calls the thread it is in, by which the thread is resolved (and, on GitLab,
  // replied to): GitHub's node id of the review thread, GitLab's discussion id. Absent where the
  // forge did not say, and on general comments.
  thread?: string
}

// A comment written and not yet sent: it waits to go with the review. `path`
// is from the folder under review; `line` is 0 for the file as a whole, and
// `startLine`, where it is before `line`, makes it a comment on those lines.
// `oldLine` puts it on a removed line, by its number in the target's version
// of the file (`line` is then 0, as on a comment the forge sends back).
export type Draft = { id: string; path: string; line: number; startLine?: number; oldLine?: number; body: string }

const DRAFT = 'draft-'

// A draft as the comment it will be, so the screens draw it where it will
// sit: its id says it is one (see `isDraft`).
export const draftComment = (draft: Draft): Comment => ({
  id: `${DRAFT}${draft.id}`,
  path: draft.path,
  line: draft.line,
  author: 'you · pending, not sent yet',
  body: draft.body,
  when: '',
  isOutdated: false,
  ...(draft.startLine !== undefined && draft.startLine > 0 && draft.startLine < draft.line
    ? { startLine: draft.startLine }
    : {}),
  ...(draft.oldLine !== undefined && draft.oldLine > 0 ? { oldLine: draft.oldLine } : {}),
})

export const isDraft = (one: Pick<Comment, 'id'>): boolean => one.id.startsWith(DRAFT)

// The id of the draft a comment made by `draftComment` stands for.
export const draftId = (one: Pick<Comment, 'id'>): string => one.id.slice(DRAFT.length)

// Whether a comment is on its file as a whole: it names a file and no line,
// and is neither one that lost its line to an edit nor one on a removed line.
export const isOnWholeFile = (one: Comment): boolean =>
  one.path !== '' && one.line === 0 && one.isOutdated !== true && one.oldLine === undefined

type Json = Record<string, unknown>

type Place = {
  forge: 'github' | 'gitlab'
  cli: 'gh' | 'glab'
  number: number
  host: string
  repo: string // "owner/repo", or "group/sub/repo"
  label: string // "PR #12" or "MR !34"
  noun: string // "pull request" or "merge request"
}

const COMMENTS_MS = 60_000

const record = (value: unknown): Json => (typeof value === 'object' && value !== null ? (value as Json) : {})

const whole = (value: unknown): number => (typeof value === 'number' && Number.isInteger(value) && value > 0 ? value : 0)

const named = (value: unknown): string => (typeof value === 'string' || typeof value === 'number' ? String(value) : '')

// Every JSON value in a CLI's output, with arrays flattened: a paginated call may print one merged
// array, or one value per page back to back.
const values = (stdout: string): unknown[] => {
  const found: unknown[] = []
  const take = (slice: string) => {
    const parsed: unknown = JSON.parse(slice)

    found.push(...(Array.isArray(parsed) ? (parsed as unknown[]) : [parsed]))
  }

  try {
    take(stdout)

    return found
  } catch {
    found.length = 0
  }

  let depth = 0
  let start = -1
  let isInString = false
  let isEscaped = false

  for (let at = 0; at < stdout.length; at++) {
    const char = stdout[at]

    if (isInString) {
      if (isEscaped) {
        isEscaped = false
      } else if (char === '\\') {
        isEscaped = true
      } else if (char === '"') {
        isInString = false
      }
    } else if (char === '"') {
      isInString = true
    } else if (char === '{' || char === '[') {
      if (depth === 0) {
        start = at
      }

      depth++
    } else if (char === '}' || char === ']') {
      depth--

      if (depth === 0 && start >= 0) {
        take(stdout.slice(start, at + 1))
        start = -1
      }
    }
  }

  if (depth !== 0) {
    throw new Error('cut short')
  }

  return found
}

const call = async (run: Run, argv: string[], timeoutMs = COMMENTS_MS) =>
  run(argv, timeoutMs).catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

// What the forge itself said went wrong: the "message" of its JSON answer, else the CLI's last line.
const forgeSaid = (ran: { stdout: string; stderr: string }): string => {
  try {
    const answer = record(JSON.parse(ran.stdout))
    const said = answer.message ?? answer.error

    return [
      typeof said === 'string' ? said : said === undefined ? '' : JSON.stringify(said),
      answer.errors === undefined ? '' : JSON.stringify(answer.errors),
    ].join(' ')
  } catch {
    return lastLine(ran.stderr)
  }
}

// One sentence for a forge call that failed. `doing` is "read" or "comment on".
const whyFailed = (
  place: Place,
  ran: { exitCode: number; stdout: string; stderr: string },
  doing: 'read' | 'comment on',
  at?: { path: string; line: number },
): string => {
  const { cli, label, noun } = place
  const all = `${ran.stderr}\n${ran.stdout}`
  const status = /HTTP (\d{3})/.exec(ran.stderr)?.[1] ?? ''

  if (status === '') {
    if (/timed? ?out/i.test(ran.stderr)) {
      return `${cli} did not answer`
    }

    if (
      ran.exitCode === -1 ||
      ran.exitCode === 127 ||
      /ENOENT|command not found|no such file|not found in \$?PATH/i.test(ran.stderr)
    ) {
      return `${cli} is not installed`
    }
  }

  if (status === '401' || (status === '' && /auth login|not logged in|authenticat|unauthorized|bad credentials/i.test(all))) {
    return `${cli} is not signed in: run ${cli} auth login`
  }

  if (/rate limit/i.test(all) || status === '429') {
    return `${place.forge === 'github' ? 'GitHub' : 'GitLab'} is refusing more calls for now (rate limit): try again in a few minutes`
  }

  if (status === '403') {
    return `You do not have permission to ${doing} this ${noun}`
  }

  if (status === '404' || /could not resolve to a/i.test(all)) {
    return `${label} was not found in ${place.repo}, or you may not see it`
  }

  if (at && (status === '422' || status === '400')) {
    if (/commit_id|head_sha|base_sha|start_sha/i.test(all)) {
      return `This ${noun} has changed since it was opened here: reopen it, then comment again`
    }

    if (/line|diff_hunk|position|path/i.test(all)) {
      return `Line ${at.line} of ${at.path} is not part of this ${noun}'s diff`
    }
  }

  const said = forgeSaid(ran).replace(/\s+/g, ' ').trim().slice(0, 160)

  return doing === 'read'
    ? `The comments of ${label} could not be read: ${said || `${cli} failed`}`
    : `The comment could not be posted on ${label}: ${said || `${cli} failed`}`
}

// Which request `typed` names, on which forge and repo: the same reading of it as resolveRequest.
const locate = async (run: Run, typed: string): Promise<Place | { error: string }> => {
  const request = parseRequest(typed)

  if (!request) {
    return { error: `"${typed.trim()}" is not a PR or MR: type a number like 12, or paste its URL` }
  }

  const remote = await call(run, ['git', 'remote', 'get-url', 'origin'], LOCAL_MS)
  const origin = remote.exitCode === 0 ? remoteParts(remote.stdout) : undefined

  if (!origin || origin.repo === '') {
    return { error: 'This repo has no remote named origin to read a PR or MR from' }
  }

  const known = forgeOf(remote.stdout)
  const forge = known === 'unknown' ? request.host : known

  if (forge === 'unknown') {
    return {
      error: `This repo's origin is not GitHub or GitLab; type "pr ${request.number}" or "mr ${request.number}" to say which it is`,
    }
  }

  if (request.repo !== undefined && request.repo.toLowerCase() !== origin.repo.toLowerCase()) {
    return { error: `That link is for ${request.repo}, but this repo's origin is ${origin.repo}; open that repo instead` }
  }

  return {
    forge,
    cli: forge === 'github' ? 'gh' : 'glab',
    number: request.number,
    host: origin.host,
    repo: origin.repo,
    label: forge === 'github' ? `PR #${request.number}` : `MR !${request.number}`,
    noun: forge === 'github' ? 'pull request' : 'merge request',
  }
}

const byTime = (comments: Comment[]): Comment[] =>
  comments
    .map((comment, index) => ({ comment, index }))
    .sort((one, other) =>
      one.comment.when === other.comment.when
        ? one.index - other.index
        : one.comment.when < other.comment.when
          ? -1
          : 1,
    )
    .map(({ comment }) => comment)

// ---- GitHub ----

type ThreadState = { isResolved: boolean; isOutdated: boolean; id: string }

const THREADS_QUERY =
  'query($owner:String!,$name:String!,$number:Int!,$endCursor:String){repository(owner:$owner,name:$name){' +
  'pullRequest(number:$number){reviewThreads(first:100,after:$endCursor){pageInfo{hasNextPage endCursor}' +
  'nodes{id isResolved isOutdated comments(first:1){nodes{databaseId}}}}}}}'

const gh = (place: Place, ...rest: string[]): string[] => ['gh', 'api', '--hostname', place.host, ...rest]

// One review comment as GitHub's REST API gives it. `threads` is keyed by the id of a thread's first comment.
const fromGithubLine = (raw: unknown, threads: Map<string, ThreadState>): Comment => {
  const one = record(raw)
  const id = named(one.id)
  const replyTo = named(one.in_reply_to_id)
  const thread = threads.get(replyTo || id)
  const isOnFile = one.subject_type === 'file'
  const line = whole(one.line)
  // A comment whose line has since changed keeps only its original_line: `line` comes back null.
  const isOutdated = !isOnFile && line === 0
  const isOnOld = one.side === 'LEFT'

  return {
    id,
    path: text(one.path),
    line: isOnOld ? 0 : line,
    author: text(record(one.user).login) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(one.created_at),
    ...(replyTo === '' ? {} : { replyTo }),
    ...(thread ? { isResolved: thread.isResolved } : {}),
    ...(thread && thread.id !== '' ? { thread: thread.id } : {}),
    isOutdated,
    ...(isOnOld && line > 0 ? { oldLine: line } : {}),
    ...(!isOnOld && whole(one.start_line) > 0 && whole(one.start_line) < line
      ? { startLine: whole(one.start_line) }
      : {}),
  }
}

const fromGithubGeneral = (raw: unknown, kind: 'issue' | 'review'): Comment => {
  const one = record(raw)

  return {
    id: `${kind}-${named(one.id)}`,
    path: '',
    line: 0,
    author: text(record(one.user).login) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(kind === 'issue' ? one.created_at : one.submitted_at),
  }
}

const githubComments = async (run: Run, place: Place): Promise<{ comments: Comment[] } | { error: string }> => {
  const [owner = '', name = ''] = place.repo.split('/')
  const base = `repos/${place.repo}`

  const [lines, talk, reviews, threadPages] = await Promise.all([
    call(run, gh(place, `${base}/pulls/${place.number}/comments?per_page=100`, '--paginate')),
    call(run, gh(place, `${base}/issues/${place.number}/comments?per_page=100`, '--paginate')),
    call(run, gh(place, `${base}/pulls/${place.number}/reviews?per_page=100`, '--paginate')),
    call(
      run,
      gh(
        place,
        'graphql',
        '--paginate',
        '-f',
        `query=${THREADS_QUERY}`,
        '-f',
        `owner=${owner}`,
        '-f',
        `name=${name}`,
        '-F',
        `number=${place.number}`,
      ),
    ),
  ])

  for (const ran of [lines, talk, reviews]) {
    if (ran.exitCode !== 0) {
      return { error: whyFailed(place, ran, 'read') }
    }
  }

  // Resolved state only exists on threads, which only GraphQL lists. Without it the comments
  // are still worth showing, so a failure here is not an error: isResolved is just left out.
  const threads = new Map<string, ThreadState>()

  if (threadPages.exitCode === 0) {
    try {
      for (const page of values(threadPages.stdout)) {
        const listed = record(record(record(record(record(page).data).repository).pullRequest).reviewThreads).nodes

        for (const node of Array.isArray(listed) ? (listed as unknown[]) : []) {
          const thread = record(node)
          const first = (record(thread.comments).nodes as unknown[] | undefined)?.[0]
          const id = named(record(first).databaseId)

          if (id !== '') {
            threads.set(id, {
              isResolved: thread.isResolved === true,
              isOutdated: thread.isOutdated === true,
              id: named(thread.id),
            })
          }
        }
      }
    } catch {
      threads.clear()
    }
  }

  try {
    return {
      comments: byTime([
        ...values(lines.stdout).map(raw => fromGithubLine(raw, threads)),
        ...values(talk.stdout).map(raw => fromGithubGeneral(raw, 'issue')),
        // A review is listed even when it only carried line comments: then its own body is empty.
        ...values(reviews.stdout)
          .map(raw => fromGithubGeneral(raw, 'review'))
          .filter(comment => comment.body.trim() !== '' && comment.when !== ''),
      ]),
    }
  } catch {
    return { error: `The comments of ${place.label} could not be read: gh gave an answer that could not be read` }
  }
}

// ---- GitLab ----

const glab = (place: Place, ...rest: string[]): string[] => ['glab', 'api', '--hostname', place.host, ...rest]

// "group/sub/app" goes in as one encoded path segment, which is how GitLab takes a project by its path.
const gitlabRequest = (place: Place): string =>
  `projects/${encodeURIComponent(place.repo)}/merge_requests/${place.number}`

// One note of a discussion. `headSha` is the request's current head, '' when it is not known.
const fromGitlabNote = (raw: unknown, rootId: string, headSha: string, thread = ''): Comment => {
  const one = record(raw)
  const id = named(one.id)
  const hasPlace = typeof one.position === 'object' && one.position !== null
  const position = record(one.position)
  const madeOn = text(position.head_sha)
  // GitLab moves a note's position along with new commits while its line survives, so a position
  // still naming an older head is one whose line has changed since.
  const isOutdated = hasPlace && headSha !== '' && madeOn !== '' ? madeOn !== headSha : undefined
  const isOnFile = position.position_type !== undefined && position.position_type !== 'text'
  const newLine = whole(position.new_line)
  const oldLine = whole(position.old_line)

  return {
    id,
    path: hasPlace ? text(position.new_path) || text(position.old_path) : '',
    line: isOutdated === true || isOnFile ? 0 : newLine,
    author: text(record(one.author).username) || text(record(one.author).name) || 'ghost',
    body: typeof one.body === 'string' ? one.body : '',
    when: text(one.created_at),
    ...(rootId === id ? {} : { replyTo: rootId }),
    ...(one.resolvable === true ? { isResolved: one.resolved === true } : {}),
    ...(isOutdated === undefined ? {} : { isOutdated }),
    ...(hasPlace && !isOnFile && newLine === 0 && oldLine > 0 ? { oldLine } : {}),
    // Only a thread that can be resolved is kept by its discussion: a general note has none.
    ...(thread === '' || one.resolvable !== true ? {} : { thread }),
  }
}

const fromGitlabDiscussion = (raw: unknown, headSha: string): Comment[] => {
  const listed = record(raw).notes
  const notes = (Array.isArray(listed) ? (listed as unknown[]) : []).filter(note => record(note).system !== true)
  const rootId = named(record(notes[0]).id)

  const thread = named(record(raw).id)

  return notes.map(note => fromGitlabNote(note, rootId, headSha, thread))
}

const gitlabComments = async (run: Run, place: Place): Promise<{ comments: Comment[] } | { error: string }> => {
  const [discussions, request] = await Promise.all([
    call(run, glab(place, `${gitlabRequest(place)}/discussions?per_page=100`, '--paginate')),
    call(run, glab(place, gitlabRequest(place))),
  ])

  if (discussions.exitCode !== 0) {
    return { error: whyFailed(place, discussions, 'read') }
  }

  let headSha = ''

  try {
    headSha = request.exitCode === 0 ? text(record(record(JSON.parse(request.stdout)).diff_refs).head_sha) : ''
  } catch {
    headSha = ''
  }

  try {
    return { comments: byTime(values(discussions.stdout).flatMap(raw => fromGitlabDiscussion(raw, headSha))) }
  } catch {
    return { error: `The comments of ${place.label} could not be read: glab gave an answer that could not be read` }
  }
}

// Where a line of the head version sits in the base version, read from `git diff -U0` output:
// `added` when the line is new, else the line it was. GitLab wants both lines for an unchanged one.
const oldLineOf = (diff: string, line: number): { isAdded: true } | { isAdded: false; oldLine: number } => {
  let shift = 0

  for (const hunk of diff.matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)) {
    const removed = hunk[2] === undefined ? 1 : Number(hunk[2])
    const start = Number(hunk[3])
    const added = hunk[4] === undefined ? 1 : Number(hunk[4])

    if (added > 0 && line >= start && line < start + added) {
      return { isAdded: true }
    }

    // With nothing added, `start` is the line the removal follows.
    if (added > 0 ? start + added - 1 < line : start < line) {
      shift += added - removed
    }
  }

  return { isAdded: false, oldLine: line - shift }
}

// Where the base's counter of lines stands at a line of the head version,
// read from the same diff: for an unchanged line that is the line it was;
// for an added one, the line of the base it was put in before. It is the
// middle part of the name GitLab knows a line of a diff by.
const oldPosOf = (diff: string, line: number): number => {
  let shift = 0

  for (const hunk of diff.matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)) {
    const from = Number(hunk[1])
    const removed = hunk[2] === undefined ? 1 : Number(hunk[2])
    const start = Number(hunk[3])
    const added = hunk[4] === undefined ? 1 : Number(hunk[4])

    if (added > 0 && line >= start && line < start + added) {
      // After what the hunk removed; with nothing removed, `from` is the
      // line the addition follows.
      return removed === 0 ? from + 1 : from + removed
    }

    if (added > 0 ? start + added - 1 < line : start < line) {
      shift += added - removed
    }
  }

  return line - shift
}

// The name GitLab knows a line of a diff by: the SHA-1 of the file's path,
// then where the base's and the head's counters of lines stand at it.
export const gitlabLineCode = async (path: string, oldPos: number, newPos: number): Promise<string> => {
  const digest = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(path))

  return `${[...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('')}_${oldPos}_${newPos}`
}

// The file's path in the base (another, for a renamed file) and how it
// changed there (`M`, `A`, `R100`, ...; '' for a file the request does not
// touch), by its path in the head.
const gitlabOldPath = async (
  run: Run,
  baseSha: string,
  headSha: string,
  path: string,
): Promise<{ status: string; oldPath: string } | undefined> => {
  const changed = await call(run, ['git', 'diff', '--name-status', '-M', '-z', baseSha, headSha, '--'], LOCAL_MS)

  if (changed.exitCode !== 0) {
    return undefined
  }

  const fields = changed.stdout.split('\0')
  let found = { status: '', oldPath: path }

  for (let index = 0; index < fields.length - 1; ) {
    const kind = fields[index] ?? ''
    const isMoved = /^[RC]/.test(kind)
    const from = fields[index + 1] ?? ''
    const to = isMoved ? (fields[index + 2] ?? '') : from

    if (to === path) {
      found = { status: kind, oldPath: from }
    }

    index += isMoved ? 3 : 2
  }

  return found
}

const gitlabPost = async (
  run: Run,
  place: Place,
  at: { path: string; line: number; commit: string; startLine?: number; oldLine?: number },
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  const request = await call(run, glab(place, gitlabRequest(place)))

  if (request.exitCode !== 0) {
    return { error: whyFailed(place, request, 'comment on') }
  }

  let refs: Json = {}

  try {
    refs = record(record(JSON.parse(request.stdout)).diff_refs)
  } catch {
    refs = {}
  }

  const baseSha = text(refs.base_sha)
  const startSha = text(refs.start_sha)
  const headSha = text(refs.head_sha)

  if (baseSha === '' || startSha === '' || headSha === '') {
    return { error: `The comment could not be posted on ${place.label}: glab did not say which commits it compares` }
  }

  if (headSha !== at.commit) {
    return { error: 'This merge request has changed since it was opened here: reopen it, then comment again' }
  }

  // A comment on a removed line is placed by that line of the base alone,
  // under the name the file had there.
  if ((at.oldLine ?? 0) > 0) {
    const was = await gitlabOldPath(run, baseSha, headSha, at.path)
    const gone = await call(
      run,
      glab(
        place,
        '-X',
        'POST',
        `${gitlabRequest(place)}/discussions`,
        '-f',
        `body=${body}`,
        '-F',
        `position=${JSON.stringify({
          position_type: 'text',
          base_sha: baseSha,
          start_sha: startSha,
          head_sha: headSha,
          old_path: was?.oldPath ?? at.path,
          new_path: at.path,
          old_line: at.oldLine,
        })}`,
      ),
    )

    if (gone.exitCode !== 0) {
      return { error: whyFailed(place, gone, 'comment on') }
    }

    try {
      const comment = fromGitlabDiscussion(JSON.parse(gone.stdout), headSha)[0]

      if (!comment) {
        throw new Error('no note')
      }

      return { comment: { ...comment, path: comment.path || at.path, line: 0, oldLine: at.oldLine as number } }
    } catch {
      return { error: `The comment may have been posted on ${place.label}, but glab's answer could not be read: reload to check` }
    }
  }

  // A comment on the file as a whole is placed by its path alone.
  if (at.line === 0) {
    const whole = await call(
      run,
      glab(
        place,
        '-X',
        'POST',
        `${gitlabRequest(place)}/discussions`,
        '-f',
        `body=${body}`,
        '-F',
        `position=${JSON.stringify({
          position_type: 'file',
          base_sha: baseSha,
          start_sha: startSha,
          head_sha: headSha,
          old_path: at.path,
          new_path: at.path,
        })}`,
      ),
    )

    if (whole.exitCode !== 0) {
      return { error: whyFailed(place, whole, 'comment on') }
    }

    try {
      const comment = fromGitlabDiscussion(JSON.parse(whole.stdout), headSha)[0]

      if (!comment) {
        throw new Error('no note')
      }

      return { comment: { ...comment, path: comment.path || at.path, line: 0 } }
    } catch {
      return { error: `The comment may have been posted on ${place.label}, but glab's answer could not be read: reload to check` }
    }
  }

  // GitLab places a note by old and new line together. Git knows both when the commits are here;
  // when they are not, the new line alone is sent, which GitLab accepts for added lines.
  const outside = { error: `Line ${at.line} of ${at.path} is not part of this merge request's diff` }
  let oldPath = at.path
  let oldLine = 0
  // The file's own diff, kept for the names of the lines a comment on
  // several of them runs from and to.
  let fileDiff: string | undefined

  const was = await gitlabOldPath(run, baseSha, headSha, at.path)

  if (was !== undefined) {
    oldPath = was.oldPath

    if (was.status === '' || was.status.startsWith('D')) {
      return outside
    }

    if (!was.status.startsWith('A')) {
      const diff = await call(
        run,
        ['git', 'diff', '--no-color', '--no-ext-diff', '-U0', '-M', baseSha, headSha, '--', ...new Set([oldPath, at.path])],
        LOCAL_MS,
      )
      const where = diff.exitCode === 0 ? oldLineOf(diff.stdout, at.line) : { isAdded: true as const }

      oldLine = where.isAdded ? 0 : where.oldLine
      fileDiff = diff.exitCode === 0 ? diff.stdout : undefined
    } else {
      // A new file is all one addition: every line was put in before line 1.
      fileDiff = ''
    }
  }

  // glab sends fields as a JSON body, where a name like position[new_line] would be one literal key
  // that GitLab ignores; -F parses a JSON object, so the position travels as one.
  const position = {
    position_type: 'text',
    base_sha: baseSha,
    start_sha: startSha,
    head_sha: headSha,
    old_path: oldPath,
    new_path: at.path,
    new_line: at.line,
    ...(oldLine > 0 ? { old_line: oldLine } : {}),
  }
  const startLine = at.startLine !== undefined && at.startLine > 0 && at.startLine < at.line ? at.startLine : 0
  const send = (where: object, said: string) =>
    call(
      run,
      glab(place, '-X', 'POST', `${gitlabRequest(place)}/discussions`, '-f', `body=${said}`, '-F', `position=${JSON.stringify(where)}`),
    )
  // A comment on several lines names the first and the last of them the way
  // GitLab knows a line of a diff. Those names are worked out here from
  // git's own diff, so where GitLab does not take them (or they could not
  // be worked out) the comment still goes: on the last line, saying which
  // lines it is about.
  const named = async (line: number): Promise<{ line_code: string; type: 'new' } | undefined> => {
    if (fileDiff === undefined) {
      return undefined
    }

    // In a new file every line is an addition before the base's line 1.
    const isNew = was?.status.startsWith('A') === true

    return { line_code: await gitlabLineCode(at.path, isNew ? 1 : oldPosOf(fileDiff, line), line), type: 'new' }
  }
  const range = startLine === 0 ? undefined : { start: await named(startLine), end: await named(at.line) }
  const ranged =
    range?.start !== undefined && range.end !== undefined
      ? await send({ ...position, line_range: range }, body)
      : undefined
  const posted =
    ranged !== undefined && ranged.exitCode === 0
      ? ranged
      : await send(position, startLine === 0 ? body : `Lines ${startLine}–${at.line}: ${body}`)

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on', at) }
  }

  try {
    const comment = fromGitlabDiscussion(JSON.parse(posted.stdout), headSha)[0]

    if (!comment) {
      throw new Error('no note')
    }

    // An older glab that does not send the position would post a general comment instead.
    return comment.path === ''
      ? { error: `The comment was posted on ${place.label}, but not on the line: update glab, and move it on GitLab` }
      : { comment }
  } catch {
    return { error: `The comment may have been posted on ${place.label}, but glab's answer could not be read: reload to check` }
  }
}

// ---- The three entry points ----

// Every comment on the request, oldest first: review comments on lines, and the general conversation.
// `typed` is what the person typed to open the request ("#12", a URL, ...), as resolveRequest takes.
// The open pull or merge request whose head is a branch of this repo, by
// what a person would type to open it ("#12") and how it is spoken of
// ("PR #12"); undefined when there is none, or no forge to ask.
export const requestOfBranch = async (
  run: Run,
  branch: string,
): Promise<
  { typed: string; label: string; title: string; baseRef: string; url: string } | undefined
> => {
  if (branch === '' || branch === 'HEAD') {
    return undefined
  }

  const place = await locate(run, '1')

  if ('error' in place) {
    return undefined
  }

  const isGitlab = place.forge === 'gitlab'
  const asked = await call(
    run,
    isGitlab
      ? glab(
          place,
          `projects/${encodeURIComponent(place.repo)}/merge_requests?state=opened&source_branch=${encodeURIComponent(branch)}`,
        )
      : gh(
          place,
          `repos/${place.repo}/pulls?state=open&head=${encodeURIComponent(`${place.repo.split('/')[0] ?? ''}:${branch}`)}`,
        ),
    20_000,
  )

  if (asked.exitCode !== 0) {
    return undefined
  }

  try {
    const first = record(values(asked.stdout)[0])
    const number = whole(isGitlab ? first.iid : first.number)

    // What it is called, and the branch it asks to be merged into.
    const title = plain(text(first.title)).slice(0, 300)
    const baseRef = isGitlab ? text(first.target_branch) : text(record(first.base).ref)
    // Its page on the forge.
    const url = isGitlab ? text(first.web_url) : text(first.html_url)

    return number === 0
      ? undefined
      : isGitlab
        ? { typed: `!${number}`, label: `MR !${number}`, title, baseRef, url }
        : { typed: `#${number}`, label: `PR #${number}`, title, baseRef, url }
  } catch {
    return undefined
  }
}

// The repo's open pull or merge requests, newest first, each by what a person
// would type to open it ("#12", "!34") and its title. None where there is no
// forge to ask, or it does not answer: a list to offer, never an error.
//
// Each also says who opened it, whether that is the person signed in to the
// forge's CLI (`isMine`), whether it is a draft, the branch it is from, and
// when it last changed (an ISO time, '' where the forge did not say).
export type Listed = {
  typed: string
  title: string
  author: string
  isMine: boolean
  isDraft: boolean
  branch: string
  when: string
  // Whether it is still open, was merged, or was closed without merging.
  state: 'open' | 'merged' | 'closed'
  // The first line or two of what its description says, as plain text; ''
  // for a request that says nothing.
  summary: string
  // Whether its checks pass ("SUCCESS", "FAILURE", "PENDING", GitLab's
  // "RUNNING", ...) and what its reviews come to ("APPROVED", ...), in the
  // forge's own words; '' where it has none or the forge did not say.
  checks: string
  decision: string
  // How much has been said on it: comments on the request as a whole (on
  // GitLab, every note), and its threads on files still open and resolved
  // (GitHub; 0 where the forge did not say).
  said: number
  open: number
  resolved: number
}

// The standing of each open request, asked of each forge its own way: the
// state its last commit's checks add up to (GitHub), or its head pipeline's
// (GitLab), and whether it is approved.
const GITHUB_STANDING =
  'query($owner:String!,$name:String!){repository(owner:$owner,name:$name){pullRequests(states:OPEN,first:50,orderBy:{field:UPDATED_AT,direction:DESC}){nodes{number reviewDecision comments{totalCount} reviewThreads(first:100){nodes{isResolved}} commits(last:1){nodes{commit{statusCheckRollup{state}}}}}}}}'
const GITLAB_STANDING =
  'query($path:ID!){project(fullPath:$path){mergeRequests(state:opened,first:50,sort:UPDATED_DESC){nodes{iid approved approvedBy(first:1){nodes{username}} headPipeline{status}}}}}'

// `isPast` lists the requests that are over in place of the open ones: those
// merged and those closed without it, the latest to change first.
export const listRequests = async (run: Run, isPast = false): Promise<Listed[]> => {
  const place = await locate(run, '1')

  if ('error' in place) {
    return []
  }

  const isGitlab = place.forge === 'gitlab'
  const gitlabList = (state: string, count: number) =>
    call(
      run,
      glab(
        place,
        `projects/${encodeURIComponent(place.repo)}/merge_requests?state=${state}&order_by=updated_at&per_page=${count}`,
      ),
      20_000,
    )
  // GitLab lists one state at a time, so the two that are over are asked
  // side by side and read as one list (two answers back to back).
  const past = async (): Promise<Awaited<ReturnType<typeof call>>> => {
    if (!isGitlab) {
      return call(run, gh(place, `repos/${place.repo}/pulls?state=closed&sort=updated&direction=desc&per_page=50`), 20_000)
    }

    const [merged, closed] = await Promise.all([gitlabList('merged', 30), gitlabList('closed', 20)])

    return merged.exitCode !== 0 && closed.exitCode !== 0
      ? merged
      : { exitCode: 0, stdout: `${merged.exitCode === 0 ? merged.stdout : ''}${closed.exitCode === 0 ? closed.stdout : ''}`, stderr: '' }
  }
  const [listed, signedIn, stood] = await Promise.all([
    isPast
      ? past()
      : isGitlab
        ? gitlabList('opened', 50)
        : call(run, gh(place, `repos/${place.repo}/pulls?state=open&per_page=50`), 20_000),
    // Who is asking, to tell their own requests from the rest.
    call(run, isGitlab ? glab(place, 'user') : gh(place, 'user'), 20_000),
    // Whether each one's checks pass, and what its reviews come to: the
    // list itself does not say, on either forge, so they are asked beside it.
    // (Requests that are over are listed without it: it is of no use there.)
    isPast ? Promise.resolve({ exitCode: 1, stdout: '', stderr: '' }) : call(
      run,
      isGitlab
        ? glab(place, 'graphql', '-f', `query=${GITLAB_STANDING}`, '-f', `path=${place.repo}`)
        : gh(
            place,
            'graphql',
            '-f',
            `query=${GITHUB_STANDING}`,
            '-f',
            `owner=${place.repo.split('/')[0] ?? ''}`,
            '-f',
            `name=${place.repo.split('/')[1] ?? ''}`,
          ),
      20_000,
    ),
  ])

  if (listed.exitCode !== 0) {
    return []
  }

  // Each request's standing by its number; none where the forge did not say.
  const standing = new Map<number, { checks: string; decision: string; said: number; open: number; resolved: number }>()

  try {
    const data = record(record(JSON.parse(stood.stdout)).data)
    const nodes = isGitlab
      ? record(record(data.project).mergeRequests).nodes
      : record(record(data.repository).pullRequests).nodes

    for (const raw of stood.exitCode === 0 && Array.isArray(nodes) ? (nodes as unknown[]) : []) {
      const node = record(raw)
      const commit = record(record((Array.isArray(record(node.commits).nodes) ? (record(node.commits).nodes as unknown[]) : [])[0]).commit)

      const threads = Array.isArray(record(node.reviewThreads).nodes) ? (record(node.reviewThreads).nodes as unknown[]) : []
      const settled = threads.filter(thread => record(thread).isResolved === true).length

      standing.set(Number(isGitlab ? node.iid : node.number), {
        said: whole(record(node.comments).totalCount),
        open: threads.length - settled,
        resolved: settled,
        // A request the forge answered for that has no checks says so (NONE):
        // the row then tells "none" from "the forge was not asked".
        checks: plain(text(isGitlab ? record(node.headPipeline).status : record(commit.statusCheckRollup).state)).slice(0, 40) || 'NONE',
        // GitLab calls a request approved when it needs no approval at all,
        // so it is said to be only where someone did approve it.
        decision: plain(
          isGitlab
            ? node.approved === true &&
              Array.isArray(record(node.approvedBy).nodes) &&
              (record(node.approvedBy).nodes as unknown[]).length > 0
              ? 'APPROVED'
              : ''
            : text(node.reviewDecision),
        ).slice(0, 40),
      })
    }
  } catch {
    standing.clear()
  }

  let me = ''

  try {
    const user = record(JSON.parse(signedIn.stdout))

    me = signedIn.exitCode === 0 ? text(isGitlab ? user.username : user.login) : ''
  } catch {
    me = ''
  }

  try {
    const rows: Listed[] = values(listed.stdout).flatMap(raw => {
      const one = record(raw)
      const number = whole(isGitlab ? one.iid : one.number)
      const by = record(isGitlab ? one.author : one.user)
      const author = text(isGitlab ? by.username : by.login)

      return number === 0
        ? []
        : [
            {
              typed: `${isGitlab ? '!' : '#'}${number}`,
              // What people wrote is made plain before it is handed on.
              title: plain(text(one.title)).slice(0, 300),
              author: plain(author).slice(0, 100),
              isMine: me !== '' && author === me,
              isDraft: (isGitlab ? (one.draft ?? one.work_in_progress) : one.draft) === true,
              branch: plain(text(isGitlab ? one.source_branch : record(one.head).ref)).slice(0, 200),
              when: text(one.updated_at),
              // GitHub calls a merged request closed, and says when it was merged.
              state: (isGitlab
                ? text(one.state) === 'merged'
                  ? 'merged'
                  : text(one.state) === 'closed'
                    ? 'closed'
                    : 'open'
                : typeof one.merged_at === 'string' && one.merged_at !== ''
                  ? 'merged'
                  : text(one.state) === 'closed'
                    ? 'closed'
                    : 'open') as Listed['state'],
              checks: standing.get(number)?.checks ?? '',
              decision: standing.get(number)?.decision ?? '',
              // GitLab's list says how many notes people left; GitHub's are
              // counted beside the checks, with which threads are settled.
              said: isGitlab ? whole(one.user_notes_count) : (standing.get(number)?.said ?? 0),
              open: standing.get(number)?.open ?? 0,
              resolved: standing.get(number)?.resolved ?? 0,
              summary:
                sampleOf(
                  typeof (isGitlab ? one.description : one.body) === 'string'
                    ? ((isGitlab ? one.description : one.body) as string)
                    : '',
                  2,
                  240,
                ).join(' · '),
            },
          ]
    })

    // Those that are over come latest first, whichever kind each is.
    return isPast ? rows.filter(one => one.state !== 'open').sort((a, b) => b.when.localeCompare(a.when)) : rows
  } catch {
    return []
  }
}

// What a request is, beyond its code: what it says it does, whether its
// checks pass, who has reviewed it, whether it can be merged, and its
// commits. `lastReviewed` is the commit the person signed in to the forge's
// CLI last reviewed it at ('' when they have not, or the forge did not say).
export type Overview = {
  title: string
  body: string
  author: string
  state: string
  isDraft: boolean
  url: string
  base: string
  head: string
  // What the forge says of merging it ("MERGEABLE", "CONFLICTING", ...) and
  // of its reviews as a whole ("APPROVED", "CHANGES_REQUESTED", ...), in its
  // own words; '' where it did not say.
  mergeable: string
  decision: string
  checks: { name: string; state: string; url: string }[]
  reviews: { author: string; state: string; when: string }[]
  commits: { hash: string; subject: string; author: string }[]
  labels: string[]
  additions: number
  deletions: number
  files: number
  lastReviewed: string
}

const count = (value: unknown): number => (typeof value === 'number' && Number.isFinite(value) ? value : 0)

// An overview as it is handed on to be drawn. All of it is what people on
// the forge wrote (a title, a branch's name, a check's, a label), so every
// word is made plain text first and held to a length, the description keeps
// its lines but nothing a terminal would act on, and the lists are bounded.
const LISTED = 200
const WORD = 300
const tidyOverview = (seen: Overview): Overview => {
  const word = (value: string): string => plain(value).slice(0, WORD)
  const link = (value: string): string => (/^https?:\/\/[\x21-\x7e]{1,2000}$/.test(value) ? value : '')

  return {
    title: word(seen.title),
    body: plainBlock(seen.body).slice(0, 200_000),
    author: word(seen.author),
    state: word(seen.state),
    isDraft: seen.isDraft,
    url: link(seen.url),
    base: word(seen.base),
    head: word(seen.head),
    mergeable: word(seen.mergeable),
    decision: word(seen.decision),
    checks: seen.checks.slice(0, LISTED).map(one => ({ name: word(one.name), state: word(one.state), url: link(one.url) })),
    reviews: seen.reviews.slice(0, LISTED).map(one => ({ author: word(one.author), state: word(one.state), when: word(one.when) })),
    commits: seen.commits.slice(-LISTED).map(one => ({ hash: word(one.hash), subject: word(one.subject), author: word(one.author) })),
    labels: seen.labels.slice(0, LISTED).map(word),
    additions: seen.additions,
    deletions: seen.deletions,
    files: seen.files,
    // A commit's hash, or nothing: it is handed to git.
    lastReviewed: /^[0-9a-f]{7,64}$/.test(seen.lastReviewed) ? seen.lastReviewed : '',
  }
}

// Reads a request's overview from the forge. `typed` is what the person
// typed to open it.
export const readOverview = async (run: Run, typed: string): Promise<{ overview: Overview } | { error: string }> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  if (place.forge === 'gitlab') {
    const [seen, approvals, listed, signedIn] = await Promise.all([
      call(run, glab(place, gitlabRequest(place))),
      call(run, glab(place, `${gitlabRequest(place)}/approvals`)),
      call(run, glab(place, `${gitlabRequest(place)}/commits?per_page=100`)),
      call(run, glab(place, 'user'), 20_000),
    ])

    if (seen.exitCode !== 0) {
      return { error: whyFailed(place, seen, 'read') }
    }

    try {
      const one = record(JSON.parse(seen.stdout))
      const pipeline = record(one.head_pipeline)
      let approved: unknown[] = []
      let isApproved = false
      let isShort = false

      try {
        const answer = record(JSON.parse(approvals.stdout))

        approved = values(JSON.stringify(answer.approved_by ?? []))
        isApproved = answer.approved === true
        isShort = count(answer.approvals_left) > 0
      } catch {
        approved = []
      }

      // Each of an answer's parts is read alone: one the forge did not give
      // leaves its own list empty and the rest as they are.
      const list = (ran: { exitCode: number; stdout: string }): Json[] => {
        try {
          return ran.exitCode === 0 ? values(ran.stdout).map(record) : []
        } catch {
          return []
        }
      }
      let me = ''

      try {
        me = signedIn.exitCode === 0 ? text(record(JSON.parse(signedIn.stdout)).username) : ''
      } catch {
        me = ''
      }

      const approvers = new Set(approved.map(raw => text(record(record(raw).user).username)))
      // The pipeline's jobs are its checks, each with its own page; and the
      // commit the person last looked at is the head the request had when
      // they last wrote on it: GitLab keeps each head it has had (its
      // versions) and when, and each note's time.
      const [jobs, notes, versions] = await Promise.all([
        count(pipeline.id) > 0
          ? call(run, glab(place, `projects/${encodeURIComponent(place.repo)}/pipelines/${count(pipeline.id)}/jobs?per_page=100`))
          : Promise.resolve({ exitCode: 1, stdout: '', stderr: '' }),
        me === ''
          ? Promise.resolve({ exitCode: 1, stdout: '', stderr: '' })
          : call(run, glab(place, `${gitlabRequest(place)}/notes?sort=desc&order_by=created_at&per_page=100`)),
        me === ''
          ? Promise.resolve({ exitCode: 1, stdout: '', stderr: '' })
          : call(run, glab(place, `${gitlabRequest(place)}/versions`)),
      ])
      const lastSaid = text(
        list(notes).find(note => text(record(note.author).username) === me && note.system !== true)?.created_at,
      )
      const seenAt =
        lastSaid === ''
          ? ''
          : text(
              list(versions)
                .filter(version => text(version.created_at) !== '' && text(version.created_at) <= lastSaid)
                .sort((one, other) => (text(one.created_at) < text(other.created_at) ? 1 : -1))[0]?.head_commit_sha,
            )
      const checks = list(jobs).map(job => ({
        name: [text(job.stage), text(job.name)].filter(part => part !== '').join(': '),
        state: text(job.status),
        url: text(job.web_url),
      }))

      return {
        overview: tidyOverview({
          title: text(one.title),
          body: typeof one.description === 'string' ? one.description : '',
          author: text(record(one.author).username),
          state: text(one.state),
          isDraft: (one.draft ?? one.work_in_progress) === true,
          url: text(one.web_url),
          base: text(one.target_branch),
          head: text(one.source_branch),
          mergeable: text(one.detailed_merge_status) || text(one.merge_status),
          decision: isApproved && !isShort ? 'APPROVED' : isShort ? 'REVIEW_REQUIRED' : approved.length > 0 ? 'APPROVED' : '',
          // Its jobs, where they could be listed; else the pipeline as one.
          checks:
            checks.length > 0
              ? checks
              : text(pipeline.status) === ''
                ? []
                : [{ name: 'pipeline', state: text(pipeline.status), url: text(pipeline.web_url) }],
          // Who has approved, then who was asked to review and has not.
          reviews: [
            ...[...approvers].map(author => ({ author, state: 'APPROVED', when: '' })),
            ...(Array.isArray(one.reviewers) ? one.reviewers : [])
              .map(raw => text(record(raw).username))
              .filter(author => author !== '' && !approvers.has(author))
              .map(author => ({ author, state: 'REVIEW_REQUESTED', when: '' })),
          ],
          // GitLab lists the newest first: oldest first here, as GitHub's are.
          commits: list(listed)
            .map(commit => ({
              hash: text(commit.short_id) || text(commit.id).slice(0, 7),
              subject: text(commit.title),
              author: text(commit.author_name),
            }))
            .reverse(),
          labels: (Array.isArray(one.labels) ? one.labels : []).map(named).filter(label => label !== ''),
          additions: 0,
          deletions: 0,
          files: Number.parseInt(text(one.changes_count), 10) || 0,
          lastReviewed: seenAt,
        }),
      }
    } catch {
      return { error: `glab's answer about ${place.label} could not be read` }
    }
  }

  const [seen, signedIn] = await Promise.all([
    call(run, [
      'gh',
      'pr',
      'view',
      String(place.number),
      '--repo',
      `${place.host}/${place.repo}`,
      '--json',
      'title,body,author,state,isDraft,url,baseRefName,headRefName,mergeable,mergeStateStatus,reviewDecision,statusCheckRollup,latestReviews,commits,labels,additions,deletions,changedFiles',
    ]),
    call(run, gh(place, 'user'), 20_000),
  ])

  if (seen.exitCode !== 0) {
    return { error: whyFailed(place, seen, 'read') }
  }

  try {
    const one = record(JSON.parse(seen.stdout))
    let me = ''

    try {
      me = signedIn.exitCode === 0 ? text(record(JSON.parse(signedIn.stdout)).login) : ''
    } catch {
      me = ''
    }

    const reviews = (Array.isArray(one.latestReviews) ? one.latestReviews : []).map(raw => {
      const review = record(raw)

      return {
        author: text(record(review.author).login),
        state: text(review.state),
        when: text(review.submittedAt),
        commit: text(record(review.commit).oid),
      }
    })

    return {
      overview: tidyOverview({
        title: text(one.title),
        body: typeof one.body === 'string' ? one.body : '',
        author: text(record(one.author).login),
        state: text(one.state),
        isDraft: one.isDraft === true,
        url: text(one.url),
        base: text(one.baseRefName),
        head: text(one.headRefName),
        mergeable: [text(one.mergeable), text(one.mergeStateStatus)].filter(part => part !== '').join(' · '),
        decision: text(one.reviewDecision),
        checks: (Array.isArray(one.statusCheckRollup) ? one.statusCheckRollup : []).map(raw => {
          const check = record(raw)

          return {
            name: text(check.name) || text(check.context),
            // A run still going has no conclusion yet: its status says so.
            state: text(check.conclusion) || text(check.state) || text(check.status),
            url: text(check.detailsUrl) || text(check.targetUrl),
          }
        }),
        reviews: reviews.map(({ author, state, when }) => ({ author, state, when })),
        commits: (Array.isArray(one.commits) ? one.commits : []).map(raw => {
          const commit = record(raw)
          const by = record((Array.isArray(commit.authors) ? commit.authors : [])[0])

          return {
            hash: text(commit.oid).slice(0, 7),
            subject: text(commit.messageHeadline),
            author: text(by.login) || text(by.name),
          }
        }),
        labels: (Array.isArray(one.labels) ? one.labels : []).map(raw => text(record(raw).name)).filter(label => label !== ''),
        additions: count(one.additions),
        deletions: count(one.deletions),
        files: count(one.changedFiles),
        lastReviewed: me === '' ? '' : (reviews.find(review => review.author === me)?.commit ?? ''),
      }),
    }
  } catch {
    return { error: `gh's answer about ${place.label} could not be read` }
  }
}

// A comment's text as it is sent, from a field that holds one line: the two
// characters `\n` typed there start a new line. And the other way, to put a
// comment back in the field to be edited.
export const unfold = (typed: string): string => typed.replace(/\\n/g, '\n')
export const fold = (body: string): string => body.replace(/\r?\n/g, '\\n')

// What was typed as a suggested replacement for the lines a comment is on,
// in the form the forges read as one: a block they offer to apply.
export const suggestionOf = (typed: string): string => `\`\`\`suggestion\n${unfold(typed)}\n\`\`\``

// The replacement a comment suggests for its lines, when it suggests one:
// the lines of its first `suggestion` block.
export const suggestedLines = (body: string): string[] | undefined => {
  const block = /```suggestion[^\n]*\n([\s\S]*?)\n?```/.exec(body.replace(/\r\n/g, '\n'))

  return block === null ? undefined : (block[1] ?? '').split('\n')
}

// Who is signed in to the forge's CLI, by the name comments carry; '' where
// the forge cannot be asked.
export const whoAmI = async (run: Run): Promise<string> => {
  const place = await locate(run, '1')

  if ('error' in place) {
    return ''
  }

  const seen = await call(run, place.forge === 'gitlab' ? glab(place, 'user') : gh(place, 'user'), 20_000)

  try {
    const user = record(JSON.parse(seen.stdout))

    return seen.exitCode === 0 ? text(place.forge === 'gitlab' ? user.username : user.login) : ''
  } catch {
    return ''
  }
}

// Where the forge keeps a comment, to change it, remove it or react to it:
// a comment on a line, one on the request as a whole (GitHub numbers the
// two apart, and prefixes the second kind here), or a GitLab note.
const commentAt = (place: Place, one: Pick<Comment, 'id' | 'thread'>): string | undefined => {
  if (place.forge === 'gitlab') {
    return /^\d+$/.test(one.id)
      ? (one.thread ?? '') !== ''
        ? `${gitlabRequest(place)}/discussions/${one.thread}/notes/${one.id}`
        : `${gitlabRequest(place)}/notes/${one.id}`
      : undefined
  }

  const general = /^issue-(\d+)$/.exec(one.id)?.[1]

  return general !== undefined
    ? `repos/${place.repo}/issues/comments/${general}`
    : /^\d+$/.test(one.id)
      ? `repos/${place.repo}/pulls/comments/${one.id}`
      : undefined
}

// Changes what a comment of the person's own says, removes it, or adds a
// thumbs-up to it. Answers '' when the forge took it, else why not.
export const changeComment = async (
  run: Run,
  typed: string,
  one: Pick<Comment, 'id' | 'thread'>,
  change: { edit: string } | 'delete' | 'like',
): Promise<string> => {
  if (typeof change === 'object' && change.edit.trim() === '') {
    return 'A comment cannot be left empty: delete it instead'
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  const at = commentAt(place, one)

  if (at === undefined) {
    return 'That is not a comment the forge lets be changed from here'
  }

  const api = (...rest: string[]) => (place.forge === 'gitlab' ? glab(place, ...rest) : gh(place, ...rest))
  const done = await call(
    run,
    change === 'delete'
      ? api('-X', 'DELETE', at)
      : change === 'like'
        ? place.forge === 'gitlab'
          ? api('-X', 'POST', `${at}/award_emoji`, '-f', 'name=thumbsup')
          : api('-X', 'POST', `${at}/reactions`, '-f', 'content=+1')
        : api('-X', place.forge === 'gitlab' ? 'PUT' : 'PATCH', at, '-f', `body=${change.edit}`),
  )

  return done.exitCode === 0 ? '' : whyFailed(place, done, 'comment on')
}

// What can be done to a request as a whole, from the pane.
export type RequestAct = 'merge' | 'squash' | 'rebase' | 'close' | 'ready' | 'checkout'

// Does it, through the forge's CLI: merges the request (as a merge commit,
// squashed, or rebased), closes it, marks a draft ready for review, or
// checks its branch out here. Answers '' when it was done, else why not.
export const actOnRequest = async (run: Run, typed: string, act: RequestAct): Promise<string> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  const number = String(place.number)
  const where = place.forge === 'gitlab' ? ['-R', `${place.host}/${place.repo}`] : ['--repo', `${place.host}/${place.repo}`]
  const argv =
    place.forge === 'gitlab'
      ? act === 'close'
        ? ['glab', 'mr', 'close', number, ...where]
        : act === 'ready'
          ? ['glab', 'mr', 'update', number, '--ready', ...where]
          : act === 'checkout'
            ? ['glab', 'mr', 'checkout', number, ...where]
            : ['glab', 'mr', 'merge', number, '--yes', ...(act === 'squash' ? ['--squash'] : act === 'rebase' ? ['--rebase'] : []), ...where]
      : act === 'close'
        ? ['gh', 'pr', 'close', number, ...where]
        : act === 'ready'
          ? ['gh', 'pr', 'ready', number, ...where]
          : act === 'checkout'
            ? ['gh', 'pr', 'checkout', number, ...where]
            : ['gh', 'pr', 'merge', number, `--${act}`, ...where]
  const done = await call(run, argv, 120_000)

  if (done.exitCode === 0) {
    return ''
  }

  // The CLI's own last words say why best (a failing check, a conflict, a
  // dirty working tree); the general reasons cover its not running at all.
  const said = lastLine(done.stderr) || lastLine(done.stdout)

  return said !== '' && done.exitCode !== -1 && done.exitCode !== 127
    ? `${place.label} was not ${act === 'checkout' ? 'checked out' : act === 'ready' ? 'marked ready' : act === 'close' ? 'closed' : 'merged'}: ${said.slice(0, 200)}`
    : whyFailed(place, done, 'read')
}

export const fetchComments = async (run: Run, typed: string): Promise<{ comments: Comment[] } | { error: string }> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  return place.forge === 'github' ? githubComments(run, place) : gitlabComments(run, place)
}

// Posts one review comment on a line of the request's head version of a file. `at.commit` is the
// full hash of the head commit the comment is anchored to; `at.path` is relative to the repo root.
export const postComment = async (
  run: Run,
  typed: string,
  // `startLine`, where it is before `line`, makes it a comment on those lines
  // together. GitHub takes the range; on GitLab the comment goes on the last
  // line and says which lines it is about.
  // `oldLine` puts the comment on a removed line, by its number in the
  // target's version of the file: the left side of the forge's own diff.
  at: { path: string; line: number; commit: string; startLine?: number; oldLine?: number },
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  if (body.trim() === '') {
    return { error: 'Write something before posting the comment' }
  }

  const oldLine = at.oldLine !== undefined && Number.isInteger(at.oldLine) && at.oldLine > 0 ? at.oldLine : 0

  const startLine = at.startLine !== undefined && at.startLine > 0 && at.startLine < at.line ? at.startLine : 0

  // Line 0 is the file as a whole, which both forges take a comment on.
  if (at.path === '' || !Number.isInteger(at.line) || at.line < 0 || at.commit === '') {
    return { error: 'Pick a line of a file in the request to comment on' }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  if (place.forge === 'gitlab') {
    // A removed line, a whole file, one line or several: each is placed
    // GitLab's own way there.
    return gitlabPost(
      run,
      place,
      { ...at, ...(oldLine > 0 ? { oldLine } : {}), ...(startLine > 0 ? { startLine } : {}) },
      body,
    )
  }

  // -f keeps the body as typed (-F would read "@file" and turn "true" into a boolean); the line must be a number.
  const posted = await call(
    run,
    gh(
      place,
      '-X',
      'POST',
      `repos/${place.repo}/pulls/${place.number}/comments`,
      '-f',
      `body=${body}`,
      '-f',
      `commit_id=${at.commit}`,
      '-f',
      `path=${at.path}`,
      ...(oldLine > 0
        ? ['-F', `line=${oldLine}`, '-f', 'side=LEFT']
        : at.line === 0
          ? ['-f', 'subject_type=file']
          : ['-F', `line=${at.line}`, '-f', 'side=RIGHT']),
      ...(startLine === 0 || oldLine > 0 ? [] : ['-F', `start_line=${startLine}`, '-f', 'start_side=RIGHT']),
    ),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on', at) }
  }

  try {
    return { comment: fromGithubLine(JSON.parse(posted.stdout), new Map()) }
  } catch {
    return { error: `The comment may have been posted on ${place.label}, but gh's answer could not be read: reload to check` }
  }
}

// Answers a review thread. `root` is the thread's first comment: GitHub replies to that comment
// by its id, GitLab adds a note to the discussion (`root.thread`).
export const replyComment = async (
  run: Run,
  typed: string,
  root: Pick<Comment, 'id' | 'thread'>,
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  if (body.trim() === '') {
    return { error: 'Write something before posting the reply' }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  if (place.forge === 'gitlab' && (root.thread ?? '') === '') {
    return { error: 'GitLab did not say which discussion that comment is in: refresh (r) and try again' }
  }

  const posted = await call(
    run,
    place.forge === 'gitlab'
      ? glab(
          place,
          '-X',
          'POST',
          `${gitlabRequest(place)}/discussions/${root.thread ?? ''}/notes`,
          '-f',
          `body=${body}`,
        )
      : gh(
          place,
          '-X',
          'POST',
          `repos/${place.repo}/pulls/${place.number}/comments/${root.id}/replies`,
          '-f',
          `body=${body}`,
        ),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on') }
  }

  try {
    const made =
      place.forge === 'gitlab'
        ? fromGitlabNote(JSON.parse(posted.stdout), root.id, '', root.thread ?? '')
        : fromGithubLine(JSON.parse(posted.stdout), new Map())

    return { comment: { ...made, replyTo: root.id } }
  } catch {
    return { error: `The reply may have been posted on ${place.label}, but the answer could not be read: refresh to check` }
  }
}

// Marks a review thread resolved, or open again. Answers '' when the forge took it, else why not.
export const resolveThread = async (
  run: Run,
  typed: string,
  thread: string,
  isResolved: boolean,
): Promise<string> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  if (thread === '') {
    return `${place.label} did not say which thread that comment is in: refresh (r) and try again`
  }

  const verb = isResolved ? 'resolveReviewThread' : 'unresolveReviewThread'
  const ran = await call(
    run,
    place.forge === 'gitlab'
      ? glab(
          place,
          '-X',
          'PUT',
          `${gitlabRequest(place)}/discussions/${thread}?resolved=${isResolved ? 'true' : 'false'}`,
        )
      : gh(
          place,
          'graphql',
          '-f',
          `query=mutation($id:ID!){${verb}(input:{threadId:$id}){thread{isResolved}}}`,
          '-f',
          `id=${thread}`,
        ),
  )

  return ran.exitCode === 0 ? '' : whyFailed(place, ran, 'comment on')
}

// The files of a request the person has marked as viewed on the forge
// itself, and the request's own id there, by which one is marked. GitHub
// keeps these; GitLab has no such mark to read, and answers undefined, as
// does a forge that cannot be asked. Paths are from the repo's root.
const VIEWED_QUERY =
  'query($owner:String!,$name:String!,$number:Int!,$endCursor:String){repository(owner:$owner,name:$name){pullRequest(number:$number){id files(first:100,after:$endCursor){pageInfo{hasNextPage endCursor} nodes{path viewerViewedState}}}}}'

export const readViewed = async (run: Run, typed: string): Promise<{ id: string; viewed: string[] } | undefined> => {
  const place = await locate(run, typed)

  if ('error' in place || place.forge !== 'github') {
    return undefined
  }

  const [owner = '', name = ''] = place.repo.split('/')
  const seen = await call(
    run,
    gh(place, 'graphql', '--paginate', '-f', `query=${VIEWED_QUERY}`, '-f', `owner=${owner}`, '-f', `name=${name}`, '-F', `number=${place.number}`),
  )

  if (seen.exitCode !== 0) {
    return undefined
  }

  try {
    let id = ''
    const viewed: string[] = []

    // A paginated call prints one answer for each page, back to back.
    for (const page of values(seen.stdout)) {
      const request = record(record(record(record(page).data).repository).pullRequest)

      id ||= text(request.id)

      for (const raw of Array.isArray(record(request.files).nodes) ? (record(request.files).nodes as unknown[]) : []) {
        const file = record(raw)

        if (file.viewerViewedState === 'VIEWED' && text(file.path) !== '') {
          viewed.push(text(file.path))
        }
      }
    }

    return id === '' ? undefined : { id, viewed: viewed.slice(0, 5000) }
  } catch {
    return undefined
  }
}

// Marks a file of a request as viewed on the forge, or takes the mark off.
// `id` is the request's own, as `readViewed` gave it; `path` is from the
// repo's root. Answers '' when the forge took it, else why not.
export const markViewed = async (
  run: Run,
  typed: string,
  id: string,
  path: string,
  isViewed: boolean,
): Promise<string> => {
  const place = await locate(run, typed)

  if ('error' in place) {
    return place.error
  }

  if (place.forge !== 'github' || id === '') {
    return ''
  }

  const verb = isViewed ? 'markFileAsViewed' : 'unmarkFileAsViewed'
  const ran = await call(
    run,
    gh(
      place,
      'graphql',
      '-f',
      `query=mutation($id:ID!,$path:String!){${verb}(input:{pullRequestId:$id,path:$path}){clientMutationId}}`,
      '-f',
      `id=${id}`,
      '-f',
      `path=${path}`,
    ),
  )

  return ran.exitCode === 0 ? '' : whyFailed(place, ran, 'read')
}

// A comment as a quotation, the way a forge's own "quote reply" starts an
// answer: each of its lines after a ">", then a clear line for what follows.
export const quoteOf = (one: Pick<Comment, 'body'>): string =>
  `${one.body
    .trim()
    .split('\n')
    .map(line => (line.trim() === '' ? '>' : `> ${line}`))
    .join('\n')}\n\n`

// Adds a comment to the request's conversation: one on the request as a
// whole, on no line. Neither forge threads these on a pull request's own
// page (GitHub not at all), so an answer to one is a new comment that quotes
// it (see `quoteOf`).
export const postGeneral = async (
  run: Run,
  typed: string,
  body: string,
): Promise<{ comment: Comment } | { error: string }> => {
  if (body.trim() === '') {
    return { error: 'Write something before posting the comment' }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return place
  }

  const posted = await call(
    run,
    place.forge === 'gitlab'
      ? glab(place, '-X', 'POST', `${gitlabRequest(place)}/notes`, '-f', `body=${body}`)
      : gh(place, '-X', 'POST', `repos/${place.repo}/issues/${place.number}/comments`, '-f', `body=${body}`),
  )

  if (posted.exitCode !== 0) {
    return { error: whyFailed(place, posted, 'comment on') }
  }

  try {
    const one = record(JSON.parse(posted.stdout))

    return {
      comment:
        place.forge === 'gitlab'
          ? {
              id: named(one.id),
              path: '',
              line: 0,
              author: text(record(one.author).username) || 'ghost',
              body: typeof one.body === 'string' ? one.body : body,
              when: text(one.created_at),
            }
          : fromGithubGeneral(one, 'issue'),
    }
  } catch {
    return { error: `The comment may have been posted on ${place.label}, but its answer could not be read: reload to check` }
  }
}

// Submits a review of the request: an approval, a request for changes, or a
// comment, with a summary. Answers '' when the forge took it, else why not.
export const submitReview = async (
  run: Run,
  typed: string,
  verdict: 'approve' | 'request-changes' | 'comment',
  summary: string,
): Promise<string> => (await submitDrafted(run, typed, verdict, summary, { drafts: [], commit: '', prefix: '' })).refusal

// Submits a review with the comments written for it (`drafts`), which go to
// the forge with the verdict. `commit` is the request's head, which the
// comments are placed on, and `prefix` the folder under review's place in
// the repo. Answers why it was not taken ('' when it was) and which drafts
// did reach the forge (`sent`, by id), so those are not sent twice.
//
// GitHub takes the comments on lines and the verdict as one review. A
// comment on a file as a whole is no part of that call there, and GitLab
// has no such call at all: those are posted one at a time, before the
// verdict.
export const submitDrafted = async (
  run: Run,
  typed: string,
  verdict: 'approve' | 'request-changes' | 'comment',
  summary: string,
  pending: { drafts: readonly Draft[]; commit: string; prefix: string },
): Promise<{ refusal: string; sent: string[] }> => {
  const body = summary.trim()
  const sent: string[] = []
  const { drafts, commit, prefix } = pending

  if (verdict !== 'approve' && body === '' && drafts.length === 0) {
    return { refusal: 'Write a summary first: it is what the review says', sent }
  }

  const place = await locate(run, typed)

  if ('error' in place) {
    return { refusal: place.error, sent }
  }

  // The comments posted one at a time: all of them on GitLab, those on a
  // whole file on GitHub.
  // A comment on a removed line is on a line too (of the other side), and
  // goes with the review.
  const isOnLine = (one: Draft): boolean => one.line > 0 || (one.oldLine ?? 0) > 0

  for (const draft of drafts.filter(one => place.forge === 'gitlab' || !isOnLine(one))) {
    const posted = await postComment(
      run,
      typed,
      {
        path: `${prefix}${draft.path}`,
        line: draft.line,
        commit,
        ...(draft.startLine === undefined ? {} : { startLine: draft.startLine }),
        ...(draft.oldLine === undefined ? {} : { oldLine: draft.oldLine }),
      },
      draft.body,
    )

    if ('error' in posted) {
      return { refusal: posted.error, sent }
    }

    sent.push(draft.id)
  }

  const refusal = await submitVerdict(
    run,
    place,
    verdict,
    body,
    place.forge === 'gitlab' ? [] : drafts.filter(isOnLine),
    commit,
    prefix,
  )

  return refusal === ''
    ? { refusal, sent: drafts.map(one => one.id) }
    : { refusal, sent }
}

const submitVerdict = async (
  run: Run,
  place: Place,
  verdict: 'approve' | 'request-changes' | 'comment',
  body: string,
  onLines: readonly Draft[],
  commit: string,
  prefix: string,
): Promise<string> => {
  if (place.forge === 'gitlab') {
    // GitLab takes "changes requested" as a quick action in a comment: the
    // line `/request_changes` on its own, which it acts on and does not
    // show. An older GitLab that does not know it shows it as text, under
    // the summary that says the same.
    if (verdict === 'request-changes') {
      const asked = await call(
        run,
        glab(
          place,
          '-X',
          'POST',
          `${gitlabRequest(place)}/notes`,
          '-f',
          `body=${body === '' ? 'Changes requested.' : body}\n\n/request_changes`,
        ),
      )

      return asked.exitCode === 0 ? '' : whyFailed(place, asked, 'comment on')
    }

    if (verdict === 'approve') {
      const approved = await call(run, glab(place, '-X', 'POST', `${gitlabRequest(place)}/approve`))

      if (approved.exitCode !== 0) {
        return whyFailed(place, approved, 'comment on')
      }
    }

    if (body === '') {
      return ''
    }

    const noted = await call(
      run,
      glab(place, '-X', 'POST', `${gitlabRequest(place)}/notes`, '-f', `body=${body}`),
    )

    return noted.exitCode === 0 ? '' : whyFailed(place, noted, 'comment on')
  }

  const event = verdict === 'approve' ? 'APPROVE' : verdict === 'comment' ? 'COMMENT' : 'REQUEST_CHANGES'

  // With comments, the review is one JSON body: a list does not fit the
  // CLI's fields.
  if (onLines.length > 0) {
    const whole = await run(
      gh(place, '-X', 'POST', `repos/${place.repo}/pulls/${place.number}/reviews`, '--input', '-'),
      COMMENTS_MS,
      JSON.stringify({
        event,
        ...(body === '' ? {} : { body }),
        ...(commit === '' ? {} : { commit_id: commit }),
        comments: onLines.map(one =>
          (one.oldLine ?? 0) > 0
            ? // A removed line is on the left of the forge's diff, by its
              // number in the target's version of the file.
              { path: `${prefix}${one.path}`, line: one.oldLine, side: 'LEFT', body: one.body }
            : {
                path: `${prefix}${one.path}`,
                line: one.line,
                side: 'RIGHT',
                body: one.body,
                ...(one.startLine !== undefined && one.startLine > 0 && one.startLine < one.line
                  ? { start_line: one.startLine, start_side: 'RIGHT' }
                  : {}),
              },
        ),
      }),
    ).catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))

    return whole.exitCode === 0 ? '' : whyFailed(place, whole, 'comment on')
  }

  // GitHub refuses a comment-only review that says nothing: with its
  // comments all posted already, there is nothing left to send.
  if (verdict === 'comment' && body === '') {
    return ''
  }

  const sent = await call(
    run,
    gh(
      place,
      '-X',
      'POST',
      `repos/${place.repo}/pulls/${place.number}/reviews`,
      '-f',
      `event=${event}`,
      ...(body === '' ? [] : ['-f', `body=${body}`]),
    ),
  )

  return sent.exitCode === 0 ? '' : whyFailed(place, sent, 'comment on')
}

// The sub-folder of the repo that `run` executes in, as a prefix ('' at the root, 'frontend/' in a
// sub-folder): the pane may be reviewing a sub-folder, and forge paths are relative to the root.
export const repoPrefix = async (run: Run): Promise<string> => {
  const ran = await call(run, ['git', 'rev-parse', '--show-prefix'], LOCAL_MS)

  return ran.exitCode === 0 ? ran.stdout.trim() : ''
}

files.hooks/run.ts:
// How a module that holds no engine handle runs a command. The hooks module,
// which holds the handle, passes each such module a `Run`; everything below
// it knows processes only through this.

export type Ran = { exitCode: number; stdout: string; stderr: string }

// Runs a command and never rejects: one that could not be started answers
// exit code -1 with the reason as its stderr, so a caller has one thing to
// check and nothing to catch.
export type Run = (
  argv: string[],
  init?: { cwd?: string; stdin?: string; timeoutMs?: number },
) => Promise<Ran>

// More files than this are not handed to one command.
export const FILE_LIMIT = 300

// The last words of what a command printed, short enough for a note or a toast.
export const tail = (text: string): string => text.trim().split('\n').slice(-2).join(' ').slice(0, 200)

files.hooks/scan.ts:
// The scan: one pass over the comparison under review. It asks git what
// differs, shows that at once, has the files checked, and publishes what is
// found as it comes in. It holds no engine handle: the hooks module passes
// it the ports it works through.

import type { Diag, GraphRow, Scan } from '../types'
import type { Progress } from './check'
import { checkChange, isCheckable, refreshServed, toolsAwaited, uncheckedNotes } from './check'
import { isFadeOnly } from './diags'
import * as git from './git'
import type { Run as ServerRun } from './lsp'
import { issueList } from './prompt'
import type { Run } from './run'
import type { Checkers } from './settings'

// How many files are checked at a time. A batch is one run of each checker
// and cannot be added to once started, so the file a person opens waits for
// the batch under way: a smaller batch is a shorter wait, at the price of
// starting the checkers more often.
export const BATCH = 100

// The most files checked of a folder git does not know, where every file is
// listed and none is singled out by a change.
export const PLAIN_CHECKED = 1000

// How many issues an automatic note tells Claude.
const ISSUES_TOLD = 15

// What a scan is asked to do beyond the changed files: `isProject` checks
// every file of every project with the command-line checkers.
export type Job = { isProject: boolean }

// What is under review, as the pane's state has it when the scan starts.
export type Subject = {
  repo: string
  base: string
  // The commit compared against the base in place of the working tree, or ''.
  target: string
  // Unchanged files to check along with the changed.
  extra: readonly string[]
  // Whether the list of every tracked file is wanted too.
  isBrowsing: boolean
  // Whether Claude is told what its own edits broke.
  isTelling: boolean
  // What was typed to open the request under review, or ''.
  requestTyped: string
  // The checkers left switched on, and whether new is told from pre-existing.
  use: Checkers
  marksNew: boolean
}

export type Ports = {
  run: Run
  servers: ServerRun
  // A file's text by its absolute path; '' for one that cannot be read.
  readFile: (path: string) => Promise<string>
  // The scan's own state: as it stands, and a change to it.
  readScan: () => Promise<Scan>
  writeScan: (change: (last: Scan) => Scan) => Promise<unknown>
  // Called once git has answered and the changed files are published, before
  // the checkers start: the moment to read an open file again.
  onListed: () => Promise<void>
  // Reads the request's comments again; answers '' or why it could not.
  readComments: (typed: string) => Promise<string>
  // The one-line summary for the status line; '' clears it.
  showStatus: (text: string) => void
  // A note to Claude, in the conversation.
  tellClaude: (text: string) => Promise<unknown>
  // The file the person has open as the scan's side has it, or '': asked
  // before each batch, since that file is checked next.
  openFile: () => Promise<string>
  // Whether another scan has been asked for since this one started: a long
  // scan then stops between batches and leaves the rest to that one.
  isOvertaken: () => boolean
}

// The whole history as the graph lays it out. Thousands of rows are too much
// to keep as state, so a reload drops them and the scan it starts reads them
// again. Written by `scanRepo` alone; read through `historyOf`.
let history: { repo: string; rows: GraphRow[] } | undefined

// Every file git tracks in the folder under review, read while the tree of
// all files is showing; too many paths to keep as state. Written by
// `scanRepo` alone; read through `allFilesOf`.
let allFiles: { repo: string; paths: string[] } | undefined

// The files Claude has edited since it was last told about its new problems,
// relative to the folder under review (added through `noteTouched`), and the
// problems it has been told.
// The files of the scan under way that no batch has reached yet. Written by
// `scanRepo` alone; read through `isQueued`. The scan's `checked` count
// changing is what redraws the readers.
let queued: { repo: string; paths: Set<string> } | undefined

const touched = new Set<string>()
const told = new Set<string>()

// The history of the repo last scanned, when that is `repo`; else none yet.
export const historyOf = (repo: string): GraphRow[] =>
  history !== undefined && history.repo === repo ? history.rows : []

// Every tracked file of the repo last scanned with `isBrowsing`, when that
// is `repo`; else none yet.
export const allFilesOf = (repo: string): string[] =>
  allFiles !== undefined && allFiles.repo === repo ? allFiles.paths : []

// Whether a file of the scan under way is still waiting for its batch.
export const isQueued = (repo: string, path: string): boolean =>
  queued !== undefined && queued.repo === repo && queued.paths.has(path)

// Why git could not compare with the base, with what to do about it.
const explainDiff = (base: string, refusal: string): string =>
  /unknown revision|bad revision|ambiguous argument|not a valid object/i.test(refusal)
    ? `"${base}" is not a branch or commit in this repo, so nothing is compared. Pick one from the graph, or run /lens again with another`
    : `git could not compare with ${base}: ${refusal}`

// Notes a file Claude edited, for the next scan to tell it what that broke.
export const noteTouched = (path: string): void => {
  touched.add(path)
}

export const scanRepo = async (
  ports: Ports,
  { repo, base, target, extra, isBrowsing, isTelling, requestTyped, use, marksNew }: Subject,
  { isProject }: Job,
): Promise<void> => {
  if (repo === '') {
    return
  }

  await ports.writeScan((last): Scan => ({ ...last, status: 'running' }))

  const notes: string[] = []
  // Which languages have a server is asked while git answers: a server
  // installed, or added to the person's config file, since the last scan
  // counts from this one on.
  const [changes, misconfigured] = await Promise.all([
    git.readChanges(ports.run, repo, base, target),
    refreshServed(ports.servers, use.servers),
  ])

  if (changes.refusal !== undefined) {
    notes.push(explainDiff(base, changes.refusal))
  }

  notes.push(...misconfigured)

  const live = changes.files.filter(one => one.status !== 'D').map(one => one.path)
  // The files to check: what differs, and the unchanged files the person
  // opened from the tree of every file.
  const wanted = [...live, ...(target === '' ? extra : []).filter(path => !live.includes(path))]

  notes.push(...uncheckedNotes(wanted))

  // A folder git does not know has no change to list: every file of it is
  // listed instead, and those a checker reads are checked.
  if (changes.isPlain) {
    allFiles = { repo, paths: await git.folderFiles(ports.run, repo) }

    const code = allFiles.paths.filter(isCheckable)

    wanted.push(...code.slice(0, PLAIN_CHECKED))
    notes.push(...uncheckedNotes(allFiles.paths))

    if (allFiles.paths.length >= git.PLAIN_FILES) {
      notes.push(`only the first ${git.PLAIN_FILES} files of this folder are listed`)
    }

    if (code.length > PLAIN_CHECKED) {
      notes.push(`only the first ${PLAIN_CHECKED} of ${code.length} code files are checked`)
    }
  } else if (isBrowsing) {
    allFiles = { repo, paths: await git.trackedFiles(ports.run, repo) }
  }

  // The files are checked a batch at a time, so the first results show
  // while the rest wait their turn.
  let left = wanted.filter(isCheckable)
  const toCheck = left.length
  const finished = new Set<string>()
  const waiting = new Set(left)

  queued = { repo, paths: waiting }

  history = { repo, rows: changes.history }

  // What git alone answers (the files that differ, their line counts, the
  // history) is shown at once; the checkers, which take the time, fill the
  // diagnostics in when they are done.
  const listed = {
    files: changes.files,
    changed: changes.changed,
    stats: changes.stats,
    // The rows themselves are the module's (`history`); the count changing
    // is what redraws the graph.
    graph: [] as GraphRow[],
    graphCount: changes.history.length,
    branches: changes.branches,
    head: changes.head,
    headHash: changes.headHash,
    dirty: changes.dirty,
    stashes: changes.stashes,
    worktrees: changes.worktrees,
    isPlain: changes.isPlain,
  }

  await ports.writeScan(
    (last): Scan => ({
      ...last,
      ...listed,
      pending: [],
      status: 'running',
      notes: [...notes],
      checked: 0,
      toCheck,
    }),
  )
  await ports.onListed()

  const targetHash =
    target === '' || changes.isPlain ? '' : await git.shortHash(ports.run, repo, target)
  const baseShort = changes.isPlain ? '' : await git.shortHash(ports.run, repo, base)

  // The scan as it goes: which tools are still running, and what they have
  // found so far. A tool that has not reported yet keeps what it found last
  // time, so a count does not drop to nothing and climb back. The writes are
  // chained, so they land in order and none is left to land after the last.
  const previous = (await ports.readScan()).diags
  const running: string[] = []
  let written: Promise<unknown> = Promise.resolve()
  const publish = (found?: Diag[]): Promise<unknown> => {
    const awaited = toolsAwaited(running)

    written = written.then(() =>
      ports.writeScan(
        (last): Scan => ({
          ...last,
          pending: [...running],
          checked: finished.size,
          diags:
            found === undefined
              ? last.diags
              : [
                  ...found,
                  ...previous.filter(
                    old =>
                      // What was known of a file no batch has reached yet
                      // stands until its turn; of the others, what a tool
                      // still out said last time.
                      (waiting.has(old.path) ||
                        (awaited.has(old.tool) && !finished.has(old.path))) &&
                      !found.some(
                        one =>
                          one.path === old.path &&
                          one.line === old.line &&
                          one.tool === old.tool &&
                          one.message === old.message,
                      ),
                  ),
                ]
                  .filter(diag => !isFadeOnly(diag))
                  .slice(0, 5000),
        }),
      ),
    )

    return written
  }
  // What the batches before the one under way found.
  const diags: Diag[] = []
  const progress: Progress = {
    start: tool => {
      running.push(tool)
      void publish()
    },
    done: (tool, found) => {
      const at = running.indexOf(tool)

      if (at !== -1) {
        running.splice(at, 1)
      }

      void publish([...diags, ...found])
    },
  }

  for (let round = 0; round === 0 || left.length > 0; round += 1) {
    // The file the person is reading is checked next, whatever its place.
    const open = await ports.openFile()

    if (left.includes(open)) {
      left = [open, ...left.filter(path => path !== open)]
    }

    const batch = left.slice(0, BATCH)

    left = left.slice(BATCH)

    for (const path of batch) {
      waiting.delete(path)
    }

    const answer = await checkChange(
      {
        run: ports.run,
        servers: ports.servers,
        readFile: ports.readFile,
      },
      {
        repo,
        base: { ref: base, short: baseShort },
        target: { ref: target, short: targetHash },
        files: changes.files,
        // What no checker reads rides with the first batch: a whole-project
        // check is asked once, and finds what it finds wherever it is.
        wanted: round === 0 ? [...batch, ...wanted.filter(path => !isCheckable(path))] : batch,
        isProject: isProject && round === 0,
        use,
        marksNew,
      },
      progress,
    )

    diags.push(...answer.diags)
    notes.push(...answer.notes.filter(note => !notes.includes(note)))

    for (const path of batch) {
      finished.add(path)
    }

    await publish([...diags])

    // A scan asked for meanwhile takes over from here: it starts with what
    // this one found, and the open file first.
    if (left.length > 0 && ports.isOvertaken()) {
      return
    }
  }

  // Every write the scan made along the way has landed before its last one.
  await written
  queued = undefined

  // A request under review has its comments read with every scan, so a
  // refresh picks up what was said since.
  if (requestTyped !== '') {
    const refusal = await ports.readComments(requestTyped)

    if (refusal !== '') {
      notes.push(`comments were not read: ${refusal}`)
    }
  }

  await ports.writeScan(
    (): Scan => ({
      ...listed,
      pending: [],
      status: 'done',
      // A hint that code is never used fades that code and is no problem to
      // count or list, as in an editor.
      diags: diags.filter(diag => !isFadeOnly(diag)).slice(0, 5000),
      faded: diags.filter(isFadeOnly).slice(0, 2000),
      notes,
      isProjectChecked: isProject,
      checked: toCheck,
      toCheck,
    }),
  )

  // The count rides in the status line too, so a glance tells whether the
  // working tree is clean without the pane open. Each mod has its own entry
  // there, so this sits beside any other mod's.
  const changedPaths = new Set(changes.files.map(one => one.path))
  // Where nothing is compared, every problem found counts.
  const mine = changes.isPlain ? diags : diags.filter(diag => changedPaths.has(diag.path))
  const errorCount = mine.filter(diag => diag.severity === 'error').length

  ports.showStatus(
    // The engine writes the mod's name before its entry, so the entry is the count alone.
    // A clean change has nothing to say: '' takes the entry off the status line.
    mine.length === 0 ? '' : `✖ ${errorCount} ⚠ ${mine.length - errorCount}`,
  )

  // Where the person asked for it, Claude is told what its own edits broke:
  // the problems this scan found in the files it changed that the base did
  // not have, each of them once.
  if (isTelling && target === '' && touched.size > 0) {
    const fresh = diags.filter(
      diag =>
        touched.has(diag.path) &&
        diag.isNew !== false &&
        diag.severity !== 'info' &&
        !told.has(`${diag.path}\n${diag.tool}\n${diag.rule}\n${diag.message}`),
    )

    touched.clear()

    if (fresh.length > 0) {
      for (const diag of fresh) {
        told.add(`${diag.path}\n${diag.tool}\n${diag.rule}\n${diag.message}`)
      }

      await ports.tellClaude(
        `lens (automatic note, switched on by the user): after your edits, the checkers report ${fresh.length} new ${fresh.length === 1 ? 'problem' : 'problems'} in files you changed.\n${issueList(fresh, ISSUES_TOLD)}`,
      )
    }
  }
}

files.hooks/screens/file.tsx:
// The file screen: a whole file in a window of the screen's own, with each
// line's diagnostics and review comments beside it, the lines the other side
// had (the diff view), who last changed each line (blame), a breadcrumb that
// opens lists to jump from, a search, and the card of a looked-up name.
//
// Only the lines the window has rows for are drawn, so the tree stays small
// however long the file is; what the scroll hook needs to move the window is
// returned with it.

import type { RenderChildren } from 'claude-code'

import type { Crumb, Diag, LineRange, Lookup, Span } from '../../types'
import { countLabel, diagsByLine } from '../diags'
import { changeLines, stepShown } from '../changes'
import type { Blamed } from '../git'
import { kindColor } from '../lists'
import type { InlayHint, OutlineItem, SemanticToken } from '../lsp-types'
import type { MiniLine } from '../minimap'
import { minimapCells } from '../minimap'
import { markSpans, withInlays } from '../parts'
import { isFinding as isLedgerFinding } from '../ledger'
import type { Comment } from '../review'
import { draftId, isDraft } from '../review'
import { applySemantic, enclosing, outlineRows } from '../semantic'
import { clamp, findMatches, shortRef, wrapText } from '../text'
import { iconOf } from '../tree'
import { changedWords } from '../words'
import type { Kit, Shell } from './frame'
import {
  CARD_BACKGROUND,
  COLOR,
  COMMENT_COLOR,
  RESOLVED_COLOR,
  PENDING_COLOR,
  COMMIT_BOX,
  talkColor as colorOfTalk,
  talkIcon,
  MARK,
  helpButton,
  notesOf,
  said,
  statusLine,
} from './frame'
import { isMarkdownFile } from './markdown'

// The most lines of an unsent comment its card shows.
const DRAFT_LINES = 6
// The most rows of what is being typed that are drawn under the field: its
// last ones, where the typing is.
const WRITE_ROWS = 8
// What `commentLine` holds while the comment being typed is on the file as a
// whole, not on a line of it.
export const FILE_COMMENT = -1
// The blame column: a short hash, eight letters of the author, how long ago.
const BLAME_WIDTH = 21
// How many lines of a looked-up name's type and docs the file screen shows.
const SYMBOL_LINES = 8
// The narrowest the breadcrumb's popover is; it widens to its longest entry.
const CRUMB_WIDTH = 46
const ADDED_BACKGROUND = '#1f3a24'
// The words that differ within a rewritten line, lit over the line's own.
const ADDED_WORD = '#2f7d43'
const REMOVED_WORD = '#9b2f2f'
const FOUND_BACKGROUND = '#7a4a00'
const REMOVED_BACKGROUND = '#4b1d1d'
// The most removed lines drawn above one line; the window cannot scroll
// inside a run of them, so a longer run is cut with a count.
const REMOVED_LINES = 20
const MINIMAP_COLUMNS = 6
// The minimap is a small corner block, not a full-height column.
const MINIMAP_ROWS = 12
// A pane narrower than this has no room to spare for the minimap.
const MINIMAP_FROM_COLUMNS = 60

// What the language server knows of the file: the file's own lines (a server
// counts a tab as one column, the screen draws four), its outline, what each
// name is, and its inlay hints, by line.
export type Insight = {
  raw: string[]
  items: OutlineItem[]
  tokens: Map<number, SemanticToken[]>
  hints: Map<number, InlayHint[]>
}

// How many lines of a comment show while the file is not expanded.
const TALK_FOLDED = 3

export type FileModel = {
  shell: Shell
  file: string
  // The commit the file is shown at; '' for the working tree's.
  commit: string
  // Whether the file as shown is what the checkers ran on: the working
  // tree's, or the comparison's own target. Only then has it diagnostics.
  isChecked: boolean
  // The file's coloured lines, and the same as plain text; undefined while
  // they are being read. `note` says why highlighting did not run, if so.
  lines: readonly Span[][] | undefined
  texts: readonly string[]
  note: string
  // The lines the other side had, by the line they came before; the lines
  // this side changed; and whether the other side has no such file at all.
  removed: Readonly<Record<number, string[]>>
  // Where the first of each run of removed lines was in the other side, by
  // the same line: what a comment on a removed line is placed by.
  removedAt: Readonly<Record<number, number>>
  changed: readonly LineRange[]
  isNewFile: boolean
  // The file's diagnostics, sorted, and the code said to be never used.
  diags: readonly Diag[]
  faded: readonly Diag[]
  // Who last changed each line, while the blame column shows.
  blame: readonly Blamed[] | undefined
  insight: Insight | undefined
  // The first line of the window (1-based), the diagnostic stepped to (its
  // place among `diags`, -1 for none), and the switches of the view.
  top: number
  cursor: number
  isExpanded: boolean
  isDiff: boolean
  // Whether the diff is cut down to what differs: each change and each
  // commented line, with a few lines around it.
  isChanges: boolean
  isMore: boolean
  isHinting: boolean
  // The search: whether its field shows, what is typed, the match the
  // person is on.
  isFinding: boolean
  find: string
  findAt: number
  // A request's review: whether this file can be commented on, whether a
  // line number now picks the line to comment on, the line picked (0 for
  // none yet), and what was said on this file's lines.
  canComment: boolean
  isCommenting: boolean
  commentLine: number
  // The first line of the comment being typed when it is on several (then
  // `commentLine` is the last); 0 when it is on one.
  commentFrom: number
  // The removed line the comment being typed is on, by its number in the
  // other side; 0 when it is on a line of this side.
  commentOld: number
  // Who the person is on the forge ('' when not known), so their own
  // comments can be changed; the comment being changed and the one asked
  // about before deleting, by id; what the field starts with while one is
  // being changed.
  me: string
  editing: string
  deleting: string
  draft: string
  // What the comment field holds now, as typed (a new line as "\n"): drawn
  // in full under the field, which is one line.
  typed: string
  // The thread being answered, by its first comment's id; '' for none.
  replyTo: string
  // What the diff is against, by name, when that is not the comparison's
  // base: the branch a request targets. '' otherwise.
  diffAgainst: string
  // Whether resolved threads are being left out (they are then not in `talk`).
  hidesResolved: boolean
  // Counts the comments sent or dropped: the field keeps its own text under
  // its key, so each new comment gets a field of its own, empty.
  commentRound: number
  talk: readonly Comment[]
  // The breadcrumb's open list, and what the folder it last opened holds.
  crumb: Crumb
  folder: { dir: string; entries: readonly string[] } | undefined
  // The name last looked up in this file.
  symbol: Lookup | undefined
}

export type FileActions = {
  // Returns to where the file was opened from.
  back: () => void
  help: () => void
  refresh: () => void
  toggleMore: () => void
  // Moves the window so `line` is its first.
  scrollTo: (line: number) => void
  // Steps to a diagnostic (its place among the file's), opening its card.
  showIssue: (index: number, top: number) => void
  // Goes to the next place the file differs; `top` is undefined when there
  // is none below.
  nextChange: (top: number | undefined) => void
  toggleDiff: () => void
  toggleExpanded: () => void
  toggleBlame: () => void
  toggleHints: () => void
  // Shows a markdown file rendered again.
  showRendered: () => void
  // The search: its field opened (or given the keyboard back), typed in,
  // a match gone to, the keyboard handed back to the pane's keys, closed.
  find: () => void
  typeFind: (text: string) => void
  showMatch: (index: number, top: number) => void
  leaveFindField: () => void
  closeFind: () => void
  // Pressing a line's number: its block goes to the prompt, or, while
  // commenting, the line is picked to comment on.
  pressLine: (line: number) => void
  // While commenting: a removed line is picked, by its number in the other
  // side and the line of this side it is drawn before.
  pressOldLine: (old: number, before: number) => void
  // Puts a line's diagnostics, with its code, into the prompt.
  sendIssues: (line: number) => void
  // Puts the review thread on a line, with the code it is about, into the prompt.
  // `isLedger` says which card on the line was pressed: the ledger's
  // findings, or (the default) the request's thread. Only that one is sent.
  sendTalk: (line: number, isLedger?: boolean) => void
  // Opens the comment box under a line as an answer to the thread there, and
  // marks that thread resolved or open again. Both write to the forge only
  // once the person posts or presses.
  replyOn: (line: number) => void
  resolveOn: (line: number, isResolved: boolean) => void
  cancelComment: () => void
  // Opens the box for a comment on the file as a whole.
  commentOnFile: () => void
  // Brings a comment on several lines back to the one its box is under.
  commentOnOneLine: () => void
  // Leaves resolved threads out, or shows them again; lists every thread.
  toggleResolved: () => void
  listThreads: () => void
  // Puts what was dragged over into the prompt.
  sendSelection: () => void
  // Looks up the name dragged over, among the lines `from`..`to` on screen.
  lookUpSelection: (from: number, to: number) => void
  closeLookup: () => void
  listUses: () => void
  listCallers: () => void
  listCallees: () => void
  listImplementations: () => void
  // Opens a file of the working tree at a line.
  openFile: (path: string, line: number) => void
  // Opens the commit that last changed a line, in the graph.
  openCommit: (hash: string) => void
  // The breadcrumb: a folder's list opened under column `left` (or closed
  // if it is the one open), the same for the names at a level of the
  // outline, a folder listed in the list already open, and the list closed.
  toggleFolder: (dir: string, left: number) => void
  toggleNames: (level: number, left: number) => void
  listFolder: (dir: string, left: number) => void
  closeCrumb: () => void
  // Scrolls to a name picked from the breadcrumb's list, and closes it.
  jumpTo: (line: number) => void
  // Commenting on a request: switched on or off, typed, and posted (Enter
  // passes the field's text; the button posts what was typed so far).
  toggleCommenting: () => void
  typeComment: (text: string) => void
  // `isNow` sends a comment of its own at once, in place of leaving it to
  // wait for the review.
  // `how` says what becomes of a comment of its own: it waits for the review
  // (the default), goes at once, or waits as a suggested replacement for its
  // lines. While a comment is being changed, it saves that.
  postComment: (entered?: string, how?: 'review' | 'now' | 'suggest') => void
  // A comment of the person's own, by its id: opened in the field to be
  // changed (under line `n`), asked about before it is deleted ('' takes the
  // question away), and deleted. And any comment given a thumbs-up.
  editComment: (id: string, n: number) => void
  askDelete: (id: string) => void
  deleteComment: (id: string) => void
  likeComment: (id: string) => void
  // Drops comments written for the review and not sent, by their ids.
  discardDrafts: (ids: readonly string[]) => void
}

// The window as drawn, for the scroll hook: the furthest its first line may
// go (where the file's last line sits on the bottom row), and where the
// breadcrumb's open list sits among the pane's rows (which rows are over it,
// where it is scrolled to, and how far it can go), if one is open.
//
// `shown` is the lines the changes-only view draws, in order, which the
// window then steps among; undefined while every line shows.
export type FileWindow = {
  maxTop: number
  shown: readonly number[] | undefined
  crumbBox: { from: number; to: number; top: number; max: number } | undefined
}

export const fileScreen = (
  kit: Kit,
  model: FileModel,
  actions: FileActions,
): { tree: RenderChildren; window: FileWindow } => {
  const { Box, Button, Text, Input, Raster } = kit
  const { shell, file, commit, lines, texts, removed, changed, isNewFile, diags, blame } = model
  const { isDiff, isMore, isFinding, isCommenting, commentLine, crumb, symbol } = model
  const info = model.insight
  const lineCount = lines?.length ?? 0
  const byLine = diagsByLine(diags, lineCount)
  const columns = shell.columns
  const hasMinimap = Raster !== undefined && columns >= MINIMAP_FROM_COLUMNS
  const blameWidth = blame === undefined ? 0 : BLAME_WIDTH + 1
  const codeColumns = columns - (hasMinimap ? MINIMAP_COLUMNS + 1 : 0) - blameWidth
  const gutter = String(Math.max(1, lineCount)).length
  const cardWidth = Math.max(24, Math.min(90, codeColumns - gutter - 4))
  // The code the checkers say is never used, by line.
  const fadedByLine = new Map<number, Diag[]>()

  for (const diag of model.faded) {
    fadedByLine.set(diag.line, [...(fadedByLine.get(diag.line) ?? []), diag])
  }

  // Where the outline's functions and classes start, for the minimap: only
  // the top two levels, or a long file's map is all outline.
  const heads = new Map<number, 1 | 2>()

  for (const item of info?.items ?? []) {
    if (item.depth <= 1 && ['function', 'method', 'constructor'].includes(item.kind)) {
      heads.set(item.line, 1)
    } else if (item.depth <= 1 && ['class', 'interface', 'type', 'enum'].includes(item.kind)) {
      heads.set(item.line, 2)
    }
  }

  // What the language server said of the name last looked up, wrapped to
  // the pane and cut to a few lines: its type or signature, then its docs.
  const symbolLines =
    symbol === undefined
      ? []
      : wrapText(symbol.text === '' ? 'The language server has nothing on that name.' : symbol.text, columns - 6).slice(
          0,
          SYMBOL_LINES,
        )
  // How many lines the breadcrumb needs: each part is its icon, its name
  // and a separator, and a part that does not fit goes to the next line.
  const crumbLength =
    (file.startsWith('/') ? [file] : file.split('/')).reduce(
      (sum, part) => sum + part.length + 5,
      0,
    ) +
    (info === undefined ? [] : enclosing(info.items, model.top)).reduce(
      (sum, item) => sum + item.name.length + 5,
      2,
    )
  const crumbLines = clamp(Math.ceil(crumbLength / columns), 1, 3)
  // The rows the header takes: status, the buttons (which wrap in a narrow
  // pane), each note, and the title. The window gets what is left.
  const headerRows =
    // The status, the breadcrumb and the title.
    2 +
    crumbLines +
    // Its box: a border above and below, the name, the lines, the call it
    // sits in when there is one, and two rows of buttons.
    (symbol === undefined ? 0 : symbolLines.length + 5 + (symbol.signature === '' ? 0 : 1)) +
    (isDiff ? 1 : 0) +
    (isFinding ? 3 : 0) +
    // The row of the whole-file button.
    (isCommenting ? 1 : 0) +
    // The box a comment on the file as a whole is typed in.
    (isCommenting && commentLine === FILE_COMMENT ? 4 : 0) +
    // The main row of buttons, and the box of the rest when it is open.
    Math.ceil(100 / columns) +
    (isMore ? 2 + Math.ceil(170 / Math.max(20, columns - 4)) : 0) +
    shell.notes.length + (model.note === '' ? 0 : 1)
  const room = clamp(shell.rows - headerRows, 5, 256)
  // Both are settled further down, once each line's height is known.
  let top = clamp(model.top, 1, lineCount)
  let maxTop = Math.max(1, lineCount)

  const moveTo = (line: number) => actions.scrollTo(clamp(line, 1, maxTop))
  // The changes-only view: the lines that show, or undefined where every
  // line does (a new file is all change, and a file with nothing changed or
  // said has nothing to cut down to).
  const cut =
    isDiff && model.isChanges && !isNewFile
      ? changeLines(
          lineCount,
          changed,
          Object.keys(removed).map(Number),
          model.talk.map(one => one.line),
        )
      : []
  const shown = cut.length === 0 ? undefined : cut
  const firstLine = shown?.[0] ?? 1
  const lastLine = shown?.[shown.length - 1] ?? lineCount
  // The line drawn after one and before it, among those that show.
  const nextLine = (n: number): number =>
    shown === undefined ? n + 1 : (shown.find(line => line > n) ?? lineCount + 1)
  const prevLine = (n: number): number =>
    shown === undefined ? n - 1 : ([...shown].reverse().find(line => line < n) ?? 0)
  // Moves the window by rows' worth of the lines that show.
  const moveBy = (by: number) =>
    moveTo(shown === undefined ? top + by : stepShown(shown, top, by))
  // The next commented line below the window's first lines, or the one
  // above; from the last it goes round to the first.
  const stepTalk = (way: 1 | -1) => {
    const lines = [...new Set(model.talk.map(one => one.line))].sort((one, other) => one - other)
    const here = top + 2
    const next =
      way === 1
        ? (lines.find(line => line > here) ?? lines[0])
        : ([...lines].reverse().find(line => line < here) ?? lines[lines.length - 1])

    if (next !== undefined) {
      moveTo(next - 2)
    }
  }

  const stepIssue = (by: number): void => {
    if (diags.length === 0) {
      return
    }

    const cursor = (model.cursor + by + diags.length) % diags.length
    const line = clamp(diags[cursor]?.line ?? 1, 1, lineCount)

    actions.showIssue(cursor, clamp(line - Math.floor(room / 3), 1, maxTop))
  }

  // The full text of a line's diagnostics: the card a hover floats over the
  // code, and the one the stepped-to line shows in the flow.
  const card = (here: readonly { diag: Diag; index: number }[]) =>
    here.flatMap(({ diag }) => [
      <Text color={COLOR[diag.severity]} bold>
        {MARK[diag.severity]} {diag.tool}
        {diag.rule === '' ? '' : ` ${diag.rule}`}
        {diag.isNew === undefined ? '' : diag.isNew ? ' · new' : ' · pre-existing'}
      </Text>,
      <Text>{diag.message.replace(/[ \t ]+/g, ' ')}</Text>,
    ])

  // The request's comments on this file's lines.
  const talkByLine = new Map<number, Comment[]>()

  for (const one of model.talk) {
    talkByLine.set(one.line, [...(talkByLine.get(one.line) ?? []), one])
  }

  // The search: what is typed in the find field, where it occurs, and which
  // match the person is on.
  const matches = isFinding ? findMatches(texts, model.find) : []
  const foundByLine = new Map<number, (readonly [number, number])[]>()

  for (const match of matches) {
    foundByLine.set(match.line, [...(foundByLine.get(match.line) ?? []), [match.from, match.to]])
  }

  const matchAt = matches.length === 0 ? -1 : clamp(model.findAt, 0, matches.length - 1)
  const stepMatch = (by: number): void => {
    if (matches.length === 0) {
      return
    }

    const next = (Math.max(0, matchAt) + by + matches.length) % matches.length

    actions.showMatch(next, clamp((matches[next]?.line ?? 1) - Math.floor(room / 3), 1, maxTop))
  }

  // One line of the file as elements, and how many rows they take.
  // `offset` is the row of the window the line starts on, where it is being
  // placed (not just measured): it decides which way the line's card opens.
  // In the diff, the removed lines drawn above a changed line are taken as
  // the lines it and those after it replaced, one for one in order: each
  // such line, by its number, with the text it replaced.
  const rewritten = new Map<number, string>()

  if (isDiff && !isNewFile) {
    for (const [before, gone] of Object.entries(removed)) {
      for (const [at, text] of gone.entries()) {
        const line = Number(before) + at

        if (!changed.some(range => line >= range[0] && line <= range[1])) {
          break
        }

        rewritten.set(line, text)
      }
    }
  }

  const codeLine = (spans: readonly Span[], n: number, offset?: number) => {
    const here = byLine.get(n) ?? []
    const first = here[0]
    const isChanged = isNewFile || changed.some(range => n >= range[0] && n <= range[1])
    const isAdded = isDiff && isChanged
    const worst = here.some(({ diag }) => diag.severity === 'error')
      ? 'error'
      : (first?.diag.severity ?? 'warning')
    // The line as it is drawn: the tokenizer's colours, corrected where the
    // language server knows what a name is; then the marks (diagnostics,
    // search matches, code that is never used); then the server's inlay
    // hints, which are not in the file and so go in last.
    const parts = withInlays(
      markSpans(
        info === undefined ? spans : applySemantic(spans, info.tokens.get(n) ?? [], info.raw[n - 1]),
        here.map(({ diag }) => [diag.col, Math.max(diag.endCol, diag.col + 1)] as const),
        foundByLine.get(n) ?? [],
        [
          ...(fadedByLine.get(n) ?? []),
          ...here.filter(({ diag }) => diag.isUnused === true).map(({ diag }) => diag),
        ].map(diag => [diag.col, Math.max(diag.endCol, diag.col + 1)] as const),
      ),
      model.isHinting ? (info?.hints.get(n) ?? []) : [],
      info?.raw[n - 1],
    )
    // In the diff, a line that replaced a removed one has the words that
    // differ between the two lit: its parts are cut where those words start
    // and end. A hint is the server's and takes up none of the file's text.
    const lit = isAdded && rewritten.has(n) ? changedWords(rewritten.get(n) ?? '', texts[n - 1] ?? '').after : []
    const litAt = new Set<number>()

    if (lit.length > 0) {
      const cut: typeof parts = []
      let col = 0

      for (const part of parts) {
        if (part.isHint) {
          cut.push(part)
          continue
        }

        const edges = [
          ...new Set(
            [0, part.text.length, ...lit.flatMap(([from, to]) => [from - col, to - col])].filter(
              edge => edge >= 0 && edge <= part.text.length,
            ),
          ),
        ].sort((one, other) => one - other)

        edges.slice(0, -1).forEach((edge, index) => {
          if (lit.some(([from, to]) => col + edge >= from && col + edge < to)) {
            litAt.add(cut.length)
          }

          cut.push({ ...part, text: part.text.slice(edge, edges[index + 1]) })
        })
        col += part.text.length
      }

      parts.splice(0, parts.length, ...cut)
    }

    const length = parts.reduce((sum, part) => sum + part.text.length, 0)
    const isOpen = model.isExpanded || here.some(({ index }) => index === model.cursor)
    // The message rides on the code's own row when the code leaves it room.
    const isBeside = gutter + 2 + length + 16 <= codeColumns
    const codeRows = Math.max(1, Math.ceil((gutter + 2 + length) / codeColumns))

    // The line number is the line's handle: pressing it adds the fold that
    // starts there (or the line alone) to the prompt.
    const number = (
      <Box flexShrink={0}>
        {/* A run of lines from one commit names it on its first line only. */}
        {blame !== undefined &&
          (n > 1 && (blame[n - 1]?.hash ?? '') === (blame[n - 2]?.hash ?? '') ? (
            <Text>{' '.repeat(BLAME_WIDTH + 1)}</Text>
          ) : (blame[n - 1]?.hash ?? '') === '' ? (
            <Text dimColor>{'uncommitted'.padEnd(BLAME_WIDTH + 1)}</Text>
          ) : (
            [
              <Button
                plain
                dimColor
                key={`blame:${n}`}
                label={`${blame[n - 1]?.hash ?? ''} ${(blame[n - 1]?.author ?? '').slice(0, 8).padEnd(8)} ${(blame[n - 1]?.age ?? '').padStart(4)}`}
                // Pressing a line's blame opens its commit in the graph.
                onPress={() => actions.openCommit(blame[n - 1]?.hash ?? '')}
              />,
              <Text> </Text>,
            ]
          ))}
        {/* The lines the comment being typed is on are marked down their
            edge, so a stretch of several can be seen before it is posted. */}
        {isCommenting &&
        commentLine > 0 &&
        n <= commentLine &&
        n >= (model.commentFrom > 0 ? model.commentFrom : commentLine) ? (
          <Text color={COMMENT_COLOR}>┃</Text>
        ) : (
          <Text color="green">{isAdded ? '+' : isChanged ? '▎' : ' '}</Text>
        )}
        <Button
          plain
          dimColor
          key={`ln:${n}`}
          label={String(n).padStart(gutter)}
          onPress={() => actions.pressLine(n)}
        />
        <Text> </Text>
      </Box>
    )
    const code = (
      <Text backgroundColor={isAdded ? ADDED_BACKGROUND : undefined}>
        {parts.length === 0 ? ' ' : ''}
        {parts.map((part, at) =>
          litAt.has(at) && !part.isFound && !part.isMarked ? (
            // A word that differs from the line this one replaced.
            <Text color={part.color === '' ? undefined : part.color} backgroundColor={ADDED_WORD} bold>
              {part.text}
            </Text>
          ) : part.isHint ? (
            // An inlay hint is the server's aside, not the file's text.
            <Text color={part.color} italic dimColor>
              {part.text}
            </Text>
          ) : part.isFaded && !part.isMarked && !part.isFound ? (
            // Code that is never used is faded, as an editor fades it.
            <Text color={part.color === '' ? undefined : part.color} dimColor>
              {part.text}
            </Text>
          ) : part.isFound ? (
            // A search's match is lit, and keeps a diagnostic's underline.
            <Text
              color={part.isMarked ? COLOR[worst] : part.color === '' ? undefined : part.color}
              backgroundColor={FOUND_BACKGROUND}
              underline={part.isMarked}
            >
              {part.text}
            </Text>
          ) : part.isMarked ? (
            <Text color={COLOR[worst]} underline>
              {part.text}
            </Text>
          ) : part.color === '' ? (
            part.text
          ) : (
            <Text color={part.color}>{part.text}</Text>
          ),
        )}
      </Text>
    )

    // What reviewers said on this line: one cut line, or the whole thread
    // when everything is expanded.
    const talk = talkByLine.get(n) ?? []
    // They are drawn as one card under the line, a thread as a review tool
    // shows it: who and when, then what was said, replies indented. Folded,
    // the card keeps the first comment's opening lines and counts the rest.
    const talkWidth = Math.max(24, Math.min(100, codeColumns - gutter - 4))
    // A request's thread and the ledger's findings on the same line are two
    // cards, each in its colour: a finding is no answer to the thread.
    const forgeTalk = talk.filter(one => !isLedgerFinding(one) && !isDraft(one))
    const ledgerTalk = talk.filter(isLedgerFinding)
    // What was written for the review and not sent yet has a card of its
    // own too, in the colour of what waits: all of it, and a way to drop it.
    const draftTalk = talk.filter(isDraft)
    const draftCard = () => {
      if (draftTalk.length === 0) {
        return { height: 0, rows: [] }
      }

      const lines = draftTalk.flatMap(one => [
        {
          isHead: true,
          text: `✎ pending${one.startLine === undefined ? '' : ` · lines ${one.startLine}–${one.line}`} · goes with your review`,
        },
        ...wrapText(one.body.trim(), talkWidth - 4)
          .slice(0, DRAFT_LINES)
          .map(text => ({ isHead: false, text })),
      ])
      const height = lines.length + 3

      return {
        height,
        rows: [
          <Box
            marginLeft={gutter + 2}
            width={talkWidth}
            height={height}
            flexDirection="column"
            borderStyle="round"
            borderColor={PENDING_COLOR}
            paddingX={1}
            overflow="hidden"
          >
            {lines.map(line => (
              <Text wrap="truncate-end" color={line.isHead ? PENDING_COLOR : undefined} bold={line.isHead}>
                {line.text === '' ? ' ' : line.text}
              </Text>
            ))}
            <Box height={1} overflow="hidden">
              <Button
                plain
                key={`draft-drop:${n}`}
                label="✕ discard"
                onPress={() => actions.discardDrafts(draftTalk.map(draftId))}
              />
            </Box>
          </Box>,
        ],
      }
    }
    const cardFor = (group: readonly Comment[], isLedger: boolean) => {
      if (group.length === 0) {
        return { height: 0, rows: [] }
      }

      const talkLines: { text: string; kind: 'head' | 'body' | 'more' }[] = []
      const scope = isLedger ? ':ledger' : ''
      // The thread's first comment, and whether it is the person's own.
      const first = group[0]
      const isMine = !isLedger && model.me !== '' && first?.author === model.me

    for (const [at, one] of (model.isExpanded ? group : group.slice(0, 1)).entries()) {
      // A finding stands by itself; an answer in a thread is set in.
      const indent = at === 0 || isLedger ? '' : '  '
      const body = wrapText(one.body.trim(), talkWidth - 4 - indent.length)

      talkLines.push({
        kind: 'head',
        text: `${indent}${at === 0 || isLedger ? talkIcon(one) : '↳'} ${one.author} · ${one.when.slice(0, 10)}${one.startLine === undefined ? '' : ` · lines ${one.startLine}–${one.line}`}${one.isResolved === true ? ' · ✓ resolved' : ''}${one.isOutdated === true ? ' · outdated' : ''}`,
      })

      for (const line of model.isExpanded ? body : body.slice(0, TALK_FOLDED)) {
        talkLines.push({ kind: 'body', text: `${indent}${line}` })
      }

      if (!model.isExpanded && (body.length > TALK_FOLDED || group.length > 1)) {
        const rest = group.length - 1
        const counted = isLedger
          ? `${rest} more ${rest === 1 ? 'finding' : 'findings'}`
          : `${rest} ${rest === 1 ? 'reply' : 'replies'}`

        talkLines.push({
          kind: 'more',
          text: `${[body.length > TALK_FOLDED ? '…' : '', rest > 0 ? counted : ''].filter(part => part !== '').join(' ')} · e expands`,
        })
      }
    }


      // What can be done with the thread sits on the card's last row. The
      // ledger's findings are closed in the ledger, and have no thread to
      // answer: theirs holds the way to the prompt alone.
      const isSettled = isLedger
        ? group.every(one => one.isResolved === true)
        : group.some(one => one.isResolved === true)
      const canSettle = !isLedger && group.some(one => one.isResolved !== undefined)
      // A settled thread steps back: a dim gold in place of its own colour.
      const talkColor = isSettled ? RESOLVED_COLOR : colorOfTalk(group[0])
      const height = talkLines.length + 2 + (model.canComment ? 1 : 0)

      return {
        height,
        rows: [
          <Box
            marginLeft={gutter + 2}
            width={talkWidth}
            height={height}
            flexDirection="column"
            borderStyle="round"
            borderColor={talkColor}
            paddingX={1}
            overflow="hidden"
          >
            {talkLines.map((line, at) => {
              const text = (
                <Text
                  wrap="truncate-end"
                  color={line.kind === 'head' ? talkColor : undefined}
                  bold={line.kind === 'head'}
                  dimColor={line.kind === 'more'}
                >
                  {line.text}
                </Text>
              )

              // The card's first row carries its handle, as a problem's
              // does: pressed, the thread and its code go to the prompt.
              return at === 0 ? (
                <Box height={1} columnGap={1} overflow="hidden">
                  <Button plain key={`talk:${n}${scope}`} label="↗" onPress={() => actions.sendTalk(n, isLedger)} />
                  {text}
                </Box>
              ) : (
                text
              )
            })}
            {model.canComment && (
              <Box height={1} columnGap={3} overflow="hidden">
                {!isLedger && (
                  <Button plain key={`reply:${n}`} label="↩ reply" onPress={() => actions.replyOn(n)} />
                )}
                {!isLedger && first !== undefined && (
                  <Button plain key={`like:${n}`} label="+1" onPress={() => actions.likeComment(first.id)} />
                )}
                {/* A comment of the person's own can be changed or removed;
                    removing is asked about first. */}
                {isMine && first !== undefined && model.deleting !== first.id && (
                  <Button plain key={`edit:${n}`} label="✎ edit" onPress={() => actions.editComment(first.id, n)} />
                )}
                {isMine && first !== undefined && model.deleting !== first.id && (
                  <Button plain key={`delete:${n}`} label="✕ delete" onPress={() => actions.askDelete(first.id)} />
                )}
                {isMine && first !== undefined && model.deleting === first.id && (
                  <Button
                    plain
                    key={`delete-yes:${n}`}
                    label="delete it for good?  yes"
                    onPress={() => actions.deleteComment(first.id)}
                  />
                )}
                {isMine && first !== undefined && model.deleting === first.id && (
                  <Button plain key={`delete-no:${n}`} label="no" onPress={() => actions.askDelete('')} />
                )}
                {canSettle && (
                  <Button
                    plain
                    key={`settle:${n}`}
                    label={isSettled ? '↺ reopen' : '✓ resolve'}
                    onPress={() => actions.resolveOn(n, !isSettled)}
                  />
                )}
                <Button
                  plain
                  key={`talk-send:${n}${scope}`}
                  label="↗ to prompt"
                  onPress={() => actions.sendTalk(n, isLedger)}
                />
              </Box>
            )}
          </Box>,
        ],
      }
    }
    const cards = [cardFor(forgeTalk, false), cardFor(ledgerTalk, true), draftCard()]
    const cardHeight = cards.reduce((sum, card) => sum + card.height, 0)
    // The box a comment or a reply is typed in opens under the line it is
    // for (under the thread, when it answers one). Only Enter or its post
    // button sends anything to the forge.
    const isWriting = isCommenting && commentLine === n && Input !== undefined
    // The field has a row to itself and the buttons the one under it, so a
    // narrow pane does not squeeze the field against them.
    // What the field holds is drawn in full under it, wrapped: the field is
    // one line, and a comment longer than it would otherwise be typed (or
    // changed) unseen. As many rows as it fills, to a bound.
    const typedRows = isWriting
      ? wrapText(model.typed.replace(/\\n/g, '\n'), Math.max(8, talkWidth - 4)).slice(-WRITE_ROWS)
      : []
    const shownTyped = typedRows.length > 1 || (typedRows[0] ?? '').length > talkWidth - 30 ? typedRows : []
    const writeHeight = isWriting ? 4 + shownTyped.length : 0
    // The lines a comment being typed is on, when it is on more than one.
    const isRange = model.commentFrom > 0 && model.commentFrom < n
    // Whether the field holds a comment of the person's own, being changed.
    const isEditing = model.editing !== '' && isWriting
    const answered = model.replyTo === '' ? undefined : forgeTalk[0]
    const writeRows =
      isWriting && Input !== undefined
        ? [
            <Box
              marginLeft={gutter + 2}
              width={talkWidth}
              height={writeHeight}
              flexDirection="column"
              borderStyle="round"
              borderColor={COMMENT_COLOR}
              paddingX={1}
              overflow="hidden"
            >
              <Box height={1} overflow="hidden">
                <Input
                  key={`comment-text:${model.commentRound}`}
                  label={
                    isEditing
                      ? 'edit your comment'
                      : answered !== undefined
                        ? `reply to ${answered.author}`
                        : model.commentOld > 0
                          ? `comment on removed line ${model.commentOld}`
                          : isRange
                            ? `comment on lines ${model.commentFrom}–${n}`
                            : `comment on line ${n}`
                  }
                  // A comment being changed starts as what it said.
                  {...(isEditing ? { value: model.draft } : {})}
                  placeholder="what to say, then Enter; \n starts a new line"
                  submitLabel="post"
                  autoFocus
                  onInput={actions.typeComment}
                  onSubmit={value => actions.postComment(value)}
                />
              </Box>
              {shownTyped.map(line => (
                <Box height={1} overflow="hidden">
                  <Text dimColor wrap="truncate-end">
                    {line === '' ? ' ' : line}
                  </Text>
                </Box>
              ))}
              <Box height={1} overflow="hidden" columnGap={2}>
                {/* An answer is posted at once. A comment of its own waits for
                    the review (Enter does that too), or goes now. */}
                {isEditing ? (
                  <Button key="comment-post" variant="primary" label="save" onPress={() => actions.postComment()} />
                ) : answered !== undefined ? (
                  <Button key="comment-post" variant="primary" label="post" onPress={() => actions.postComment()} />
                ) : (
                  [
                    <Button
                      key="comment-post"
                      variant="primary"
                      label="add to review"
                      onPress={() => actions.postComment()}
                    />,
                    // What is typed, offered as a replacement for the lines
                    // the comment is on: the forge shows a way to apply it.
                    <Button
                      key="comment-suggest"
                      label="suggest as change"
                      onPress={() => actions.postComment(undefined, 'suggest')}
                    />,
                    <Button key="comment-now" label="post now" onPress={() => actions.postComment(undefined, 'now')} />,
                  ]
                )}
                <Button key="comment-cancel" label="cancel" onPress={actions.cancelComment} />
              </Box>
            </Box>,
          ]
        : []
    // One element as tall as its lines and its border: the window counts the
    // card and the box by `talkHeight`.
    const talkHeight = cardHeight + writeHeight
    const talkRows = [...cards.flatMap(card => card.rows), ...writeRows]

    if (first === undefined) {
      return {
        rows: codeRows + talkHeight,
        elements: [
          <Box>
            {number}
            {code}
          </Box>,
          ...talkRows,
        ],
      }
    }

    // A Button takes no colour of its own, so the message stays a Text in
    // its severity's colour and the arrow before it is the handle: pressing
    // it adds the line's diagnostics, with its code, to the prompt. The
    // message is cut to fit so the arrow is never pushed off the row.
    const briefRoom = Math.max(
      8,
      isBeside ? codeColumns - gutter - length - 10 : codeColumns - gutter - 8,
    )
    // A line's message is marked NEW when the change brought any of its
    // diagnostics, and drawn dim when every one of them was already there.
    const isFresh = here.some(({ diag }) => diag.isNew === true)
    const isOld = here.every(({ diag }) => diag.isNew === false)
    const briefText = `${isFresh ? 'NEW ' : ''}${first.diag.message.split('\n')[0] ?? ''}${here.length > 1 ? `  +${here.length - 1} more` : ''}`
    const brief = (
      <Box flexShrink={0}>
        <Button plain key={`err:${n}`} label="↗" onPress={() => actions.sendIssues(n)} />
        <Text color={COLOR[worst]} dimColor={isOld} bold={isFresh}>
          {' '}
          {MARK[worst]}{' '}
          {briefText.length > briefRoom ? `${briefText.slice(0, briefRoom - 1)}…` : briefText}
        </Text>
      </Box>
    )
    const cardRows = here.reduce(
      (sum, { diag }) => sum + 1 + Math.ceil(diag.message.length / Math.max(1, cardWidth - 4)),
      2,
    )

    // The card opens above its line where the window has the rows for it,
    // and below where it has not (the first lines of the window): there it
    // would run off the top.
    const isBelow = !isOpen && offset !== undefined && offset < cardRows
    const cardBox = (place: { top: number } | { bottom: number }, scope?: string) => (
      <Box
        position="absolute"
        {...place}
        left={gutter + 2}
        width={cardWidth}
        display="none"
        hover={scope === undefined ? { display: 'flex' } : { display: 'flex', scope }}
        flexDirection="column"
        borderStyle="round"
        borderColor={COLOR[worst]}
        backgroundColor={CARD_BACKGROUND}
        paddingX={1}
      >
        {card(here)}
      </Box>
    )

    return {
      rows: codeRows + (isOpen ? cardRows : isBeside ? 0 : 1) + talkHeight,
      // A card that opens below is drawn after every row of the window, or
      // the rows under its line would be painted over it; it and its line
      // share a hover group, so the pointer on the line still reveals it.
      overlay: isBelow ? cardBox({ top: (offset ?? 0) + codeRows }, `card:${n}`) : undefined,
      elements: [
        <Box key={`line:${n}`} {...(isBelow ? { hover: { scope: `card:${n}` } } : {})}>
          {number}
          <Box flexShrink={isBeside ? 0 : 1}>{code}</Box>
          {isBeside && (
            <Box flexShrink={1} marginLeft={2}>
              {brief}
            </Box>
          )}
          {/* Above its line the card can hang off the line itself: rows are
              painted top to bottom, so nothing after it covers it there. */}
          {!isOpen && !isBelow && cardBox({ bottom: 1 })}
        </Box>,
        !isBeside && !isOpen && <Box marginLeft={gutter + 2}>{brief}</Box>,
        isOpen && (
          <Box
            marginLeft={gutter + 2}
            width={cardWidth}
            flexDirection="column"
            borderStyle="round"
            borderColor={COLOR[worst]}
            paddingX={1}
          >
            {card(here)}
          </Box>
        ),
        ...talkRows,
      ],
    }
  }

  // Only the lines the window has rows for are drawn, so the tree stays
  // small however long the file is.
  const windowRows = []
  // The cards that open below their line, drawn after the rows (see `codeLine`).
  const overlays: RenderChildren[] = []
  let used = 0
  let last = top - 1

  // In the diff view the lines the base had and the working tree dropped
  // are drawn above the line they came before, as a diff interleaves them.
  const removedRows = (before: number) => {
    const gone = isDiff ? (removed[before] ?? []) : []
    const rows = gone.slice(0, REMOVED_LINES).map((text, at) => {
      // Where the line was rewritten, not just removed, the words the new
      // line does not have are lit.
      const lit = rewritten.get(before + at) === text ? changedWords(text, texts[before + at - 1] ?? '').before : []
      const edges = [...new Set([0, text.length, ...lit.flat()])]
        .filter(edge => edge >= 0 && edge <= text.length)
        .sort((one, other) => one - other)

      return (
        <Box>
          {/* While commenting, a removed line's mark is its handle, with its
              number in the other side: pressed, the comment is on that line. */}
          {isCommenting && model.removedAt[before] !== undefined ? (
            <Box flexShrink={0}>
              <Text color={model.commentOld === (model.removedAt[before] ?? 0) + at ? COMMENT_COLOR : 'red'}>
                {model.commentOld === (model.removedAt[before] ?? 0) + at ? '┃' : '-'}
              </Text>
              <Button
                plain
                dimColor
                key={`old:${(model.removedAt[before] ?? 0) + at}`}
                label={String((model.removedAt[before] ?? 0) + at).padStart(gutter)}
                onPress={() => actions.pressOldLine((model.removedAt[before] ?? 0) + at, before)}
              />
              <Text> </Text>
            </Box>
          ) : (
            <Text color="red">{`-${' '.repeat(gutter)} `}</Text>
          )}
          <Text color="#f48771" backgroundColor={REMOVED_BACKGROUND} wrap="truncate-end">
            {text === ''
              ? ' '
              : edges.slice(0, -1).map((edge, index) => {
                  const piece = text.slice(edge, edges[index + 1])

                  return lit.some(([from, to]) => edge >= from && edge < to) ? (
                    <Text backgroundColor={REMOVED_WORD} bold>
                      {piece}
                    </Text>
                  ) : (
                    piece
                  )
                })}
          </Text>
        </Box>
      )
    })

    return gone.length > REMOVED_LINES
      ? [
          ...rows,
          <Text color="red" dimColor>
            {' '.repeat(gutter + 2)}… {gone.length - REMOVED_LINES} more removed lines
          </Text>,
        ]
      : rows
  }

  // The window stops once the file's last line reaches its bottom row:
  // walking up from the end, `maxTop` is the first line of the last full
  // window, counting the rows each line and its diagnostics really take.
  maxTop = Math.max(1, lastLine)

  // In the changes-only view, a row stands for the unchanged lines left out
  // above a line (`before` is that line, or one past the file's last).
  const gapRows = (before: number) => {
    const hidden = shown === undefined ? 0 : Math.min(before, lineCount + 1) - prevLine(before) - 1

    // A rule across the code's width, so one change is set apart from the
    // next: it says how many lines it stands for.
    const label = ` ${hidden} unchanged ${hidden === 1 ? 'line' : 'lines'} `
    const lead = '─'.repeat(gutter + 2)
    const width = codeColumns + blameWidth

    return hidden <= 0
      ? []
      : [
          <Text color={COMMIT_BOX} dimColor wrap="truncate-end">
            {lead}
            {label}
            {'─'.repeat(Math.max(0, width - lead.length - label.length))}
          </Text>,
        ]
  }
  // What follows the last line that shows: the unchanged lines left out
  // after it, one row.
  const tailGap = shown === undefined || lastLine >= lineCount ? [] : gapRows(lineCount + 1)

  if (lines !== undefined) {
    const rowsOf = (n: number): number =>
      codeLine(lines[n - 1] ?? [], n).rows + removedRows(n).length + gapRows(n).length
    // The last line always shows, with what was removed after it.
    let filled = removedRows(lineCount + 1).length + tailGap.length + rowsOf(maxTop)

    while (maxTop > firstLine && filled + rowsOf(prevLine(maxTop)) <= room) {
      maxTop = prevLine(maxTop)
      filled += rowsOf(maxTop)
    }
  }

  // A top on a line left out moves to the next that shows.
  top = Math.min(shown === undefined ? top : stepShown(shown, top, 0), maxTop)
  last = top - 1

  for (let at = top; lines !== undefined && at <= lastLine && used < room; at = nextLine(at)) {
    const above = [...gapRows(at), ...removedRows(at)]
    const drawn = codeLine(lines[at - 1] ?? [], at, used + above.length)
    used += above.length + drawn.rows
    windowRows.push(...above, ...drawn.elements)
    last = at

    if (drawn.overlay !== undefined) {
      overlays.push(drawn.overlay)
    }
  }

  // Lines removed from the end of the file come before a line it no longer has.
  if (lines !== undefined && last === lineCount) {
    windowRows.push(...removedRows(lineCount + 1))
  }

  if (lines !== undefined && last === lastLine) {
    windowRows.push(...tailGap)
  }

  // The next place the file differs from the base, below the window's top.
  const nextChange = (): number | undefined =>
    [...changed.map(range => range[0]), ...Object.keys(removed).map(Number)]
      .sort((a, b) => a - b)
      .find(line => line > top + 2)

  const minimap =
    hasMinimap && lines !== undefined
      ? minimapCells(
          lines.map((spans, at): MiniLine => {
            const text = spans.map(span => span[1]).join('')
            const here = byLine.get(at + 1) ?? []

            return {
              indent: text.length - text.trimStart().length,
              length: text.trimEnd().length,
              mark:
                here.length === 0 ? 0 : here.some(({ diag }) => diag.severity === 'error') ? 2 : 1,
              isChanged: changed.some(range => at + 1 >= range[0] && at + 1 <= range[1]),
              isTalked: talkByLine.has(at + 1),
              isSettled: (talkByLine.get(at + 1) ?? []).some(one => one.isResolved === true),
              head: heads.get(at + 1) ?? 0,
            }
          }),
          MINIMAP_COLUMNS,
          Math.min(room, MINIMAP_ROWS),
          top,
          last - top + 1,
        )
      : undefined

  // The breadcrumb: the file's path, a folder at a time, then the class and
  // function around the top of the window. Pressing a part opens a list
  // under it: a folder's own entries, or the names beside that one.
  const pathParts = file.startsWith('/') ? [file] : file.split('/')
  const around = info === undefined ? [] : enclosing(info.items, top)
  let crumbOffset = 0
  // Each part wears its icon in its colour (a folder's, a file type's, a
  // name's kind); the label is the Button, which takes no colour itself.
  const crumbPart = (
    glyph: string,
    color: string,
    label: string,
    key: string,
    press: (left: number) => void,
  ) => {
    const left = crumbOffset

    crumbOffset += label.length + 5

    // One box per part, which does not shrink: a part stays whole, and
    // wraps to the next line as a whole.
    return (
      <Box flexShrink={0}>
        <Text color={color === '' ? undefined : color}>{glyph} </Text>
        <Button plain key={key} label={label} onPress={() => press(left % columns)} />
        <Text dimColor> › </Text>
      </Box>
    )
  }
  const trail = [
    ...pathParts.flatMap((part, at) => {
      const isFile = at === pathParts.length - 1
      const icon = iconOf(file)

      return crumbPart(
        isFile ? icon.glyph : '\u{f07b}',
        isFile ? icon.color : '#dcb67a',
        part,
        `crumb:${at}`,
        left => actions.toggleFolder(pathParts.slice(0, at).join('/'), left),
      )
    }),
    ...around.flatMap((item, at) =>
      crumbPart(
        outlineRows([item])[0]?.label.trimStart().charAt(0) ?? '·',
        kindColor(item.kind),
        item.name,
        `crumb-in:${at}`,
        left => actions.toggleNames(at, left),
      ),
    ),
    info !== undefined && (
      <Button
        plain
        dimColor
        key="crumb-more"
        label="…"
        onPress={() => actions.toggleNames(around.length, crumbOffset)}
      />
    ),
  ]

  // What the open part lists. A folder lists what it holds, folders first,
  // with a way up; a name lists the names beside it in the outline.
  type Entry = { label: string; glyph: string; color: string; isHere: boolean; press: () => void }
  let entries: Entry[] = []

  if (crumb.kind === 'dir' && model.folder !== undefined && model.folder.dir === crumb.dir) {
    const within = crumb.dir === '' ? '' : `${crumb.dir}/`

    entries = [
      ...(crumb.dir === ''
        ? []
        : [
            {
              label: '..',
              glyph: '\u{f07c}',
              color: '#dcb67a',
              isHere: false,
              press: () =>
                actions.listFolder(
                  crumb.dir.includes('/') ? crumb.dir.slice(0, crumb.dir.lastIndexOf('/')) : '',
                  crumb.left,
                ),
            },
          ]),
      ...model.folder.entries.map((name): Entry => {
        const isFolder = name.endsWith('/')
        const full = `${within}${name.replace(/\/$/, '')}`
        const icon = iconOf(full)

        return {
          label: name,
          glyph: isFolder ? '\u{f07b}' : icon.glyph,
          color: isFolder ? '#dcb67a' : icon.color,
          isHere: file === full || file.startsWith(`${full}/`),
          press: () => (isFolder ? actions.listFolder(full, crumb.left) : actions.openFile(full, 1)),
        }
      }),
    ]
  } else if (crumb.kind === 'symbol' && info !== undefined) {
    const parent = crumb.level === 0 ? undefined : around[crumb.level - 1]

    entries = outlineRows(
      info.items.filter(item =>
        parent === undefined
          ? item.depth === 0
          : item.depth === parent.depth + 1 && item.line >= parent.line && item.line <= parent.endLine,
      ),
    ).map(({ item, label }) => ({
      label: item.name,
      glyph: label.trimStart().charAt(0),
      color: kindColor(item.kind),
      isHere: around[crumb.level] === item,
      press: () => actions.jumpTo(clamp(item.line, 1, maxTop)),
    }))
  }

  // The list takes the room there is: as wide as its longest entry needs,
  // up to the pane's width, and as tall as the window under it allows.
  const crumbRows = clamp(room - 3, 6, 30)
  const crumbWidth = clamp(
    Math.max(CRUMB_WIDTH, ...entries.map(entry => entry.label.length + 14)),
    CRUMB_WIDTH,
    columns - 2,
  )
  // It opens on the entry the file is at, and the wheel moves it.
  const hereAt = entries.findIndex(entry => entry.isHere)
  const crumbTop = clamp(
    crumb.top < 0 ? hereAt - Math.floor(crumbRows / 2) : crumb.top,
    0,
    entries.length - crumbRows,
  )

  return {
    window: {
      maxTop,
      shown,
      // Where the popover sits among the pane's rows: under the status and
      // the breadcrumb, inside the comparison border if any.
      crumbBox:
        entries.length === 0
          ? undefined
          : {
              from: shell.inset / 2 + 1 + crumbLines,
              to: shell.inset / 2 + 2 + crumbLines + Math.min(entries.length, crumbRows) + 1,
              top: crumbTop,
              max: Math.max(0, entries.length - crumbRows),
            },
    },
    tree: (
      <Box flexDirection="column">
        {statusLine(kit, shell)}
        {/* The breadcrumb takes the lines its path needs, up to three: a part
            is never squeezed, and what does not fit on a line goes to the next. */}
        <Box height={crumbLines} overflow="hidden" flexWrap="wrap">
          {trail}
        </Box>
        {/* The keys used all the time stay on one row; the rest open in a box
            under it (a), so the header is not a wall of them. A key works
            while its button is drawn, so the box is where the others live. */}
        <Box columnGap={2} flexWrap="wrap">
          <Button plain key="back" hotkey="b" label="back" onPress={actions.back} />
          <Button plain key="next" hotkey="n" label="next issue" onPress={() => stepIssue(1)} />
          <Button plain key="prev" hotkey="p" label="prev issue" onPress={() => stepIssue(-1)} />
          <Button
            plain
            key="down"
            hotkey="d"
            label="down"
            onPress={() => moveBy(Math.floor(room / 2))}
          />
          <Button
            plain
            key="up"
            hotkey="u"
            label="up"
            onPress={() => moveBy(-Math.floor(room / 2))}
          />
          <Button
            plain
            key="diff"
            hotkey="v"
            // The key goes round: the file, its diff, the diff cut down to
            // what differs.
            label={!isDiff ? 'diff view' : model.isChanges ? 'file view' : 'changes only'}
            onPress={actions.toggleDiff}
          />
          <Button plain key="find" hotkey="f" label="find" onPress={actions.find} />
          {/* A markdown file's way back to how it reads is always at hand. */}
          {isMarkdownFile(file) && (
            <Button plain key="rendered" hotkey="m" label="rendered" onPress={actions.showRendered} />
          )}
          <Button
            plain
            key="more"
            hotkey="a"
            label={isMore ? 'less' : 'more…'}
            onPress={actions.toggleMore}
          />
          {helpButton(kit, actions.help)}
        </Box>
        {/* Folded, the box is still drawn, at no height: a key works while
            its button is in the drawing, so the less-used keys answer
            whether or not the box is open. */}
        {(
          <Box
            columnGap={2}
            flexWrap="wrap"
            {...(isMore
              ? { borderStyle: 'round' as const, borderDimColor: true, paddingX: 1 }
              : { height: 0, overflow: 'hidden' as const })}
          >
            <Button plain key="top" hotkey="g" label="top" onPress={() => moveTo(1)} />
            <Button
              plain
              key="expand"
              hotkey="e"
              label={model.isExpanded ? 'collapse' : 'expand'}
              onPress={actions.toggleExpanded}
            />
            <Button
              plain
              key="change"
              hotkey="c"
              label="next change"
              onPress={() => {
                const line = nextChange()

                actions.nextChange(line === undefined ? undefined : clamp(line - 2, 1, maxTop))
              }}
            />
            <Button
              plain
              key="blame"
              hotkey="l"
              label={blame === undefined ? 'blame' : 'hide blame'}
              onPress={actions.toggleBlame}
            />
            {commit === '' && (
              <Button
                plain
                key="inspect"
                hotkey="t"
                label="look up selection"
                onPress={() => actions.lookUpSelection(top, last)}
              />
            )}
            {commit === '' && (
              <Button
                plain
                key="hints"
                hotkey="i"
                label={model.isHinting ? 'hide hints' : 'inlay hints'}
                onPress={actions.toggleHints}
              />
            )}
            <Button
              plain
              key="selection"
              hotkey="s"
              label="selection to prompt"
              onPress={actions.sendSelection}
            />
            {model.canComment && (
              <Button
                plain
                key="comment"
                hotkey="o"
                label={isCommenting ? 'stop commenting' : 'comment'}
                onPress={actions.toggleCommenting}
              />
            )}
            {model.canComment && (
              <Button plain key="talk-next" hotkey="w" label="next comment" onPress={() => stepTalk(1)} />
            )}
            {model.canComment && (
              <Button plain key="talk-prev" hotkey="q" label="prev comment" onPress={() => stepTalk(-1)} />
            )}
            {model.canComment && (
              <Button
                plain
                key="talk-resolved"
                hotkey="z"
                label={model.hidesResolved ? 'show resolved' : 'hide resolved'}
                onPress={actions.toggleResolved}
              />
            )}
            {model.canComment && (
              <Button plain key="talk-all" hotkey="y" label="all threads" onPress={actions.listThreads} />
            )}
            <Button plain key="refresh" hotkey="r" label="refresh" onPress={actions.refresh} />
          </Box>
        )}
        {notesOf(kit, shell.notes)}
        {model.note !== '' && (
          <Text color="yellow" wrap="truncate-end">
            ! {model.note}
          </Text>
        )}
        <Text bold wrap="truncate-end">
          {model.isChecked ? countLabel(diags) || '✓' : ''}
          {lineCount > 0 ? `  ${top}–${last} of ${lineCount}` : ''}
          {commit === '' ? '' : `  @ ${commit}`}
          {!isDiff
            ? ''
            : shown !== undefined
              ? '  · changes only'
              : model.isChanges && !isNewFile
                ? '  · diff (nothing differs here)'
                : '  · diff'}
        </Text>
        {/* The looked-up name: what it is, and a way to where it is defined. */}
        {symbol !== undefined && (
          <Box flexDirection="column" borderStyle="round" borderColor="cyan" paddingX={1}>
            <Text bold color="cyan" wrap="truncate-end">
              {symbol.name}
            </Text>
            {symbolLines.map(text => (
              <Box height={1} overflow="hidden">
                <Text>{text === '' ? ' ' : text}</Text>
              </Box>
            ))}
            {/* The call the name sits in, the argument being given in brackets. */}
            {symbol.signature !== '' && (
              <Box height={1} overflow="hidden">
                <Text dimColor>in a call: {symbol.signature}</Text>
              </Box>
            )}
            {/* Where it is declared, and where its type is. */}
            <Box columnGap={2} height={1} overflow="hidden">
              {symbol.path !== '' && (
                <Button
                  key="symbol-go"
                  variant="primary"
                  label={`definition: ${symbol.path.split('/').slice(-2).join('/')}:${symbol.line}`}
                  onPress={() => actions.openFile(symbol.path, symbol.line)}
                />
              )}
              {symbol.typePath !== '' && (
                <Button
                  key="symbol-type"
                  label={`its type: ${symbol.typePath.split('/').slice(-2).join('/')}:${symbol.typeLine}`}
                  onPress={() => actions.openFile(symbol.typePath, symbol.typeLine)}
                />
              )}
              {symbol.path === '' && symbol.typePath === '' && (
                <Text dimColor>The server does not say where it is defined.</Text>
              )}
            </Box>
            {/* Where it reaches: each of these opens a list to jump from. */}
            <Box columnGap={2} height={1} overflow="hidden">
              <Button key="symbol-uses" label="uses" onPress={actions.listUses} />
              <Button key="symbol-callers" label="callers" onPress={actions.listCallers} />
              <Button key="symbol-callees" label="what it calls" onPress={actions.listCallees} />
              {symbol.hasImplementations && (
                <Button
                  key="symbol-implementations"
                  label="implementations"
                  onPress={actions.listImplementations}
                />
              )}
              <Button key="symbol-close" label="close" onPress={actions.closeLookup} />
            </Box>
          </Box>
        )}
        {/* The comment row: a line number picks the line, and only Enter or
            the post button sends anything to the forge. */}
        {/* Commenting is told by the frame's colour (see the hooks module),
            not by a row of words here. */}
        {/* The file as a whole can be commented on too, on no line: its
            button has the row under the hint to itself. */}
        {isCommenting && Input !== undefined && (
          <Box height={1} overflow="hidden" columnGap={2}>
            <Button
              plain
              key="comment-file"
              label={commentLine === FILE_COMMENT ? '[whole file ✓]' : '[whole file]'}
              onPress={actions.commentOnFile}
            />
            {/* A comment stretched over several lines says so here, and
                pressed goes back to the one line. */}
            {model.commentFrom > 0 && commentLine > model.commentFrom && (
              <Button
                plain
                key="comment-range"
                label={`[lines ${model.commentFrom}–${commentLine}: back to one line]`}
                onPress={actions.commentOnOneLine}
              />
            )}
          </Box>
        )}
        {isCommenting && Input !== undefined && commentLine === FILE_COMMENT && (
          <Box
            height={4}
            flexDirection="column"
            borderStyle="round"
            borderColor={COMMENT_COLOR}
            paddingX={1}
            overflow="hidden"
          >
            <Box height={1} overflow="hidden">
              <Input
                key={`comment-file-text:${model.commentRound}`}
                label="comment on this file"
                placeholder="what to say of the file as a whole, then Enter"
                submitLabel="post"
                autoFocus
                onInput={actions.typeComment}
                onSubmit={value => actions.postComment(value)}
              />
            </Box>
            <Box height={1} overflow="hidden" columnGap={2}>
              <Button
                key="comment-file-post"
                variant="primary"
                label="add to review"
                onPress={() => actions.postComment()}
              />
              <Button key="comment-file-now" label="post now" onPress={() => actions.postComment(undefined, 'now')} />
              <Button key="comment-file-cancel" label="cancel" onPress={actions.cancelComment} />
            </Box>
          </Box>
        )}
        {/* The find row: typing narrows the matches, Enter goes to the next. */}
        {/* The field keeps its own text: what is typed is not drawn back into
            it, which would race the typing and drop keys. While it has the
            keyboard every key is text, so Enter also hands the keyboard to
            the buttons beside it, where the pane's keys work again. */}
        {isFinding && Input !== undefined && (
          <Box
            columnGap={2}
            height={3}
            overflow="hidden"
            borderStyle="round"
            borderColor={COMMIT_BOX}
            paddingX={1}
          >
            <Input
              key="find-text"
              label="find"
              placeholder="text in this file, then Enter"
              submitLabel="go"
              autoFocus
              onInput={actions.typeFind}
              onSubmit={() => {
                stepMatch(1)
                actions.leaveFindField()
              }}
            />
            <Text dimColor>
              {model.find === ''
                ? ''
                : matches.length === 0
                  ? 'no matches'
                  : `${matchAt + 1} of ${matches.length}`}
            </Text>
            <Button plain key="find-next" hotkey="j" label="next" onPress={() => stepMatch(1)} />
            <Button plain key="find-prev" hotkey="k" label="prev" onPress={() => stepMatch(-1)} />
            <Button plain key="find-close" hotkey="x" label="close find" onPress={actions.closeFind} />
          </Box>
        )}
        {/* The diff's key: which side each mark belongs to. */}
        {isDiff && (
          <Box columnGap={2}>
            <Text color="red">
              − removed ·{' '}
              {!model.isChecked
                ? `${shortRef(commit)}^`
                : model.diffAgainst !== ''
                  ? model.diffAgainst
                  : shell.isComparing
                    ? shell.against
                    : 'your last commit'}
            </Text>
            <Text color="green">+ added · {commit !== '' ? shortRef(commit) : shell.headName}</Text>
          </Box>
        )}
        {lines === undefined && <Text dimColor>Loading…</Text>}
        <Box height={room} overflow="hidden">
          <Box flexDirection="column" width={codeColumns + blameWidth} overflow="hidden">
            {windowRows}
            {overlays}
          </Box>
          {Raster !== undefined && minimap !== undefined && (
            <Box marginLeft={1}>
              <Raster key="minimap" columns={MINIMAP_COLUMNS} rows={Math.min(room, MINIMAP_ROWS)} cells={minimap} />
            </Box>
          )}
        </Box>
        {/* The breadcrumb's popover: drawn last, so it paints over the rows
            under the breadcrumb and moves none of them. */}
        {entries.length > 0 && (
          <Box
            position="absolute"
            top={1 + crumbLines}
            left={clamp(crumb.left, 0, columns - crumbWidth)}
            width={crumbWidth}
            flexDirection="column"
            borderStyle="round"
            borderColor={COMMIT_BOX}
            backgroundColor={CARD_BACKGROUND}
          >
            {entries.slice(crumbTop, crumbTop + crumbRows).map((entry, at) => (
              <Box height={1} overflow="hidden" backgroundColor={CARD_BACKGROUND}>
                <Text color={entry.color === '' ? undefined : entry.color}>
                  {' '}
                  {entry.glyph}{' '}
                </Text>
                <Button
                  plain
                  key={`crumb-row:${crumbTop + at}`}
                  label={entry.label.slice(0, crumbWidth - 12)}
                  onPress={entry.press}
                />
                {entry.isHere && <Text color={COMMIT_BOX}> ◂ here</Text>}
              </Box>
            ))}
            <Box columnGap={2} height={1} overflow="hidden" backgroundColor={CARD_BACKGROUND}>
              <Text dimColor>
                {' '}
                {crumbTop + 1}–{Math.min(entries.length, crumbTop + crumbRows)} of {entries.length}
              </Text>
              {entries.length > crumbRows && <Text dimColor>wheel to scroll</Text>}
              <Button plain key="crumb-close" label="close" onPress={actions.closeCrumb} />
            </Box>
          </Box>
        )}
      </Box>
    ),
  }
}

