// The file tree: paths as rows of folders and files, which of them a closed
// folder hides, and the icon a file wears wherever it is named.

// A folder holding more files than this starts closed in the tree.
const BIG_FOLDER = 40

export type TreeRow = {
  kind: 'dir' | 'file'
  path: string
  name: string
  depth: number
  size: number
}

type TreeNode = { dirs: Map<string, TreeNode>; files: string[]; size: number }

// The paths as a folder tree, in drawing order: folders before files, and a
// chain of folders that each hold only one folder drawn as one row (a/b/c).
export const buildTree = (paths: readonly string[]): TreeRow[] => {
  const root: TreeNode = { dirs: new Map(), files: [], size: 0 }

  for (const path of paths) {
    let node = root

    for (const part of path.split('/').slice(0, -1)) {
      const child = node.dirs.get(part) ?? { dirs: new Map(), files: [], size: 0 }
      node.dirs.set(part, child)
      child.size += 1
      node = child
    }

    node.files.push(path)
  }

  const rows: TreeRow[] = []

  const walk = (node: TreeNode, prefix: string, depth: number): void => {
    for (const [first, child] of [...node.dirs].sort((a, b) => a[0].localeCompare(b[0]))) {
      let name = first
      let last = child

      while (last.files.length === 0 && last.dirs.size === 1) {
        const [only] = [...last.dirs]

        if (only === undefined) {
          break
        }

        name += `/${only[0]}`
        last = only[1]
      }

      rows.push({ kind: 'dir', path: prefix + name, name, depth, size: last.size })
      walk(last, `${prefix}${name}/`, depth + 1)
    }

    for (const path of [...node.files].sort()) {
      rows.push({ kind: 'file', path, name: path.slice(prefix.length), depth, size: 1 })
    }
  }

  walk(root, '', 0)

  return rows
}

// The rows left once closed folders hide what is under them. A big folder
// starts closed and the rest open, or every folder starts closed (`isShut`,
// for a tree of the whole repo); `toggled` flips a folder from its default.
export const visibleTree = (
  rows: readonly TreeRow[],
  toggled: readonly string[],
  isShut = false,
): { row: TreeRow; isClosed: boolean }[] => {
  const shown: { row: TreeRow; isClosed: boolean }[] = []
  let hidden: string | undefined

  for (const row of rows) {
    if (hidden !== undefined && row.path.startsWith(hidden)) {
      continue
    }

    const isClosed =
      row.kind === 'dir' && (isShut || row.size > BIG_FOLDER) !== toggled.includes(row.path)

    hidden = isClosed ? `${row.path}/` : undefined
    shown.push({ row, isClosed })
  }

  return shown
}

// The file-type glyphs and their colours are the kit's, shared with the parked
// and ledger mods.
export { iconOf } from './kit/icons'
export type { Icon } from './kit/icons'

files.hooks/words.ts:
// What changed inside a changed line: a removed line and the added line that
// replaced it are compared word by word, so the screens can light the words
// that differ and leave the rest of the two lines as they are.

// A stretch of a line by its columns, 0-based, `to` exclusive.
export type Stretch = [from: number, to: number]

// Lines with more words than this are not compared: the table the comparison
// fills grows with the product of the two lines' words.
const WORDS = 400

// A line as its words: runs of letters and digits, runs of spaces, and every
// other character by itself.
const wordsOf = (text: string): string[] => text.match(/[A-Za-z0-9_]+|\s+|[^A-Za-z0-9_\s]/g) ?? []

// The words of `before` and of `after` that the other does not have, as
// stretches of each line. Lines that share nothing, or are too long to
// compare, come back with no stretches: the whole line is the change then,
// which its own colour already says.
export const changedWords = (before: string, after: string): { before: Stretch[]; after: Stretch[] } => {
  const old = wordsOf(before)
  const now = wordsOf(after)

  if (old.length === 0 || now.length === 0 || old.length > WORDS || now.length > WORDS) {
    return { before: [], after: [] }
  }

  // The longest run of words the two have in common, in order: `held[i][j]`
  // is its length over the words from `i` of one and `j` of the other.
  const held: number[][] = Array.from({ length: old.length + 1 }, () =>
    new Array<number>(now.length + 1).fill(0),
  )

  for (let i = old.length - 1; i >= 0; i -= 1) {
    for (let j = now.length - 1; j >= 0; j -= 1) {
      held[i]![j] =
        old[i] === now[j] ? (held[i + 1]?.[j + 1] ?? 0) + 1 : Math.max(held[i + 1]?.[j] ?? 0, held[i]?.[j + 1] ?? 0)
    }
  }

  // Words that are only spaces do not make two lines alike.
  if (!old.some(word => word.trim() !== '' && now.includes(word))) {
    return { before: [], after: [] }
  }

  const gone: Stretch[] = []
  const come: Stretch[] = []
  // A stretch is added to the last where it touches it, so a run of changed
  // words is one stretch.
  const mark = (list: Stretch[], from: number, to: number) => {
    const last = list[list.length - 1]

    if (last !== undefined && last[1] === from) {
      last[1] = to
    } else {
      list.push([from, to])
    }
  }
  let [i, j, at, to] = [0, 0, 0, 0]

  while (i < old.length || j < now.length) {
    const [left, right] = [old[i], now[j]]

    if (left !== undefined && right !== undefined && left === right) {
      at += left.length
      to += right.length
      i += 1
      j += 1
    } else if (right !== undefined && (left === undefined || (held[i]?.[j + 1] ?? 0) >= (held[i + 1]?.[j] ?? 0))) {
      mark(come, to, to + right.length)
      to += right.length
      j += 1
    } else if (left !== undefined) {
      mark(gone, at, at + left.length)
      at += left.length
      i += 1
    }
  }

  // Two lines with most of what they say changed read better as two whole
  // lines: the share is of their letters and marks, spaces aside.
  const inked = (text: string): number => text.replace(/\s/g, '').length
  const changed = (list: Stretch[], text: string): number =>
    inked(text) === 0 ? 0 : list.reduce((sum, [from, end]) => sum + inked(text.slice(from, end)), 0) / inked(text)

  return changed(gone, before) > 0.6 && changed(come, after) > 0.6
    ? { before: [], after: [] }
    : { before: gone, after: come }
}

files.hooks/screens/talk.tsx:
// The conversation of a request: what was said on it as a whole, and the
// comments that sit on no line (the code under them has changed, or they are
// on a file as a whole), with the box an answer is typed in. The file tree
// draws it under the request's files, and the request's own page under what
// the request says.

import { hostOf, markLinks, mediaOf } from '../media'
import type { Comment } from '../review'
import { isOnWholeFile } from '../review'
import { wrapText } from '../text'
import type { Kit, Shell } from './frame'
import { COMMENT_COLOR, COMMIT_BOX, LINK_ICON, said, talkColor, talkIcon } from './frame'

// How many of the conversation's latest comments are listed.
export const CONVERSATION_ROWS = 15
// The most lines of one of them shown when it is opened; as markdown, the
// most characters (an element's text is bounded); and the most pictures,
// videos and files listed under it.
const TALK_LINES = 40
const TALK_SHOWN = 8000
const TALK_MEDIA = 12

export type TalkModel = {
  shell: Shell
  // The comments to list: those of them on no line are the conversation.
  comments: readonly Comment[]
  // Whether there is a request to say something on.
  canTalk: boolean
  // Whether it is drawn as part of a section above it, a step in.
  isInSection: boolean
  // How many of its latest are listed.
  rows: number
  // The comment opened in full ('' for none); the one being answered ('new'
  // for a comment of its own, '' for none); and how many have been sent.
  talkOpen: string
  talkReply: string
  talkRound: number
}

export type TalkActions = {
  // Opens the file a comment is on.
  open: (path: string) => void
  openTalk: (id: string) => void
  writeTalk: (id: string) => void
  typeTalk: (text: string) => void
  postTalk: (entered?: string) => void
}

export const conversation = (kit: Kit, model: TalkModel, actions: TalkActions) => {
  const { Box, Button, Text, Input, Markdown, Link } = kit
  const { shell, comments, canTalk, isInSection } = model
  const quoted = comments.find(one => one.id === model.talkReply && one.path === '')

  return (
    <Box flexDirection="column">
      {comments.some(one => one.line === 0) && !isInSection && <Text> </Text>}
      {comments.some(one => one.line === 0) && (
        <Box columnGap={2}>
          <Text bold={!isInSection} dimColor={isInSection}>
            {isInSection ? '  ' : ''}Conversation ({comments.filter(one => one.line === 0).length})
          </Text>
          {canTalk && (
            <Button
              plain
              key="talk-new"
              hotkey="o"
              label={model.talkReply === 'new' ? 'close' : 'comment'}
              onPress={() => actions.writeTalk(model.talkReply === 'new' ? '' : 'new')}
            />
          )}
          <Text dimColor>press a name to read it all</Text>
        </Box>
      )}
      {comments
        .filter(one => one.line === 0)
        .slice(-model.rows)
        .map(one =>
          one.path === '' ? (
            // A comment on the request as a whole: its mark in the comments'
            // colour, and its author's name opens it in full, with a way to
            // answer it.
            <Box flexDirection="column">
              <Box height={1} overflow="hidden">
                <Box flexShrink={0}>
                  <Text color={COMMENT_COLOR}>
                    {isInSection ? '  ' : ''}
                    {talkIcon(one)}{' '}
                  </Text>
                  <Button
                    plain
                    key={`talk-open:${one.id}`}
                    label={one.author}
                    onPress={() => actions.openTalk(model.talkOpen === one.id ? '' : one.id)}
                  />
                </Box>
                <Text dimColor={model.talkOpen === one.id} wrap="truncate-end">
                  {' '}
                  {model.talkOpen === one.id
                    ? `· ${one.when.slice(0, 10)}`
                    : `: ${one.body.replace(/\s+/g, ' ')}`}
                </Text>
              </Box>
              {/* Opened, the comment reads as it was written: the surface
                  renders its markdown where it can, and what it links to
                  that a terminal cannot show (a picture, a video, a file)
                  is listed under it, each with the site it goes to. */}
              {model.talkOpen === one.id &&
                (Markdown !== undefined ? (
                  <Box marginLeft={isInSection ? 4 : 2} flexDirection="column">
                    <Markdown text={markLinks(one.body.trim().slice(0, TALK_SHOWN), LINK_ICON)} />
                  </Box>
                ) : (
                  wrapText(one.body.trim(), Math.max(20, shell.columns - 6))
                    .slice(0, TALK_LINES)
                    .map(line => (
                      <Text wrap="truncate-end">
                        {isInSection ? '  ' : ''}
                        <Text color={COMMENT_COLOR}>┃</Text> {line === '' ? ' ' : line}
                      </Text>
                    ))
                ))}
              {model.talkOpen === one.id &&
                mediaOf(one.body)
                  .slice(0, TALK_MEDIA)
                  .map(media => (
                    <Box height={1} overflow="hidden" marginLeft={isInSection ? 4 : 2}>
                      <Text dimColor>{media.kind === 'image' ? 'picture ' : `${media.kind} `}</Text>
                      {/* `mediaOf` keeps http and https links alone; the test
                          is made here too, as the overview makes it, so the
                          link does not rest on that one place. */}
                      {Link !== undefined && /^https?:\/\//i.test(media.url) ? (
                        <Text color={COMMIT_BOX} underline>
                          <Link href={media.url}>
                            {media.label} {LINK_ICON}
                          </Link>
                        </Text>
                      ) : (
                        <Text>{media.label}</Text>
                      )}
                      <Text dimColor> → {hostOf(media.url)}</Text>
                    </Box>
                  ))}
              {model.talkOpen === one.id && canTalk && (
                <Box columnGap={2} marginLeft={isInSection ? 4 : 2}>
                  <Button
                    plain
                    key={`talk-quote:${one.id}`}
                    label="quote reply"
                    onPress={() => actions.writeTalk(one.id)}
                  />
                  <Button plain key={`talk-close:${one.id}`} label="close" onPress={() => actions.openTalk('')} />
                </Box>
              )}
            </Box>
          ) : (
            // A comment on a file names it, and the name opens the file.
            <Box height={1} overflow="hidden">
              <Box flexShrink={0}>
                <Text color={talkColor(one)}>
                  {isInSection ? '  ' : ''}
                  {talkIcon(one)}{' '}
                </Text>
                <Button
                  plain
                  key={`talk-file:${one.id}`}
                  label={one.path}
                  onPress={() => actions.open(one.path)}
                />
              </Box>
              {/* A ledger finding with no line is on its file as a whole; a
                  request's comment with none has lost its line to an edit. */}
              <Text color={talkColor(one)} wrap="truncate-end">
                {' '}
                ({isOnWholeFile(one) ? 'whole file' : one.oldLine !== undefined ? 'removed line' : 'outdated'}) · {said(one)}
              </Text>
            </Box>
          ),
        )}
      {/* The box a comment on the request as a whole is typed in: a new one,
          or an answer that starts by quoting the comment it answers. It sits
          under the conversation, where the next thing said will go. Nothing
          is sent until Enter or its button. */}
      {canTalk && Input !== undefined && model.talkReply !== '' && (
        <Box flexDirection="column" borderStyle="round" borderColor={COMMENT_COLOR} paddingX={1}>
          {quoted !== undefined && (
            <Text dimColor wrap="truncate-end">
              &gt; {quoted.author}: {quoted.body.replace(/\s+/g, ' ')}
            </Text>
          )}
          <Input
            key={`talk-text:${model.talkRound}:${model.talkReply}`}
            label={quoted === undefined ? 'comment' : 'reply'}
            placeholder={
              quoted === undefined
                ? 'a comment on the request as a whole'
                : `your answer to ${quoted.author}; their comment is quoted above it`
            }
            submitLabel="post"
            autoFocus
            onInput={actions.typeTalk}
            onSubmit={value => actions.postTalk(value)}
          />
          <Box columnGap={2}>
            <Button key="talk-post" variant="primary" label="post" onPress={() => actions.postTalk()} />
            <Button key="talk-cancel" label="cancel" onPress={() => actions.writeTalk('')} />
          </Box>
        </Box>
      )}
    </Box>
  )
}

